for lang, data in pairs(NEW_WINGS) do
    local content = FDJ.ContentLocales[lang] or {}
    FDJ.ContentLocales[lang] = content
    content.dungeons = content.dungeons or {}
    content.bosses = content.bosses or {}
    content.places = content.places or {}
    content.quests = content.quests or {}
    local gy = content.dungeons["Scarlet Monastery: Graveyard"]
    local rfk = content.dungeons["Razorfen Kraul"]
    for i, key in ipairs(NEW_WING_KEYS) do
        if content.dungeons[key] == nil then
            local from = (i == 3) and rfk or gy
            content.dungeons[key] = { name = data.dungeons[i], location = from and from.location }
        end
    end
    if content.places["Razorfen Downs"] == nil then content.places["Razorfen Downs"] = data.dungeons[3] end
    for english, localName in pairs(data.npc or {}) do
        if content.places[english] == nil then content.places[english] = localName end
    end
    for _, english in ipairs(NEW_WING_BOSSES) do
        local localName = data.npc and data.npc[english]
        if localName and content.bosses[english] == nil then content.bosses[english] = localName end
    end
    for id, entry in pairs(data.quests or {}) do
        if content.quests[id] == nil then content.quests[id] = entry end
    end
end

