  ruRU = {
    dungeons = { "Ульдаман", "Зул'Фаррак", "Бесплодные земли", "Танарис" },
    bosses = { ["Archaedas"] = "Аркедас", ["Grimlok"] = "Гримлок", ["Revelosh"] = "Ревелош", ["Ancient Stone Keeper"] = "Древний Хранитель Камня", ["Ironaya"] = "Иронайа", ["Chief Ukorz Sandscalp"] = "Вождь Укорз Песчаная Плешь", ["Witch Doctor Zum'rah"] = "Знахарь Зум'рах", ["Gahz'rilla"] = "Газ'рилла", ["Shadowpriest Sezz'ziz"] = "Темный жрец Шезз'зиз", ["Galgann Firehammer"] = "Галганн Огнемолот", ["Ruuzlu"] = "Руузлу", ["Antu'sul"] = "Анту'сул", ["Sandarr Dunereaver"] = "Сандарр Разоритель Барханов", ["Dustwraith"] = "Пыльный призрак", ["Zerillis"] = "Зериллис", ["The Lost Dwarves"] = "Потерянные дворфы" },
    quests = {
      [17] = { name = "В Ульдаман за реагентами", objective = "Принесите 12 грибов-малиновиков Гхаку Целителю в Телсамар." },
      [704] = { name = "Судьба Эгмонда", objective = "Принесите 4 резные каменные урны геологу Сталекруту в Лок Модан." },
      [709] = { name = "Лекарство от судьбы", objective = "Принесите табличку Рьюн'эха Тельдарину Заблудшему." },
      [721] = { name = "Предвестник надежды", objective = "Найдите Греза Тяжелоступа в Ульдамане." },
      [722] = { name = "Амулет тайн", objective = "Найдите амулет Тяжелоступа и верните его ему в Ульдаман." },
      [1139] = { name = "Утерянные таблички Воли", objective = "Найдите табличку Воли и принесите ее советнику Белграму в Стальгорн." },
      [1360] = { name = "Возвращенное сокровище", objective = "Достаньте сокровище Крома Крепкорука из сундука в северном зале Ульдамана и принесите ему в Стальгорн." },
      [2200] = { name = "Назад в Ульдаман", objective = "Выясните, где именно в Ульдамане находится ожерелье Талваша. Убитый паладин, о котором он упоминал, был последним владельцем этого ожерелья." },
      [2201] = { name = "Время собирать камни", objective = "Найдите рубин, сапфир, и топаз, которые спрятаны в разных местах Ульдамана. Когда найдете, свяжитесь с Талвашем де Кисселем, используя фиал Видения, который он предоставил." },
      [2202] = { name = "В Ульдаман за реактивом", objective = "Принести 12 грибов-малиновиков Джаркалу Замшелому Клыку в Каргат." },
      [2204] = { name = "Восстановление ожерелье", objective = "Добудьте источник энергии из самого мощного волшебного создания, которое найдете в Ульдамане и доставьте его Талвашу де Кисселю в Стальгорн." },
      [2240] = { name = "Потайной чертог", objective = "Прочитайте журнал Бейлога, исследуйте, потайной чертог и потом доложите об увиденном геологу Грозовой Вершине." },
      [2278] = { name = "Платиновые Диски", objective = "Поговорите с каменным Стражем и запомните все, что он передаст вам. Когда он закончит свой пересказ событий древности, активируйте диски Норганнона." },
      [2279] = { name = "Платиновые Диски", objective = "Отнесите миниатюрную копию дисков Норганнона в Лигу Исследователей в Стальгорне." },
      [2280] = { name = "Платиновые Диски", objective = "Отнесите миниатюрную копию дисков Норганнона кому-то из мудрецов с Громового Утеса." },
      [2283] = { name = "Пропавшее ожерелье", objective = "Найдите на раскопках Ульдамана драгоценное ожерелье (возможно, поврежденное) и принесите его в Оргриммар Драну Дрофферсу." },
      [2284] = { name = "Пропавшее ожерелье, этап 2", objective = "Разыщите ключ к местонахождению самоцветов в глубинах Ульдамана." },
      [2339] = { name = "Найти самоцветы и источник энергии", objective = "Добудьте все три самоцвета и источник энергии для ожерелья из Ульдамана и принесите их Джаркалу Замшелому Клыку в Каргат. Джаркал считает, что источник энергии можно найти у самой сильной твари в Ульдамане." },
      [2342] = { name = "Возвращенные сокровища", objective = "Принесите Патрику Гарретту в Подгород фамильное сокровище из сундука в Южном зале Ульдамана." },
      [2398] = { name = "Потерянные дворфы", objective = "Найдите Бейлога в Ульдамане." },
      [2418] = { name = "Камни Силы", objective = "Принесите 8 дентриевых камней Силы и 8 энелиевых камней Силы Ригглфаззу в Бесплодные земли." },
      [2768] = { name = "Изыскательский стержень", objective = "Принесите изыскательский стержень главному инженеру Чепухастеру в Прибамбасск." },
      [2770] = { name = "Газ'рилла", objective = "Принесите искрящую чешую Газ'риллы Виззлу Медноштифу на Мерцающую равнину." },
      [2846] = { name = "Тиара глубин", objective = "Принесите Тиару Глубин Табете в Пыльную Трясину." },
      [2865] = { name = "Панцири скарабеев", objective = "Принести 5 целых панцирей скарабея Тран'реку в Прибамбасск." },
      [2936] = { name = "Паучья богиня", objective = "Прочитайте надписи на табличке Теки, узнайте имя паучьей богини, которой поклоняются тролли Сухокожих, а потом возвращайтесь к мастеру Гадрину." },
      [2991] = { name = "Медальон Некрума", objective = "Отнесите медальон Некрума Тадиусу Мрачной Тени в Выжженные земли." },
      [3042] = { name = "Троллье месиво", objective = "Принесите 20 фиалов с Тролльим месивом." },
      [3527] = { name = "Пророчество Мошару", objective = "Принесите первую и вторую таблички Мошару Йе'кинье в Танарис." },
    },
  },
  koKR = {
    dungeons = { "울다만", "줄파락", "황야의 땅", "타나리스" },
    bosses = { ["Archaedas"] = "아카에다스", ["Grimlok"] = "그림로크", ["Revelosh"] = "레벨로쉬", ["Ancient Stone Keeper"] = "고대 바위 문지기", ["Ironaya"] = "아이로나야", ["Chief Ukorz Sandscalp"] = "족장 우코르즈 샌드스칼프", ["Witch Doctor Zum'rah"] = "의술사 줌라", ["Gahz'rilla"] = "가즈릴라", ["Shadowpriest Sezz'ziz"] = "어둠의사제 세즈지즈", ["Galgann Firehammer"] = "갈간 파이어해머", ["Ruuzlu"] = "루즐루", ["Antu'sul"] = "안투술", ["Sandarr Dunereaver"] = "산다르 듄리버", ["Dustwraith"] = "더스트레이스", ["Zerillis"] = "제릴리스", ["The Lost Dwarves"] = "길 잃은 드워프" },
    quests = {
      [17] = { name = "울다만에서 재료 찾기", objective = "텔사마에 있는 가크 힐터치에게 자홍버섯 12개를 가져가야 합니다." },
      [704] = { name = "아그몬드의 운명", objective = "모단 호수에 있는 발굴조사단장 아이언밴드에게 돌조각 단지 4개를 가져가야 합니다." },
      [709] = { name = "멸망의 해결책", objective = "실성한 텔두린에게 류네의 서판을 가져가야 합니다." },
      [721] = { name = "희망의 전조", objective = "울다만에서 해머토 그레즈를 찾아야 합니다." },
      [722] = { name = "비밀의 아뮬렛", objective = "해머토의 아뮬렛을 찾아 울다만에 있는 해머토에게 가져가야 합니다." },
      [1139] = { name = "잃어버린 결의의 서판", objective = "결의의 서판을 찾아 아이언포지에 있는 조언자 벨그룸에게 가져가야 합니다." },
      [1360] = { name = "보물 찾기", objective = "울다만의 북쪽 대전당에 있는 궤짝에서 크롬 스타우트암의 보물을 찾아서 아이언포지에 있는 크롬 스타우트암에게 가져다주어야 합니다." },
      [2200] = { name = "울다만으로 돌아가기", objective = "울다만 안에서 탈바쉬의 목걸이의 행방에 대한 단서를 찾아야 합니다. 탈바쉬가 말했던 성기사가 그 단서를 가진 최후의 인물일 것입니다." },
      [2201] = { name = "보석 찾기", objective = "울다만에 흩어져 있는 루비, 사파이어, 토파즈를 찾아야 합니다. 모두 찾으면 탈바쉬가 준 수정점 유리병을 사용하여 그에게 연락해야 합니다." },
      [2202] = { name = "울다만에서 재료 찾기", objective = "카르가스에 있는 자칼 모스멜드에게 자홍버섯 12개를 가져가야 합니다." },
      [2204] = { name = "목걸이 복원", objective = "울다만에서 가장 강력한 피조물을 찾아 부서진 목걸이의 마력원천을 손에 넣은 다음, 아이언포지에 있는 탈바쉬 델 키젤에게 목걸이와 함께 가져가야 합니다." },
      [2240] = { name = "비밀 석실", objective = "밸로그의 일지를 읽고 비밀 석실을 조사한 후 발굴조사단장 스톰파이크에게 보고해야 합니다." },
      [2278] = { name = "백금 원반", objective = "바위감시자와 대화하고 그가 알고 있는 고대의 지식을 배우십시오. 지식을 배운 후에는 노르간논의 원반을 가동하십시오." },
      [2279] = { name = "백금 원반", objective = "아이언포지에 있는 탐험가 연맹에 노르간논의 소형 백금 원반을 가져가야 합니다." },
      [2280] = { name = "백금 원반", objective = "썬더 블러프에 있는 현자 중 하나에게 노르간논의 소형 원반을 가져가야 합니다." },
      [2283] = { name = "목걸이 회수", objective = "울다만 발굴 현장에서 값진 목걸이를 찾아 오그리마에 있는 드란 드로퍼스에게 가져다주어야 합니다. 목걸이는 파손된 것이라도 괜찮습니다." },
      [2284] = { name = "목걸이 회수 - 2차 시도", objective = "울다만 깊은 곳에서 보석의 행방에 대한 단서를 찾아야 합니다." },
      [2339] = { name = "보석과 마력원천 찾기", objective = "울다만에서 목걸이에 필요한 보석 3개와 마력원천을 회수한 후 카르가스에 있는 자칼 모스멜드에게 가져다주어야 합니다. 자칼의 말에 의하면 울다만에서 가장 강한 피조물을 처치하면 마력원천을 얻을 수 있다고 합니다." },
      [2342] = { name = "보물 되찾기", objective = "울다만의 남쪽 대전당에 있는 궤짝에서 가레트가의 보물을 찾아 언더시티에 있는 그에게 가져가야 합니다." },
      [2398] = { name = "길 잃은 드워프", objective = "울다만에서 밸로그를 찾아야 합니다." },
      [2418] = { name = "마법석", objective = "황야의 땅에 있는 리글퍼즈에게 덴트리움 마법석 8개와 안알레움 마법석 8개를 가져가야 합니다." },
      [2768] = { name = "자동 탐사막대", objective = "가젯잔에 있는 선임기술자 빌지위즐에게 자동 탐사막대를 가져가야 합니다." },
      [2770] = { name = "가즈릴라", objective = "소금 평원에 있는 위즐 브라스볼츠에게 가즈릴라의 전기 비늘을 가져가야 합니다." },
      [2846] = { name = "심연의 티아라", objective = "먼지진흙 습지대에 있는 타베사에게 심연의 티아라를 가져가야 합니다." },
      [2865] = { name = "왕쇠똥구리 껍질", objective = "가젯잔에 있는 트란렉에게 온전한 왕쇠똥구리 껍질 5개를 가져가야 합니다." },
      [2936] = { name = "거미 신", objective = "데카의 서판을 읽고 마른나무껍질부족 거미 신의 이름을 알아낸 후, 가드린 장로에게 돌아가십시오." },
      [2991] = { name = "네크룸의 메달", objective = "네크룸의 메달을 저주받은 땅에 있는 샤디우스 그림섀이드에게 가져가야 합니다." },
      [3042] = { name = "트롤 경화제", objective = "가젯잔에 있는 트렌튼 라이트해머에게 트롤 경화제 20병을 가져가야 합니다." },
      [3527] = { name = "모쉬아루의 예언", objective = "타나리스에 있는 예킨야에게 첫번째 모쉬아루 서판과 두번째 모쉬아루 서판을 가져가야 합니다." },
    },
  },
  zhCN = {
    dungeons = { "奥达曼", "祖尔法拉克", "荒芜之地", "塔纳利斯" },
    bosses = { ["Archaedas"] = "阿扎达斯", ["Grimlok"] = "格瑞姆洛克", ["Revelosh"] = "鲁维罗什", ["Ancient Stone Keeper"] = "古代的石头看守者", ["Ironaya"] = "艾隆纳亚", ["Chief Ukorz Sandscalp"] = "乌克兹·沙顶", ["Witch Doctor Zum'rah"] = "巫医祖穆拉恩", ["Gahz'rilla"] = "加兹瑞拉", ["Shadowpriest Sezz'ziz"] = "暗影祭司塞瑟斯", ["Galgann Firehammer"] = "加加恩·火锤", ["Ruuzlu"] = "卢兹鲁", ["Antu'sul"] = "安图苏尔", ["Sandarr Dunereaver"] = "杉达尔·沙掠者", ["Dustwraith"] = "灰尘怨灵", ["Zerillis"] = "泽雷利斯", ["The Lost Dwarves"] = "失踪的矮人" },
    quests = {
      [17] = { name = "奥达曼的蘑菇", objective = "收集12颗紫色蘑菇，把它们交给塞尔萨玛的加克。" },
      [704] = { name = "阿戈莫德的命运", objective = "收集4个雕纹石罐，把它们交给洛克莫丹的勘察员基恩萨·铁环。" },
      [709] = { name = "化解灾难", objective = "把雷乌纳石板带给迷失者塞尔杜林。" },
      [721] = { name = "一线希望", objective = "在奥达曼找到铁趾格雷兹。" },
      [722] = { name = "铁趾的护符", objective = "找到铁趾的护符，把它交给奥达曼的铁趾。" },
      [1139] = { name = "意志石板", objective = "找到意志石板，把它们交给铁炉堡的顾问贝尔格拉姆。" },
      [1360] = { name = "失而复得", objective = "到奥达曼的北部大厅去找到克罗姆·粗臂的箱子，从里面拿出他的宝贵财产，然后回到铁炉堡把东西交给他。" },
      [2200] = { name = "回到奥达曼", objective = "去奥达曼寻找塔瓦斯的魔法项链，被杀的圣骑士是最后一个拿着它的人。" },
      [2201] = { name = "寻找宝石", objective = "在奥达曼寻找红宝石、蓝宝石和黄宝石的下落。找到它们之后，通过塔瓦斯德给你的占卜之瓶和他进行联系。" },
      [2202] = { name = "奥达曼的蘑菇", objective = "收集12颗紫色蘑菇，把它们交给卡加斯的加卡尔。" },
      [2204] = { name = "修复项链", objective = "从奥达曼最强大的石人身上获得能量源，然后将其交给铁炉堡的塔瓦斯德。" },
      [2240] = { name = "密室", objective = "阅读巴尔洛戈的日记，探索密室，然后向铁炉堡的勘察员塔伯斯·雷矛汇报。" },
      [2278] = { name = "白金圆盘", objective = "和石头守护者交谈，从他那里了解更多古代的知识。一旦你了解到了所有的内容之后就激活诺甘农圆盘。" },
      [2279] = { name = "白金圆盘", objective = "把迷你版的诺甘农圆盘带到铁炉堡的探险者协会去。" },
      [2280] = { name = "白金圆盘", objective = "把迷你版的诺甘农圆盘带到雷霆崖的贤者那里。" },
      [2283] = { name = "搜寻项链", objective = "在奥达曼挖掘场中寻找一条珍贵的项链，然后将其交给奥格瑞玛的德兰·杜佛斯。项链有可能已经损坏。" },
      [2284] = { name = "搜寻项链，再来一次", objective = "在奥达曼里找寻宝石的线索。" },
      [2339] = { name = "寻找宝贝", objective = "从奥达曼找回项链上的所有三块宝石和能量源，然后把它们交给卡加斯的加卡尔。" },
      [2342] = { name = "寻找宝物", objective = "从奥达曼南部大厅的箱子中找到加勒特的家族宝藏，然后把它交给幽暗城的帕特里克·加瑞特。" },
