      [5341] = { name = "Fortune de la famille Barov", objective = "S’aventurer jusqu’à Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété de Southshore. Revenir auprès d’Alexi Barov quand la tâche est accomplie." },
      [5343] = { name = "Fortune de la famille Barov", objective = "S’aventurer jusqu’à la Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété de Southshore. Revenir auprès de Weldon Barov quand la tâche est accomplie." },
      [5382] = { name = "Docteur Theolen Krastinov, le boucher", objective = "Trouver le docteur Theolen Krastinov à l’intérieur de la Scholomance. Le tuer, puis brûler le Cadavre d’Eva Sarkhoff et le Cadavre de Lucien Sarkhoff. Retourner auprès d’Eva Sarkhoff quand la tâche est accomplie." },
      [5384] = { name = "Kirtonos le héraut", objective = "Revenir à Scholomance avec le Sang des innocents. Trouver le porche et placer le Sang des innocents dans le brasero. Kirtonos viendra dévorer votre âme. Combattre vaillamment, sans perdre un pouce de terrain ! Détruire Kirtonos et revenir auprès d’Eva Sarkhoff." },
      [5466] = { name = "La Liche, Ras Murmegivre", objective = "Trouver Ras Murmegivre dans Scholomance. Après l’avoir trouvé, utiliser le Souvenir lié sur son visage mort-vivant. Si sa transformation en mortel réussit, l’abattre et prendre la Tête humaine de Ras Murmegivre. Apporter la tête au Magistrat Marduke." },
      [5515] = { name = "Sac des horreurs de Krastinov", objective = "Trouver Jandice Barov dans Scholomance et la tuer. Sur son cadavre, récupérer le Sac des horreurs de Krastinov. Rapporter le sac à Eva Sarkhoff." },
      [5529] = { name = "Portée contaminée", objective = "Tuer 20 Jeunes pestiférés, puis retourner auprès de Betina Bigglezink à la Chapelle de l’Espoir de Lumière." },
      [7028] = { name = "Forces maléfiques retorses", objective = "Collecter 25 Ciselures de Cristaux Théradriques pour Saule, en Désolace." },
      [7029] = { name = "La corruption de Vylelangue", objective = "Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange, dans Maraudon. En faire usage sur les Vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir. Soigner 8 plantes en tuant les Engeances de Noxxious, puis retourner voir Vark Battlescar, à Proie-de-l'Ombre." },
      [7041] = { name = "La corruption de Vylelangue", objective = "Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange dans Maraudon. En faire usage sur les vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir. Soigner 8 plantes en tuant les Engeances, puis retourner voir Taliendra, à la Combe de Nijel." },
      [7044] = { name = "Légendes de Maraudon", objective = "Retrouver les deux parties du Sceptre de Celebras : le Bâtonnet de Celebras et le Diamant de Celebras. Trouvez un moyen de parler à Celebras." },
      [7046] = { name = "Le sceptre de Celebras", objective = "Aidez Celebras le Racheté pendant qu'il recrée le Sceptre de Celebras. Parlez-lui après la réussite du rituel." },
      [7064] = { name = "Corruption de la terre et de la graine", objective = "Anéantir la princesse Theradras et retourner voir Selendra près de Proie-de-l'Ombre, en Désolace." },
      [7065] = { name = "Corruption de la terre et de la Graine", objective = "Tuer la princesse Theradras, et retourner voir le Gardien Marandis, à la Combe de Nijel en Désolace." },
      [7066] = { name = "Graine de vie", objective = "Chercher Remulos à Reflet-de-Lune, et lui donner la Graine de vie." },
      [7067] = { name = "Les instructions du paria", objective = "Lire les instructions du paria. Après cela, obtenir l'Amulette d'union de Maraudon et la ramener au centaure renégat, dans le sud de Désolace." },
      [7068] = { name = "Fragments d'Ombréclat", objective = "Collecter 10 Fragments d'Ombréclats dans Maraudon, et les ramener à Uthel'nay, à Orgrimmar." },
      [7070] = { name = "Fragments d'Ombréclat", objective = "Collecter 10 Fragments d'Ombréclats, et les porter à l'archimage Tervosh, dans le marécage d'Âprefange." },
    },
  },
  esES = {
    dungeons = { "Templo Sumergido", "Scholomance", "Maraudon", "Pantano de las Penas", "Tierras de la Peste del Oeste", "Desolace" },
    bosses = { ["Darkmaster Gandling"] = "Maestro oscuro Gandling", ["Shade of Eranikus"] = "Sombra de Eranikus", ["Jammal'an the Prophet"] = "Jammal'an el Profeta", ["Ogom the Wretched"] = "Ogom el Desdichado", ["Morphaz"] = "Morphaz", ["Weaver"] = "Sastrón", ["Dreamscythe"] = "Guadañasueños", ["Hazzas"] = "Hazzas", ["Avatar of Hakkar"] = "Avatar de Hakkar", ["Atal'alarion"] = "Atal'alarion", ["Vectus"] = "Vectus", ["Marduk Blackpool"] = "Marduz Pozonegro", ["Lady Illucia Barov"] = "Lady Illucia Barov", ["Jandice Barov"] = "Jandice Barov", ["Lord Alexei Barov"] = "Lord Alexei Barov", ["Instructor Malicia"] = "Instructor Malicia", ["Kirtonos the Herald"] = "Kirtonos el Heraldo", ["The Ravenian"] = "El Devorador", ["Ras Frostwhisper"] = "Ras Levescarcha", ["Lorekeeper Polkelt"] = "Tradicionalista Polkelt", ["Doctor Theolen Krastinov"] = "Doctor Theolen Krastinov", ["Rattlegore"] = "Traquesangre", ["Princess Theradras"] = "Princesa Theradras", ["Landslide"] = "Derrumblo", ["Celebras the Cursed"] = "Celebras el Maldito", ["Lord Vyletongue"] = "Lord Lenguavil", ["Meshlok the Harvester"] = "Meshlok el Cosechador", ["Razorlash"] = "Latisable", ["Noxxion"] = "Noxxion", ["Rotgrip"] = "Escamapodrida", ["Tinkerer Gizlock"] = "Manitas Gizlock" },
    quests = {
      [1445] = { name = "El Templo de Atal'Hakkar", objective = "Reúne 20 fetiches de Hakkar y llévaselos a Fel'Zerul en Rocal." },
      [1446] = { name = "El profeta Jammal'an", objective = "El exiliado de Atal'ai, en las Tierras del Interior, quiere la cabeza de Jammal'an." },
      [1475] = { name = "En El Templo de Atal'Hakkar", objective = "Consigue 10 tablillas de Atal'ai para Brohann Barriliga, en Ventormenta." },
      [3373] = { name = "Esencia de Eranikus", objective = "Coloca la esencia de Eranikus en la fuente de esencia situada en su guarida del Templo Sumergido." },
      [3380] = { name = "El Templo Sumergido", objective = "Encuentra a Marvon Buscarroblones en Tanaris." },
      [3446] = { name = "En las profundidades", objective = "Encuentra el Altar de Hakkar en el Templo Sumergido, en el Pantano de las Penas." },
      [3447] = { name = "El secreto del círculo", objective = "Ve al Templo Sumergido y descubre el secreto oculto en el círculo de estatuas." },
      [3528] = { name = "El dios Hakkar", objective = "Llévale el Huevo relleno de Hakkar a Yeh'kinya, que está en Tanaris." },
      [4771] = { name = "Gambito del Alba", objective = "Coloca el Gambito del Alba en la Sala de la Visión de Scholomance. Derrota a Vectus y ve a ver a Betina Bigglezink." },
      [5341] = { name = "La fortuna de la familia Barov", objective = "Aventúrate a Scholomance y recupera la fortuna familiar de los Barov. La fortuna se compone de cuatro escrituras: Las escrituras de Castel Darrow, Las escrituras de Rémol, Las escrituras del Molino Tarren y Las escrituras de Costasur. Regresa con Alexi Barov cuando hayas terminado esta tarea." },
      [5343] = { name = "La fortuna de la familia Barov", objective = "Aventúrate a Scholomance y recupera la fortuna familiar de los Barov. La fortuna se compone de cuatro escrituras: Las escrituras de Castel Darrow, Las escrituras de Rémol, Las escrituras del Molino Tarren y Las escrituras de Costasur. Regresa con Weldon Barov cuando hayas terminado esta tarea." },
      [5382] = { name = "Doctor Theolen Krastinov, el Carnicero", objective = "Busca al doctor Theolen Krastinov en el interior de Scholomance. Acaba con él y quema los restos de Eva Sarkhoff y los restos de Lucien Sarkhoff. Cuando hayas terminado tu tarea regresa con Eva Sarkhoff." },
      [5384] = { name = "Kirtonos el Heraldo", objective = "Vuelve a Scholomance con la Sangre de los inocentes. Busca el Porche y coloca la Sangre de los inocentes en el blandón. Kirtonos acudirá a devorar tu alma. Lucha con valentía, ¡no cedas ni una pulgada! Destruye a Kirtonos y vuelve con Eva Sarkhoff." },
      [5466] = { name = "El Lich, Ras Levescarcha", objective = "Busca a Ras Levescarcha en Scholomance. Cuando lo hayas encontrado utiliza las Memorias del Vínculo del Alma sobre su rostro no-muerto. Si consiguieras convertirlo en mortal, derrótale y recupera la Cabeza humana de Ras Levescarcha. Lleva la cabeza al magistrado Marduke." },
      [5515] = { name = "Bolsa de los horrores de Krastinov", objective = "Localiza a Jandice Barov en Scholomance y destrúyela. En su cadáver encontrarás la Bolsa de los horrores de Krastinov. Devuélvele la bolsa a Eva Sarkhoff." },
      [5529] = { name = "Crías infestadas", objective = "Mata a 20 crías de dragón infectadas y ve a ver a Betina Bigglezink a la Capilla de la Esperanza de la Luz." },
      [7028] = { name = "Los males de Maraudón", objective = "Recoge 25 tallas de cristal terádrico y llévaselas a Willow a Desolace." },
      [7029] = { name = "La corrupción de Lenguavil", objective = "Llena el vial revestido en el estanque naranja de Maraudon. Aplica el líquido a la hiedra tallovil para que emerja el vástago tóxico. Cura 8 plantas eliminando su vástago tóxico e informa a Vark Marcaguerra en la Aldea Cazasombras." },
      [7041] = { name = "La corrupción de Lenguavil", objective = "Llena el vial revestido en el estanque naranja de Maraudon. Aplica el líquido a la hiedra tallovil para que emerja el vástago tóxico. Cura 8 plantas eliminando su vástago tóxico e informa a Talendria en Punta de Nijel." },
      [7044] = { name = "Leyendas de Maraudón", objective = "Recupera las 2 partes del Cetro de Celebras: la vara y el diamante Celebrian. Encuentra el modo de hablar con Celebras." },
      [7046] = { name = "El Cetro de Celebras", objective = "Ayuda a Celebras el Redimido mientras reconstruye el Cetro de Celebras. Habla con él después del ritual." },
      [7064] = { name = "Corrupción de la tierra y de la semilla", objective = "Mata a la princesa Theradras y ve a ver a Selendra cerca de la Aldea Cazasombras, en Desolace." },
      [7065] = { name = "Corrupción de la tierra y de la semilla", objective = "Mata a la princesa Theradras y ve a ver al guardián Marandis a Punta de Nijel, en Desolace." },
      [7066] = { name = "La semilla de la vida", objective = "Busca a Remulos en Claro de la Luna y dale la semilla de la vida." },
      [7067] = { name = "Las instrucciones del Paria", objective = "Lee las instrucciones del Paria. Busca el Amuleto de Unidad en Maraudon y llévaselo al sur de Desolace." },
      [7068] = { name = "Fragmentos Oscuros", objective = "Recoge 10 fragmentos oscuros en Maraudon y llévaselos a Uthel'nay a Orgrimmar." },
      [7070] = { name = "Fragmentos Oscuros", objective = "Recoge 10 fragmentos oscuros en Maraudon y llévaselos al archimago Tervosh a Theramore, en la costa de Marjal Revolcafango." },
    },
  },
  itIT = {
    dungeons = { "Tempio Sommerso", "Scholomance", "Maraudon", false, false, false },
  },
  ptBR = {
    dungeons = { "Templo Submerso", "Scolomântia", "Maraudon", "Pântano das Mágoas", "Terras Pestilentas Ocidentais", "Desolação" },
    bosses = { ["Darkmaster Gandling"] = "Umbromestre Gandling", ["Shade of Eranikus"] = "Vulto de Erânicos", ["Jammal'an the Prophet"] = "Jammal'an, o Profeta", ["Ogom the Wretched"] = "Ogom, o Patife", ["Morphaz"] = "Morphaz", ["Weaver"] = "Tecelão", ["Dreamscythe"] = "Darquimeros", ["Hazzas"] = "Hazzas", ["Avatar of Hakkar"] = "Avatar de Hakkar", ["Atal'alarion"] = "Atal'alarion", ["Vectus"] = "Vectus", ["Marduk Blackpool"] = "Marduque Lagonero", ["Lady Illucia Barov"] = "Lady Ilúcia Barov", ["Jandice Barov"] = "Janice Barov", ["Lord Alexei Barov"] = "Lorde Alexei Barov", ["Instructor Malicia"] = "Instrutora Malícia", ["Kirtonos the Herald"] = "Kirtonos, o Arauto", ["The Ravenian"] = "O Corvino", ["Ras Frostwhisper"] = "Ras Friomúrmuro", ["Lorekeeper Polkelt"] = "Erudito Pulquério", ["Doctor Theolen Krastinov"] = "Doutor Theolen Krastinov", ["Rattlegore"] = "Ossorrange", ["Princess Theradras"] = "Princesa Theradras", ["Landslide"] = "Soterrador", ["Celebras the Cursed"] = "Celebras, o Amaldiçoado", ["Lord Vyletongue"] = "Lorde Torpelíngua", ["Meshlok the Harvester"] = "Meshloc, o Ceifador", ["Razorlash"] = "Azorrague", ["Noxxion"] = "Tóxxico", ["Rotgrip"] = "Putrigarra", ["Tinkerer Gizlock"] = "Engenhoqueiro Bugitranca" },
    quests = {
      [1445] = { name = "O templo de Atal'Hakkar", objective = "Obtenha 20 Fetiches de Hakkar e leve-os para Vil'Zerul em Pedregal." },
      [1446] = { name = "Jammal'an, o Profeta", objective = "O Exilado Atal'ai nas Terras Agrestes quer a Cabeça de Jammal'an." },
      [1475] = { name = "No templo de Atal'Hakkar", objective = "Leve 10 Tabuletas Atal'ai para Brohann Barrilga em Ventobravo." },
      [3373] = { name = "A Essência de Erânicos", objective = "Coloque a Essência de Erânicos na Fonte de Essência encontrada neste covil do Templo Submerso." },
      [3380] = { name = "O Templo Submerso", objective = "Encontre Marlon Catarrebite em Tanaris." },
      [3446] = { name = "Nas profundezas", objective = "Encontre o Altar de Hakkar no Templo Submerso, que fica no Pântano das Mágoas." },
      [3447] = { name = "Segredo do círculo", objective = "Entre no Templo Submerso e descubra o segredo escondido no círculo de estátuas." },
      [3528] = { name = "O deus Hakkar", objective = "Leve o Ovo de Hakkar Cheio para Yeh'kinya, em Tanaris." },
      [4771] = { name = "Aposta da Aurora", objective = "Coloque a Aposta da Aurora na Sala de Exibição de Scolomântia. Derrote Vectus, depois fale novamente com Betina Bigozinco." },
      [5341] = { name = "A fortuna da família Barov", objective = "Desbrave Scolomântia e recupere a fortuna da família Barov. A fortuna é composta por quatro escrituras: A Escritura de Castro das Flechas, A Escritura de Montalvo, A Escritura da Serraria Tarren e A Escritura de Costa Sul. Fale novamente com Alexei Barov quando tiver terminado a tarefa." },
      [5343] = { name = "A fortuna da família Barov", objective = "Desbrave Scolomântia e recupere a fortuna da família Barov. A fortuna é composta por quatro escrituras: A Escritura de Castro das Flechas, a Escritura de Montalvo, a Escritura da Serraria Tarren e a Escritura de Costa Sul. Fale novamente com Weldon Barov quando tiver terminado a tarefa." },
      [5382] = { name = "Doutor Theolen Krastinov, o Carniceiro", objective = "Encontre o Doutor Theolen Krastinov em Scolomântia. Destrua-o, depois queime os Restos Mortais de Eva Sarkhoff e os Restos Mortais de Lucien Sarkhoff. Fale novamente com Eva Sarkhoff depois que tiver terminado a tarefa." },
      [5384] = { name = "Kirtonos, o Arauto", objective = "Volte a Scolomântia com o Sangue dos Inocentes em mãos. Encontre a varanda e derrame o Sangue dos Inocentes no braseiro. Kirtonos virá na intenção de devorar sua alma. Lute com bravura, não dê nenhuma brecha! Destrua Kirtonos e fale novamente com Eva Sarkhoff." },
      [5466] = { name = "Ras Friomúrmuro, o lich", objective = "Procure por Ras Friomúrmuro em Scolomântia. Quando o encontrar, use a Lembrança Vinculada em sua versão morto-vivo. Quando conseguir transformá-lo novamente em mortal, mate-o e recupere a Cabeça Humana de Ras Friomúrmuro. Leve a cabeça de volta ao Magistrado Marduque." },
      [5515] = { name = "Saco de Horrores de Krastinov", objective = "Localize Janice Barov em Scolomântia e a destrua. Recupere o Saco de Horrores de Krastinov do cadáver dela. Entregue o saco a Eva Sarkhoff." },
      [5529] = { name = "Filhotes Pestilentos", objective = "Mate 20 Filhotes Pestilentos, depois fale novamente com Betina Bigozinco, na Capela Esperança da Luz." },
      [7028] = { name = "Raízes do mal", objective = "Colete 25 Entalhes de Cristal Terádrico para Faia, na Desolação." },
      [7029] = { name = "A corrupção de Torpelíngua", objective = "Encha a Ampola Cerúlea Tampada na poça de cristal laranja, em Maraudon. Use a Ampola Cerúlea Cheia nos Cipós Caule Torpe para forçar os Rebentos Tóxxicos corrompidos a emergir. Cure 8 plantas ao matar os Rebentos Tóxxicos, depois fale novamente com Vark Chaga de Guerra, na Aldeia Pescassombra." },
      [7041] = { name = "A corrupção de Torpelíngua", objective = "Encha a Ampola Cerúlea Tampada na poça de cristal laranja, em Maraudon. Use a Ampola Cerúlea Cheia nos Cipós Caule Torpe para forçar os Rebentos Tóxxicos corrompidos a emergir. Cure 8 plantas ao matar os Rebentos Tóxxicos, depois fale novamente com Talendria, no Posto do Nijel." },
      [7044] = { name = "Lendas de Maraudon", objective = "Recupere as duas partes do Cetro de Celebras: o Bastão de Celebras e o Diamante de Celebras. Encontre um jeito de falar com Celebras." },
      [7046] = { name = "O Cetro de Celebras", objective = "Ajude Celebras, o Redimido, a criar o Cetro de Celebras. Fale com ele quando o ritual estiver concluído." },
      [7064] = { name = "Corrupção da terra e dos grãos", objective = "Mate a Princesa Theradras e fale novamente com Selendra perto da Aldeia Pescassombra, na Desolação." },
      [7065] = { name = "Corrupção da terra e dos grãos", objective = "Mate a Princesa Theradras e fale novamente com o Guardião Marandis no Posto do Nijel, na Desolação." },
      [7066] = { name = "A semente da vida", objective = "Procure Remulos, na Clareira da Lua, e entregue a ele a Semente da Vida." },
      [7067] = { name = "As instruções do pária", objective = "Leia as Instruções do Pária. Depois, obtenha em Maraudon o Amuleto da União e devolva-o ao Centauro Pária, na parte sul de Desolação." },
      [7068] = { name = "Fragmentos de lascanegra", objective = "Colete 10 Fragmentos de Lascanegra em Maraudon e leve-os para Uthel'nay, em Orgrimmar." },
      [7070] = { name = "Fragmentos de lascanegra", objective = "Colete 10 Fragmentos de Lascanegra em Maraudon e leve-os para o Arquimago Tervosh, em Theramore, na costa do Pântano Vadeoso." },
    },
  },
  ruRU = {
    dungeons = { "Затонувший храм", "Некроситет", "Мародон", "Болото Печали", "Западные Чумные земли", "Пустоши" },
    bosses = { ["Darkmaster Gandling"] = "Темный магистр Гандлинг", ["Shade of Eranikus"] = "Тень Эраникуса", ["Jammal'an the Prophet"] = "Джаммал'ан Пророк", ["Ogom the Wretched"] = "Огом Презренный", ["Morphaz"] = "Морфаз", ["Weaver"] = "Ткачик", ["Dreamscythe"] = "Жнец Снов", ["Hazzas"] = "Хаззас", ["Avatar of Hakkar"] = "Аватара Хаккара", ["Atal'alarion"] = "Атал'аларион", ["Vectus"] = "Вектус", ["Marduk Blackpool"] = "Мардук Блэкпул", ["Lady Illucia Barov"] = "Леди Иллюсия Баров", ["Jandice Barov"] = "Джандис Баров", ["Lord Alexei Barov"] = "Лорд Алексей Баров", ["Instructor Malicia"] = "Инструктор Коварница", ["Kirtonos the Herald"] = "Киртонос Глашатай", ["The Ravenian"] = "Равениан", ["Ras Frostwhisper"] = "Рас Снегошепот", ["Lorekeeper Polkelt"] = "Сказитель Полкелт", ["Doctor Theolen Krastinov"] = "Доктор Теолен Крастинов", ["Rattlegore"] = "Громоклин", ["Princess Theradras"] = "Принцесса Терадрас", ["Landslide"] = "Сель", ["Celebras the Cursed"] = "Селебрас Проклятый", ["Lord Vyletongue"] = "Лорд Злоязыкий", ["Meshlok the Harvester"] = "Мешлок Жнец", ["Razorlash"] = "Бритвохлест", ["Noxxion"] = "Ноксион", ["Rotgrip"] = "Гнилопасть", ["Tinkerer Gizlock"] = "Ремонтник Гизлок" },
    quests = {
      [1445] = { name = "Храм Атал'Хаккара", objective = "Соберите 20 фетишей Хаккара и принесите их Фел'зерулу в Каменор." },
      [1446] = { name = "Джаммал'ан Пророк", objective = "Принесите изгнаннику Атал'ай из Внутренних земель голову Джаммал'ана." },
      [1475] = { name = "В Храме Атал'Хаккара", objective = "Соберите 10 табличек Атал'ай для Брохана Бочкопуза из Штормграда." },
      [3373] = { name = "Сущность Эраникуса", objective = "Поместите сущность Эраникуса в купель сущности в его логове в затонувшем храме." },
      [3380] = { name = "Затонувший храм", objective = "Найдите Марвона Клепальщика в Танарисе." },
      [3446] = { name = "Во глубине болот", objective = "Найдите алтарь Хаккара в затонувшем храме на Болоте Печали." },
      [3447] = { name = "Тайна камня", objective = "Отправляйтесь в затонувший храм и узнайте, что скрывается в круге статуй." },
      [3528] = { name = "Бог Хаккар", objective = "Отнесите заполненное яйцо Хаккара Йе'кинье в Танарис." },
      [4771] = { name = "Рассветный гамбит", objective = "Отнесите \"Рассветный гамбит\" в Демонстрационную комнату в Некроситете. Уничтожьте Вектуса и возвращайтесь к Бетине Биггльцинк." },
      [5341] = { name = "Сокровище Баровых", objective = "Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Алексию Барову." },
      [5343] = { name = "Сокровище Баровых", objective = "Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Велдону Барову." },
      [5382] = { name = "Доктор Теолен Крастинов – Мясник", objective = "Найдите в Некроситете доктора Теолена Крастинова. Убейте его, затем сожгите останки Евы и Люсьена Саркофф. Выполнив задание, возвращайтесь к Еве Саркофф." },
      [5384] = { name = "Киртонос Глашатай", objective = "Вернитесь в Некроситет с кровью невинных. Найдите балкон и вылейте кровь в жаровню. На зов явится Киртонос. Сражайтесь как герой, не сдавайтесь! Уничтожьте Киртоноса и возвращайтесь к Еве Саркофф." },
      [5466] = { name = "Рас Снегошепот – лич", objective = "Отыщите в Некроситете Раса Снегошепота. Найдя его, воспользуйтесь Книгой Души против его посмертного облика. Если удастся превратить Раса в смертного, убейте его и заберите человеческую голову Раса Снегошепота. Отнесите голову мировому судье Мардуку." },
      [5515] = { name = "Мешок ужасов Крастинова", objective = "Найдите в Некроситете Джандис Баров и уничтожьте ее. Заберите мешок ужасов Крастинова. Отнесите мешок Еве Саркофф." },
      [5529] = { name = "Зачумленные детеныши дракона", objective = "Убейте 20 зачумленных детенышей дракона, затем возвращайтесь к Бетине Биггльцинк в Часовню Последней Надежды." },
      [7028] = { name = "Хрустальные орнаменты", objective = "Соберите 25 терадрических хрустальных орнаментов для Ивы из Пустошей." },
      [7029] = { name = "Порча Злоязыкого", objective = "Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона. Полейте гнусь-лозу из полного церуленового фиала, выгнав ядовитую лозу. Исцелите 8 растений, убивая ядовитые лозы, и вернитесь к Варку Боевому Шраму в Деревню Ночных Охотников." },
      [7041] = { name = "Порча Злоязыкого", objective = "Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона. Полейте гнусь-лозу из полного церуленового фиала, выгнав ядовитую лозу. Исцелите 8 растений, убивая ядовитые лозы, и вернитесь к Талендрии из Высоты Найджела." },
      [7044] = { name = "Легенды Мародона", objective = "Добудьте две части скипетра Келебраса – жезл Келебраса и бриллиант Келебраса. Найдите способ поговорить с Келебрасом." },
      [7046] = { name = "Скипетр Келебраса", objective = "Помогите Селебрасу Искупленному воссоздать скипетр Селебраса. По завершении ритуала снова обратитесь к нему." },
      [7064] = { name = "Яблочко от яблоньки...", objective = "Убейте принцессу Терадрас и вернитесь к Селендре неподалеку от Деревни Ночных Охотников в Пустошах." },
      [7065] = { name = "Яблочко от яблоньки...", objective = "Убейте принцессу Терадрас и вернитесь к хранителю Марандису на Высоту Найджела в Пустоши." },
      [7066] = { name = "Семя Жизни", objective = "Найдите в Лунной поляне Ремулоса и отдайте ему Семя Жизни." },
      [7067] = { name = "Инструкции кентавра-парии", objective = "Прочтите инструкции кентавра-парии, добудьте из Мародона амулет Соединения и верните его кентавру-парии из южной части Пустошей." },
      [7068] = { name = "Фрагменты осколка сумрака", objective = "Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их Утель'наю в Оргриммар." },
      [7070] = { name = "Фрагменты осколка сумрака", objective = "Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их верховному магу Тервошу в Терамор на побережье Пылевых топей." },
    },
  },
  koKR = {
    dungeons = { "가라앉은 사원", "스칼로맨스", "마라우돈", "슬픔의 늪", "서부 역병지대", "잊혀진 땅" },
    bosses = { ["Darkmaster Gandling"] = "암흑스승 간들링", ["Shade of Eranikus"] = "에라니쿠스의 사령", ["Jammal'an the Prophet"] = "예언자 잠말란", ["Ogom the Wretched"] = "비운의 오그옴", ["Morphaz"] = "몰파즈", ["Weaver"] = "위버", ["Dreamscythe"] = "드림사이드", ["Hazzas"] = "하자스", ["Avatar of Hakkar"] = "학카르의 화신", ["Atal'alarion"] = "아탈알라리온", ["Vectus"] = "벡투스", ["Marduk Blackpool"] = "마르두크 블랙풀", ["Lady Illucia Barov"] = "여군주 일루시아 바로브", ["Jandice Barov"] = "잔다이스 바로브", ["Lord Alexei Barov"] = "군주 알렉세이 바로브", ["Instructor Malicia"] = "조교 말리시아", ["Kirtonos the Herald"] = "사자 키르토노스", ["The Ravenian"] = "라베니안", ["Ras Frostwhisper"] = "라스 프로스트위스퍼", ["Lorekeeper Polkelt"] = "현자 폴켈트", ["Doctor Theolen Krastinov"] = "학자 테올렌 크라스티노브", ["Rattlegore"] = "들창어금니", ["Princess Theradras"] = "공주 테라드라스", ["Landslide"] = "산사태", ["Celebras the Cursed"] = "저주받은 셀레브라스", ["Lord Vyletongue"] = "군주 바일텅", ["Meshlok the Harvester"] = "정원사 메슬로크", ["Razorlash"] = "칼날채찍", ["Noxxion"] = "녹시온", ["Rotgrip"] = "썩은아귀", ["Tinkerer Gizlock"] = "땜장이 기즐록" },
    quests = {
      [1445] = { name = "아탈학카르 신전", objective = "스토나드에 있는 펠제룰에게 학카르의 우상 20개를 가져가야 합니다." },
      [1446] = { name = "예언자 잠말란", objective = "잠말란을 처치하고 그 증거로 그의 머리카락을 동부 내륙지에 있는 추방된 아탈라이트롤에게 가져가야 합니다." },
      [1475] = { name = "아탈학카르 신전으로", objective = "스톰윈드에 있는 브로한 캐스크벨리에게 아탈라이 서판 10개를 가져가야 합니다." },
      [3373] = { name = "에라니쿠스의 정수", objective = "가라앉은 사원의 이 안식처에 있는 정수의 샘에 에라니쿠스의 정수를 놓아야 합니다." },
      [3380] = { name = "가라앉은 사원", objective = "타나리스에서 마본 리벳시커를 찾아야 합니다." },
      [3446] = { name = "심연의 늪", objective = "슬픔의 늪에 있는 가라앉은 사원에서 학카르 제단을 찾아야 합니다." },
      [3447] = { name = "돌무리의 비밀", objective = "가라앉은 사원으로 가서 원 모양으로 서 있는 석상들에 감춰진 비밀을 알아내야 합니다." },
      [3528] = { name = "학카르의 화신", objective = "타나리스에 있는 예킨야에게 충만한 학카르의 알을 가져가야 합니다." },
      [4771] = { name = "여명의 계략", objective = "스칼로맨스의 스칼로맨스 강당 문에 여명의 계략을 놓아두고 벡투스를 처치한 후 베티나 비글징크에게 돌아가야 합니다." },
      [5341] = { name = "바로브 가의 유산", objective = "스칼로맨스로 가서 바로브 가의 유산을 회수해야 합니다. 이 재산은 카엘 다로우 증서, 브릴 증서, 타렌 밀농장 증서, 사우스쇼어 증서의 4개 땅문서로 이루어져 있습니다. 임무를 완수한 후 알렉시 바로브에게 돌아가야 합니다." },
      [5343] = { name = "바로브 가의 유산", objective = "스칼로맨스로 가서 바로브 가의 유산을 회수해야 합니다. 이 유산은 카엘 다로우 증서, 브릴 증서, 타렌 밀농장 증서, 사우스쇼어 증서의 4개 땅문서로 이루어져 있습니다. 이 임무를 완수한 후 웰던 바로브에게 돌아가야 합니다." },
      [5382] = { name = "도살자, 테올렌 크라스티노브", objective = "스칼로맨스 내에서 학자 테올렌 크라스티노브를 찾아 처치한 후 에바 사크호프의 유해와 루시엔 사크호프의 유해를 불태우십시오. 임무를 완수하면 에바 사크호프에게 돌아가야 합니다." },
      [5384] = { name = "사자 키르토노스", objective = "순결한 피를 가지고 스칼로맨스로 돌아가야 합니다. 사자의 창을 찾아 사자의 화롯불에 순결한 피를 올려 놓으면 키르토노스가 영혼을 차지하기 위해 나타납니다. 용맹하게 싸우고 단 한 발짝도 물러서지 마십시오! 키르토노스를 처치한 후 에바 사크호프에게 돌아가야 합니다." },
      [5466] = { name = "리치, 라스 프로스트위스퍼", objective = "스칼로맨스에서 라스 프로스트위스퍼를 찾아야 합니다. 영혼이 쓰인 유품을 언데드 상태인 라스의 얼굴에 사용하십시오. 그를 산 자로 되돌리는 데 성공하면 그를 쓰러뜨리고 사람이 된 라스 프로스트위스퍼의 머리카락을 가지고 집정관 마르듀크에게 가야 합니다." },
      [5515] = { name = "소름끼치는 크라스티노브의 가방", objective = "스칼로맨스에서 잔다이스 바로브를 찾아 처치해야 합니다. 그녀의 시체에서 소름끼치는 크라스티노브의 가방을 찾은 후 에바 사크호프에게 가져가야 합니다." },
      [5529] = { name = "역병 걸린 작은 새끼용", objective = "역병 걸린 작은 새끼용 20마리를 처치한 후 희망의 빛 예배당에 있는 베티나 비글징크에게 돌아가야 합니다." },
      [7028] = { name = "뒤틀린 악마", objective = "트라드릭 수정 조각상 25개를 모아서 잊혀진 땅에 있는 윌로우에게 가져가야 합니다." },
      [7029] = { name = "바일텅의 타락", objective = "마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다. 오염된 녹시온의 후예가 나타나게 하려면 바일줄기 덩굴나무 위에 감청색 약병에 담긴 액체를 부어야 합니다. 녹시온의 후예를 죽이는 방법으로 8개의 식물을 치료한 다음 그늘수렵 마을에 있는 바르크 배틀스카에게 돌아가야 합니다." },
      [7041] = { name = "바일텅의 타락", objective = "마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다. 오염된 녹시온의 후예가 나타나게 하려면 바일줄기 덩굴나무 위에 감청색 약병에 담긴 액체를 부어야 합니다. 녹시온의 후예를 죽이는 방법으로 8개의 식물을 치료한 다음 나이젤의 야영지에 있는 탈렌드리아에게 돌아가야 합니다." },
      [7044] = { name = "마라우돈의 전설", objective = "셀레브라스의 홀 조각인 셀레브리안 마법봉과 셀레브리안 다이아몬드를 찾아야 합니다. 셀레브라스와 대화를 나눌 방법을 찾아야 합니다." },
      [7046] = { name = "셀레브라스의 홀", objective = "회복된 셀레브라스가 셀레브라스의 홀을 만드는 동안 그를 도와야 합니다. 의식을 마친 후 그와 대화하십시오." },
      [7064] = { name = "대지와 씨앗의 오염", objective = "공주 테라드라스를 해치우고 잊혀진 땅의 그늘수렵 마을 근처에 있는 셀렌드라에게 돌아가야 합니다." },
      [7065] = { name = "대지와 씨앗의 오염", objective = "공주 테라드라스를 해치우고 잊혀진 땅의 나이젤의 야영지에 있는 수호자 마란디스를 찾아가야 합니다." },
      [7066] = { name = "생명의 씨앗", objective = "달의 숲에 있는 수호자 레물로스를 찾아 생명의 씨앗을 전해 주어야 합니다." },
      [7067] = { name = "추방자의 지시서", objective = "추방자의 지시서를 읽은 다음 마라우돈에서 결속의 아뮬렛을 획득해서 잊혀진 땅 남부에 있는 켄타우로스 추방자에게 가져가야 합니다." },
      [7068] = { name = "음영석 조각", objective = "마라우돈에서 음영석 조각 10개를 모아서 오그리마에 있는 우텔나이에게 가져가야 합니다." },
      [7070] = { name = "음영석 조각", objective = "마라우돈에서 음영석 조각 10개를 모아서 먼지진흙 습지대의 해안에 위치한 테라모어에 있는 대마법사 테르보쉬에게 가져가야 합니다." },
    },
  },
  zhCN = {
    dungeons = { "沉没的神庙", "通灵学院", "玛拉顿", "悲伤沼泽", "西瘟疫之地", "凄凉之地" },
    bosses = { ["Darkmaster Gandling"] = "黑暗院长加丁", ["Shade of Eranikus"] = "伊兰尼库斯的阴影", ["Jammal'an the Prophet"] = "预言者迦玛兰", ["Ogom the Wretched"] = "可悲的奥戈姆", ["Morphaz"] = "摩弗拉斯", ["Weaver"] = "德拉维沃尔", ["Dreamscythe"] = "德姆塞卡尔", ["Hazzas"] = "哈扎斯", ["Avatar of Hakkar"] = "哈卡的化身", ["Atal'alarion"] = "阿塔拉利恩", ["Vectus"] = "维克图斯", ["Marduk Blackpool"] = "马杜克·布莱克波尔", ["Lady Illucia Barov"] = "伊露希亚·巴罗夫", ["Jandice Barov"] = "詹迪斯·巴罗夫", ["Lord Alexei Barov"] = "阿雷克斯·巴罗夫", ["Instructor Malicia"] = "讲师玛丽希亚", ["Kirtonos the Herald"] = "传令官基尔图诺斯", ["The Ravenian"] = "拉文尼亚", ["Ras Frostwhisper"] = "莱斯·霜语", ["Lorekeeper Polkelt"] = "博学者普克尔特", ["Doctor Theolen Krastinov"] = "瑟尔林·卡斯迪诺夫教授", ["Rattlegore"] = "血骨傀儡", ["Princess Theradras"] = "瑟莱德丝公主", ["Landslide"] = "兰斯利德", ["Celebras the Cursed"] = "被诅咒的塞雷布拉斯", ["Lord Vyletongue"] = "维利塔恩", ["Meshlok the Harvester"] = "收割者麦什洛克", ["Razorlash"] = "锐刺鞭笞者", ["Noxxion"] = "诺克赛恩", ["Rotgrip"] = "洛特格里普", ["Tinkerer Gizlock"] = "工匠吉兹洛克" },
    quests = {
      [1445] = { name = "阿塔哈卡神庙", objective = "收集20个哈卡神像，把它们带给斯通纳德的费泽鲁尔。" },
      [1446] = { name = "预言者迦玛兰", objective = "辛特兰的阿塔莱流放者要你给他带回迦玛兰的头。" },
      [1475] = { name = "进入阿塔哈卡神庙", objective = "为暴风城的布罗哈恩·铁桶收集10块阿塔莱石板。" },
      [3373] = { name = "伊兰尼库斯精华", objective = "把伊兰尼库斯精华放在精华之泉里，精华之泉就在沉没的神庙中，伊兰尼库斯的巢穴里。" },
      [3380] = { name = "沉没的神庙", objective = "到塔纳利斯找到玛尔冯·瑞文斯克。" },
      [3446] = { name = "深入神庙", objective = "在悲伤沼泽沉没的神庙中找到哈卡祭坛。" },
      [3447] = { name = "雕像群的秘密", objective = "到沉没的神庙去，揭开雕像群中隐藏的秘密。" },
      [3528] = { name = "神灵哈卡", objective = "将装满的哈卡之卵交给塔纳利斯的叶基亚。" },
      [4771] = { name = "黎明先锋", objective = "将黎明先锋放在通灵学院的观察室里。打败维克图斯，然后回到贝蒂娜·比格辛克那里去。" },
      [5341] = { name = "巴罗夫家族的宝藏", objective = "到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到阿莱克斯·巴罗夫那儿去。" },
      [5343] = { name = "巴罗夫家族的宝藏", objective = "到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到维尔顿·巴罗夫那儿去。" },
      [5382] = { name = "瑟尔林·卡斯迪诺夫教授", objective = "在通灵学院中找到瑟尔林·卡斯迪诺夫教授。杀死他，并烧毁艾瓦·萨克霍夫和卢森·萨克霍夫的遗体。任务完成后就回到艾瓦·萨克霍夫那儿。" },
      [5384] = { name = "传令官基尔图诺斯", objective = "带着无辜者之血回到通灵学院，将它放在门廊的火盆下面，基尔图诺斯会前来吞噬你的灵魂。勇敢地战斗吧，不要退缩！杀死基尔图诺斯，然后回到艾瓦·萨克霍夫那儿。" },
      [5466] = { name = "巫妖莱斯·霜语", objective = "在通灵学院里找到莱斯·霜语。当你找到他之后，使用禁锢灵魂的遗物破除其亡灵的外壳。如果你成功地破除了他的不死之身，就杀掉他并拿到莱斯·霜语的头颅。把那个头颅交给马杜克镇长。" },
      [5515] = { name = "卡斯迪诺夫的恐惧之袋", objective = "在通灵学院找到詹迪斯·巴罗夫并打败她。从她的尸体上找到卡斯迪诺夫的恐惧之袋，然后将其交给艾瓦·萨克霍夫。" },
      [5529] = { name = "瘟疫之龙", objective = "杀掉20只瘟疫龙崽，然后向圣光之愿礼拜堂的贝蒂娜·比格辛克复命。" },
      [7028] = { name = "扭曲的邪恶", objective = "为凄凉之地的维洛收集25个瑟莱德丝水晶雕像。" },
      [7029] = { name = "维利塔恩的污染", objective = "在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。在维利斯塔姆藤蔓上使用装满水的天蓝水瓶，使堕落的诺克赛恩幼体出现。治疗8株植物并杀死那些诺克赛恩幼体，然后向葬影村的瓦克·战痕复命。" },
      [7041] = { name = "维利塔恩的污染", objective = "在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。在维利斯塔姆藤蔓上使用装满水的天蓝水瓶，使堕落的诺克赛恩幼体出现。治疗8株植物并杀死那些诺克赛恩幼体，然后向尼耶尔前哨站的塔琳德莉亚复命。" },
      [7044] = { name = "玛拉顿的传说", objective = "找回塞雷布拉斯节杖的两个部分：塞雷布拉斯魔棒和塞雷布拉斯钻石。然后设法和塞雷布拉斯对话。" },
      [7046] = { name = "塞雷布拉斯节杖", objective = "帮助赎罪的塞雷布拉斯制作塞雷布拉斯节杖。当仪式完成之后再和他谈谈。" },
      [7064] = { name = "大地的污染", objective = "杀死瑟莱德丝公主，然后回到凄凉之地葬影村附近的瑟琳德拉那里复命。" },
      [7065] = { name = "大地的污染", objective = "杀死瑟莱德丝公主，然后回到凄凉之地尼耶尔前哨站的守护者玛兰迪斯那里复命。" },
      [7066] = { name = "生命之种", objective = "到月光林地去找到雷姆洛斯，将生命之种交给他。" },
      [7067] = { name = "贱民的指引", objective = "阅读贱民的指引，然后从玛拉顿得到联合坠饰，将其交给凄凉之地南部的半人马贱民。" },
      [7068] = { name = "暗影残片", objective = "从玛拉顿收集10块暗影残片，然后把它们交给奥格瑞玛的尤塞尔奈。" },
      [7070] = { name = "暗影残片", objective = "从玛拉顿收集10块暗影残片，然后把它们交给尘泥沼泽塞拉摩岛上的大法师特沃什。" },
    },
  },
