      [5341] = { name = "巴羅夫家族的寶藏", objective = "到通靈學院中去取得巴羅夫家族的寶藏。這份寶藏包括四份地契：凱爾達隆地契、布瑞爾地契、塔倫米爾地契，還有南海鎮地契。完成任務之後就回到阿萊克斯·巴羅夫那兒去。" },
      [5343] = { name = "巴羅夫家族的寶藏", objective = "到通靈學院中去取得巴羅夫家族的寶藏。這份寶藏包括四份地契：凱爾達隆地契、布瑞爾地契、塔倫米爾地契，還有南海鎮地契。完成任務之後就回到維爾頓·巴羅夫那兒去。" },
      [5382] = { name = "瑟爾林·卡斯迪諾夫教授", objective = "在通靈學院中找到瑟爾林·卡斯迪諾夫教授。殺死他，並燒燬艾瓦·薩克霍夫和盧森·薩克霍夫的遺體。任務完成後就回到艾瓦·薩克霍夫那兒。" },
      [5384] = { name = "傳令官基爾圖諾斯", objective = "帶著無辜者之血回到通靈學院，將它放在門廊的火盆下面，基爾圖諾斯會前來吞噬你的靈魂。勇敢地戰鬥吧，不要退縮！殺死基爾圖諾斯，然後回到艾瓦·薩克霍夫那兒。" },
      [5466] = { name = "巫妖萊斯·霜語", objective = "在通靈學院裡找到萊斯·霜語。當你找到他之後，使用禁錮靈魂的遺物破除其亡靈的外殼。如果你成功地破除了他的不死之身，就殺掉他並拿到萊斯·霜語的頭顱。把那個頭顱交給馬杜克鎮長。" },
      [5515] = { name = "卡斯迪諾夫的恐懼之袋", objective = "在通靈學院找到詹迪斯·巴羅夫並打敗她。從她的屍體上找到卡斯迪諾夫的恐懼之袋，然後將其交給艾瓦·薩克霍夫。" },
