      [7028] = { name = "扭曲的邪惡", objective = "為淒涼之地的維洛收集25個瑟萊德絲水晶雕像。" },
      [7029] = { name = "維利塔恩的汙染", objective = "在瑪拉頓裡用天藍水瓶在橙色水晶池中裝滿水。在維利斯塔姆藤蔓上使用裝滿水的天藍水瓶，使墮落的諾克賽恩幼體出現。治療8株植物並殺死那些諾克賽恩幼體，然後向葬影村的瓦克·戰痕覆命。" },
      [7041] = { name = "維利塔恩的汙染", objective = "在瑪拉頓裡用天藍水瓶在橙色水晶池中裝滿水。在維利斯塔姆藤蔓上使用裝滿水的天藍水瓶，使墮落的諾克賽恩幼體出現。治療8株植物並殺死那些諾克賽恩幼體，然後向尼耶爾前哨站的塔琳德莉亞覆命。" },
      [7044] = { name = "瑪拉頓的傳說", objective = "找回塞雷布拉斯節杖的兩個部分：塞雷布拉斯魔棒和塞雷布拉斯鑽石。然後設法和塞雷布拉斯對話。" },
      [7046] = { name = "塞雷布拉斯節杖", objective = "幫助贖罪的塞雷布拉斯製作塞雷布拉斯節杖。當儀式完成之後再和他談談。" },
      [7064] = { name = "大地的汙染", objective = "殺死瑟萊德絲公主，然後回到淒涼之地葬影村附近的瑟琳德拉那裡覆命。" },
      [7065] = { name = "大地的汙染", objective = "殺死瑟萊德絲公主，然後回到淒涼之地尼耶爾前哨站的守護者瑪蘭迪斯那裡覆命。" },
      [7066] = { name = "生命之種", objective = "到月光林地去找到雷姆洛斯，將生命之種交給他。" },
