      [5212] = { name = "Das Fleisch lügt nicht", objective = "Sammelt 20 verseuchte Fleischproben in Stratholme und bringt sie zu Betina Bigglezink zurück. Ihr vermutet, dass Ihr besagte Fleischproben bei jeder Kreatur in Stratholme finden könnt." },
      [5213] = { name = "Der aktive Wirkstoff", objective = "Reist nach Stratholme und durchsucht die Ziggurats. Sucht neue Geißeldaten und bringt sie zu Betina Bigglezink zurück." },
      [5214] = { name = "Der große Fras Siabi", objective = "Sucht Fras Siabis Raucherladen in Stratholme und bergt einen Kasten von Siabis Tollem Tabak. Kehrt zu Smokey LaRue zurück, wenn Eure Aufgabe erledigt ist." },
      [5243] = { name = "Häuser der Heiligen", objective = "Begebt Euch nach Stratholme im Norden. Durchsucht die Vorratskisten, die über die Stadt verstreut sind, und holt 5 Einheiten Heiliges Wasser von Stratholme. Kehrt zu Leonid Barthalomew dem Geachteten zurück, wenn Ihr genug der gesegneten Flüssigkeit gesammelt habt." },
      [5251] = { name = "Der Archivar", objective = "Reist nach Stratholme und sucht Archivar Galford vom Scharlachroten Kreuzzug. Vernichtet ihn und verbrennt das Scharlachrote Archiv." },
      [5262] = { name = "Die Wahrheit zeigt sich mit Macht", objective = "Bringt den Kopf von Balnazzar zu Fürst Nicholas Zverenhoff in den Östlichen Pestländern." },
      [5263] = { name = "Übertroffen", objective = "Zieht nach Stratholme und vernichtet Baron Rivendare. Nehmt seinen Kopf und kehrt zu Fürst Nicholas Zverenhoff zurück." },
      [5282] = { name = "Die ruhelosen Seelen", objective = "Wendet Egans Blaster auf die geisterhaften und spektralen Bürger von Stratholme an. Wenn die ruhelosen Geister ihre geisterhaften Hüllen sprengen, wendet den Blaster erneut an - dann sind sie endlich frei! Befreit 15 ruhelose Seelen und kehrt zu Egan zurück." },
      [5518] = { name = "Der Ogeranzug der Gordok", objective = "Bringt 4 Runenstoffballen, 8 Stücke unverwüstliches Leder, 2 Runenfaden und etwas Ogergerbemittel zu Knot Thimblejack. Momentan ist er im Gordokflügel von Düsterbruch angekettet." },
      [5525] = { name = "Befreit Knot!" },
      [5848] = { name = "Von Liebe und Familie", objective = "Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind. Bringt das Gemälde zu Tirion Fordring." },
      [6163] = { name = "Ramstein", objective = "Reist nach Stratholme und tötet Ramstein den Würger. Bringt seinen Kopf als Souvenir zu Nathanos." },
      [7441] = { name = "Pusillin und der Älteste Azj'Tordin", objective = "Reist nach Düsterbruch und macht den Dämonen Pusillin ausfindig. Überzeugt ihn mit allen Mitteln davon, Euch Azj'Tordin's Buch der Zauberformeln zu geben. Kehrt mit dem Buch zu Az'Tordin, an Lariss' Pavillon in Feralas, zurück." },
      [7461] = { name = "Der innere Wahnsinn", objective = "Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen. Betretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Anschließend müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten. Kehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück." },
      [7462] = { name = "Der Schatz der Shen'dralar", objective = "Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!" },
      [7481] = { name = "Elfische Legenden", objective = "Sucht in Düsterbruch nach Kariel Winthalus. Meldet Euch anschließend bei Sage Korolusk in Camp Mojache." },
      [7482] = { name = "Elfische Legenden", objective = "Sucht in Düsterbruch nach Kariel Winthalus. Meldet Euch anschließend bei der Gelehrten Runethorn in Feathermoon." },
      [7488] = { name = "Lethtendris' Netz", objective = "Bringt Lethtendris' Netz zu Latronicus Moonspear in der Festung Feathermoon, in Feralas." },
      [7489] = { name = "Lethtendris' Netz", objective = "Bringt Lethtendris' Netz zu Talo Thornhoof im Camp Mojache in Feralas." },
      [7703] = { name = "Die offene Rechnung der Gordok", objective = "Findet die Stulpen der Gordokmacht und bringt sie zu Captain Kromcrush in Düsterbruch. Kromcrush zufolge sagen die \"Alte Zeit Geschichten\", dass Tortheldrin - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- sie einem der Gordokkönige gestohlen hat." },
      [8945] = { name = "Die letzte Bitte eines toten Mannes", objective = "Geht nach Stratholme und befreit Ysida Harmon aus den Fängen von Baron Rivendare." },
    },
  },
  frFR = {
    dungeons = { "Hache-tripes : Est", "Hache-tripes : Ouest", "Hache-tripes : Nord", "Stratholme : Vivants", "Stratholme : Morts-vivants", "Feralas", "Maleterres de l'Est" },
    bosses = { ["Skul"] = "Krân", ["Magistrate Barthilas"] = "Magistrat Barthilas", ["Baroness Anastari"] = "Baronne Anastari", ["Nerub'enkan"] = "Nerub'enkan", ["Maleki the Pallid"] = "Maleki le Blafard", ["Ramstein the Gorger"] = "Ramstein Grandgosier", ["Baron Rivendare"] = "Baron Rivendare", ["The Unforgiven"] = "Le Condamné", ["Hearthsinger Forresten"] = "Hearthsinger Forresten", ["Timmy the Cruel"] = "Timmy le Cruel", ["Stonespine"] = "Echine-de-pierre", ["Archivist Galford"] = "Archiviste Galford", ["Balnazzar"] = "Balnazzar", ["Cannon Master Willey"] = "Maître canonnier Willey", ["Postmaster Malown"] = "Postier Malown", ["Tsu'zee"] = "Tsu'zee", ["Prince Tortheldrin"] = "Prince Tortheldrin", ["Magister Kalendris"] = "Magistère Kalendris", ["Illyanna Ravenoak"] = "Illyanna Ravenoak", ["Tendris Warpwood"] = "Tendris Crochebois", ["Zevrim Thornhoof"] = "Zevrim Thornhoof", ["Alzzin the Wildshaper"] = "Alzzin le Modeleur", ["Immol'thar"] = "Immol'thar", ["King Gordok"] = "Roi Gordok", ["Hydrospawn"] = "Hydrogénos", ["Guard Fengus"] = "Garde Fengus", ["Stomper Kreeg"] = "Kreeg le Marteleur", ["Guard Slip'kik"] = "Garde Slip'kik", ["Cho'Rush the Observer"] = "Cho'Rush l'Observateur", ["Captain Kromcrush"] = "Capitaine Kromcrush", ["Guard Mol'dar"] = "Garde Mol'dar", ["Lethtendris"] = "Lethtendris", ["Lord Hel'nurath"] = "Seigneur Hel'nurath" },
    quests = {
      [5122] = { name = "Le médaillon de foi" },
      [5125] = { name = "L'estimation d'Aurius" },
      [5212] = { name = "La chair ne ment pas", objective = "Récupérer 20 Echantillons de chair pestiférée à Stratholme puis les rapporter à Betina Bigglezink. Vous pensez que toutes les créatures de Stratholme possèdent de tels échantillons de chair." },
      [5213] = { name = "L'agent actif", objective = "Se rendre jusqu’à Stratholme et fouiller les ziggourats. Trouver et ramener de nouvelles informations sur le Fléau à Betina Bigglezink." },
      [5214] = { name = "Le grand Fras Siabi", objective = "Trouver le magasin de tabac de Fras Siabi dans Stratholme et récupérer une boîte de Tabac de Siabi. Retourner auprès de Smokey LaRue quand le travail est fait." },
      [5243] = { name = "Les demeures du Sacré", objective = "Se rendre à Stratholme, au nord. Fouiller les caisses de fournitures qui encombrent la cité et récupérer 5 Eaux sacrées de Stratholme. Retourner auprès de Leonid Barthalomew le Révéré quand vous avez récolté assez de liquide béni." },
      [5251] = { name = "L'archiviste", objective = "Voyager jusqu’à Stratholme et trouver l’Archiviste Galford de la Croisade écarlate. L’abattre et brûler les Archives écarlates." },
      [5262] = { name = "La vérité vient du ciel", objective = "Apporter la Tête de Balnazzar au duc Nicholas Zverenhoff dans les Maleterres de l’est." },
      [5263] = { name = "Au-dessus et au-delà", objective = "S’aventurer dans Stratholme et tuer le baron Rivendare. Prendre sa tête et retourner auprès du duc Nicholas Zverenhoff." },
      [5282] = { name = "Âmes tourmentées", objective = "Se servir du Libérateur d'Egan sur les citoyens fantomatiques et spectraux de Stratholme. Quand les esprits sans repos se libèrent de leur enveloppes fantomatiques, utiliser de nouveau le Libérateur – ils seront enfin libres ! Libérer 15 Esprits sans repos puis retourner auprès d’Egan." },
      [5518] = { name = "La tenue d'ogre gordok", objective = "Apportez 4 Rouleaux d'étoffe runique, 8 Cuirs robustes, 2 Fils runiques et du Tanin ogre à Knot Thimblejack. Il est actuellement enchaîné dans l’aile Gordok de Hache-tripes." },
      [5525] = { name = "Libérez Knot !" },
      [5848] = { name = "De l'amour et de la famille", objective = "Se rendre à Stratholme, dans la partie nord des Maleterres. C’est dans le Bastion écarlate que se trouve le tableau De l'amour et de la famille, caché derrière une autre peinture représentant les lunes jumelles. Rapporter le tableau à Tirion Fordring." },
      [6163] = { name = "Ramstein", objective = "Aller à Stratholme et tuer Ramstein Grandgosier. Prendre sa tête, et l’apporter à Nathanos." },
      [7441] = { name = "Pusillin et l'Ancien Azj'Tordin", objective = "Rendez-vous à Hache-tripes et trouvez le diablotin Pusillin. Persuadez-le par tous les moyens de vous rendre le Livre d’Incantations d’Azj’Tordin. Si vous parvenez à le récupérer, retournez voir Azj’Tordin au Pavillon de Lariss, en Feralas." },
      [7461] = { name = "Folie intérieure", objective = "Vous devez détruire les gardiens qui protègent les 5 Pylônes qui alimentent la Prison d’Immol’thar. Une fois que les Pylônes seront coupés, le champ de force qui entoure Immol’thar se dissipera. Entrez dans la Prison d’Immol’thar et éradiquez l’infâme démon qui se trouve en son cœur. Enfin, affrontez le prince Tortheldrin à l’Athenaeum. Lorsque vous aurez terminé, retournez voir l’Ancienne des Shen’dralar dans la cour." },
      [7462] = { name = "Le trésor des Shen'dralar", objective = "Retournez à l’Athenaeum et trouvez le Trésor des Shen’dralar. Prenez votre récompense !" },
      [7481] = { name = "Légendes elfiques", objective = "Fouillez Hache-tripes à la recherche de Kariel Winthalus. Lorsque vous aurez des informations, donnez-les au Sage Korolusk de Camp Mojache." },
      [7482] = { name = "Légendes elfiques", objective = "Fouillez Hache-tripes à la recherche de Kariel Winthalus. Lorsque vous aurez des informations, donnez-les à l’Erudite Runethorn, à Feathermoon." },
      [7488] = { name = "Le filet de Lethtendris", objective = "Ramenez le Filet de Lethtendris à Latronicus Moonspear au bastion de Feathermoon en Feralas." },
      [7489] = { name = "Le filet de Lethtendris", objective = "Ramenez le Filet de Lethtendris à Talo Thornhoof au Camp Mojache, en Feralas." },
      [7703] = { name = "Affaires inachevées chez les Gordok", objective = "Trouvez le Gantelet de Puissance Gordok et rendez-le au capitaine Kromcrush à Hache-tripes. Selon Kromcrush, les histoires des « vieux » racontent que Tortheldrin – un « vilain » elfe qui se fait appeler prince – l’a volé à l’un des rois gordok." },
      [8945] = { name = "La supplique du mort", objective = "Entrez à Stratholme et sauvez Ysida Harmon du baron Rivendare." },
    },
  },
  esES = {
    dungeons = { "La Masacre: Este", "La Masacre: Oeste", "La Masacre: Norte", "Stratholme: Vivos", "Stratholme: No-muertos", "Feralas", "Tierras de la Peste del Este" },
    bosses = { ["Skul"] = "Skul", ["Magistrate Barthilas"] = "Magistrado Barthilas", ["Baroness Anastari"] = "Baronesa Anastari", ["Nerub'enkan"] = "Nerub'enkan", ["Maleki the Pallid"] = "Maleki el Pálido", ["Ramstein the Gorger"] = "Ramstein el Empachador", ["Baron Rivendare"] = "Barón Osahendido", ["The Unforgiven"] = "El imperdonable", ["Hearthsinger Forresten"] = "Escupezones Foreste", ["Timmy the Cruel"] = "Timmy el Cruel", ["Stonespine"] = "Pidrespina", ["Archivist Galford"] = "Archivista Galford", ["Balnazzar"] = "Balnazzar", ["Cannon Master Willey"] = "Maestro cañonero Willey", ["Postmaster Malown"] = "Jefe de correos Gassol", ["Tsu'zee"] = "Tsu'zee", ["Prince Tortheldrin"] = "Príncipe Tortheldrin", ["Magister Kalendris"] = "Magister Kalendris", ["Illyanna Ravenoak"] = "Illyanna Roblecuervo", ["Tendris Warpwood"] = "Tendris Madeguerra", ["Zevrim Thornhoof"] = "Zevrim Pezuñahendida", ["Alzzin the Wildshaper"] = "Alzzin el Formaferal", ["Immol'thar"] = "Immol'thar", ["King Gordok"] = "Rey Gordok", ["Hydrospawn"] = "Hidromilecio", ["Guard Fengus"] = "Guardia Fengus", ["Stomper Kreeg"] = "Vapuleador Kreeg", ["Guard Slip'kik"] = "Guardia Slip'kik", ["Cho'Rush the Observer"] = "Cho'Rush el Observador", ["Captain Kromcrush"] = "Capitán Kromcrush", ["Guard Mol'dar"] = "Guardia Mol'dar", ["Lethtendris"] = "Lethtendris", ["Lord Hel'nurath"] = "Lord Hel'nurath" },
    quests = {
      [5122] = { name = "El medallón de Fe" },
      [5125] = { name = "La estimación de Aurius" },
      [5212] = { name = "La carne no miente", objective = "Recoge 20 muestras de carne infestada de Stratholme y vuelve con Betina Bigglezink. Sospechas que podrías obtener una muestra de cualquier criatura de Stratholme." },
      [5213] = { name = "El agente activo", objective = "Viaja a Stratholme y busca los zigurats. Encuentra información sobre la Plaga y llévasela a Betina Bigglezink." },
      [5214] = { name = "El gran Fras Siabi", objective = "Encuentra la Tienda de humo de Fras Siabi en Stratholme y recupera una caja del tabaco de calidad de Siabi. Cuando lo hayas hecho, vuelve con Smokey LaRue." },
      [5243] = { name = "Las casas de lo sagrado", objective = "Viaja al norte, a Stratholme. Registra los cajones de provisiones que hay por toda la ciudad y recupera 5 de agua bendita de Stratholme. Vuelve junto a Leonid Barthalomew el Venerado cuando hayas reunido suficiente líquido bendecido." },
      [5251] = { name = "El archivista", objective = "Viaja a Stratholme y encuentra al archivista Galford de La Cruzada Escarlata. Acaba con él y quema el Archivo Escarlata." },
      [5262] = { name = "La verdad cae del cielo", objective = "Lleva la cabeza de Balnazzar al Duque Nicholas Zverenhoff en las Tierras de la Peste del Este." },
      [5263] = { name = "Por encima y más allá", objective = "Viaja a Stratholme y acaba con el barón Osahendido. Coge su cabeza y vuelve con el duque Nicolas Zverenhoff." },
      [5282] = { name = "Espíritus inquietos", objective = "Utiliza el libertador de Egan en los ciudadanos espectrales y fantasmas de Stratholme. Cuando las almas se liberen de sus recipientes fantasmales, vuelve a usarlo y lograrás liberarlos para siempre. Libera 15 almas y regresa a Egan." },
      [5518] = { name = "El traje de orgo Gordok", objective = "Lleva 4 madejas de paño rúnico, 8 retales de cuero basto, 2 hebras de hilo rúnico y tanino de ogro a Knot Llavededo. Actualmente está encadenado en el interior del ala Gordok de La Masacre." },
      [5525] = { name = "¡Libera a Knot!" },
      [5848] = { name = "De amor y familia", objective = "Viaja a Stratholme, en la zona norte de las Tierras de la Peste. En El Bastión Escarlata encontrarás el cuadro 'De amor y familia', oculto tras otra pintura que representa las lunas gemelas de nuestro mundo. Devuelve la pintura a Tirion Fordring." },
      [6163] = { name = "Ramstein", objective = "Viaja a Stratholme y mata a Ramstein el Empachador. Coge su cabeza y llévasela como souvenir a Nathanos." },
      [7441] = { name = "Pusillín y el ancestro Azj'Tordin", objective = "Viaja a La Masacre y encuentra al diablillo Pusillín. Convence a Pusillín de que te dé el libro de conjuros de Azj'Tordin, por cualquier medio. Si consigues hacerte con el libro de conjuros, vuelve al Pabellón Lariss de Feralas y busca a Azj'Tordin." },
      [7461] = { name = "Locura interior", objective = "Debes destruir a los guardianes que rodean las 5 torres que controlan la Prisión de Immol'thar. Una vez desactivadas las torres, el campo de fuerza que rodea a Immol'thar se disipará. Entra en la Prisión de Immol'thar y erradica al demonio que hace guardia en su interior. Por último, haz frente al príncipe Tortheldrin en El Athenaeum. Si consigues completar esta misión, ve al patio a buscar al Anciano Shen'dralar." },
      [7462] = { name = "El tesoro de los Shen'dralar", objective = "Regresa a El Athenaeum y encuentra el tesoro de Shen'dralar. ¡Reclama tu recompensa!" },
      [7481] = { name = "Leyendas élficas", objective = "Busca a Kariel Winthalus en La Masacre. Vuelve al Campamento Mojache e informa al Sabio Korolusk de cualquier cosa que encuentres." },
      [7482] = { name = "Leyendas élficas", objective = "Busca a Kariel Winthalus en La Masacre. Vuelve al Bastión Plumaluna a informar al erudito Runaespina de lo que hayas encontrado." },
      [7488] = { name = "La Membrana de Lethtendris", objective = "Lleva la Membrana de Lethtendris a Latronicus Lanzaluna al Bastión Plumaluna de Feralas." },
      [7489] = { name = "La Membrana de Lethtendris", objective = "Lleva la Membrana de Lethtendris a Talo Pezuñahendida al Campamento Mojache de Feralas." },
      [7703] = { name = "El aunto inacabado de Gordok", objective = "Encuentra el Guante del Poder de Gordok y llévaselo al capitán Kromcrush a La Masacre. Según Kromcrush, una \"historia muy, muy vieja\" dice que Tortheldrin, un elfo \"asqueroso\" que se llamaba a sí mismo príncipe, robó el guantelete a uno de los reyes de Gordok." },
      [8945] = { name = "La súplica de un muerto", objective = "Ve a Stratholme y rescata a Ysida Harmon del Barón Osahendido." },
    },
  },
  itIT = {
    dungeons = { "Dire Maul: Est", "Dire Maul: Ovest", "Dire Maul: Nord", "Stratholme: Vivi", "Stratholme: Non Morti", false, false },
  },
  ptBR = {
    dungeons = { "Gládio Cruel: Leste", "Gládio Cruel: Oeste", "Gládio Cruel: Norte", "Stratholme: Vivos", "Stratholme: Mortos-vivos", "Feralas", "Terras Pestilentas Orientais" },
    bosses = { ["Skul"] = "Kranio", ["Magistrate Barthilas"] = "Magistrado Barthilas", ["Baroness Anastari"] = "Baronesa Anastari", ["Nerub'enkan"] = "Nerub'enkan", ["Maleki the Pallid"] = "Malaki, o Pálido", ["Ramstein the Gorger"] = "Ramstein, o Devorador", ["Baron Rivendare"] = "Barão Rivendare", ["The Unforgiven"] = "O Imperdoável", ["Hearthsinger Forresten"] = "Cantalar Forresten", ["Timmy the Cruel"] = "Tico, o Cruel", ["Stonespine"] = "Petrespáduas", ["Archivist Galford"] = "Arquivista Galford", ["Balnazzar"] = "Balnazzar", ["Cannon Master Willey"] = "Mestre de Canhões Gualter", ["Postmaster Malown"] = "Chefe do Correio Malown", ["Tsu'zee"] = "Tsu'zee", ["Prince Tortheldrin"] = "Príncipe Tortheldrin", ["Magister Kalendris"] = "Magíster Kalendris", ["Illyanna Ravenoak"] = "Illyanna Corvalho", ["Tendris Warpwood"] = "Gavíneo Lenhatorta", ["Zevrim Thornhoof"] = "Zevrim Cascardo", ["Alzzin the Wildshaper"] = "Azzin, o Selvamorfo", ["Immol'thar"] = "Immol'thar", ["King Gordok"] = "Rei Gordok", ["Hydrospawn"] = "Rebentágua", ["Guard Fengus"] = "Guarda Fengus", ["Stomper Kreeg"] = "Pisoteador Kreeg", ["Guard Slip'kik"] = "Guarda Kishutt", ["Cho'Rush the Observer"] = "Ez'Magg, o Observador", ["Captain Kromcrush"] = "Capitão Kebrapaw", ["Guard Mol'dar"] = "Guarda Mol'dar", ["Lethtendris"] = "Letendris", ["Lord Hel'nurath"] = "Lorde Hel'nurath" },
    quests = {
      [5122] = { name = "O Medalhão da Fé" },
      [5125] = { name = "O ajuste de contas de Aurius" },
      [5212] = { name = "A carne não mente", objective = "Recupere 20 Amostras de Carne Infectada de Stratholme e leve-as para Betina Bigozinco. Você desconfia que qualquer criatura em Stratholme poderia ter essa amostra de carne." },
      [5213] = { name = "O agente ativo", objective = "Vá para Stratholme e vasculhe os zigurates. Encontre novos Dados do Flagelo e leve-os para Betina Bigozinco." },
      [5214] = { name = "A tentação de Fras Siabi", objective = "Encontre a tabacaria de Fras Siabi em Stratholme e recolha uma caixa do Tabaco da Lata do Fras Siabi. Fale novamente com Leandro Leonardo depois que tiver terminado o serviço." },
      [5243] = { name = "Casas do sagrado", objective = "Viaje para Stratholme, ao norte. Procure os caixotes de suprimentos que cobrem a cidade e recupere 5 Águas Bentas de Stratholme. Fale novamente com Leonid Bartolomeu, o Venerado, quando coletar fluido abençoado suficiente." },
      [5251] = { name = "O arquivista", objective = "Viaje até Stratholme e encontre o Arquivista Galford da Cruzada Escarlate. Destrua-o e queime o Arquivo Escarlate." },
      [5262] = { name = "A verdade desaba sobre todos", objective = "Leve a Cabeça do Balnazzar para o Duque Nicolau Zverenhoff nas Terras Pestilentas Orientais." },
      [5263] = { name = "Acima e além", objective = "Desbrave Stratholme e destrua o Barão Rivendare. Corte sua cabeça e leve-a de volta para o Duque Nicolau Zverenhoff." },
      [5282] = { name = "As almas inquietas", objective = "Use o Canhão de Ectoplasma do Egan nos moradores fantasmagóricos e espectrais de Stratholme. Depois de livrá-los da forma de fantasma, use o canhão de novo e BLAU: liberdade! Liberte 15 Almas Inquietas, depois fale novamente com Egan." },
      [5518] = { name = "O traje de ogro Gordok", objective = "Leve 4 Peças de Runatrama, 8 Couros Rústicos, 2 Fios Rúnicos e Tanino Ôgrico para Fiapo Agulhacerta. Atualmente, ele está acorrentado dentro da ala Gordok do Gládio Cruel." },
      [5525] = { name = "Liberdade ainda que tardia" },
      [5848] = { name = "Do amor e da família", objective = "Viaje para Stratholme, na parte norte das Terras Pestilentas. No Bastião Escarlate, você encontrará a pintura \"Do Amor e da Família\", escondida atrás de outro quadro que retrata as luas gêmeas do nosso mundo. Leve a pintura de volta para Tirion Fordring." },
      [6163] = { name = "Ramstein", objective = "Vá a Stratholme e mate Ramstein, o Devorador. Leve a cabeça dele como souvenir para Nathanos." },
      [7441] = { name = "Pusillin e o Ancião Azj'Tordin", objective = "Vá ao Gládio Cruel e encontre o Diabrete Pusillin. Convença-o usando qualquer meio que for necessário a lhe dar o Livro de Encantamentos de Azj'Tordin. Fale novamente com Azj'Tordin no Pavilhão Lariss, em Feralas, caso você recupere o Livro de Encantamentos." },
      [7461] = { name = "A loucura intrínseca", objective = "Mate os guardiões que cercam os cinco pilares de força da Prisão de Immol'thar. Quando os pilares se desligarem, o campo de força que cerca Immol'thar se dissipará. Destrua o terrível demônio que fica no coração da Prisão de Immol'thar. Por fim, enfrente o Príncipe Tortheldrin, no Ateneu. Fale novamente com a Anciã Shen'dralar, no pátio, após cumprir a missão." },
      [7462] = { name = "O tesouro de Shen'dralar", objective = "Volte ao Ateneu e encontre o Tesouro dos Shen'dralar. Reclame sua recompensa!" },
      [7481] = { name = "Lendas élficas", objective = "Procure Kariel Winthalus em Gládio Cruel. Reporte-se, então, ao Sábio Korolusk na Aldeia Mojache com qualquer informação que você possa encontrar." },
      [7482] = { name = "Lendas élficas", objective = "Procure Kariel Winthalus em Gládio Cruel. Reporte-se, então, à Erudita Runacardos em Plumaluna com qualquer informação que você encontrar." },
      [7488] = { name = "A teia de Letendris", objective = "Leve a Teia de Letendris para Latrônicus Lunalança no Domínio de Plumaluna, em Feralas." },
      [7489] = { name = "A teia de Letendris", objective = "Leve a Teia de Letendris para Talo Casco de Espinhos na Aldeia Mojache, em Feralas." },
      [7703] = { name = "Negócios pendentes", objective = "Encontre as Manoplas do Poder de Gordok e devolva-as para o Capitão Kebrapaw no Gládio Cruel. De acordo com Kebrapaw, a \"história de ancião\" diz que Tortheldrin — um elfo \"medonho\" que se diz príncipe — roubou as manoplas de um dos reis Gordok." },
      [8945] = { name = "Súplica de um morto", objective = "Entre em Stratholme e resgate Ysida Harmon do Barão Rivendare." },
    },
  },
  ruRU = {
    dungeons = { "Забытый Город: Восток", "Забытый Город: Запад", "Забытый Город: Север", "Стратхольм: Живые", "Стратхольм: Нежить", "Фералас", "Восточные Чумные земли" },
