    quests = {
      [5122] = { name = "Медальон Веры" },
      [5125] = { name = "Слова Аурия" },
      [5212] = { name = "Плоть не лжет", objective = "Принесите 20 препаратов чумной плоти из Стратхольма Бетине Биггльцинк. Предположительно, любая тварь из Стратхольма сойдет за препарат." },
      [5213] = { name = "Вирус чумы", objective = "Отправляйтесь в Стратхольм и исследуйте зиккураты. Доставьте сведения о Плети Бетине Биггльцинк." },
      [5214] = { name = "Великий Фрас Сиаби", objective = "Найдите табачную лавку Фраса Сиаби в Стратхольме, отыщите в ней пачку лучшего табака Сиаби и принесите ее Дымку ЛаРу." },
      [5243] = { name = "Святая вода", objective = "Отправляйтесь на север, в Стратхольм. Обыщите брошенные ящики с припасами и соберите 5 мер святой воды Стратхольма. Возвращайтесь к Леониду Бартоломею Чтимому, как только воды будет достаточно." },
      [5251] = { name = "Архивариус", objective = "Отправляйтесь в Стратхольм и отыщите архивариуса Галфорда из Алого ордена. Убейте его и сожгите архив Алых." },
      [5262] = { name = "Ошеломляющая истина", objective = "Отнесите голову Бальназара герцогу Николасу Зверенхоффу в Восточные Чумные земли." },
      [5263] = { name = "Быстрее, выше, сильнее", objective = "Отправляйтесь в Стратхольм и убейте барона Ривендера. Принесите его голову герцогу Николасу Зверенхоффу." },
      [5282] = { name = "Мятущиеся души", objective = "Стреляйте в призраков и неупокоенных на улицах Стратхольма из излучателя Эгана. Когда душа вырвется из призрачной оболочки, выстрелите в нее еще раз, и она обретет свободу. Освободите 15 неупокоенных душ и возвращайтесь к Эгану." },
      [5518] = { name = "Броня огров Гордока", objective = "Принесите 4 рулона рунной ткани, 8 кусков прочной кожи, 2 мотка рунной нити и огрскую дубильную кислоту Уззлу Наперстяку. Он прикован в секторе Гордока в Забытом Городе." },
      [5525] = { name = "Освободите Нотта!" },
      [5848] = { name = "Символ семейной любви", objective = "Отправляйтесь в Статхольм в северную часть Чумных земель. Найдите в Бастионе Алого ордена картину \"Символ семейной любви\", спрятанную за другой, изображающей две луны нашего мира. Отнесите картину Тириону Фордрингу." },
      [6163] = { name = "Рамштейн", objective = "Отправляйтесь в Стратхольм и убейте Рамштайна Ненасытного. Принесите его голову Натаносу в качестве сувенира." },
      [7441] = { name = "Пузиллин и старейший Аж'Тордин", objective = "Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж'Тордина. Если добудете книгу, вернитесь к Аж'Тордину в павильон Лорисс в Фераласе." },
      [7461] = { name = "Древнее безумие", objective = "Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер'тера, рассеется. Войдите в Тюрьму Бессмер'тера и уничтожьте злого демона, который находится внутри. И, наконец, сразитесь с принцем Тортелдрином в Читальне. Если задание будет выполнено успешно, вернитесь во двор, к прародительнице Шен'дралар." },
      [7462] = { name = "Сокровище Шен'дралар", objective = "Вернитесь в Читальню и найдите сокровище Шен'дралар. Получите свою награду!" },
      [7481] = { name = "Эльфийские легенды", objective = "Попытайтесь найти в Забытом Городе Кариэля Винтхалуса. Вернитесь в Лагерь Мохаче к ведуну Королуску и сообщите ему все, что вам удалось узнать." },
      [7482] = { name = "Эльфийские легенды", objective = "Попытайтесь найти в Забытом Городе Кариэля Винтхалуса. Вернитесь в крепость Оперенной Луны к школяру Рунному Шипу и сообщите ей все, что вам удалось узнать." },
      [7488] = { name = "Сеть Лефтендрис", objective = "Принесите сеть Лефтендрис Латроникусу Лунному Копью в Крепость Оперенной Луны в Фераласе." },
      [7489] = { name = "Сеть Лефтендрис", objective = "Принесите сеть Лефтендрис Тало Терновому Копыту в Лагере Мохаче в Фераласе." },
      [7703] = { name = "Неоконченное дело Гордоков", objective = "Добудьте латную рукавицу Мощи Гордока и вернитесь с ней к капитану Давигрому в Забытом Городе. По словам Давигрома, в \"старых байках\" говорится, что Тортелдрин – \"страшный эльф\", называющий себя принцем, – похитил эту рукавицу у одного из королей Гордоков." },
      [8945] = { name = "Просьба мертвеца", objective = "Отправляйтесь в Стратхольм и спасите Исиду Хармон от Барона Ривендера." },
    },
  },
  koKR = {
    dungeons = { "혈투의 전장: 동쪽", "혈투의 전장: 서쪽", "혈투의 전장: 북쪽", "스트라솔름: 정문", "스트라솔름: 언데드", "페랄라스", "동부 역병지대" },
    bosses = { ["Skul"] = "스컬", ["Magistrate Barthilas"] = "집정관 발실라스", ["Baroness Anastari"] = "남작부인 아나스타리", ["Nerub'enkan"] = "네룹엔칸", ["Maleki the Pallid"] = "냉혈한 말레키", ["Ramstein the Gorger"] = "먹보 람스타인", ["Baron Rivendare"] = "남작 리븐데어", ["The Unforgiven"] = "용서받지 못한 자", ["Hearthsinger Forresten"] = "하스싱어 포레스턴", ["Timmy the Cruel"] = "잔혹한 티미", ["Stonespine"] = "뾰족바위", ["Archivist Galford"] = "기록관 갈포드", ["Balnazzar"] = "발나자르", ["Cannon Master Willey"] = "포병대장 윌리", ["Postmaster Malown"] = "우체국장 말로운", ["Tsu'zee"] = "츄지", ["Prince Tortheldrin"] = "왕자 토르텔드린", ["Magister Kalendris"] = "마술사 칼렌드리스", ["Illyanna Ravenoak"] = "일샨나 레이븐오크", ["Tendris Warpwood"] = "굽이나무 텐드리스", ["Zevrim Thornhoof"] = "제브림 쏜후프", ["Alzzin the Wildshaper"] = "칼날바람 알진", ["Immol'thar"] = "이몰타르", ["King Gordok"] = "왕 고르독", ["Hydrospawn"] = "히드로스폰", ["Guard Fengus"] = "경비병 펜구스", ["Stomper Kreeg"] = "천둥발 크리그", ["Guard Slip'kik"] = "경비병 슬립킥", ["Cho'Rush the Observer"] = "정찰병 초루쉬", ["Captain Kromcrush"] = "대장 크롬크러쉬", ["Guard Mol'dar"] = "경비병 몰다르", ["Lethtendris"] = "레스텐드리스", ["Lord Hel'nurath"] = "군주 헬누라스" },
    quests = {
      [5122] = { name = "신념의 메달" },
      [5125] = { name = "아우리우스의 복수" },
      [5212] = { name = "거짓말하지 않는 육체", objective = "스트라솔름에서 20개의 역병걸린 살덩어리 견본을 베티나 비글징크에게 가져다주어야 합니다. 스트라솔름의 어떤 생물에서든 살덩어리 견본을 구할 수 있을 것 같습니다." },
      [5213] = { name = "활성 역병 인자", objective = "스트라솔름으로 가서 지구라트를 조사해야 합니다. 스컬지 자료를 찾아 베티나 비글징크에게 돌아가야 합니다." },
      [5214] = { name = "위대한 프라스 샤비", objective = "스트라솔름에서 샤비의 최고급 담배를 회수하여 스모키 라루에게 가져가야 합니다." },
      [5243] = { name = "성스러운 집", objective = "북쪽에 있는 스트라솔름으로 가서 도시 어딘가에 흩어진 보급품 상자를 찾아 스트라솔름 성수 5병을 가져와야 합니다. 성수를 충분히 모으고 나면 존경받는 리어니드 바돌로매에게 돌아가야 합니다." },
      [5251] = { name = "기록관", objective = "스트라솔름으로 가서 붉은십자군의 기록관, 갈포드를 찾아서 그를 처치하고 붉은십자군 기록을 불태워 버려야 합니다." },
      [5262] = { name = "밝혀지는 진실", objective = "동부 역병지대에 있는 공작 니콜라스 즈바른호프에게 발나자르의 혼을 가져가야 합니다." },
      [5263] = { name = "뛰어난 존재", objective = "스트라솔름으로 가서 남작 리븐데어를 처치하고 그의 혼을 공작 니콜라스 즈바른호프에게 가져가야 합니다." },
      [5282] = { name = "잠 못드는 영혼", objective = "스트라솔름 시민의 영혼과 원혼들에게 에간의 제령포를 사용해야 합니다. 원혼들이 그들을 가두고 있던 감옥에서 풀려나면 다시 총을 사용하여 그들에게 자유를 선사하십시오! 15명의 잠 못드는 영혼을 자유롭게 하고 에간에게 돌아가야 합니다." },
      [5518] = { name = "고르독 오우거 위장복", objective = "룬무늬 두루마리 4개, 튼튼한 가죽 8장, 룬문자 실타래 2개, 그리고 오우거 타닌을 노트 팀블잭에게 가져가야 합니다. 노트 팀블잭은 혈투의 전장에 있는 고르독일족 은신처 구석에 족쇄에 묶여 있습니다." },
      [5525] = { name = "노트 구출 대작전" },
      [5848] = { name = "가족과 사랑", objective = "역병지대의 북쪽, 스트라솔름에 있는 붉은십자군 성채로 가서 쌍둥이 달 그림을 찾으십시오. 그 뒤에 숨겨진 '가족과 사랑'이라는 그림을 찾아 티리온 폴드링에게 가져가야 합니다." },
      [6163] = { name = "람스타인", objective = "스트라솔름으로 가서 먹보 람스타인을 처치하고 그 증거로 그의 머리카락을 나타노스에게 가져가야 합니다." },
      [7441] = { name = "푸실린과 노쇠한 아즈토르딘", objective = "혈투의 전장으로 가서 푸실린이라는 임프를 찾으십시오. 어떤 수단을 써서라도 아즈토리딘의 마법서를 돌려받아야 합니다. 마법서를 회수하면 페랄라스의 라리스 정자에 있는 아즈토리딘에게 돌아가야 합니다." },
      [7461] = { name = "내면의 광기", objective = "이몰타르의 감옥에 힘을 공급하는 다섯 개의 수정탑을 둘러싼 수호자들을 처치해야 합니다. 수정탑의 마력이 약해지면 이몰타르를 둘러싼 마법진도 분산될 것입니다. 이몰타르의 감옥에 들어가 그 심장부에 서 있는 사악한 이몰타르를 처치하고, 마지막으로 도서관에 있는 토르텔드린 왕자와 맞서 싸우십시오. 이 임무를 완수하면 안마당에 있는 셴드랄라 고대인에게 돌아가야 합니다." },
      [7462] = { name = "셴드랄라의 보물", objective = "도서관으로 되돌아가 셴드랄라의 보물을 찾아야 합니다. 임무 완수에 대한 보상을 받으십시오!" },
      [7481] = { name = "엘프의 전설", objective = "혈투의 전장을 뒤져 카리엘 윈탈루스를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 모자케 야영지에 있는 현자 코로루스크에게 돌아가야 합니다." },
      [7482] = { name = "엘프의 전설", objective = "혈투의 전장을 뒤져 카리엘 윈탈루스를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 페더문 요새에 있는 학자 룬쏜에게 돌아가야 합니다." },
      [7488] = { name = "레스텐드리스의 그물", objective = "페랄라스의 페더문 요새에 있는 라트로니쿠스 문스피어에게 레스텐드리스의 그물을 가져가야 합니다." },
      [7489] = { name = "레스텐드리스의 그물", objective = "페랄라스의 모자케 야영지에 있는 탈로 쏜후프에게 레스텐드리스의 그물을 가져가야 합니다." },
      [7703] = { name = "고르독 일 마무리", objective = "권력의 고르독 건틀릿을 찾아 혈투의 전장에 있는 대장 크롬크러쉬에게 가져가야 합니다. 크롬크러쉬의 \"옛날 얘기\"에 따르면 자칭 왕자라는 토르텔드린이라는 이름의 \"기분 나쁜\" 엘프가 고르독 왕에게서 빼앗아갔다고 합니다." },
      [8945] = { name = "죽은 자의 부탁", objective = "스트라솔름으로 가서 남작 리븐데어로부터 이시다 하몬을 구해야 합니다." },
    },
  },
  zhCN = {
    dungeons = { "厄运之槌：东", "厄运之槌：西", "厄运之槌：北", "斯坦索姆：血色区", "斯坦索姆：亡灵区", "菲拉斯", "东瘟疫之地" },
    bosses = { ["Skul"] = "斯库尔", ["Magistrate Barthilas"] = "巴瑟拉斯镇长", ["Baroness Anastari"] = "安娜丝塔丽男爵夫人", ["Nerub'enkan"] = "奈鲁布恩坎", ["Maleki the Pallid"] = "苍白的玛勒基", ["Ramstein the Gorger"] = "吞咽者拉姆斯登", ["Baron Rivendare"] = "瑞文戴尔男爵", ["The Unforgiven"] = "不可宽恕者", ["Hearthsinger Forresten"] = "弗雷斯特恩", ["Timmy the Cruel"] = "悲惨的提米", ["Stonespine"] = "石脊", ["Archivist Galford"] = "档案管理员加尔福特", ["Balnazzar"] = "巴纳扎尔", ["Cannon Master Willey"] = "炮手威利", ["Postmaster Malown"] = "邮差马龙", ["Tsu'zee"] = "苏斯", ["Prince Tortheldrin"] = "托塞德林王子", ["Magister Kalendris"] = "卡雷迪斯镇长", ["Illyanna Ravenoak"] = "伊琳娜·暗木", ["Tendris Warpwood"] = "特迪斯·扭木", ["Zevrim Thornhoof"] = "瑟雷姆·刺蹄", ["Alzzin the Wildshaper"] = "奥兹恩", ["Immol'thar"] = "伊莫塔尔", ["King Gordok"] = "戈多克大王", ["Hydrospawn"] = "海多斯博恩", ["Guard Fengus"] = "卫兵芬古斯", ["Stomper Kreeg"] = "践踏者克雷格", ["Guard Slip'kik"] = "卫兵斯里基克", ["Cho'Rush the Observer"] = "观察者克鲁什", ["Captain Kromcrush"] = "克罗卡斯", ["Guard Mol'dar"] = "卫兵摩尔达", ["Lethtendris"] = "蕾瑟塔蒂丝", ["Lord Hel'nurath"] = "赫尔努拉斯" },
    quests = {
      [5122] = { name = "信仰奖章" },
      [5125] = { name = "奥里克斯的清算" },
      [5212] = { name = "血肉不会撒谎", objective = "从斯坦索姆找回20个瘟疫肉块，并把它们交给贝蒂娜·比格辛克。你觉得斯坦索姆中的生灵都不大可能长着肉……" },
      [5213] = { name = "活跃的探子", objective = "到斯坦索姆去探索那里的通灵塔。找到新的天灾军团档案，把它交给贝蒂娜·比格辛克。" },
      [5214] = { name = "弗拉斯·希亚比", objective = "找到弗拉斯·希亚比在斯坦索姆的烟草店，并从中找回一盒希亚比的烟草，把它交给烟鬼拉鲁恩。" },
      [5243] = { name = "神圣之屋", objective = "到北方的斯坦索姆去，寻找散落在城市中的补给箱，并收集5瓶斯坦索姆圣水。当你找到足够的圣水之后就回去向莱尼德·巴萨罗梅复命。" },
      [5251] = { name = "档案管理员", objective = "在斯坦索姆城中找到血色十字军的档案管理员加尔福特，杀掉他，然后烧毁血色十字军档案。" },
      [5262] = { name = "可怕的真相", objective = "将巴纳扎尔的头颅交给东瘟疫之地的尼古拉斯·瑟伦霍夫公爵。" },
      [5263] = { name = "超越", objective = "到斯坦索姆去杀掉瑞文戴尔男爵，把他的头颅交给尼古拉斯·瑟伦霍夫公爵。" },
      [5282] = { name = "永不安息的灵魂", objective = "对斯坦索姆城中的鬼魂使用埃根的冲击器。当那些永不安息的灵魂挣脱他们的外壳时，再次使用埃根的冲击器——他们就可以获得自由了！解放15个永不安息的灵魂，然后回到埃根那里去。" },
      [5518] = { name = "戈多克食人魔装", objective = "把4份符文布卷、8块硬甲皮、2卷符文线和一份食人魔鞣酸交给诺特·希姆加克。他现在被拴在厄运之槌的戈多克食人魔那边。" },
      [5525] = { name = "逃出生天！" },
      [5848] = { name = "爱与家庭", objective = "到瘟疫之地北部的斯坦索姆去。你可以在血色十字军堡垒中找到“爱与家庭”这幅画，它被隐藏在另一幅描绘两个月亮的画之后。把这幅画还给提里奥·弗丁。" },
      [6163] = { name = "吞咽者拉姆斯登", objective = "到斯坦索姆去，杀掉吞咽者拉姆斯登。把他的头颅交给纳萨诺斯。" },
      [7441] = { name = "普希林和埃斯托尔迪", objective = "到厄运之槌去找到小鬼普希林。你可以使用任何手段从小鬼那里得到埃斯托尔迪的咒术之书。找到咒术之书后，回到拉瑞斯小亭的埃斯托尔迪那里。" },
      [7461] = { name = "伊莫塔尔的疯狂", objective = "你必须干掉5座水晶塔周围的守卫，那5座水晶塔维持着关押伊莫塔尔的监狱。一旦水晶塔的能量被削弱，伊莫塔尔周围的能量力场就会消散。进入伊莫塔尔的监狱，干掉站在中间的那个恶魔。最后，在图书馆挑战托塞德林王子。当任务完成之后，到庭院中去找辛德拉古灵。" },
      [7462] = { name = "辛德拉的宝藏", objective = "返回图书馆去找到辛德拉的宝藏。拿取你的奖励吧！" },
      [7481] = { name = "精灵的传说", objective = "到厄运之槌去寻找卡里尔·温萨鲁斯。向莫沙彻营地的先知科鲁拉克报告你所找到的信息。" },
      [7482] = { name = "精灵的传说", objective = "到厄运之槌去寻找卡里尔·温萨鲁斯。向羽月要塞的学者卢索恩·纹角报告你所找到的信息。" },
      [7488] = { name = "蕾瑟塔蒂丝的网", objective = "把蕾瑟塔蒂丝的网交给菲拉斯羽月要塞的拉托尼库斯·月矛。" },
      [7489] = { name = "蕾瑟塔蒂丝的网", objective = "把蕾瑟塔蒂丝的网交给非拉斯莫沙彻营地的塔罗·刺蹄。" },
      [7703] = { name = "戈多克食人魔的事务", objective = "找到戈多克力量护手，并将它交给厄运之槌的克罗卡斯。根据克罗卡斯所说的，“传说”自称是王子的精灵托塞德林从一名戈多克食人魔手中偷走了那件神器。" },
      [8945] = { name = "死人的请求", objective = "进入斯坦索姆，从瑞文戴尔男爵手中救出伊思达。" },
    },
  },
