      [6163] = { name = "吞嚥者拉姆斯登", objective = "到斯坦索姆去，殺掉吞嚥者拉姆斯登。把他的頭顱交給納薩諾斯。" },
      [7441] = { name = "普希林和埃斯托爾迪", objective = "到厄運之槌去找到小鬼普希林。你可以使用任何手段從小鬼那裡得到埃斯托爾迪的咒術之書。找到咒術之書後，回到拉瑞斯小亭的埃斯托爾迪那裡。" },
      [7461] = { name = "伊莫塔爾的瘋狂", objective = "你必須幹掉5座水晶塔周圍的守衛，那5座水晶塔維持著關押伊莫塔爾的監獄。一旦水晶塔的能量被削弱，伊莫塔爾周圍的能量力場就會消散。進入伊莫塔爾的監獄，幹掉站在中間的那個惡魔。最後，在圖書館挑戰託塞德林王子。當任務完成之後，到庭院中去找辛德拉古靈。" },
      [7462] = { name = "辛德拉的寶藏", objective = "返回圖書館去找到辛德拉的寶藏。拿取你的獎勵吧！" },
      [7481] = { name = "精靈的傳說", objective = "到厄運之槌去尋找卡里爾·溫薩魯斯。向莫沙徹營地的先知科魯拉克報告你所找到的資訊。" },
      [7482] = { name = "精靈的傳說", objective = "到厄運之槌去尋找卡里爾·溫薩魯斯。向羽月要塞的學者盧索恩·紋角報告你所找到的資訊。" },
      [7488] = { name = "蕾瑟塔蒂絲的網", objective = "把蕾瑟塔蒂絲的網交給菲拉斯羽月要塞的拉託尼庫斯·月矛。" },
      [7489] = { name = "蕾瑟塔蒂絲的網", objective = "把蕾瑟塔蒂絲的網交給非拉斯莫沙徹營地的塔羅·刺蹄。" },
      [7703] = { name = "戈多克食人魔的事務", objective = "找到戈多克力量護手，並將它交給厄運之槌的克羅卡斯。根據克羅卡斯所說的，“傳說”自稱是王子的精靈託塞德林從一名戈多克食人魔手中偷走了那件神器。" },
