      [4004] = { name = "La Princesse sauvée ?", objective = "Retourner voir Thrall !" },
      [4024] = { name = "Un goût de flammes", objective = "Partir pour les Profondeurs de Blackrock et tuer Bael'Gar. Vous savez seulement que le géant demeure à l'intérieur des Profondeurs de Blackrock. Se souvenir d'utiliser l'Ecaille des dragons noirs altérée pour capturer l'Essence ardente. Apporter l'Essence ardente recouverte à Cyrus Therepentous." },
      [4063] = { name = "La révolte des machines", objective = "Trouver et tuer le seigneur des golems Argelmach. Rapporter sa tête à Lotwil. Collecter également 10 Noyaux d'élémentaire intacts sur les Golems ravarage et les Assemblages porteguerre qui protègent Argelmach. Vous savez cela car vous êtes médium." },
      [4081] = { name = "TUER A VUE : nains Sombrefer", objective = "Pénétrer dans les Profondeurs de Blackrock et tuer les vils agresseurs ! Le chef de guerre Goretooth veut que vous tuiez 15 Gardes Ragenclumes, 10 Gardiens Ragenclumes et 5 Fantassins Ragenclumes. Retourner le voir une fois votre mission accomplie." },
      [4082] = { name = "TUER A VUE : Officiers de haut rang Sombrefer", objective = "Pénétrer dans les Profondeurs de Blackrock et tuer les vils agresseurs ! Le Chef de guerre Goretooth veut que vous tuiez 10 Médecins Ragenclumes, 10 Soldats Ragenclumes et 10 Officiers Ragenclumes. Retourner le voir une fois votre mission accomplie." },
      [4083] = { name = "Le Calice spectral" },
      [4123] = { name = "Le Coeur de la montagne", objective = "Apporter le Cœur de la montagne à Maxwort Uberglint dans les Steppes ardentes." },
      [4126] = { name = "Hurley Blackbreath", objective = "Apporter la Recette perdue de la Thunderbrew à Ragnar Thunderbrew à Kharanos." },
      [4132] = { name = "Opération : Mort à Forgehargne", objective = "Voyagez jusqu'aux Profondeurs de Blackrock et tuez le général Forgehargne ! Une fois votre mission accomplie, retournez voir le seigneur de guerre Goretooth." },
      [4134] = { name = "La recette perdue de Thunderbrew", objective = "Apporter la Recette perdue de la Thunderbrew à Vivian Lagrave à Kargath." },
      [4136] = { name = "Ribbly Screwspigot", objective = "Apporter la Tête de Ribbly à Yuka Screwspigot dans les Steppes ardentes." },
      [4201] = { name = "Le philtre d'amour", objective = "Apporter 4 Gromsang, 10 Veines d'argent de géant et la Fiole de Nagmara remplie à la gouvernante Nagmara dans les Profondeurs de Blackrock." },
      [4241] = { name = "Maréchal Windsor", objective = "Partir pour le mont Blackrock au nord-ouest et pénétrer dans les Profondeurs de Blackrock. Découvrir ce qu'il est advenu du Maréchal Windsor. Vous vous souvenez que John le Loqueteux a dit que Windsor avait été traîné en prison." },
      [4263] = { name = "Incendius !", objective = "Trouver le Seigneur Incendius dans les Profondeurs de Blackrock et le détruire !" },
      [4282] = { name = "Un espoir en lambeaux", objective = "Rapporter les Renseignements perdus du maréchal Windsor. Le maréchal Windsor pense qu'ils sont détenus par le seigneur golem Argelmach et par le général Forgehargne." },
      [4322] = { name = "Evasion !", objective = "Aider le maréchal Windsor à récupérer son équipement et à libérer ses amis. Ensuite, retourner voir le maréchal Maxwell." },
      [4362] = { name = "Le destin du Royaume", objective = "Retourner dans les Profondeurs de Blackrock et secourir la Princesse Moira Bronzebeard, prisonnière de l'Empereur Dagran Thaurissan." },
      [4363] = { name = "La surprise de la Princesse", objective = "Retourner à Ironforge et parler au roi Magni Bronzebeard." },
    },
  },
  esES = {
    dungeon = "Profundidades de Roca Negra", location = "Montaña Roca Negra",
    bosses = { ["High Interrogator Gerstahn"] = "Alto Interrogador Gerstahn", ["Lord Roccor"] = "Lord Roccor", ["Houndmaster Grebmar"] = "Domador de jaurías Grebmar", ["Gorosh the Dervish"] = "Gorosh el Endemoniado", ["Grizzle"] = "Grisez", ["Eviscerator"] = "Eviscerador", ["Ok'thor the Breaker"] = "Ok'thor el Rompedor", ["Anub'shiah"] = "Anub'shiah", ["Hedrum the Creeper"] = "Hedrum el Trepador", ["Pyromancer Loregrain"] = "Piromántico Cultugrano", ["Fineous Darkvire"] = "Finoso Virunegro", ["Warder Stilgiss"] = "Guarda Stilgiss", ["Lord Incendius"] = "Lord Incendius", ["Bael'Gar"] = "Bael'Gar", ["General Angerforge"] = "General Forjira", ["Golem Lord Argelmach"] = "Señor Gólem Argelmach", ["Hurley Blackbreath"] = "Hurley Negrálito", ["Phalanx"] = "Falange", ["Ribbly Screwspigot"] = "Ribbly Llavenrosca", ["Plugger Spazzring"] = "Plugger Aropatoso", ["Ambassador Flamelash"] = "Embajador Latifuego", ["Panzor the Invincible"] = "Panzor el Invencible", ["The Seven"] = "Los Siete", ["Magmus"] = "Magmus", ["Princess Moira Bronzebeard"] = "Princesa Moira Barbabronce", ["Emperor Dagran Thaurissan"] = "Emperador Dagran Thaurissan" },
    quests = {
      [3802] = { name = "El legado de los Hierro Negro", objective = "Mata a Finoso Virunegro y recupera el gran martillo, Ferrovil. Lleva a Ferrovil al Santuario de Thaurissan y coloca el martillo en la estatua de Franclorn Forjafina." },
      [3907] = { name = "La discordia de las llamas", objective = "Adéntrate en las Profundidades de Roca Negra y localiza a Lord Incendius. Mátalo y llévale toda la información que encuentres a Truenozón." },
      [3981] = { name = "Comandante Gor'shak", objective = "Encuentra al comandante Gor'shak en las Profundidades de Roca Negra. Recuerdas que en el dibujo burdo había rejas sobre el rostro del orco. Quizás deberías buscar una cárcel o algo similar." },
      [3982] = { name = "¿Qué pasa?", objective = "Defiende a Gor'shak." },
      [4003] = { name = "El rescate real", objective = "Mata al emperador Dagran Thaurissan para liberar a la princesa Barbabronce del hechizo." },
      [4004] = { name = "¿Princesa salvada?", objective = "¡Vuelve junto a Thrall!" },
      [4024] = { name = "Un sabor a llamarada", objective = "Viaja hasta las Profundidades de Roca Negra y mata a Bael'Gar. Solo sabes que el gigante vive en las Profundidades de Roca Negra. Acuérdate de usar la escama alterada de Vuelo Negro sobre los restos de Bael'Gar para capturar la esencia fiera. Llévale la esencia fiera recubierta a Cyrus Therepentio." },
      [4063] = { name = "La revuelta de las máquinas", objective = "Encuentra al Señor Gólem Argelmach y mátalo. Llévale su cabeza a Lotwil. Asimismo tendrás que reunir 10 núcleos de elemental intactos de los golems Furiatracadores y de los constructos belisario que protegen a Argelmach. Lo sabes porque eres un adivino." },
      [4081] = { name = "MATAR INMEDIATAMENTE: enanos Hierro Negro", objective = "Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores! El señor de la guerra Dientegore quiere que mates a 15 custodios de Yunque Colérico, 10 alcaides de Yunque Colérico y 5 lacayos de Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea." },
      [4082] = { name = "MATAR INMEDIATAMENTE: oficiales Hierro Negro de alto rango", objective = "Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores! El señor de la guerra Dientegore quiere que mates a 10 médicos de Yunque Colérico, 10 soldados de Yunque Colérico y 10 oficiales de Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea." },
      [4083] = { name = "El cáliz espectral" },
      [4123] = { name = "El Corazón de la Montaña", objective = "Llévale el Corazón de la Montaña a Maxwort Suprandor en Las Estepas Ardientes." },
      [4126] = { name = "Hurley Negrálito", objective = "Llévale la receta perdida de Cebatruenos a Ragnar Cebatruenos en Kharanos." },
      [4132] = { name = "Operación: muerte a Forjafuria", objective = "Viaja hasta las Profundidades de Roca Negra ¡y mata al general Forjira! Vuelve junto al señor de la guerra Dientegore cuando hayas acabado la tarea." },
      [4134] = { name = "La receta perdida de Cebatruenos", objective = "Llévale la receta perdida de Cebatruenos a Vivian Latumba en Kargath." },
      [4136] = { name = "Ribbly Llavenrosca", objective = "Llévale la cabeza de Ribbly a Yuka Llavenrosca en Las Estepas Ardientes." },
      [4201] = { name = "La poción de enamoramiento", objective = "Llévale 4 gromsanguinas, 10 venas de plata gigantescas y el vial lleno de Nagmara a la maestra Nagmara en las Profundidades de Roca Negra." },
      [4241] = { name = "El alguacil Windsor", objective = "Viaja a la Montaña Roca Negra al noroeste y adéntrate en las Profundidades de Roca Negra. Averigua qué le ha ocurrido al alguacil Windsor. Recuerdas que John Andrajoso había comentado que se habían llevado a una cárcel a Windsor." },
      [4263] = { name = "¡Incendius!", objective = "Encuentra a Lord Incendius en las Profundidades de Roca Negra ¡y acaba con él!" },
      [4282] = { name = "Una esperanza hecha trizas", objective = "Devuélvele al alguacil Windsor la información perdida. El alguacil Windsor cree que la información está siendo retenida en manos del Señor Gólem Argelmach y del general Forjira." },
      [4322] = { name = "La fuga de la prisión", objective = "Ayuda al alguacil Windsor a recuperar su equipo y a liberar a sus amigos. Vuelve junto al alguacil Maxwell si lo consigues." },
      [4362] = { name = "El destino del reino", objective = "Vuelve a las Profundidades de Roca Negra y rescata a la princesa Moira Barbabronce de las garras del emperador Dragan Thaurissan." },
      [4363] = { name = "La sorpresa de la princesa", objective = "Regresa a Forjaz y habla con el rey Magni Barbabronce." },
    },
  },
  itIT = {
    dungeon = "Profondità di Roccianera", location = false,
    bosses = { ["The Seven"] = "I Sette" },
  },
  ptBR = {
    dungeon = "Abismo Rocha Negra", location = "Montanha Rocha Negra",
    bosses = { ["High Interrogator Gerstahn"] = "Suprema Interrogadora Gerstahn", ["Lord Roccor"] = "Lorde Pétror", ["Houndmaster Grebmar"] = "Mestre de Matilha Grebmar", ["Gorosh the Dervish"] = "Gorosh, o Dervixe", ["Grizzle"] = "Resmungo", ["Eviscerator"] = "Eviscerador", ["Ok'thor the Breaker"] = "Ok'thor, o Quebrador", ["Anub'shiah"] = "Anub'shiah", ["Hedrum the Creeper"] = "Hedrum, o Rastejante", ["Pyromancer Loregrain"] = "Piromante Sábia Semente", ["Fineous Darkvire"] = "Fineous Forçanegra", ["Warder Stilgiss"] = "Carcereiro Stilgiss", ["Lord Incendius"] = "Lorde Incendius", ["Bael'Gar"] = "Bael'gar", ["General Angerforge"] = "General Forjaversa", ["Golem Lord Argelmach"] = "Lorde Golem Argelmach", ["Hurley Blackbreath"] = "Hurley Bafonegro", ["Phalanx"] = "Falange", ["Ribbly Screwspigot"] = "Ribas Parafuseta", ["Plugger Spazzring"] = "Birra Guardachave", ["Ambassador Flamelash"] = "Embaixador Fogaçoite", ["Panzor the Invincible"] = "Panzor, o Invencível", ["The Seven"] = "Os Sete", ["Magmus"] = "Magmus", ["Princess Moira Bronzebeard"] = "Princesa Moira Barbabronze", ["Emperor Dagran Thaurissan"] = "Imperador Dagran Thaurissan" },
    quests = {
      [3802] = { name = "Legado dos Ferro Negro", objective = "Mate Fineous Forçanegra e recupere o grande martelo Ferrovil. Leve-o para o Santuário de Thaurissan e coloque-o na estátua de Franclorn Forjífice." },
      [3907] = { name = "Desarmonia do fogo", objective = "Entre no Abismo Rocha Negra e encontre o Lorde Incendius. Mate-o e leve todas as informações que puder para o Coração Trovejante." },
      [3981] = { name = "Comandante Gor'shak", objective = "Encontre o Comandante Gor'shak no Abismo Rocha Negra. Você se lembra que o tosco desenho incluía barras rabiscadas sobre o orc. Talvez você devesse procurar algum tipo de prisão." },
      [3982] = { name = "O que está acontecendo?", objective = "Defenda Gor'shak." },
      [4003] = { name = "O resgate real", objective = "Mate o Imperador Dagran Thaurissan e liberte a Princesa Moira Barbabronze do feitiço maligno." },
      [4004] = { name = "A princesa foi resgatada?", objective = "Fale novamente com Thrall!" },
      [4024] = { name = "O gosto das chamas", objective = "Vá para o Abismo Rocha Negra e mate Bael'gar. A única coisa que você sabe é que o gigante mora no Abismo Rocha Negra. Lembre-se de usar a Muda de Pele Alterada da Revoada Negra nos restos mortais de Bael'gar para capturar a Essência Abrasadora. Leve a Essência Abrasadora Aprisionada para Ciro Terepento." },
      [4063] = { name = "O levante das máquinas", objective = "Encontre e mate Lorde Golem Argelmach. Leve a cabeça dele para Lotwil. Você também precisará coletar 10 Núcleos de Elemental Intactos dos Golens Rasgafúria e Constructos Armipotentes que protegem Argelmach. Você sabe disso porque é paranormal." },
      [4081] = { name = "SE VIR, MATE: Anões Ferro Negro", objective = "Desbrave o Abismo Rocha Negra e destrua aqueles invasores degenerados! O Senhor da Guerra Trincador quer que você mate 15 Guardas Furiadastra, 10 Carcereiros Furiadastra e 5 Soldados Rasos Furiadastra. Fale novamente com ele quando o trabalho estiver terminado." },
      [4082] = { name = "SE VIR, MATE: Oficiais Ferro Negro de Alta Patente", objective = "Vá até o Abismo Rocha Negra e destrua aqueles invasores degenerados! O Senhor da Guerra Trincador quer que você mate 10 Socorristas Furiadastra, 10 Soldados Furiadastra e 10 Oficiais Furiadastra. Fale novamente com ele quando o trabalho for concluído." },
      [4083] = { name = "Cálice Espectral" },
      [4123] = { name = "O Coração da Montanha", objective = "Leve o Coração da Montanha para Maxwort Uberraio nas Estepes Ardentes." },
      [4126] = { name = "Hurley Bafonegro", objective = "Leve a Receita Perdida de Cervaforte para Ragnar Cervaforte em Kharanos." },
      [4132] = { name = "Operação: Morte ao Forjaversa", objective = "Viaje para o Abismo Rocha Negra e mate o General Forjaversa! Fale novamente com o Senhor da Guerra Trincador quando a tarefa estiver concluída." },
      [4134] = { name = "Receita Perdida de Cervaforte", objective = "Leve a Receita Perdida de Cervaforte para Vivian Latumba em Karrath." },
      [4136] = { name = "Ribas Parafuseta", objective = "Leve a Cabeça do Ribas para Yuka Parafuseta nas Estepes Ardentes." },
      [4201] = { name = "A poção do amor", objective = "Leve 4 Sangues-de-grom, 10 Veios de Prata Gigantes e a Ampola da Nagmara Cheia para a Lady Nagmara no Abismo Rocha Negra." },
      [4241] = { name = "Marechal Vilasboas", objective = "Viaje para a Montanha Rocha Negra, a noroeste, e entre no Abismo Rocha Negra. Descubra o que aconteceu com o Marechal Vilasboas. Você se lembra de João Roto falando sobre Vilasboas ter sido arrastado para uma prisão." },
      [4263] = { name = "Incendius!", objective = "Encontre Lorde Incendius no Abismo Rocha Negra e destrua-o!" },
      [4282] = { name = "Um fiapo de esperança", objective = "Recupere as Informações Perdidas do Marechal Vilasboas. O Marechal Vilasboas acredita que as informações estão sendo mantidas pelo Lorde Golem Argelmach e pelo General Forjaversa." },
      [4322] = { name = "Fuga da prisão!", objective = "Ajude o Marechal Vilasboas a recuperar seu equipamento e libertar seus amigos. Se conseguir, fale novamente com o Oficial Maxwell." },
      [4362] = { name = "O destino do reino", objective = "Volte ao Abismo Rocha Negra e resgate a Princesa Moira Barbabronze das garras malignas do Imperador Dagran Thaurissan." },
      [4363] = { name = "A surpresa da Princesa", objective = "Volte a Altaforja e fale com o Rei Magni Barbabronze." },
    },
  },
  ruRU = {
    dungeon = "Глубины Черной горы", location = "Черная гора",
    bosses = { ["High Interrogator Gerstahn"] = "Верховный дознаватель Герштан", ["Lord Roccor"] = "Лорд Роккор", ["Houndmaster Grebmar"] = "Псарь Гребмар", ["Gorosh the Dervish"] = "Горош Дервиш", ["Grizzle"] = "Гриззл", ["Eviscerator"] = "Потрошитель", ["Ok'thor the Breaker"] = "Ок'тор Разрушитель", ["Anub'shiah"] = "Ануб'шиа", ["Hedrum the Creeper"] = "Хедрум Ползун", ["Pyromancer Loregrain"] = "Пироман Зерно Мудрости", ["Fineous Darkvire"] = "Точень Темнострой", ["Warder Stilgiss"] = "Тюремщик Стилгисс", ["Lord Incendius"] = "Лорд Опалитель", ["Bael'Gar"] = "Бейл'Гор", ["General Angerforge"] = "Генерал Кузня Гнева", ["Golem Lord Argelmach"] = "Повелитель големов Аргелмах", ["Hurley Blackbreath"] = "Харли Пьянодых", ["Phalanx"] = "Фаланкс", ["Ribbly Screwspigot"] = "Риббли Крутипроб", ["Plugger Spazzring"] = "Штоппор Наливалс", ["Ambassador Flamelash"] = "Посол Огнехлыст", ["Panzor the Invincible"] = "Панцер Непобедимый", ["The Seven"] = "Семеро", ["Magmus"] = "Магмус", ["Princess Moira Bronzebeard"] = "Принцесса Мойра Бронзобород", ["Emperor Dagran Thaurissan"] = "Император Дагран Тауриссан" },
    quests = {
      [3802] = { name = "Наследие Черного Железа", objective = "Убейте Точеня Темностроя и добудьте великий молот, Железный Друг. Отнесите Железного Друга в святилище Тауриссана и вложите его в руки статуи Франклорна Искусника." },
      [3907] = { name = "Дисгармония пламени", objective = "Ступайте в глубины Черной горы и выследите лорда Опалителя. Убейте его и принесите Громосерду все, что может дать какую-то информацию." },
      [3981] = { name = "Командир Гор'шак", objective = "Найдите командира Гор'шака в Глубинах Черной горы. Судя по рисунку в записке, искать следует в темнице где-то вроде того." },
      [3982] = { name = "Что происходит?", objective = "Защитите Горшака." },
      [4003] = { name = "Спасение принцессы", objective = "Убейте императора Даграна Тауриссана и освободите принцессу Мойру Бронзобород от его черного заклятия." },
      [4004] = { name = "Спасенная принцесса", objective = "Вернитесь к Траллу." },
      [4024] = { name = "Вкус пламени", objective = "Отправьтесь в глубины Черной горы и убейте Бейл'Гора. Известно лишь то, что великан живет в глубинах. Воспользуйтесь измененной сброшенной шкурой черного дракона и возьмите из останков Бейл'Гора сущность Огня. Отнесите пойманную сущность Огня Цирусу Раскаивателю." },
      [4063] = { name = "Восстание машин", objective = "Найдите и убейте повелителя големов Аргелмаха. Принесите его голову Лотвилу. Также соберите 10 невредимых ядер стихий с беспощадных големов и созданий-завоевателей, охраняющих Аргелмаха. Информация передана посредством телепатии." },
      [4081] = { name = "УНИЧТОЖИТЬ НА МЕСТЕ: Дворфы Черного Железа", objective = "Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров! По приказу полководца Клинозуба уничтожьте 15 охранников, 10 надсмотрщиков и 5 пехотинцев из клана Ярости Горна. Вернитесь сразу по выполнении задания." },
      [4082] = { name = "УНИЧТОЖИТЬ НА МЕСТЕ: Высокопоставленные чины Черного Железа", objective = "Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров! По приказу полководца Клинозуба уничтожьте 10 медиков, 10 солдат и 10 офицеров из клана Ярости Горна. Вернитесь сразу по выполнении задания." },
      [4083] = { name = "Призрачный кубок" },
      [4123] = { name = "Сердце горы", objective = "Принесите сердце горы Максворту Суперблеску в Пылающие степи." },
      [4126] = { name = "Харли Пьянодых", objective = "Найдите украденный рецепт громоварского и верните его Рагнару Громовару в Каранос." },
      [4132] = { name = "Операция:смерть Кузне Гнева", objective = "Отправляйтесь в Глубины Черной горы и убейте генерала Кузню Гнева. Вернитесь к полководцу Клинозубу по выполнении задания." },
      [4134] = { name = "Украденный рецепт громоварского", objective = "Принесите рецепт громоварского светлого Вивиан Лягроб в Каргат." },
      [4136] = { name = "Риббли Крутипроб", objective = "Принесите голову Риббли Юке Крутипроб в Пылающие степи." },
      [4201] = { name = "Приворотное зелье", objective = "Принесите 4 листа крови Грома, 10 огромных серебряных слитков и наполненный сосуд Нагмары госпоже Нагмаре в Глубины Черной горы." },
      [4241] = { name = "Маршал Винздор", objective = "Отправляйтесь на Черную гору на северо-западе и войдите в ее глубины. Узнайте, что сталось с маршалом Виндзором. Кажется, Джон-Оборванец говорил о том, что Виндзора утащили в темницу." },
      [4263] = { name = "Опалитель!", objective = "Отыщите и уничтожьте лорда Опалителя в глубинах Черной горы!" },
      [4282] = { name = "Проблеск надежды", objective = "Верните маршалу Виндзору утерянную информацию. Маршал уверен, что информацией завладели повелитель големов Аргелмах и генерал Кузня Гнева." },
      [4322] = { name = "Побег!", objective = "Помогите маршалу Виндзору забрать вещи и освободить его друзей, после чего вернитесь к маршалу Максвеллу и получите дальнейшие инструкции." },
      [4362] = { name = "Судьба королевства", objective = "Вернитесь в Глубины Черной горы и освободите принцессу Мойру Бронзобород от злобного императора Даграна Тауриссана." },
      [4363] = { name = "Королевский сюрприз", objective = "Вернитесь в Стальгорн и переговорите с королем Магни Бронзобородом." },
    },
  },
  koKR = {
    dungeon = "검은바위 나락", location = "검은바위 산",
    bosses = { ["High Interrogator Gerstahn"] = "대심문관 게르스탄", ["Lord Roccor"] = "불의군주 록코르", ["Houndmaster Grebmar"] = "사냥개조련사 그렙마르", ["Gorosh the Dervish"] = "광신자 고로쉬", ["Grizzle"] = "그리즐", ["Eviscerator"] = "적출자", ["Ok'thor the Breaker"] = "파괴자 오크토르", ["Anub'shiah"] = "아눕쉬아", ["Hedrum the Creeper"] = "왕거미 헤드룸", ["Pyromancer Loregrain"] = "화염술사 로어그레인", ["Fineous Darkvire"] = "파이너스 다크바이어", ["Warder Stilgiss"] = "문지기 스틸기스", ["Lord Incendius"] = "불의군주 인센디우스", ["Bael'Gar"] = "밸가르", ["General Angerforge"] = "사령관 앵거포지", ["Golem Lord Argelmach"] = "골렘 군주 아젤마크", ["Hurley Blackbreath"] = "헐레이 블랙브레스", ["Phalanx"] = "팔란스", ["Ribbly Screwspigot"] = "리블리 스크류스피곳", ["Plugger Spazzring"] = "플러거 스파즈링", ["Ambassador Flamelash"] = "사자 화염채찍", ["Panzor the Invincible"] = "무적의 판저", ["The Seven"] = "일곱 문지기", ["Magmus"] = "마그무스", ["Princess Moira Bronzebeard"] = "공주 모이라 브론즈비어드", ["Emperor Dagran Thaurissan"] = "제왕 다그란 타우릿산" },
    quests = {
      [3802] = { name = "검은무쇠단 유물", objective = "파이너스 다크바이어를 처치하고 거대한 망치, 무쇠지옥을 회수해야 합니다. 무쇠지옥을 타우릿산의 제단으로 가져가서 프랑클론 포지라이트의 석상에 두어야 합니다." },
      [3907] = { name = "불의 부조화", objective = "검은바위 나락에 들어가 불의군주 인센디우스를 찾아, 그를 처치한 후 얻게 되는 모든 정보를 썬더하트에게 가져가야 합니다." },
      [3981] = { name = "사령관 고르샤크", objective = "검은바위 나락에서 사령관 고르샤크를 찾아야 합니다. 조잡하게 그려진 오크 그림에 쇠창살이 그려져 있던 것이 생각납니다. 감옥 같은 곳을 찾아봐야 할 것 같습니다." },
      [3982] = { name = "사태 파악", objective = "고르샤크를 보호해야 합니다." },
      [4003] = { name = "공주 구출", objective = "제왕 다그란 타우릿산을 처치하고 그의 사악한 마법에서 공주 모이라 브론즈비어드를 해방시켜야 합니다." },
      [4004] = { name = "구출된 공주?", objective = "스랄에게 돌아가야 합니다!" },
      [4024] = { name = "화염의 맛", objective = "검은바위 나락으로 가서 밸가르를 처치하십시오. 이 거인이 검은바위 나락 내에 살고 있다는 것만 알고 있으며 밸가르의 시체에 변형된 검은용군단 허물을 사용해 불의 정수를 추출해야만 합니다. 키루스 테레펜터스에게 담겨진 불의 정수를 가져가야 합니다." },
      [4063] = { name = "기계들의 봉기", objective = "골렘 군주 아젤마크를 찾아 처치하고 그 증거로 그의 머리카락을 로트윌에게 가져가야 합니다. 그리고 아젤마크를 호위하는 재앙의 피조물과 맹위의 전투골렘들에게서 온전한 원소핵 10개도 모아야 합니다." },
      [4081] = { name = "죽음의 본보기: 검은무쇠단 드워프", objective = "검은바위 나락으로 가서 사악한 침략자들을 쳐부수십시오! 장군 고어투스가 성난모루단 보초 15명, 성난모루단 교도관 10명, 성난모루단 보병 5명을 처치해 달라고 부탁했습니다. 임무를 완수하면 장군 고어투스에게 돌아가십시오." },
      [4082] = { name = "죽음의 본보기: 검은무쇠단 고위 관리", objective = "검은바위 나락으로 가서 사악한 침략자들을 쳐부수십시오! 장군 고어투스가 성난모루단 간호병 10명, 성난모루단 병사 10명, 그리고 성난모루단 장교 10명을 처치해 달라고 부탁했습니다. 임무를 완수하면 고어투스에게 돌아가십시오." },
      [4083] = { name = "유령의 성배" },
      [4123] = { name = "산의 정수", objective = "불타는 평원에 있는 맥스워트 우버글린트에게 산의 정수를 가져가야 합니다." },
      [4126] = { name = "헐레이 블랙브레스", objective = "카라노스에 있는 라그나르 썬더브루에게 잃어버린 썬더브루 제조법을 가져가야 합니다." },
      [4132] = { name = "앵거포지 척살 작전", objective = "검은바위 나락으로 가서 사령관 앵거포지를 처치한 후 장군 고어투스에게 돌아가야 합니다." },
      [4134] = { name = "잃어버린 썬더브루 제조법", objective = "카르가스에 있는 비비안 라그레이브에게 잃어버린 썬더브루 제조법을 가져가야 합니다." },
      [4136] = { name = "리블리 스크류스피곳", objective = "리블리를 처치하고 그 증거로 그의 머리카락을 불타는 평원에 있는 유카 스크류스피곳에게 가져가야 합니다." },
      [4201] = { name = "사랑의 묘약", objective = "검은바위 나락에 있는 여왕 나그마라에게 그롬의 피 4개, 거대한 은 광석 10개, 가득 찬 나그마라의 약병을 가져가야 합니다." },
      [4241] = { name = "치안대장 윈저", objective = "북서쪽에 있는 검은바위 산으로 가서 검은바위 나락으로 들어가십시오. 치안대장 윈저에게 무슨 일이 있었는지 알아내야 합니다. 털보 존은 윈저가 감옥으로 끌려갔다고 했습니다." },
      [4263] = { name = "인센디우스!", objective = "검은바위 나락에서 불의군주 인센디우스를 찾아 처치해야 합니다." },
      [4282] = { name = "잔존하는 희망", objective = "치안대장 윈저의 잃어버린 단서를 가져 와야 합니다. 치안대장 윈저는 골렘 군주 아젤마크와 사령관 앵거포지가 이 정보를 가지고 있을 것이라 생각합니다." },
      [4322] = { name = "탈옥!", objective = "치안대장 윈저가 자신의 장비를 되찾고 갇힌 동료들을 풀어 주는 것을 도와야 합니다. 성공하면 치안대장 맥스웰에게 돌아가십시오." },
      [4362] = { name = "왕국의 운명", objective = "검은바위 나락으로 돌아가 제왕 다그란 타우릿산의 사악한 손아귀에서 공주 모이라 브론즈비어드를 구출해야 합니다." },
      [4363] = { name = "브론즈비어드 공주", objective = "아이언포지로 돌아가서 국왕 마그니 브론즈비어드와 대화해야 합니다." },
    },
  },
  zhCN = {
    dungeon = "黑石深渊", location = "黑石山",
    bosses = { ["High Interrogator Gerstahn"] = "审讯官格斯塔恩", ["Lord Roccor"] = "洛考尔", ["Houndmaster Grebmar"] = "驯犬者格雷布玛尔", ["Gorosh the Dervish"] = "修行者高罗什", ["Grizzle"] = "格里兹尔", ["Eviscerator"] = "剜眼者", ["Ok'thor the Breaker"] = "破坏者奥科索尔", ["Anub'shiah"] = "阿努希尔", ["Hedrum the Creeper"] = "爬行者赫杜姆", ["Pyromancer Loregrain"] = "控火师罗格雷恩", ["Fineous Darkvire"] = "弗诺斯·达克维尔", ["Warder Stilgiss"] = "典狱官斯迪尔基斯", ["Lord Incendius"] = "伊森迪奥斯", ["Bael'Gar"] = "贝尔加", ["General Angerforge"] = "安格弗将军", ["Golem Lord Argelmach"] = "傀儡统帅阿格曼奇", ["Hurley Blackbreath"] = "霍尔雷·黑须", ["Phalanx"] = "法拉克斯", ["Ribbly Screwspigot"] = "雷布里·斯库比格特", ["Plugger Spazzring"] = "普拉格", ["Ambassador Flamelash"] = "弗莱拉斯大使", ["Panzor the Invincible"] = "无敌的潘佐尔", ["The Seven"] = "七贤人", ["Magmus"] = "玛格姆斯", ["Princess Moira Bronzebeard"] = "铁炉堡公主茉艾拉·铜须", ["Emperor Dagran Thaurissan"] = "达格兰·索瑞森大帝" },
    quests = {
      [3802] = { name = "黑铁的遗产", objective = "杀掉弗诺斯·达克维尔并拿回战锤铁胆。把铁胆之锤拿到索瑞森神殿去，将其放在弗兰克罗恩·铸铁的雕像上。" },
      [3907] = { name = "不和谐的火焰", objective = "进入黑石深渊并找到伊森迪奥斯。杀掉它，然后把你找到的信息汇报给桑德哈特。" },
      [3981] = { name = "指挥官哥沙克", objective = "在黑石深渊里找到指挥官哥沙克。在那幅草图上画着的是一个铁栏后面的兽人，也许你应该到某个类似监狱的地方去找找看。" },
      [3982] = { name = "出了什么事？", objective = "保护哥沙克。" },
      [4003] = { name = "拯救公主", objective = "杀掉达格兰·索瑞森大帝，然后将铁炉堡公主茉艾拉·铜须从他的邪恶诅咒中拯救出来。" },
      [4004] = { name = "拯救公主？", objective = "向萨尔报告！" },
      [4024] = { name = "烈焰精华", objective = "到黑石深渊去杀掉贝尔加。你只知道这个巨型怪物住在黑石深渊的最深处。记住你要使用特殊的黑龙皮从贝尔加的尸体上采集烈焰精华。将你采集到的烈焰精华交给塞勒斯·萨雷芬图斯。" },
      [4063] = { name = "机器的崛起", objective = "找到并杀掉傀儡统帅阿格曼奇，将他的头交给鲁特维尔。你还需要从守卫着阿格曼奇的狂怒傀儡和战斗傀儡身上收集10块完整的元素核心。" },
      [4081] = { name = "格杀勿论：黑铁矮人", objective = "到黑石深渊去消灭那些邪恶的侵略者！军官高图斯要你去杀死15个铁怒卫士、10个铁怒狱卒和5个铁怒步兵。完成任务之后回去向他复命。" },
      [4082] = { name = "格杀勿论：高阶黑铁军官", objective = "到黑石深渊去消灭那些邪恶的侵略者！高图斯军阀要你杀死10个铁怒医师、10个铁怒士兵和10个铁怒军官。完成任务之后回去向他复命。" },
      [4083] = { name = "鬼魂之杯" },
      [4123] = { name = "山脉之心", objective = "把山脉之心交给燃烧平原的麦克斯沃特·尤博格林。" },
      [4126] = { name = "霍尔雷·黑须", objective = "把遗失的雷酒秘方带给卡拉诺斯的拉格纳·雷酒。" },
      [4132] = { name = "行动：杀死安格弗将军", objective = "到黑石深渊去杀掉安格弗将军！当任务完成之后向军官高图斯复命。" },
      [4134] = { name = "遗失的雷酒秘方", objective = "把遗失的雷酒秘方交给卡加斯的薇薇安·拉格雷。" },
      [4136] = { name = "雷布里·斯库比格特", objective = "把雷布里的头颅交给燃烧平原的尤卡·斯库比格特。" },
      [4201] = { name = "爱情药水", objective = "将4份格罗姆之血、10块巨型银矿和装满水的娜玛拉之瓶交给黑石深渊的娜玛拉小姐。" },
      [4241] = { name = "温德索尔元帅", objective = "到西北部的黑石山脉去，在黑石深渊中找到温德索尔元帅的下落。狼狈不堪的约翰曾告诉你说温德索尔被关进了一个监狱。" },
      [4263] = { name = "伊森迪奥斯！", objective = "在黑石深渊里找到伊森迪奥斯，然后把他干掉！" },
      [4282] = { name = "一丝希望", objective = "找回温德索尔元帅遗失的情报。温德索尔元帅确信那些情报在安格弗将军和傀儡统帅阿格曼奇的手里。" },
      [4322] = { name = "冲破牢笼！", objective = "帮助温德索尔元帅拿回他的装备并救出他的朋友。当你成功之后就回去向麦克斯韦尔元帅复命。" },
      [4362] = { name = "王国的命运", objective = "回到黑石深渊，从达格兰·索瑞森大帝的魔掌中救出铁炉堡公主茉艾拉·铜须。" },
      [4363] = { name = "语出惊人的公主", objective = "回到铁炉堡去，与国王麦格尼·铜须谈一谈。" },
    },
  },
  zhTW = {
    dungeon = "黑石深淵", location = "黑石山",
    bosses = { ["High Interrogator Gerstahn"] = "審訊官格斯塔恩", ["Lord Roccor"] = "洛考爾", ["Houndmaster Grebmar"] = "馴犬者格雷布瑪爾", ["Gorosh the Dervish"] = "修行者高羅什", ["Grizzle"] = "格里茲爾", ["Eviscerator"] = "剜眼者", ["Ok'thor the Breaker"] = "破壞者奧科索爾", ["Anub'shiah"] = "阿努希爾", ["Hedrum the Creeper"] = "爬行者赫杜姆", ["Pyromancer Loregrain"] = "控火師羅格雷恩", ["Fineous Darkvire"] = "弗諾斯·達克維爾", ["Warder Stilgiss"] = "典獄官斯迪爾基斯", ["Lord Incendius"] = "伊森迪奧斯", ["Bael'Gar"] = "貝爾加", ["General Angerforge"] = "安格弗將軍", ["Golem Lord Argelmach"] = "傀儡統帥阿格曼奇", ["Hurley Blackbreath"] = "霍爾雷·黑鬚", ["Phalanx"] = "法拉克斯", ["Ribbly Screwspigot"] = "雷布里·斯庫比格特", ["Plugger Spazzring"] = "普拉格", ["Ambassador Flamelash"] = "弗萊拉斯大使", ["Panzor the Invincible"] = "無敵的潘佐爾", ["The Seven"] = "七賢人", ["Magmus"] = "瑪格姆斯", ["Princess Moira Bronzebeard"] = "鐵爐堡公主茉艾拉·銅須", ["Emperor Dagran Thaurissan"] = "達格蘭·索瑞森大帝" },
    quests = {
      [3802] = { name = "黑鐵的遺產", objective = "殺掉弗諾斯·達克維爾並拿回戰錘鐵膽。把鐵膽之錘拿到索瑞森神殿去，將其放在弗蘭克羅恩·鑄鐵的雕像上。" },
      [3907] = { name = "不和諧的火焰", objective = "進入黑石深淵並找到伊森迪奧斯。殺掉它，然後把你找到的資訊彙報給桑德哈特。" },
      [3981] = { name = "指揮官哥沙克", objective = "在黑石深淵裡找到指揮官哥沙克。在那幅草圖上畫著的是一個鐵欄後面的獸人，也許你應該到某個類似監獄的地方去找找看。" },
      [3982] = { name = "出了什麼事？", objective = "保護哥沙克。" },
      [4003] = { name = "拯救公主", objective = "殺掉達格蘭·索瑞森大帝，然後將鐵爐堡公主茉艾拉·銅須從他的邪惡詛咒中拯救出來。" },
      [4004] = { name = "拯救公主？", objective = "向薩爾報告！" },
      [4024] = { name = "烈焰精華", objective = "到黑石深淵去殺掉貝爾加。你只知道這個巨型怪物住在黑石深淵的最深處。記住你要使用特殊的黑龍皮從貝爾加的屍體上採集烈焰精華。將你採集到的烈焰精華交給塞勒斯·薩雷芬圖斯。" },
      [4063] = { name = "機器的崛起", objective = "找到並殺掉傀儡統帥阿格曼奇，將他的頭交給魯特維爾。你還需要從守衛著阿格曼奇的狂怒傀儡和戰鬥傀儡身上收集10塊完整的元素核心。" },
      [4081] = { name = "格殺勿論：黑鐵矮人", objective = "到黑石深淵去消滅那些邪惡的侵略者！軍官高圖斯要你去殺死15個鐵怒衛士、10個鐵怒獄卒和5個鐵怒步兵。完成任務之後回去向他覆命。" },
      [4082] = { name = "格殺勿論：高階黑鐵軍官", objective = "到黑石深淵去消滅那些邪惡的侵略者！高圖斯軍閥要你殺死10個鐵怒醫師、10個鐵怒士兵和10個鐵怒軍官。完成任務之後回去向他覆命。" },
      [4083] = { name = "鬼魂之杯" },
      [4123] = { name = "山脈之心", objective = "把山脈之心交給燃燒平原的麥克斯沃特·尤博格林。" },
      [4126] = { name = "霍爾雷·黑鬚", objective = "把遺失的雷酒秘方帶給卡拉諾斯的拉格納·雷酒。" },
      [4132] = { name = "行動：殺死安格弗將軍", objective = "到黑石深淵去殺掉安格弗將軍！當任務完成之後向軍官高圖斯覆命。" },
      [4134] = { name = "遺失的雷酒秘方", objective = "把遺失的雷酒秘方交給卡加斯的薇薇安·拉格雷。" },
      [4136] = { name = "雷布里·斯庫比格特", objective = "把雷布里的頭顱交給燃燒平原的尤卡·斯庫比格特。" },
      [4201] = { name = "愛情藥水", objective = "將4份格羅姆之血、10塊巨型銀礦和裝滿水的娜瑪拉之瓶交給黑石深淵的娜瑪拉小姐。" },
      [4241] = { name = "溫德索爾元帥", objective = "到西北部的黑石山脈去，在黑石深淵中找到溫德索爾元帥的下落。狼狽不堪的約翰曾告訴你說溫德索爾被關進了一個監獄。" },
      [4263] = { name = "伊森迪奧斯！", objective = "在黑石深淵裡找到伊森迪奧斯，然後把他幹掉！" },
      [4282] = { name = "一絲希望", objective = "找回溫德索爾元帥遺失的情報。溫德索爾元帥確信那些情報在安格弗將軍和傀儡統帥阿格曼奇的手裡。" },
      [4322] = { name = "衝破牢籠！", objective = "幫助溫德索爾元帥拿回他的裝備並救出他的朋友。當你成功之後就回去向麥克斯韋爾元帥覆命。" },
      [4362] = { name = "王國的命運", objective = "回到黑石深淵，從達格蘭·索瑞森大帝的魔掌中救出鐵爐堡公主茉艾拉·銅須。" },
      [4363] = { name = "語出驚人的公主", objective = "回到鐵爐堡去，與國王麥格尼·銅須談一談。" },
    },
  },
}
for lang, data in pairs(BRD_LOC) do
    local content = FDJ.ContentLocales[lang] or {}
    FDJ.ContentLocales[lang] = content
    content.dungeons = content.dungeons or {}
    content.bosses = content.bosses or {}
    content.places = content.places or {}
    content.quests = content.quests or {}
    if content.dungeons["Blackrock Depths"] == nil then
        content.dungeons["Blackrock Depths"] = { name = data.dungeon, location = data.location or nil }
    end
    for english, localName in pairs(data.bosses or {}) do
        if content.bosses[english] == nil then content.bosses[english] = localName end
        if content.places[english] == nil then content.places[english] = localName end
    end
    for id, entry in pairs(data.quests or {}) do
        if content.quests[id] == nil then content.quests[id] = entry end
    end
end

