    dungeon = "黑石塔上层", location = "黑石山",
    bosses = { ["Pyroguard Emberseer"] = "烈焰卫士艾博希尔", ["Solakar Flamewreath"] = "索拉卡·火冠", ["Jed Runewatcher"] = "杰德", ["Goraluk Anvilcrack"] = "古拉鲁克", ["Gyth"] = "盖斯", ["Warchief Rend Blackhand"] = "大酋长雷德·黑手", ["The Beast"] = "比斯巨兽", ["Lord Valthalak"] = "瓦塔拉克公爵", ["General Drakkisath"] = "达基萨斯将军" },
    quests = {
      [4734] = { name = "冷冻龙蛋", objective = "在孵化间对着某颗龙蛋使用龙蛋冷冻器初号机。" },
      [4735] = { name = "收集龙蛋", objective = "将电动采集模块和8颗收集到的龙蛋交给燃烧平原烈焰峰的丁奇·斯迪波尔。" },
      [4743] = { name = "晋升印章", objective = "到尘泥沼泽中的巨龙沼泽去。找到上古老龙埃博斯塔夫，对他发起无情的攻击，直到他的意志被摧毁。此时，你必须尽快将未铸造的晋升印章放在这条龙面前，并使用龙力宝珠控制他的躯体，强迫他将黑龙的烈焰喷向未铸造的晋升印章！" },
      [4974] = { name = "为部落而战！", objective = "去黑石塔杀死大酋长雷德·黑手，带着他的头颅返回奥格瑞玛。" },
      [5089] = { name = "达基萨斯将军的命令", objective = "把达基萨斯将军的命令交给燃烧平原的麦克斯韦尔元帅。" },
      [5102] = { name = "达基萨斯将军之死", objective = "到黑石塔去杀掉达基萨斯将军，完成任务之后就回到麦克斯韦尔元帅那里复命。" },
      [5127] = { name = "恶魔熔炉", objective = "到黑石塔去找到古拉鲁克。杀死他，然后用血污长矛刺入他的尸体。当他的灵魂被吸干后，这支矛就会成为穿魂长矛。你还必须找到未铸造的符文覆饰胸甲。将穿魂长矛和未铸造的符文覆饰胸甲都交给冬泉谷的罗拉克斯。" },
      [6502] = { name = "龙火护符", objective = "你必须从达基萨斯将军身上取回黑龙勇士之血，你可以在黑石塔的晋升大厅后面的房间里找到他。" },
      [6602] = { name = "黑龙勇士之血", objective = "到黑石塔去杀掉达基萨斯将军，把它的血交给雷克萨。" },
      [7761] = { name = "黑手的命令", objective = "真是个愚蠢的兽人。看来你需要找到那枚烙印并获得达基萨斯徽记才可以使用命令宝珠。你从信中获知，达基萨斯将军守卫着烙印。也许你应该就此进行更深入的调查。" },
    },
  },
