    quests = {
      [4734] = { name = "冷凍龍蛋", objective = "在孵化間對著某顆龍蛋使用龍蛋冷凍器初號機。" },
      [4735] = { name = "收集龍蛋", objective = "將電動採集模組和8顆收集到的龍蛋交給燃燒平原烈焰峰的丁奇·斯迪波爾。" },
      [4743] = { name = "晉升印章", objective = "到塵泥沼澤中的巨龍沼澤去。找到上古老龍埃博斯塔夫，對他發起無情的攻擊，直到他的意志被摧毀。此時，你必須儘快將未鑄造的晉升印章放在這條龍面前，並使用龍力寶珠控制他的軀體，強迫他將黑龍的烈焰噴向未鑄造的晉升印章！" },
      [4974] = { name = "為部落而戰！", objective = "去黑石塔殺死大酋長雷德·黑手，帶著他的頭顱返回奧格瑞瑪。" },
      [5089] = { name = "達基薩斯將軍的命令", objective = "把達基薩斯將軍的命令交給燃燒平原的麥克斯韋爾元帥。" },
      [5102] = { name = "達基薩斯將軍之死", objective = "到黑石塔去殺掉達基薩斯將軍，完成任務之後就回到麥克斯韋爾元帥那裡覆命。" },
      [5127] = { name = "惡魔熔爐", objective = "到黑石塔去找到古拉魯克。殺死他，然後用血汙長矛刺入他的屍體。當他的靈魂被吸乾後，這支矛就會成為穿魂長矛。你還必須找到未鑄造的符文覆飾胸甲。將穿魂長矛和未鑄造的符文覆飾胸甲都交給冬泉谷的羅拉克斯。" },
      [6502] = { name = "龍火護符", objective = "你必須從達基薩斯將軍身上取回黑龍勇士之血，你可以在黑石塔的晉升大廳後面的房間裡找到他。" },
      [6602] = { name = "黑龍勇士之血", objective = "到黑石塔去殺掉達基薩斯將軍，把它的血交給雷克薩。" },
      [7761] = { name = "黑手的命令", objective = "真是個愚蠢的獸人。看來你需要找到那枚烙印並獲得達基薩斯徽記才可以使用命令寶珠。你從信中獲知，達基薩斯將軍守衛著烙印。也許你應該就此進行更深入的調查。" },
    },
  },
}
for lang, data in pairs(UBRS_LOC) do
    local content = FDJ.ContentLocales[lang] or {}
    FDJ.ContentLocales[lang] = content
    content.dungeons = content.dungeons or {}
    content.bosses = content.bosses or {}
    content.places = content.places or {}
    content.quests = content.quests or {}
    if content.dungeons["Upper Blackrock Spire"] == nil then
        content.dungeons["Upper Blackrock Spire"] = { name = data.dungeon, location = data.location or nil }
    end
    for english, localName in pairs(data.bosses or {}) do
        if content.bosses[english] == nil then content.bosses[english] = localName end
        if content.places[english] == nil then content.places[english] = localName end
    end
    for id, entry in pairs(data.quests or {}) do
        if content.quests[id] == nil then content.quests[id] = entry end
    end
end

