    quests = {
      [4701] = { name = "Abattez-la", objective = "Allez au Pic Blackrock et anéantir la menace worg à sa source. Tandis que vous quittiez Helendis, il a crié un nom : Halycon. C'est ce que disent les orcs en parlant des worgs." },
      [4724] = { name = "La maîtresse de meute", objective = "Tuer Halycon, la maîtresse de la meute des worgs Bloodaxe." },
      [4729] = { name = "Les animaux exotiques de Kibler", objective = "Aller au Pic Blackrock et trouver de Jeunes worgs Bloodaxe. Utiliser la cage pour transporter ces petites bêtes féroces. Rapporter un Jeune worg en cage à Kibler." },
      [4742] = { name = "Le sceau de l'ascension", objective = "Trouver les trois gemmes de commandement : la Gemme de Smolderthorn, la Gemme de Pierre-du-pic et la Gemme de Bloodaxe. Rapportez-les, ainsi que le Sceau d'ascension non décoré, à Vaelan. Les généraux, comme vous l'a dit Vaelan, sont : le maître de guerre Voone de Smolderthorn ; le généralissime Omokk des Pierres-du-pic ; et le seigneur Wyrmthalak de Bloodaxe." },
