      [4742] = { name = "El Sello de Ascensión", objective = "Encuentra las 3 gemas del mando: La gema de Espina Ahumada, la gema de Cumbrerroca y la gema de Hacha de Sangre. Llévaselas, junto con el Sello de Ascensión sin adornos a Vaelan. Los generales, como te dijo Vaelan, son: el maestro de guerra Voone de los Espina Ahumada, el Alto señor Omokk de los Cumbrerroca y el Señor Supremo Vermiothalak de los Hacha de Sangre." },
      [4862] = { name = "Bestia amaestrada", objective = "Viaja a la Cumbre de Roca Negra y reúne 15 huevos de araña de la cumbre para Kibler. Yo diría que se pueden encontrar estos huevos cerca de arañas." },
      [4866] = { name = "La leche de la madre", objective = "En el corazón de la Cumbre de Roca Negra encontrarás a Madre Telabrasada. Provócala para que te envenene. Lo más seguro es que tendrás que matarla también. Vuelve junto a John Andrajoso cuando estés envenenado para que pueda extraer el veneno de ti." },
