  ptBR = {
    dungeon = "Pico da Rocha Negra Inferior", location = "Montanha Rocha Negra",
    bosses = { ["Spirestone Butcher"] = "Carniceiro Agulhapétrea", ["Highlord Omokk"] = "Grão-lorde Omokk", ["Shadow Hunter Vosh'gajin"] = "Caçadora Sombria Vosh'gajin", ["War Master Voone"] = "Senhor da Guerra Voone", ["Mother Smolderweb"] = "Mãe Queimateia", ["Crystal Fang"] = "Presa de Cristal", ["Urok Doomhowl"] = "Urok Uivo-da-ruína", ["Bannok Grimaxe"] = "Bannok Sinistracha", ["Quartermaster Zigris"] = "Intendente Zigris", ["Halycon"] = "Halycon", ["Gizrul the Slavener"] = "Gizrul, o Subjugador", ["Ghok Bashguud"] = "Ghok Surrabem", ["Overlord Wyrmthalak"] = "Lorde Supremo Wyrmthalak" },
    quests = {
      [4701] = { name = "Acabando com ela", objective = "Vá ao Pico da Rocha Negra e destrua a fonte da ameaça worg. Quando você deixou Helendis, ele gritou um nome: Halycon. É assim que os orcs se referem aos worgs." },
      [4724] = { name = "Senhora do matilha", objective = "Mate Halycon, senhora da matilha dos Worgs Machado Sangrento." },
      [4729] = { name = "Mascotes exóticas do Kibler", objective = "Vá para o Pico da Rocha Negra e encontre Filhotes de Worg Machado Sangrento. Use a jaula para carregar essas pequenas feras. Leve um Filhote de Worg Enjaulado para Kibler." },
      [4742] = { name = "Selo da Ascensão", objective = "Encontre as três gemas da autoridade: a Gema de Espinho Fúmeo, a Gema de Agulhapétrea e a Gema de Machado Sangrento. Entregue-as, junto com o Selo da Ascensão sem Adorno, a Vaelan. Os generais, como informado a você por Vaelan, são: Senhor da Guerra Voone dos Fumocardo, Grão-lorde Omokk dos Agulhapétrea e Lorde Supremo Wyrmthalak dos Machado Sangrento." },
      [4862] = { name = "Nojento!", objective = "Vá para o Pico da Rocha Negra e colete 15 Ovos de Aranha do Pináculo para Kibler. Pelo nome, é de se pensar que eles fiquem perto das aranhas." },
      [4866] = { name = "Leite materno", objective = "No coração do Pico da Rocha Negra você vai encontrar a Mãe Queimateia. Chame a atenção dela e deixe-a envenenar você. É bem provável que você precise matá-la também. Fale novamente com João Roto depois que for envenenado para que ele possa \"ordenhar\" você." },
      [4867] = { name = "Urok Uivo-da-ruína", objective = "Leia o Pergaminho do Warosh. Traga o Mojo do Warosh para Warosh." },
      [4903] = { name = "O comando do Senhor da Guerra", objective = "Mate o Grão-lorde Omokk, o Senhor da Guerra Voone e o Lorde Supremo Wyrmthalak. Recupere Documentos Importantes dos Rocha Negra. Fale novamente com o Senhor da Guerra Trincador, em Karrath, quanto a missão tiver sido cumprida." },
      [5081] = { name = "A missão de Maxwell", objective = "Vá para o Pico da Rocha Negra e mate o Senhor da Guerra Voone, o Grão-lorde Omokk e o Lorde Supremo Wyrmthalak. Fale novamente com o Oficial Maxwell quando terminar o trabalho." },
    },
  },
  ruRU = {
    dungeon = "Вершина Черной горы (низ)", location = "Черная гора",
    bosses = { ["Spirestone Butcher"] = "Мясник из клана Черной Вершины", ["Highlord Omokk"] = "Вождь Омокк", ["Shadow Hunter Vosh'gajin"] = "Темная охотница Вос'гаджин", ["War Master Voone"] = "Воевода Вун", ["Mother Smolderweb"] = "Мать Дымная Паутина", ["Crystal Fang"] = "Хрустальный Клык", ["Urok Doomhowl"] = "Аррок Смертный Вопль", ["Bannok Grimaxe"] = "Баннок Люторез", ["Quartermaster Zigris"] = "Интендант Зигрис", ["Halycon"] = "Халикон", ["Gizrul the Slavener"] = "Гизрул Поработитель", ["Ghok Bashguud"] = "Гок Крепкобив", ["Overlord Wyrmthalak"] = "Властитель Змейталак" },
    quests = {
      [4701] = { name = "Устранение опасности", objective = "Отправьтесь на пик Черной горы и уничтожьте источник опасности. Хелендис кричит вам вслед одно имя: Халикон. Именно его упоминали орки в связи с воргами." },
      [4724] = { name = "Праматерь стаи", objective = "Убейте Халикон, праматерь стаи воргов Кровавого Топора." },
      [4729] = { name = "Редкие звери Киблера", objective = "Отправьтесь на пик Черной горы и отыщите там щенков воргов легиона Кровавого Топора. Посадите маленьких тварей в клетку и отнесите Киблеру." },
      [4742] = { name = "Печать Вознесения", objective = "Найдите самоцвет Тлеющего Терновника, самоцвет Черной Вершины и самоцвет Кровавого Топора. Верните их Ваелану вместе с простой печатью Вознесения. Камни могут быть у трех генералов: у воеводы Вуна из клана Тлеющего Терновника, у вождя Омокка из клана Черной Вершины и у повелителя Змейталака из клана Кровавого Топора." },
      [4862] = { name = "Товар на любителя", objective = "Отправьтесь на пик Черной горы и принесите Киблеру 15 яиц скального паука. Судя по всему, яйца надо искать недалеко от пауков." },
      [4866] = { name = "Материнское молоко", objective = "Найдите в самом сердце пика Черной горы мать Дымную Паутину. Сражайтесь с ней, пока она не введет вам свой яд. Скорее всего ее также придется убить. Когда яд будет в вас, вернитесь к Джону-Оборванцу, чтобы он смог добыть яд." },
      [4867] = { name = "Аррок Смертный Вопль", objective = "Прочитайте записку Вароша. Принесите Варошу его амулет." },
      [4903] = { name = "Приказ полководца", objective = "Убейте вождя Омокка, воеводу Вуна и повелителя Змейталака. Найденные при них важные бумаги Черной горы доставьте полководцу Клинозубу в Каргат." },
      [5081] = { name = "Миссия Максвелла", objective = "Отправляйтесь на пик Черной горы и устраните воеводу Вуна, вождя Омокка и повелителя Змейталака. По выполнении задания вернитесь к маршалу Максвеллу." },
    },
  },
  koKR = {
    dungeon = "검은바위 첨탑 하층", location = "검은바위 산",
    bosses = { ["Spirestone Butcher"] = "뾰족바위일족 학살자", ["Highlord Omokk"] = "대군주 오모크", ["Shadow Hunter Vosh'gajin"] = "어둠사냥꾼 보쉬가진", ["War Master Voone"] = "대장군 부네", ["Mother Smolderweb"] = "여왕 불그물거미", ["Crystal Fang"] = "수정 맹독거미", ["Urok Doomhowl"] = "우로크 둠하울", ["Bannok Grimaxe"] = "반노크 그림액스", ["Quartermaster Zigris"] = "병참장교 지그리스", ["Halycon"] = "할리콘", ["Gizrul the Slavener"] = "흉포한 기즈룰", ["Ghok Bashguud"] = "고크 배시구드", ["Overlord Wyrmthalak"] = "대군주 웜타라크" },
    quests = {
      [4701] = { name = "검은늑대 위협의 근원 파괴", objective = "검은바위 첨탑으로 가서 검은늑대 위협의 근원을 파괴해야 합니다. 헬렌디스를 떠날 때 헬렌디스가 오크들이 특정한 검은늑대를 부르는 말인 할리콘이라는 이름을 외치는 것을 들었습니다." },
      [4724] = { name = "검은늑대 무리의 어미", objective = "도끼부대 검은늑대 무리의 어미, 할리콘을 처치해야 합니다." },
      [4729] = { name = "키블러의 진귀한 애완동물", objective = "검은바위 첨탑으로 가서 새끼 도끼부대 검은늑대를 찾아야 합니다. 우리를 사용하여 이 사나운 야수들을 운반하여 키블러에게 사로잡은 새끼 검은늑대를 가져가야 합니다." },
      [4742] = { name = "승천의 인장", objective = "사령관의 세 가지 보석인 가시불꽃부족 보석, 뾰족바위일족 보석, 도끼부대 보석을 찾아, 가공하지 않은 승천의 인장과 함께 밸란에게 가져가야 합니다. 밸란이 말한 장군들은 가시불꽃부족의 대장군 부네, 뾰족바위일족의 대군주 오모크와 도끼부대의 대군주 웜타라크입니다." },
      [4862] = { name = "더러운 거미알", objective = "검은바위 첨탑으로 가서 키블러를 위해 첨탑 거미알 15개를 수집해야 합니다. 들리는 소문으로는 그 알들은 거미들이 서식하는 근처에서 찾을 수 있다고 합니다." },
      [4866] = { name = "여왕 거미의 독", objective = "검은바위 첨탑 중심부에서 여왕 불그물거미를 찾을 수 있습니다. 여왕 불그물거미를 공격하거나 접근하여 그 독에 중독되어야 합니다. 독에 걸릴 확률을 높이기 위해서는 거미를 죽여야 할 수도 있습니다. 중독되면 털보 존에게 돌아가서 그가 그 독을 추출하게 해야 합니다." },
      [4867] = { name = "우로크 둠하울", objective = "와로쉬의 두루마리를 읽어야 합니다. 와로쉬에게 그의 부적을 가져가야 합니다." },
      [4903] = { name = "장군의 명령", objective = "대군주 오모크와 대장군 부네, 대군주 웜타라크를 처단해야 합니다. 검은바위의 중요한 문서들을 확보해야 합니다. 임무를 완수하는 대로 카르가스의 장군 고어투스에게로 돌아가야 합니다." },
      [5081] = { name = "맥스웰의 임무", objective = "검은바위 첨탑으로 가서 대장군 부네와 대군주 오모크, 그리고 요새의 대군주 웜타라크를 처치해야 합니다. 임무를 완수하면 맥스웰 치안 대장에게 돌아가십시오." },
    },
  },
  zhCN = {
    dungeon = "黑石塔下层", location = "黑石山",
    bosses = { ["Spirestone Butcher"] = "尖石屠夫", ["Highlord Omokk"] = "欧莫克大王", ["Shadow Hunter Vosh'gajin"] = "暗影猎手沃什加斯", ["War Master Voone"] = "指挥官沃恩", ["Mother Smolderweb"] = "烟网蛛后", ["Crystal Fang"] = "水晶之牙", ["Urok Doomhowl"] = "乌洛克", ["Bannok Grimaxe"] = "班诺克·巨斧", ["Quartermaster Zigris"] = "军需官兹格雷斯", ["Halycon"] = "哈雷肯", ["Gizrul the Slavener"] = "奴役者基兹鲁尔", ["Ghok Bashguud"] = "霍克·巴什古德", ["Overlord Wyrmthalak"] = "维姆萨拉克" },
    quests = {
      [4701] = { name = "座狼之源", objective = "到黑石塔去摧毁那里的座狼源头。当你离开的时候，赫林迪斯喊出了一个名字：哈雷肯。这个词就是兽人语中“座狼”的意思。" },
      [4724] = { name = "座狼的首领", objective = "杀死血斧座狼的领袖，哈雷肯。" },
      [4729] = { name = "基布雷尔的特殊宠物", objective = "到黑石塔去找到血斧座狼幼崽。使用笼子来捕捉这些凶猛的小野兽，然后把笼中的座狼幼崽交给基布雷尔。" },
      [4742] = { name = "晋升印章", objective = "找到三块命令宝石：燃棘宝钻、尖石宝钻和血斧宝钻。把它们和原始晋升印章一起交给维埃兰。可能携带这三块宝石的将军是：燃棘氏族的指挥官沃恩、尖石氏族的欧莫克大王，以及血斧氏族的维姆萨拉克。" },
      [4862] = { name = "蜘蛛卵", objective = "到黑石塔去为基布雷尔收集15枚尖塔蜘蛛卵。听说那些蜘蛛周围有许多这样的卵。" },
      [4866] = { name = "蛛后的乳汁", objective = "你可以在黑石塔的中心地带找到烟网蛛后。与她战斗，让她在你体内注入毒汁。如果你有能力的话，就杀死她吧。当你中毒之后，回到狼狈不堪的约翰那儿，他会从你的身体里抽取这些“蛛后的乳汁”。" },
      [4867] = { name = "乌洛克", objective = "阅读瓦罗什的卷轴。将瓦罗什的魔精交给他。" },
      [4903] = { name = "高图斯的命令", objective = "杀死欧莫克大王、指挥官沃恩和维姆萨拉克。找到重要的黑石文件，然后向卡加斯的军官高图斯汇报。" },
      [5081] = { name = "麦克斯韦尔的任务", objective = "到黑石塔去消灭指挥官沃恩、欧莫克大王和维姆萨拉克。完成任务之后回到麦克斯韦尔元帅处复命。" },
    },
  },
  zhTW = {
    dungeon = "黑石塔下層", location = "黑石山",
    bosses = { ["Spirestone Butcher"] = "尖石屠夫", ["Highlord Omokk"] = "歐莫克大王", ["Shadow Hunter Vosh'gajin"] = "暗影獵手沃什加斯", ["War Master Voone"] = "指揮官沃恩", ["Mother Smolderweb"] = "煙網蛛後", ["Crystal Fang"] = "水晶之牙", ["Urok Doomhowl"] = "烏洛克", ["Bannok Grimaxe"] = "班諾克·巨斧", ["Quartermaster Zigris"] = "軍需官茲格雷斯", ["Halycon"] = "哈雷肯", ["Gizrul the Slavener"] = "奴役者基茲魯爾", ["Ghok Bashguud"] = "霍克·巴什古德", ["Overlord Wyrmthalak"] = "維姆薩拉克" },
    quests = {
      [4701] = { name = "座狼之源", objective = "到黑石塔去摧毀那裡的座狼源頭。當你離開的時候，赫林迪斯喊出了一個名字：哈雷肯。這個詞就是獸人語中“座狼”的意思。" },
      [4724] = { name = "座狼的首領", objective = "殺死血斧座狼的領袖，哈雷肯。" },
      [4729] = { name = "基布雷爾的特殊寵物", objective = "到黑石塔去找到血斧座狼幼崽。使用籠子來捕捉這些兇猛的小野獸，然後把籠中的座狼幼崽交給基布雷爾。" },
      [4742] = { name = "晉升印章", objective = "找到三塊命令寶石：燃棘寶鑽、尖石寶鑽和血斧寶鑽。把它們和原始晉升印章一起交給維埃蘭。可能攜帶這三塊寶石的將軍是：燃棘氏族的指揮官沃恩、尖石氏族的歐莫克大王，以及血斧氏族的維姆薩拉克。" },
      [4862] = { name = "蜘蛛卵", objective = "到黑石塔去為基布雷爾收集15枚尖塔蜘蛛卵。聽說那些蜘蛛周圍有許多這樣的卵。" },
      [4866] = { name = "蛛後的乳汁", objective = "你可以在黑石塔的中心地帶找到煙網蛛後。與她戰鬥，讓她在你體內注入毒汁。如果你有能力的話，就殺死她吧。當你中毒之後，回到狼狽不堪的約翰那兒，他會從你的身體裡抽取這些“蛛後的乳汁”。" },
      [4867] = { name = "烏洛克", objective = "閱讀瓦羅什的卷軸。將瓦羅什的魔精交給他。" },
      [4903] = { name = "高圖斯的命令", objective = "殺死歐莫克大王、指揮官沃恩和維姆薩拉克。找到重要的黑石檔案，然後向卡加斯的軍官高圖斯彙報。" },
      [5081] = { name = "麥克斯韋爾的任務", objective = "到黑石塔去消滅指揮官沃恩、歐莫克大王和維姆薩拉克。完成任務之後回到麥克斯韋爾元帥處覆命。" },
    },
  },
}
for lang, data in pairs(LBRS_LOC) do
    local content = FDJ.ContentLocales[lang] or {}
    FDJ.ContentLocales[lang] = content
    content.dungeons = content.dungeons or {}
    content.bosses = content.bosses or {}
    content.places = content.places or {}
    content.quests = content.quests or {}
    if content.dungeons["Lower Blackrock Spire"] == nil then
        content.dungeons["Lower Blackrock Spire"] = { name = data.dungeon, location = data.location or nil }
    end
    for english, localName in pairs(data.bosses or {}) do
        if content.bosses[english] == nil then content.bosses[english] = localName end
        if content.places[english] == nil then content.places[english] = localName end
    end
    for id, entry in pairs(data.quests or {}) do
        if content.quests[id] == nil then content.quests[id] = entry end
    end
end

