    [8257] = { name = "Morphaz' Blut", objective = "Tötet Morphaz im versunkenen Tempel von Atal'Hakkar und bringt Greta Mosshoof im Teufelswald sein Blut. Der Eingang zum versunkenen Tempel liegt in den Sümpfen des Elends." },
    [8236] = { name = "Der azurblaue Schlüssel", objective = "Bringt den azurblauen Schlüssel zu Lord Jorach Ravenholdt." },
    [8413] = { name = "Die Macht des Voodoos", objective = "Bringt Bath'rah dem Windbehüter die Voodoofedern." },
    [8422] = { name = "Federn von Trollen", objective = "Bringt 6 Voodoofedern von den Trollen aus dem versunkenen Tempel." },
    [8425] = { name = "Voodoofedern", objective = "Bringt die Voodoofedern der Trolle im versunkenen Tempel zu dem gefallenen Helden der Horde." },
    [4362] = { name = "Das Schicksal des Königreichs", objective = "Kehrt in die Blackrocktiefen zurück und rettet Prinzessin Moira Bronzebeard aus den Fängen des bösen Imperators Dagran Thaurissan." },
    [4003] = { name = "Die königliche Rettung", objective = "Tötet Imperator Dagran Thaurissan und befreit Prinzessin Moira Bronzebeard von seinem bösen Zauber." },
    [7201] = { name = "Das letzte Element", objective = "Begebt Euch in die Blackrocktiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hingemurmelt hat." },
    [4286] = { name = "Feine Sachen", objective = "Reist in die Blackrocktiefen und holt 20 Dunkeleisengürteltaschen. Kehrt zu Oralius zurück, sobald die Aufgabe erledigt ist. Ihr nehmt an, dass die Dunkeleisenzwerge in den Blackrocktiefen diese 'Gürteltaschen'-Dinger tragen." },
    [7848] = { name = "Abstimmung mit dem Kern", objective = "Begebt Euch zum Portal in den Blackrocktiefen, das in den geschmolzenen Kern führt, und findet ein Kernfragment. Kehrt mit dem Fragment zu Lothos Riftwaker am Blackrock zurück." },
    [5001] = { name = "Bijous Habseligkeiten", objective = "Sucht Bijous Habseligkeiten und bringt sie ihr. Viel Glück!" },
    [4982] = { name = "Bijous Habseligkeiten", objective = "Sucht Bijous Habseligkeiten und bringt sie ihr. Ihr erinnert Euch daran, dass sie erwähnte, ihre Sachen auf der untersten Ebene der Stadt versteckt zu haben." },
    [4788] = { name = "Die letzten Schrifttafeln", objective = "Bringt Ausgrabungsleiter Ironboot in Tanaris die fünfte und sechste Schrifttafel von Mosh'aru." },
    [6569] = { name = "Oculus-Illusionen", objective = "Reist zur Blackrockspitze und sammelt 20 schwarze Drachenbrutaugen. Kehrt zu Myranda der Vettel zurück, sobald Ihr die Aufgabe erfüllt habt." },
    [4764] = { name = "Doomriggers Schnalle", objective = "Bringt Mayara Brightwing in der brennenden Steppe Doomriggers Schnalle." },
    [4768] = { name = "Die Darkstone-Schrifttafel", objective = "Bringt der Schattenmagierin Vivian Lagrave in Kargath die Darkstone-Schrifttafel." },
    [5160] = { name = "Die oberste Beschützerin", objective = "Begebt Euch nach Winterspring und sucht Haleh. Gebt ihr Awbees Schuppe." },
    [5526] = { name = "Die Splitter der Teufelsranke", objective = "Sucht die Teufelsranke in Düsterbruch und nehmt einen Teufelsrankensplitter mit Euch. Aller Wahrscheinlichkeit nach, werdet Ihr Alzzin den Wildformer töten müssen, um an die Teufelsranke zu gelangen. Benutzt das Requiliar der Reinheit, um darin den Splitter sicher zu versiegeln und bringt das versiegelte Reliquiar zu Rabine Saturna in Nighthaven, Moonglade." },
    [7463] = { name = "Arcane Erfrischung", objective = "Reist nach Düsterbruch in das Wucherborkenviertel und besiegt den Wasserelementar Hydrobrut. Kehrt anschließend mit der Hydrobrutessenz, zum Hüter des Wissens Lydros im Athenaeum zurück." },
    [7461] = { name = "Der innere Wahnsinn", objective = "Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen. Betretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Anschließend müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten. Kehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück." },
    [5247] = { name = "Fragmente der Vergangenheit", objective = "Bringt einen verzauberten Thoriumbarren, 5 Kristallflicker und eine Phiole mit Düsterwasser zu Aurora Skycaller beim Nordpassturm in den östlichen Pestländern." },
    [7643] = { name = "Der uralte Pferdegeist", objective = "Beschafft spezielles Pferdefutter mit dem man ein Geisterpferd füttern kann. Meredith Carlson in Southshore scheint dafür eine recht gute Quelle zu sein. Reist anschließend nach Düsterbruch in Feralas und tötet Tendris Wucherborke. Dies wird den uralten Pferdegeist befreien. Füttert den Geist zur Beruhigung mit dem speziellen Pferdefutter. Gebt dem Pferdegeist das Arkanitpferdegeschirr, um es segnen zu lassen." },
    [7631] = { name = "Schreckensross von Xoroth", objective = "Lest Morzuls Anweisungen. Beschwört ein xorothianisches Schreckensross, besiegt es und bindet seinen Geist an Euch." },
    [7506] = { name = "Der Smaragdgrüne Traum", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
    [7503] = { name = "Das größte Volk von Jägern", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
    [7500] = { name = "Das Arkanistenkochbuch", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
    [7501] = { name = "Vom Licht und wie man es schwingt", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
    [7504] = { name = "Heiliger Fleischklops: Was das Licht Dir nicht erzählt", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
    [7498] = { name = "Garona: Eine Studie über Heimlichkeit und Verrat", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
    [7505] = { name = "Frostschock und Du", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
    [7502] = { name = "Schatten einspannen", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
    [7499] = { name = "Kodex der Verteidigung", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück." },
    [7629] = { name = "Wichtellieferung", objective = "Bringt den Wichtel im Gefäß in das Alchimielabor in der Scholomance. Bringt nach der Herstellung des Pergaments, dass Gefäß zurück zu Gorzeeki Wildeyes." },
    [7647] = { name = "Gerechtigkeit und Erlösung", objective = "Benutzt das Orakel der Anrufung im Herzen des Kellergewölbes des großen Ossuariums, in Scholomance. Damit ruft Ihr die verfluchten Geister, über deren Schicksal Ihr richten müsst. Durch das besiegen der Geister wird der Todesritter Schattensichel beschworen. Besiegt ihn und holt Euch die verlorene Seele des gefallenen Streitrosses. Gebt die Seele des gefallenen Streitrosses und das gesegnete und verzauberte Pferdegeschirr Schattensichels gefallenem Streitross zurück." },
    [7668] = { name = "Die Bedrohung durch Schattensichel", objective = "Wendet das Orakel der Anrufung inmitten des Kellergewölbes des großen Ossuariums in Scholomance an. Ihr werdet damit Geister herbeirufen, die es zu bekämpfen gilt. Nach Vernichtung dieser Geister wird der Todesritter Schattensichel auftauchen; besiegt ihn. Bringt Schattensichels Kopf zu Sagorne Creststrider im Tal der Weisheit in Orgrimmar." },
    [5463] = { name = "Menethils Geschenk", objective = "Begebt Euch nach Stratholme und sucht Menethils Geschenk. Platziert das Andenken der Erinnerung auf dem unheiligen Boden." },
    [261] = { name = "Auf dem Scharlachroten Pfad", objective = "Vernichtet 30 untote Verheerer und kehrt dann zu Bruder Anton auf die Nijelspitze zurück." },
    [1052] = { name = "Auf dem Scharlachroten Pfad", objective = "Bringt Raleigh dem Andächtigen in Southshore Bruder Antons Empfehlungsschreiben." },
    [6522] = { name = "Eine unheilige Allianz", objective = "Bringt die kleine Rolle zu Varimathras nach Undercity." },
    [720] = { name = "Ein Hoffnungsschimmer", objective = "Sucht Ausgrabungsleiter Ryedol und teilt ihm mit, dass Hammertoe Grez noch am Leben ist." },
    [738] = { name = "Sucht Agmond", objective = "." },
    [739] = { name = "Murdaloc", objective = "Tötet Agmonds Mörder Murdaloc. Tötet 12 Knochenknacker der Steingrufttroggs. Erstattet Ausgrabungsleiter Ironband am Loch Modan Bericht." },
    [723] = { name = "Ein Funken Hoffnung", objective = "Bringt Ausgrabungsleiter Ryedol im Ödland Hammertoes Amulett." },
    [724] = { name = "Ein Funken Hoffnung", objective = "Bringt Historiker Karnik in Ironforge Hammertoes Amulett." },
    [725] = { name = "Kunde über die Bedrohung breitet sich aus", objective = "Sucht Berater Belgrum und gebt ihm die Notiz." },
    [726] = { name = "Kunde über die Bedrohung breitet sich aus", objective = "Sprecht mit Historiker Karnik." },
    [762] = { name = "Ein Botschafter des Bösen", objective = "Tötet den Botschafter Infernus in der Festung Angor und bringt Berater Belgrum in Ironforge einen Beweis seines Tod." },
    [2198] = { name = "Die zerrissene Halskette", objective = "Sucht nach dem Erschaffer der zerrissenen Halskette, um etwas über ihren möglichen Wert zu erfahren." },
    [2199] = { name = "Lehren haben ihren Preis", objective = "Bringt fünf Silberbarren zu Talvash del Kissel in Ironforge." },
    [2200] = { name = "Rückkehr nach Uldaman", objective = "Sucht in Uldaman nach Hinweisen auf den momentanen Zustand von Talvashs Halskette. Der getötete Paladin, den Talvash erwähnte, hatte die Kette zuletzt." },
    [2318] = { name = "Übersetzung des Tagebuchs", objective = "Sucht jemanden, der das Tagebuch des Paladins übersetzen kann. Der nächstgelegene Ort, wo Ihr so jemanden finden könntet, ist Kargath im Ödland." },
    [2338] = { name = "Übersetzung des Tagebuchs", objective = "Leiht Jarkal die Halskette. Im Gegenzug wird er das Tagebuch für Euch übersetzen." },
    [2500] = { name = "Reagenzien-Suche im Ödland", objective = "Beschafft die Reagenzien, die Ghak Healtouch aus dem Ödland braucht, und bringt sie ihm nach Thelsamar." },
    [2258] = { name = "Reagenzien-Suche im Ödland", objective = "Bringt Jarkal Mossmeld in Kargath im Ödland 5 Bussard-Mägen, 10 Klippenkojoten-Fangzähne und 5 Felselementarsplitter." },
    [1954] = { name = "Die Höllenkugel", objective = "Bringt eine Höllenkugel zu Tabetha in den Marschen von Dustwallow." },
    [1955] = { name = "Die Austreibung", objective = "Tötet den Dämon der Kugel und sprecht dann mit Tabetha." },
    [2988] = { name = "Käfige der Witherbark", objective = "Durchsucht die Käfige in den beiden Dörfern der Witherbark und kehrt dann zu Greifenmeister Talonaxe zurück." },
    [2989] = { name = "Der Altar von Zul", objective = "Überprüft die Oberfläche des Altars von Zul und kehrt dann zu Greifenmeister Talonaxe zurück." },
    [2990] = { name = "Thadius Grimshade", objective = "Bringt Scharfschnabels Feder zu Thadius Grimshade in die verwüsteten Lande." },
    [2933] = { name = "Giftflaschen", objective = "Bringt eine Giftflasche zu einem Apotheker nach Tarrens Mühle." },
    [2934] = { name = "Unbeschädigter Giftbeutel", objective = "Bringt Apotheker Lydon in Tarrens Mühle einen unbeschädigten Giftbeutel." },
    [2935] = { name = "Konsultiert Meister Gadrin", objective = "Sprecht mit Meister Gadrin in Sen'jin." },
    [3520] = { name = "Kreischergeister", objective = "Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya in Steamwheedle zurück." },
    [1448] = { name = "Auf der Suche nach dem Tempel", objective = "Brohann Caskbelly in Stormwind möchte, dass Ihr den Tempel von Atal'Hakkar sucht." },
    [1449] = { name = "Ins Hinterland", objective = "Sprecht mit dem obersten Than, Falstad Wildhammer, in Aerie Peak im Hinterland." },
    [1450] = { name = "Greifenmeister Talonaxe", objective = "Sprecht mit Greifenmeister Talonaxe im Horst bei Aerie Peak." },
    [1451] = { name = "Rhapsody-Shindigger", objective = "Sucht Rhapsody Shindigger im Hinterland." },
    [1452] = { name = "Rhapsodys Kalimdor-Cocktail", objective = "Rhapsody Shindigger im Hinterland möchte, dass Ihr ihm 3 Muskelmägen eines Roc, 3 Groddoc-Lebern und 3 Eisenfelllebern bringt." },
    [1469] = { name = "Rhapsodys Geschichte", objective = "Bringt das Schrifttafelfragment der Atal'ai zu Brohann Caskbelly in Stormwind." },
    [1424] = { name = "Tränenteich", objective = "Fel'Zerul in Stonard möchte, dass Ihr 10 Artefakte der Atal'ai sammelt." },
    [1429] = { name = "Der Verbannte der Atal'ai", objective = "Bringt das Artefaktbündel der Atal'ai zu dem Verbannten der Atal'ai ins Hinterland." },
    [1444] = { name = "Rückkehr zu Fel'Zerul", objective = "Kehrt zu Fel'Zerul in Stonard zurück." },
    [3444] = { name = "Der runde Stein", objective = "Holt den runden Stein aus Marvon Rivetseekers Werkstatt in Ratchet." },
    [4787] = { name = "Das uralte Ei", objective = "Bringt das uralte Ei zu Yeh'kinya nach Tanaris." },
    [4141] = { name = "Muigin und Larion", objective = "Sammelt 15 Blutblüten und kehrt zu Muigin zurück." },
    [4142] = { name = "Ein Besuch bei Gregan", objective = "Bringt Gregan Brewspewer in Feralas eine Blutblüte." },
    [4145] = { name = "Larion und Muigin", objective = "Jagt 5 Blutblütenpeitscher, 5 Blutblütendrescher, 5 Blutblütenschinder und 5 Blutblütenfallen für Larion in Marshals Zuflucht." },
    [4147] = { name = "Marvons Werkstatt", objective = "Reist zu Marvon Rivetseekers Werkstatt in Ratchet." },
    [9052] = { name = "Blutblütengift", objective = "Sammelt Blutkappenpilze und Gorishistachel und kehrt zu Torwa Pathfinder im Un'Goro Krater zurück." },
    [9051] = { name = "Giftexperiment", objective = "Stecht einen Teufelssaurier mit dem Teufelssaurierhaken." },
    [8153] = { name = "Gehörnte Renner", objective = "Bringt ein perfektes Rennergeweih zu Ogtinc nach Azshara. Er befindet sich auf den Klippen nordöstlich der Ruinen von Eldarath." },
    [8231] = { name = "Wellenjagd", objective = "Bringt 6 Wellenhauerschuppen zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath." },
    [8251] = { name = "Magischer Staub", objective = "Bringt Erzmagier Xylem in Azshara 10 glitzernde Staubproben." },
    [8252] = { name = "Die Koralle der Sirenen", objective = "Sammelt 6 verzauberte Korallen und bringt sie zum Erzmagier Xylem." },
    [8414] = { name = "Austreibung des Bösen", objective = "Sammelt 20 Geißelsteine des Dieners und bringt sie zu Hohepriester Thel'danis in den westlichen Pestländern." },
    [8416] = { name = "Gereinigte Geißelsteine", objective = "Bringt den gereinigten Geißelstein zu Kommandant Ashlan Valorfist an der Chillwindspitze." },
    [8255] = { name = "Renner für einen höheren Zweck", objective = "Beschafft 4 gesunde Rennerdrüsen und bringt sie zu Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath." },
    [8256] = { name = "Sekret des Untodes", objective = "Beschafft ein Sekret des Untodes für Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath." },
    [8234] = { name = "Die versiegelte azurblaue Tasche", objective = "Erlangt die versiegelte azurblaue Tasche von dem Schamanen der Holzschlundfeste in Azshara zurück. Bringt sie anschließend zum Erzmagier Xylem, der ebenfalls in Azshara zu finden ist." },
    [8235] = { name = "Verschlüsselte Fragmente", objective = "Bringt Erzmagier Xylem in Azshara 10 verschlüsselte Fragmente." },
    [8410] = { name = "Elementarbeherrschung", objective = "Bath'rah der Windbehüter möchte, dass Ihr jeweils eine Probe Luft, Feuer, Erde und Wasser für ihn sammelt." },
    [8412] = { name = "Geistertotem", objective = "Bringt Bath'rah dem Windbehüter die Komponenten für das Geistertotem." },
    [8419] = { name = "Die Bitte eines Wichtels", objective = "Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald." },
    [8420] = { name = "Heiß und brennend", objective = "Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald." },
    [8421] = { name = "Das richtige Zeug", objective = "Bringt 10 Stück faules Holz und 4 Blutgiftessenzen zu Impsy im Teufelswald." },
    [8423] = { name = "Kriegerverwandtschaft", objective = "Tötet 7 Hölleneber in den verwüsteten Landen und kehrt zu dem gefallenen Helden der Horde zurück." },
    [8424] = { name = "Krieg den Schattenanbetern", objective = "Merzt die Schattenanbeter in den verwüsteten Landen aus und kehrt zum gefallenen Helden der Horde zurück." },
    [3801] = { name = "Dunkeleisenerbe", objective = "Sprecht mit Franclorn Forgewright, wenn Ihr daran interessiert seid, einen Schlüssel für die Hauptstadt zu erhalten." },
    [4262] = { name = "Übermeister Pyron", objective = "Erschlagt Übermeister Pyron und kehrt dann zu Jalinda Sprig zurück. Ihr erinnert Euch an Jalindas Worte, dass Pyron den Steinbruch bewachen würde. Vielleicht solltet Ihr dort nachsehen?" },
    [3702] = { name = "Die glimmenden Ruinen von Thaurissan", objective = "Hört die Erzählung der königlichen Historikerin Archesonus über die Geschichte von Thaurissan." },
    [3701] = { name = "Die glimmenden Ruinen von Thaurissan", objective = "Begebt Euch zu den Ruinen von Thaurissan in der brennenden Steppe und sammelt Informationen über die Thaurissan-Relikte. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt." },
    [4341] = { name = "Kharan Mighthammer", objective = "Begebt Euch in die Blackrocktiefen und findet Kharan Mighthammer. Der König erwähnte, dass Kharan dort gefangen sei - vielleicht solltet Ihr nach einem Gefängnis Ausschau halten." },
    [4342] = { name = "Kharans Geschichte", objective = "Lasst Kharan Mighthammer seine Geschichte erzählen." },
    [4361] = { name = "Der Überbringer schlechter Botschaften...", objective = "Kehrt nach Ironforge zurück und überbringt König Magni Bronzebeard die schlechten Nachrichten." },
    [4182] = { name = "Drachkin-Bedrohung", objective = "Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 schwarze Wyrmkin und 1 Schwarzdrachen. Kehrt zu Helendis Riverhorn zurück, sobald die Aufgabe erledigt ist." },
    [4183] = { name = "Die wahren Meister", objective = "Reist nach Seenhain und händigt Magistrat Solomon Helendis Riverhorns Brief aus." },
    [4184] = { name = "Die wahren Meister", objective = "Reist nach Stormwind und tragt Solomons Hilfegesuch dem Hochlord Bolvar Fordragon vor. Bolvar residiert in der Burg Stormwind." },
    [4185] = { name = "Die wahren Meister", objective = "Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon." },
    [4186] = { name = "Die wahren Meister", objective = "Händigt Bolvars Erlass an Magistrat Solomon in Seenhain aus." },
    [4223] = { name = "Die wahren Meister", objective = "Sprecht mit Marshal Maxwell in der brennenden Steppe." },
    [4224] = { name = "Die wahren Meister", objective = "Sprecht mit dem struppigen John, um etwas über Marshal Windsors Schicksal zu erfahren, und kehrt dann zu Marshal Maxwell zurück, wenn Ihr diese Aufgabe erledigt habt. Ihr erinnert Euch daran, dass Marshal Maxwell Euch geraten hat, ihn in einer Höhle im Norden zu suchen." },
    [4241] = { name = "Marshal Windsor", objective = "Reist zum Blackrock im Nordwesten und dann weiter zu den Blackrocktiefen. Findet heraus, was aus Marshal Windsor geworden ist. Ihr erinnert Euch daran, dass der struppige John sagte, man hätte Windsor in ein Gefängnis verschleppt." },
    [4242] = { name = "Verlorene Hoffnung", objective = "Überbringt Marshal Maxwell die schlechten Neuigkeiten." },
    [4264] = { name = "Eine zusammengeknüllte Notiz", objective = "Soeben seid Ihr auf etwas gestoßen, das Marshal Windsor mit Sicherheit sehr interessiert. Vielleicht besteht ja doch noch Hoffnung." },
    [4282] = { name = "Ein Funken Hoffnung", objective = "Holt Marshal Windsors verloren gegangene Informationen zurück. Marshal Windsor glaubt, dass sich die Informationen in den Händen des Golemlords Argelmach und des Generals Zornesschmied befinden." },
    [3906] = { name = "Disharmonie der Flamme", objective = "Reist zum Steinbruch am Blackrock und tötet Übermeister Pyron. Kehrt zu Thunderheart zurück, sobald Ihr den Auftrag erledigt habt." },
    [3981] = { name = "Kommandant Gor'shak", objective = "Sucht Kommandant Gor'shak in den Blackrocktiefen. Ihr erinnert Euch, dass auf dem primitiv gezeichneten Bild des Orcs auch Gitter vor dem Gesicht zu sehen waren. Vielleicht solltet Ihr nach einer Art Gefängnis suchen." },
    [3982] = { name = "Was ist los?", objective = "Verteidigt Gor'shak." },
    [4001] = { name = "Was ist los?", objective = "Sprecht mit Kharan Mighthammer und sammelt Informationen über die Entführung von Prinzessin Moira Bronzebeard. Bringt diese Informationen dann zu Thrall nach Orgrimmar. Ihr erinnert Euch, dass Gor'shak gesagt hat, Kharan werde in einer Zelle in seiner Nähe festgehalten." },
    [4002] = { name = "Das östliche Königreich", objective = "Sprecht mit Thrall, wenn Ihr bereit seid, die von ihm geplante Mission zu übernehmen." },
    [4081] = { name = "SOFORT TÖTEN: Dunkeleisenzwerge", objective = "Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren! Kriegsherr Goretooth möchte, dass Ihr 15 Gardisten der Zorneshämmer, 10 Aufseher der Zorneshämmer und 5 Fußsoldaten der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt." },
    [4122] = { name = "Grark Lorkrub", objective = "Begebt Euch in die brennende Steppe und sucht Grark Lorkrub. Ihr erinnert Euch, dass Lexlort gesagt hat, er sei zuletzt in einer großen Festung der Blackrock gesehen worden. Wenn Ihr Grark Lorkrub gefunden habt, verwendet die Thoriumfesseln, um ihn zu binden, und bringt ihn dann über den Blackrock in die sengende Schlucht zurück. Lexlorts Männer werden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen." },
    [4121] = { name = "Gefährliche Zwickmühle", objective = "Eskortiert Euren Gefangenen, Grark Lorkrub, durch die brennende Steppe und durch den Blackrock in die sengende Schlucht. Euch fällt ein, dass Lexlort gesagt hat, seine Männer würden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen. Ihr werdet außerdem Eure Thoriumfesseln an Lexlort übergeben müssen." },
    [4061] = { name = "Aufstieg der Maschinen", objective = "Begebt Euch in die brennende Steppe und beschafft für Theodora Mulvadania 10 gerissene Elementarsplitter. Euch fällt ein, dass Theodora gesagt hat, die Golems und Elementare in der Gegend seien eine gute Quelle für solche Splitter." },
    [4062] = { name = "Aufstieg der Maschinen", objective = "Bringt die Elementarsplitterprobe zu Lotwil Veriatus. Ihr erinnert Euch, dass Theodora sagte, Lotwil sei in einem Lager im Osten stationiert." },
    [5002] = { name = "Nachricht an Maxwell", objective = "Begebt Euch in die brennende Steppe und leitet Bijous Informationen an Marshal Maxwell weiter." },
    [4981] = { name = "Agentin Bijou", objective = "Begebt Euch zur Blackrockspitze und findet heraus, was aus Bijou geworden ist." },
    [5065] = { name = "Die verlorenen Schrifttafeln von Mosh'aru", objective = "Bringt Ausgrabungsleiter Ironboot in Tanaris die dritte und vierte Schrifttafel von Mosh'aru." },
    [4726] = { name = "Brutlingessenz", objective = "Bringt 8 Brutlingessenzen sowie den Draco-Incarcinatrix 900 zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe." },
    [4808] = { name = "Felnok Steelspring", objective = "Gebt Felnok Steelspring Tinkees Brief." },
    [4809] = { name = "Hörner der Eiswindschimären", objective = "Bringt Felnok Steelspring 8 unbeschädigte Hörner einer Eiswindschimäre." },
    [4810] = { name = "Rückkehr zu Tinkee", objective = "Bringt Tinkee Steamboil in der brennenden Steppe Felnoks Päckchen." },
    [4907] = { name = "Tinkee Steamboil", objective = "Sprecht mit Tinkee Steamboil." },
    [4734] = { name = "Ei-Frosten", objective = "Benutzt den Prototyp des Eiszilloskops an einem Ei im Horst." },
    [4903] = { name = "Befehl des Kriegsherrn", objective = "Tötet Hochlord Omokk, Kriegsmeister Voone und Oberanführer Wyrmthalak. Findet die wichtigen Blackrockdokumente. Kehrt zum Kriegsherrn Goretooth nach Kargath zurück, sobald Ihr diese Mission erledigt habt." },
    [4941] = { name = "Eitriggs Weisheit", objective = "Sprecht mit Etrigg in Orgrimmar. Wenn Ihr die Angelegenheit mit Etrigg besprochen habt, bittet Thrall um Rat. Ihr erinnert Euch, dass Ihr Etrigg in Thralls Gemächern gesehen habt." },
    [4974] = { name = "Für die Horde!", objective = "Begebt Euch zur Blackrockspitze und tötet den Kriegshäuptling Rend Blackhand. Nehmt seinen Kopf und kehrt nach Orgrimmar zurück." },
    [6566] = { name = "Was der Wind erzählt", objective = "Hört Thrall zu." },
    [6567] = { name = "Der Champion der Horde", objective = "Sucht Rexxar auf. Der Kriegshäuptling hat Euch erklärt, wo Ihr ihn finden könnt. Sucht die Wege von Desolace zwischen dem Steinkrallengebirge und Feralas ab." },
    [6568] = { name = "Nachricht von Rexxar", objective = "Überbringt Myranda der Vettel in den westlichen Pestländern Rexxars Nachricht." },
    [6402] = { name = "Treffen in Stormwind", objective = "Reist nach Stormwind und begebt Euch zu den Stadttoren. Sprecht mit Knappe Rowe, damit er Marshal Windsor über Eure Ankunft informiert." },
    [6403] = { name = "Die große Maskerade", objective = "Folgt Reginald Windsor durch Stormwind. Schützt ihn vor Gefahren!" },
    [6501] = { name = "Das Großdrachenauge", objective = "Ihr müsst die Welt nach jemandem absuchen, der fähig ist, die Macht des Fragments des Großdrachenauges wieder herzustellen. Die einzige Information, die Ihr über ein solches Wesen besitzt ist, dass es existiert." },
    [6570] = { name = "Aschenschwinge", objective = "Reist zum Drachensumpf in den Marschen von Dustwallow und begebt Euch in Aschenschwinges Bau. Sobald Ihr darin seid, tragt das Amulett der drachischen Subversion und sprecht mit Aschenschwinge." },
    [6582] = { name = "Die Prüfung der Schädel, Scryer", objective = "Ihr müsst Scryer, den Champion der blauen Großdrachen, finden und ihn töten. Schlagt seinem Kadaver den Schädel ab und bringt ihn zu Aschenschwinge. Ihr wisst, dass Scryer in Winterspring zu finden ist." },
    [6583] = { name = "Die Prüfung der Schädel, Somnus", objective = "Vernichtet den Drachenchampion des grünen Drachenschwarms, Somnus. Nehmt seinen Schädel und bringt ihn zu Aschenschwinge zurück." },
    [6584] = { name = "Die Prüfung der Schädel, Chronalis", objective = "Chronalis, ein Kind Nozdormus, bewacht die Höhlen der Zeit in der Tanariswüste. Vernichtet ihn und bringt seinen Schädel zu Aschenschwinge." },
    [6585] = { name = "Die Prüfung der Schädel, Axtroz", objective = "Begebt Euch nach Grim Batol und spürt Axtroz auf, den Drachenchampion des Roten Drachenschwarms. Vernichtet ihn und nehmt seinen Schädel. Bringt den Schädel zu Aschenschwinge zurück." },
    [6601] = { name = "Aufstieg...", objective = "Mir scheint, als sei die Charade jetzt vorüber. Ihr wisst, dass das Amulett der drachischen Unterwanderung, das Myranda die Vettel für Euch erschuf, auf der Blackrockspitze nicht funktioniert. Vielleicht solltet Ihr Rexxar aufsuchen und ihm Eure Notlage erklären. Zeigt ihm das glanzlose Drachenfeueramulett. Er wird hoffentlich wissen, was als Nächstes zu tun ist." },
    [5089] = { name = "General Drakkisaths Befehl", objective = "Bringt den Befehl von General Drakkisath zu Marshal Maxwell in der brennenden Steppe." },
    [5527] = { name = "Ein Reliquiar der Reinheit", objective = "Reist nach Silithus und sucht in den Ruinen des Südwindpostens nach einem Reliquiar der Reinheit. Sollte Eure Suche Erfolg haben, kehrt zu Rabine Saturna in Nighthaven, Moonglade zurück." },
    [5244] = { name = "Die Ruinen von Kel'Theril", objective = "Sprecht mit Jaron Stoneshaper in Starfall." },
    [5245] = { name = "Die gequälten Seelen von Kel'Theril", objective = "Benutzt Jarons Hacke, um die vier Fragmente des Hochgeborenenrelikts zu suchen. Bringt sie zu Aurora Skycaller in den Östlichen Pestländern." },
    [5246] = { name = "Fragmente der Vergangenheit", objective = "Sucht die hochheiligen Schriften der Hochgeborenen im Tempel von Zin-Malor in Azshara und bringt sie zu Aurora Skycaller beim Nordpassturm in den östlichen Pestländern." },
    [7637] = { name = "Ein Opfer darbieten", objective = "Reist nach Ironforge und besorgt Euch Hohepriester Rohans Weihrauchschwenker. Eine Spende von 150 Gold wird erforderlich sein, um es zu bekommen." },
    [7639] = { name = "Lass Gerechtigkeit walten", objective = "Bringt den Weihrauchschwenker zu Lord Grayson Shadowbreaker in Stormwind zurück." },
    [7640] = { name = "Der Exorzismus des Schreckenstals", objective = "Vertreibt mit Hilfe des Weihrauchschwenkers die Geister im Schreckenstal. Vernichtet 25 Schreckenstalgeister und kehrt anschließend zu Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind zurück." },
    [7641] = { name = "Grimand Elmores Werk", objective = "Sprecht mit Grimand Elmore im Zwergendistrikt von Stormwind." },
    [7642] = { name = "Fünf Dinge", objective = "Bringt 40 Lagen Runenstoff, 6 Arkanitbarren, 10 Artha's Tränen, 5 Phiolen heiliges Wasser aus Stratholme und 150 Gold zu Grimand Elmore im Zwergendistrikt von Stormwind." },
    [7648] = { name = "Grimands feinste Arbeit", objective = "Bringt das Arkanitpferdegeschirr zur Begutachtung zu Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind." },
    [7645] = { name = "Mit Mana angereichertes Pferdefutter", objective = "Treibt 20 angereicherte Manakekse - die ausschlaggebende Zutat für die Herstellung von mit Mana angereichertem Pferdefutter - für Merideth Carlson aus Southshore in dem Vorgebirge von Hillsbrad auf. Die Argentumdämmerung ist als alleiniger Händler dieser Kekse bekannt. Zusätzlich müsst Ihr ihre Gefühle noch mit 50 Goldstücken besänftigen." },
    [7563] = { name = "Kochendes Blut", objective = "Mor'zul Bloodbringer in der brennenden Steppe möchte, dass Ihr ihm 30 Flaschen mit dem Blut der tobenden Bestien bringt." },
    [7564] = { name = "Garzeeki Wildeyes", objective = "Bringt den Behälter mit Blut zu Gorzeeki Wildeyes in der brennenden Steppe." },
    [7623] = { name = "Lord Banehollow", objective = "Erwerbt schattenhaftige Tränke von Gorzeeki in der brennenden Steppe. Benutzt die Tränke um durch Jaedenar zu reisen und sprecht mit Lord Banehollow." },
    [7624] = { name = "Ulathek der Verräter", objective = "Stellt Euch Ulathek und bringt das Herz des Verräters zu Lord Banehollow in Jaedenar." },
    [7625] = { name = "Xorothianischer Sternenstaub", objective = "Erwerbt xorothianischen Sternenstaub von Ur'dan. Bringt es anschließend Gorzeeki in der brennenden Steppe." },
    [7626] = { name = "Die Glocke von Dethmoora", objective = "Bringt 10 Elixiere der Schattenmacht zu Gorzeeki Wildeyes in die brennende Steppe." },
    [7627] = { name = "Das Rad des Schwarzen Marsches", objective = "Bringt 6 große glänzende Splitter und 25 Stücke Dunkeleisenerz zu Gorzeeki Wildeyes in die brennende Steppe." },
    [7628] = { name = "Die Altarkerze des Jüngsten Gerichts", objective = "Bringt 35 Schuppen eines schwarzen Drachen zu Gorzeeki Wildeyes in der brennenden Steppe." },
    [7630] = { name = "Arkanit", objective = "Bringt 3 Arkanitbarren zu Gorzeeki in der brennenden Steppe." },
    [5461] = { name = "Der Mensch Ras Frostraunen", objective = "Reist in das Arathihochland zu den Ruinen von Stromgarde. Durchsucht Stromgarde nach einem Andenken der Erinnerung. Wenn Ihr einen solchen Gegenstand findet, kehrt mit ihm zu Magistrat Marduke zurück." },
    [5462] = { name = "Der Sterbende Ras Frostraunen", objective = "Reist zur Hoffnung des Lichts in den Östlichen Pestländern und sucht Leonid Barthalomew den Geachteten auf. Zeigt ihm das Andenken der Erinnerung und berichtet ihm alles, was Ihr entdeckt habt." },
    [5464] = { name = "Menethils Geschenk", objective = "Bringt das seelengebundene Andenken zu Leonid Barthalomew in den Östlichen Pestländern." },
    [5465] = { name = "Seelengebundenes Andenken", objective = "Kehrt zu Magistrat Marduke in Caer Darrow zurück. Zeigt ihm das seelengebundene Andenken." },
    [5522] = { name = "Leonid Barthalomew", objective = "Bringt die gefrorenen Eier zu Leonid Barthalomew in den Östlichen Pestländern." },
    [5531] = { name = "Betina Bigglezink", objective = "Bringt die gefrorenen Eier zu Betina Bigglezink." },
    [7644] = { name = "Gesegnetes Arkanitpferdegeschirr", objective = "Kehrt mit dem gesegneten Arkanitpferdegeschirr zu Lord Grayson Shadowbreaker in das Kathedralenviertel von Stormwind zurück." },
    [7646] = { name = "Das Orakel der Anrufung", objective = "Bringt Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind einen Azerothianischen Diamanten und einen makellosen schwarzen Diamanten." },
    [7667] = { name = "Materielle Unterstützung", objective = "Wenn Ihr Sagorne Crestrider im Tal der Weisheit von Orgrimmar helfen wollt, so bringt ihm einen azerothianischen und einen makellosen schwarzen Diamanten." },
    [5251] = { name = "Der Archivar", objective = "Reist nach Stratholme und sucht Archivar Galford vom Scharlachroten Kreuzzug. Vernichtet ihn und verbrennt das Scharlachrote Archiv." },
    [5542] = { name = "Dämonenhunde", objective = "Erschlagt 20 kleine Seuchenhunde, 5 Seuchenhunde und 5 rasende Seuchenhunde. Kehrt zu Tirion Fordring zurück, sobald Ihr die Aufgabe erfüllt habt." },
    [5543] = { name = "Blutgefärbter Himmel", objective = "Erschlagt 30 Seuchenfledermäuse und kehrt zu Tirion Fordring zurück." },
    [5544] = { name = "Aassammlung", objective = "Sucht nach den Aaslarven und Aasverschlingern dieses Gebiets. Erschlagt sie und sammelt ihr Fleisch. Kehrt zu Tirion Fordring zurück, wenn Ihr 15 Scheiben Aaswurmfleisch gesammelt habt." },
    [5742] = { name = "Erlösung", objective = "Hört Euch an, was Tirion Fordring zu sagen hat." },
    [5781] = { name = "Von vergessenen Erinnerungen", objective = "Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt." },
    [5845] = { name = "Von verlorener Ehre", objective = "Reist nach Northdale im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt." },
    [5846] = { name = "Von Liebe und Familie", objective = "Begebt Euch zur Insel Caer Darrow im südlich-zentralen Bereich der Pestländer und sucht nach Hinweisen, wo sich das Gemälde befinden könnte." },
    [5262] = { name = "Die Wahrheit zeigt sich mit Macht", objective = "Bringt den Kopf von Balnazzar zu Fürst Nicholas Zverenhoff in den Östlichen Pestländern." },
    [6133] = { name = "Das Ersuchen des Waldläuferlords", objective = "Begebt Euch zur nördlichsten Grenze der Östlichen Pestländer und bringt die Quel'Thalas-Registratur zurück. Der Gegenstand befindet sich irgendwo in der Quel'Lithien-Lodge. Außerdem müsst Ihr 8 Waldläufer, 8 Pfadschreiter und 8 Waldarbeiter töten." },
    [6042] = { name = "Die kleinen Ärgernisse des Un-Lebens", objective = "Erschlagt 20 giftige Seuchenfledermäuse und 10 monströse Seuchenfledermäuse. Kehrt zu Nathanos Blightcaller zurück, wenn Ihr fertig seid." },
    [6022] = { name = "Töten zu einem bestimmten Zweck", objective = "Begebt Euch zu Corins Kreuzung im Osten und besiegt die Mitglieder der Geißel, die in der Stadt leben. Sammelt 7 Stücke lebendige Fäulnis in unter 10 Minuten. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis." },
    [6135] = { name = "Dämmerschwinge, oh, wie ich Euch hasse...", objective = "Sucht Dämmerschwinge und tötet ihn. Nehmt ein Büschel vom Fell Dämmerschwinges und bringt es zu Nathanos Blightcaller. Man sagt, dass Dämmerschwinge nördlich von hier durch das Land streift." },
    [6136] = { name = "Der Korpulente", objective = "Sucht in den nördlichen Wüsten der Östlichen Pestländer nach Blutschlinger und vernichtet ihn. Kehrt zu Nathanos Blightcaller zurück, sobald Ihr diese Mission erledigt habt." },
  },
  frFR = {
    [1113] = { name = "Des cœurs zélés", objective = "Le maître apothicaire Faranell, à Undercity, veut 20 Cœurs zélés." },
    [6521] = { name = "Une alliance impie", objective = "Apporter la Tête de l'Ambassadeur Malcin à Varimathras, à Undercity." },
    [1956] = { name = "L'Energie d'Uldaman", objective = "Récupérer une Source d'énergie en obsidienne et la rapporter à Tabetha dans le marécage d'Âprefange." },
    [4143] = { name = "Brouillard maléfique", objective = "Récupérer 5 Echantillons de brume atal'ai puis retourner voir Muigin dans le cratère d'Un'Goro." },
    [4146] = { name = "Carburant de baguette", objective = "Remettre la Baguette déchargée et 5 Echantillons de brume atal'ai à Larion au refuge des Marshal." },
    [9053] = { name = "Un meilleur ingrédient", objective = "Récupérez une Liane putride sur le Gardien au fond du Temple englouti et revenez voir Torwa Pathfinder." },
    [8232] = { name = "Le drake vert", objective = "Apporter la Dent de Morphaz à Ogtinc en Azshara. Ogtinc demeure au sommet des falaises au nord-est des ruines d'Eldarath." },
    [8253] = { name = "Détruire Morphaz", objective = "Récupérer le Fragment d’arcane sur Morphaz et le rendre à l’archimage Xylem." },
    [8418] = { name = "Forger la pierre de pouvoir", objective = "Apporter les plumes vaudou à Ashlam Valorfist." },
    [8257] = { name = "Le sang de Morphaz", objective = "Tuez Morphaz dans le temple englouti d’Atal'Hakkar, et ramenez son sang à Greta Mosshoof à Gangrebois. L’entrée du temple englouti se trouve dans le marais des Chagrins." },
    [8236] = { name = "La clé d’azur", objective = "Rendre la Clé d'azur au seigneur Jorach Ravenholdt." },
    [8413] = { name = "Vaudou !", objective = "Apporter les Plumes vaudou à Bath'rah la Vigie des vents." },
    [8422] = { name = "Les trolls d'un même plumage…", objective = "Apporter 6 Plumes vaudou des trolls du Temple englouti." },
    [8425] = { name = "Plumes vaudou", objective = "Apportez les Plumes vaudou des trolls du Temple englouti au Héros déchu de la Horde." },
    [4362] = { name = "Le destin du Royaume", objective = "Retourner dans les Profondeurs de Blackrock et secourir la Princesse Moira Bronzebeard, prisonnière de l'Empereur Dagran Thaurissan." },
    [4003] = { name = "Un sauvetage royal", objective = "Tuer l'Empereur Thaurissan et libérer la princesse Moira Bronzebeard de son sort maléfique." },
    [7201] = { name = "Le dernier élément", objective = "Partir pour les Profondeurs de Blackrock et trouver 10 Essences des éléments. Commencer vos recherches par les golems et par les créateurs de golems. Vivian Lagrave a aussi marmonné quelque chose à propos d'élémentaires." },
    [4286] = { name = "Du beau matériel", objective = "Se rendre dans les Profondeurs de Blackrock et trouver 20 Sacoches Sombrefer. Retourner voir Oralius lorsque vous aurez accompli cette tâche. Logiquement, ces sacoches devraient être sur les nains Sombrefer des Profondeurs de Blackrock." },
    [7848] = { name = "Harmonisation avec le Cœur du Magma", objective = "Aventurez-vous jusqu'au portail d'entrée du Cœur du Magma dans les profondeurs de Blackrock et récupérez un Fragment du Magma. Lorsque ce sera fait, retournez voir Lothos Riftwalker au mont Blackrock." },
    [5001] = { name = "Les effets de Bijou", objective = "Retrouver les Affaires de Bijou et les lui rapporter. Bonne chance !" },
    [4982] = { name = "Les effets de Bijou", objective = "Trouver les Affaires de Bijou et les lui rapporter. Elle vous a dit les avoir cachées dans le niveau inférieur de la ville." },
    [4788] = { name = "Les dernières tablettes", objective = "Apporter la cinquième et la sixième Tablette Mosh'aru au Prospecteur Ironboot à Tanaris." },
    [6569] = { name = "Illusions d'Occulus", objective = "Aller au Pic Blackrock et collecter 20 Yeux de draconide noir. Retourner voir Myranda la Mégère, quand la tâche sera terminée." },
    [4764] = { name = "Le fermoir de Doomrigger", objective = "Apporter le Fermoir de Doomrigger à Mayara Brightwing, dans les Steppes ardentes." },
    [4768] = { name = "La tablette de Darkstone", objective = "Apporter la Tablette de Darkstone à l'ombremage Vivian Lagrave à Kargath." },
    [5160] = { name = "Le Protectorat de la matrone", objective = "Aller jusqu’au Berceau-de-l'Hiver et trouver Haleh. Lui donner l’Ecaille d'Awbee." },
    [5526] = { name = "Fragment de la Gangrevigne", objective = "Trouvez la Gangrevigne à Hache-tripes et prenez-en un fragment. Il est probable que vous ne pourrez vous en emparer qu’après la mort d’Alzzin le Modeleur. Servez-vous du Reliquaire de Pureté pour conserver le fragment, et retournez à Reflet-de-Lune voir Rabine Saturna au village de Havrenuit." },
    [7463] = { name = "Rafraîchissement arcanique", objective = "Rendez-vous dans le quartier de Crochebois de Hache-tripes et tuez Hydrogénos, l’élémentaire de l’eau. Retournez voir le Gardien du savoir Lydros à l’Athenaeum avec l’Essence d’Hydrogénos." },
    [7461] = { name = "Folie intérieure", objective = "Vous devez détruire les gardiens qui protègent les 5 Pylônes qui alimentent la Prison d’Immol’thar. Une fois que les Pylônes seront coupés, le champ de force qui entoure Immol’thar se dissipera. Entrez dans la Prison d’Immol’thar et éradiquez l’infâme démon qui se trouve en son cœur. Enfin, affrontez le prince Tortheldrin à l’Athenaeum. Lorsque vous aurez terminé, retournez voir l’Ancienne des Shen’dralar dans la cour." },
    [5247] = { name = "Fragments du passé", objective = "Apporter une Barre de thorium enchanté, 5 Cristaux de restauration et une Fiole d'eau redoutable à Aurora Skycaller à la tour du Col du nord, dans les Maleterres de l’est." },
    [7643] = { name = "L'ancien esprit équin", objective = "Procurez-vous un aliment pour chevaux capable de nourrir un esprit équin. Il semble que Merideth Carlson, à Southshore, sache en fabriquer. Ensuite, rendez-vous au donjon de Hache-tripes en Feralas, et tuez Tendris Crochebois. Sa mort libérera l’Ancien esprit équin. Nourrissez-le avec l’aliment spécial afin de l’apaiser. Enfin, donnez-lui le Caparaçon d’arcanite pour qu’il le bénisse." },
    [7631] = { name = "Le destrier de l'effroi de Xoroth", objective = "Lisez les Instructions de Mor’zul. Invoquez un Destrier de l’effroi xorothien, vainquez-le, et liez son esprit." },
    [7506] = { name = "Le Rêve d'Emeraude…", objective = "Rendez ce livre à ses légitimes propriétaires." },
    [7503] = { name = "La plus grande race de chasseurs", objective = "Rendez ce livre à ses légitimes propriétaires." },
    [7500] = { name = "Les recettes de l’arcaniste", objective = "Rendez ce livre à ses légitimes propriétaires." },
    [7501] = { name = "La lumière et comment l'altérer", objective = "Rendez ce livre à ses légitimes propriétaires." },
    [7504] = { name = "Sainte Bolognaise : Ce que la lumière ne vous dit pas", objective = "Rendez ce livre à ses légitimes propriétaires." },
    [7498] = { name = "Garona : une étude en discrétion et en trahison", objective = "Rendez ce livre à ses légitimes propriétaires." },
    [7505] = { name = "Le Horion de givre et vous", objective = "Rendez ce livre à ses légitimes propriétaires." },
    [7502] = { name = "Contrôler les ombres", objective = "Rendez ce livre à ses légitimes propriétaires." },
    [7499] = { name = "Le codex de défense", objective = "Rendez ce livre à ses légitimes propriétaires." },
    [7629] = { name = "Livraison de diablotin", objective = "Apporter le Diablotin en bouteille au laboratoire d'alchimie de la Scholomance. Une fois le parchemin créé, retournez voir Gorzeeki Wildeyes." },
    [7647] = { name = "Jugement et rédemption", objective = "Utilisez le Clairvoyant au coeur du sous-sol du Grand ossuaire, dans la Scholomance. Cela attirera des esprits que vous devrez juger. Lorsqu’ils seront vaincus, le Chevalier de la mort Ravassombre apparaîtra. Vainquez-le et purifiez l’âme du destrier déchu. Ensuite, donnez l’Ame rachetée du destrier et le Caparaçon enchanté et béni au Destrier déchu de Ravassombre." },
    [7668] = { name = "La menace de Ravassombre", objective = "Servez-vous du Clairvoyant au centre du sous-sol du Grand ossuaire de la Scholomance. Cela attirera des esprits que vous devrez combattre. Les vaincre fera apparaître le Chevalier de la mort Ravassombre. Tuez-le. Ramenez la Tête de Ravassombre à Sagorne Crestrider de la vallée de la Sagesse, à Orgrimmar." },
    [5463] = { name = "Le cadeau de Menethil", objective = "Voyager jusqu’à Stratholme et trouver le cadeau de Menethil. Placer le Souvenir de la mémoire sur le sol impie." },
    [261] = { name = "Sur le chemin écarlate", objective = "Détruire 30 Ravageurs morts-vivants, puis retourner voir Frère Anton, à la Combe de Nijel." },
    [1052] = { name = "Sur le chemin écarlate", objective = "Apporter la Lettre de recommandation du Frère Anton à Raleigh le Dévot à Southshore." },
    [6522] = { name = "Une alliance impie", objective = "Apporter le Petit parchemin à Varimathras, à Undercity." },
    [720] = { name = "Un signe d'espoir", objective = "Trouver le Prospecteur Ryedol et lui dire que Hammertoe Grez est en vie." },
    [738] = { name = "Trouver Agmond", objective = "." },
    [739] = { name = "Murdaloc", objective = "Tuer l'assassin d'Agmond : Murdaloc. Tuer 12 Briseurs d’os Cavepierre. Et revenir voir le Prospecteur Ironband au Loch Modan." },
    [723] = { name = "Espérance en la foi", objective = "Porter l'Amulette de Hammertoe au Prospecteur Ryedol dans les Terres ingrates." },
    [724] = { name = "Espérance en la foi", objective = "Apporter l'Amulette de Hammertoe à l'historien Karnik à Ironforge." },
    [725] = { name = "Avertir de la menace", objective = "Trouver le Conseiller Belgrum et lui donner la Note." },
    [726] = { name = "Avertir de la menace", objective = "Parler à l'Historien Karnik." },
    [762] = { name = "Un ambassadeur du mal", objective = "Tuer l'Ambassadeur Infernus, à la Forteresse d'Angor, et apporter la preuve de sa mort au Conseiller Belgrum à Ironforge." },
    [2198] = { name = "Le Collier brisé", objective = "Chercher celui qui a fabriqué le Collier brisé pour découvrir sa valeur potentielle." },
    [2199] = { name = "Le Prix de la Connaissance", objective = "Apporter 5 Barres d'Argent à Talvash del Kissel, à Ironforge." },
    [2200] = { name = "Retour à Uldaman", objective = "Chercher des indices sur le Collier de Talvash à Uldaman. Le paladin dont il a parlé est la dernière personne à l'avoir porté." },
    [2318] = { name = "La Traduction du Journal", objective = "Trouver quelqu'un qui puisse traduire le journal du paladin. L'endroit le plus proche est Kargath, dans les Terres ingrates." },
    [2338] = { name = "La Traduction du Journal", objective = "Laisser Jarkal emprunter le Collier en échange de la traduction du Journal." },
    [2500] = { name = "Les réactifs des Terres ingrates", objective = "Aller chercher les réactifs dont Ghak Healtouch a besoin dans les Terres ingrates, puis les lui rapporter à Thelsamar." },
    [2258] = { name = "Les réactifs des Terres ingrates", objective = "Apporter 5 Gésiers de busard, 10 Crocs de coyote des rochers et 5 Fragments d'élémentaire de roche à Jarkal Mossmeld, à Kargath, dans les Terres ingrates." },
    [1954] = { name = "L'orbe infernal", objective = "Apporter un Orbe infernal à Tabetha dans le marécage d'Âprefange." },
    [1955] = { name = "L'Exorcisme", objective = "Tuer le démon de l'Orbe puis parler à Tabetha." },
    [2988] = { name = "Les cages Witherbark", objective = "Inspecter les cages dans les deux villages Witherbark, puis retourner auprès du Maître des gryphons Talonaxe." },
    [2989] = { name = "L'autel de Zul", objective = "Regarder sur le dessus de l'autel de Zul, puis retourner auprès du Maître des gryphons Talonaxe." },
    [2990] = { name = "Thadius Grimshade", objective = "Apporter la Plume de Bec-tranchant à Thadius Grimshade, dans les Terres foudroyées." },
    [2933] = { name = "Bouteilles de venin", objective = "Apporter une Bouteille de venin à un apothicaire, au Moulin-de-Tarren." },
    [2934] = { name = "Glande à venin intacte", objective = "Rapporter une Glande à venin intacte à l'Apothicaire Lydon, au Moulin-de-Tarren." },
    [2935] = { name = "Consulter Maître Gadrin", objective = "Parler à Maître Gadrin au Village de Sen'jin." },
    [3520] = { name = "Esprits de Hurleurs", objective = "Capturer l’Esprit de 3 Hurleurs en Feralas, puis retourner voir Yeh'kinya à Port Gentepression." },
    [1448] = { name = "À la recherche du temple", objective = "Brohann Caskbelly à Stormwind veut que vous recherchiez le temple d'Atal'Hakkar." },
    [1449] = { name = "Vers les Hinterlands", objective = "Parler au haut-thane Falstad Wildhammer, au Nid-de-l'Aigle des Hinterlands." },
    [1450] = { name = "Le Maître des gryphons Talonaxe", objective = "Parler au Maître des gryphons Talonaxe dans la Volière de Nid-de-l'Aigle" },
    [1451] = { name = "Rhapsody Shindigger", objective = "Chercher Rhapsody Shindigger dans les Hinterlands." },
    [1452] = { name = "Le Kocktail Kalimdor de Rhapsody", objective = "Rhapsody Shindigger dans les Hinterlands veut que vous lui rameniez 3 Gésiers de roc, 3 Foies de Groddoc et 3 Foies de Ferpoil." },
    [1469] = { name = "L'histoire de Rhapsody", objective = "Apporter le Fragment de tablette atal'ai à Brohann Caskbelly à Stormwind." },
    [1424] = { name = "Le bassin des larmes", objective = "Fel’zerul à Stonard veut que vous rassembliez 10 Artefacts atal'ai." },
    [1429] = { name = "L'Exilé atal'ai", objective = "Apporter les Artefacts atal'ai à l'Exilé atal'ai dans les Hinterlands." },
    [1444] = { name = "De retour vers Fel’Zerul", objective = "Retourner voir Fel’Zerul à Stonard." },
    [3444] = { name = "Le Cercle de pierres", objective = "Récupérer le Cercle de pierres à l'Atelier de Marvon Rivetseeker à Ratchet." },
    [4787] = { name = "L'oeuf antique", objective = "Apporter l'Oeuf antique à Yeh'kinya à Tanaris." },
    [4141] = { name = "Muigin et Larion", objective = "Récolter 15 Pétales-de-sang et retourner voir Muigin." },
    [4142] = { name = "Visite à Gregan", objective = "Apporter une Pétale-de-sang à Gregan Brewspewer en Feralas." },
    [4145] = { name = "Larion et Muigin", objective = "Chasser 5 Flagellants Pétale-de-sang, 5 Batteurs Pétale-de-sang, 5 Ecorcheurs Pétale-de-sang et 5 Trappeurs Pétale-de-sang pour Larion au refuge des Marshal." },
    [4147] = { name = "Atelier de Marvon", objective = "Se rendre à l'Atelier de Marvon Rivetseeker à Ratchet." },
    [9052] = { name = "Le poison de Pétale-de-sang", objective = "Récupérez 8 Chapeaux de sang et 8 Dards de Gorishi, puis retournez voir Torwa Pathfinder au cratère d'Un'goro." },
    [9051] = { name = "Test de toxicité", objective = "Piquez un Diablosaure avec l'Aiguillon de diablosaure. Retournez voir Torwa Pathfinder au Cratère d'Un'goro lorsque vous aurez accompli cette tâche." },
    [8153] = { name = "La ramure de coursier", objective = "Rapporter deux Ramures de coursier parfaites à Ogtinc en Azshara. Ogtinc vit au sommet des collines au nord-est des ruines d’Eldarath." },
    [8231] = { name = "Vandales des flots", objective = "Apporter 6 Ecailles de vandale des flots à Ogtinc en Azshara. Ogtinc demeure au sommet des falaises au nord-est des ruines d'Eldarath." },
    [8251] = { name = "La poussière magique", objective = "Procurer 10 doses de Poussière lumineuse à l’archimage Xylem." },
    [8252] = { name = "Le corail des sirènes", objective = "Récupérer 6 Coraux enchantés et les apporter à l’archimage Xylem." },
    [8414] = { name = "La dissipation du mal", objective = "Récupérez 20 Pierres du Fléau des serviteurs et apportez-les au grand prêtre Thel'danis dans les Maleterres de l'ouest." },
    [8416] = { name = "Pierres du Fléau inertes", objective = "Apporter la Pierre du Fléau inerte au commandant Ashlam Valorfist à la pointe du Noroît." },
    [8255] = { name = "Courser les coursiers", objective = "Récupérer 4 Glandes de coursier en bonne santé et les apporter à Ogtinc en Azshara. Ogtinc réside au sommet des falaises, au nord-est des ruines d’Eldarath." },
    [8256] = { name = "L'ichor de non-mort", objective = "Récupérer une dose d’Ichor de non-mort pour le compte d’Ogtinc en Azshara. Ogtinc réside au sommet des falaises, au nord-est des ruines d’Eldarath." },
    [8234] = { name = "Sac azur scellé", objective = "Récupérer le Sac azur scellé auprès du chaman Grumegueule en Azshara. Puis apportez le sac à l'archimage Xylem, également en Azshara." },
    [8235] = { name = "Les fragments codés", objective = "Apporter 10 Fragments codés à l'archimage Xylem à Azshara." },
    [8410] = { name = "La maîtrise des éléments", objective = "Rassembler un échantillon d'air, de feu, de terre et d'eau pour Bath'rah la Vigie des Vents." },
    [8412] = { name = "Le totem des esprits", objective = "Apportez les différents morceaux du Totem des esprits à Bath’rah la Vigie des Vents." },
    [8419] = { name = "La demande d'un diablotin", objective = "Apportez un morceau de Gangrétoffe à Démonet à Gangrebois." },
    [8420] = { name = "Chaud et piquant", objective = "Apportez un morceau de gangrétoffe à Démonet à Gangrebois." },
    [8421] = { name = "L'anti-étoffe des héros", objective = "Apporter 10 morceaux de Bois pourri et 4 Essences de Vénéneuse à Démonet, en Gangrebois." },
    [8423] = { name = "Fraternité entre guerriers", objective = "Tuer 7 Sangliers infernaux dans les Terres foudroyées et revenir voir le Héros déchu de la Horde." },
    [8424] = { name = "La guerre contre les liges d'ombre", objective = "Tuez les Liges d'ombre dans les Terres foudroyées et revenez voir le Héros déchu de la Horde." },
    [3801] = { name = "Héritage Sombrefer", objective = "Parler à Franclorn Forgewright si obtenir une clé de la Cité majeure vous intéresse." },
    [4262] = { name = "Grand seigneur Pyron", objective = "Tuer le Grand seigneur Pyron et retourner voir Jalinda Sprig. Jalinda vous a dit qu'il gardait la carrière. Peut-être devriez-vous chercher à cet endroit ?" },
    [3702] = { name = "Les ruines fumantes de Thaurissan", objective = "Écouter l'historienne royale Archesonus raconter l'histoire de Thaurissan." },
    [3701] = { name = "Les ruines fumantes de Thaurissan", objective = "Aller dans les ruines de Thaurissan, dans les Steppes ardentes. Récupérer des informations sur les Reliques de Thaurissan, puis retourner auprès de l’Historienne royale Archesonus." },
    [4341] = { name = "Kharan Mighthammer", objective = "Aller dans les Profondeurs de Blackrock et trouver Kharan Mighthammer. Le roi a mentionné que Kharan était retenu prisonnier là-bas ; cherchez une prison." },
    [4342] = { name = "Légende de Kharan", objective = "Écouter Kharan Mighthammer raconter son histoire." },
    [4361] = { name = "Le porteur des mauvaises nouvelles", objective = "Retourner à Ironforge et apporter la mauvaise nouvelle au Roi Magni Bronzebeard." },
    [4182] = { name = "La menace des draconiens", objective = "Tuer 15 Rejetons noirs, 10 Draconides noirs, 4 Wyrmides noirs et 1 Drake noir. Retrouver Helendis Riverhorn une fois la tâche accomplie." },
    [4183] = { name = "Les véritables maîtres", objective = "Voyager jusqu'au Lakeshire et remettre la Lettre d'Helendis Riverhorn au Magistrat Solomon." },
    [4184] = { name = "Les véritables maîtres", objective = "Voyager vers Stormwind et remettre la Demande d'aide de Solomon au généralissime Bolvar Fordragon. Bolvar demeure dans le Donjon de Stormwind." },
    [4185] = { name = "Les véritables maîtres", objective = "Parler au généralissime Bolvar Fordragon après avoir parlé à dame Katrana Prestor." },
    [4186] = { name = "Les véritables maîtres", objective = "Apporter le Décret de Bolvar au Magistrat Solomon au Lakeshire." },
    [4223] = { name = "Les véritables maîtres", objective = "Parler au maréchal Maxwell dans les Steppes ardentes." },
    [4224] = { name = "Les véritables maîtres", objective = "Parlez à John le Loqueteux pour apprendre ce qu'il est advenu du maréchal Windsor puis retournez voir le maréchal Maxwell lorsque vous aurez accompli cette tâche. Vous vous rappelez que le maréchal Maxwell vous a dit de le chercher dans une grotte au nord." },
    [4241] = { name = "Maréchal Windsor", objective = "Partir pour le mont Blackrock au nord-ouest et pénétrer dans les Profondeurs de Blackrock. Découvrir ce qu'il est advenu du Maréchal Windsor. Vous vous souvenez que John le Loqueteux a dit que Windsor avait été traîné en prison." },
    [4242] = { name = "Espoir abandonné", objective = "Donner les mauvaises nouvelles au maréchal Maxwell." },
    [4264] = { name = "Une Note chiffonnée", objective = "Il se peut que vous ayez simplement buté sur quelque chose qui pourrait intéresser le maréchal Windsor au plus haut point. Il reste peut-être encore un peu d'espoir, après tout…" },
    [4282] = { name = "Un espoir en lambeaux", objective = "Rapporter les Renseignements perdus du maréchal Windsor. Le maréchal Windsor pense qu'ils sont détenus par le seigneur golem Argelmach et par le général Forgehargne." },
    [3906] = { name = "Discordance des flammes", objective = "Partir pour la carrière dans le mont Blackrock et tuer le Grand maître Pyron. Retourner voir Thunderheart une fois votre mission accomplie." },
    [3981] = { name = "Le commandant Gor'shak", objective = "Trouver le commandant Gor'shak dans les Profondeurs de Blackrock. Le dessin grossier représentait également des barreaux. Peut-être devriez-vous rechercher un genre de prison." },
    [3982] = { name = "Que se passe-t-il ?", objective = "Défendre Gor'shak." },
    [4001] = { name = "Que se passe-t-il ?", objective = "Parler à Kharan Mighthammer et obtenir autant de renseignements que possible sur l'enlèvement de la princesse Moira Bronzebeard. Apporter ces renseignements à Thrall à Orgrimmar. Gor'shak a dit que Kharan était détenu dans une cellule proche." },
    [4002] = { name = "Les Royaumes de l'est", objective = "Parler à Thrall si vous êtes <prêt/prête> à vous charger de la mission qu'il a prévue." },
    [4081] = { name = "TUER A VUE : nains Sombrefer", objective = "Pénétrer dans les Profondeurs de Blackrock et tuer les vils agresseurs ! Le chef de guerre Goretooth veut que vous tuiez 15 Gardes Ragenclumes, 10 Gardiens Ragenclumes et 5 Fantassins Ragenclumes. Retourner le voir une fois votre mission accomplie." },
    [4122] = { name = "Grark Lorkrub", objective = "Partez pour les Steppes ardentes et trouvez Grark Lorkrub. Lexlort a mentionné le fait que la dernière fois où on l'a vu, il se trouvait dans une imposante forteresse des Blackrock. Une fois Grark Lorkrub découvert, l'enchaîner avec les chaînes en thorium, puis le ramener par le mont Blackrock jusque dans la gorge des Vents brûlants. Des hommes de Lexlort attendront de l'autre côté de la gorge et le mettront sous bonne garde." },
    [4121] = { name = "Situation précaire", objective = "Escortez votre prisonnier, Grark Lorkrub, au-delà des Steppes ardentes et du mont Blackrock, jusqu'à la gorge des Vents brûlants. Rappelez-vous que Lexlort a précisé que ses hommes attendraient de l'autre côté pour arrêter Grark. On vous demandera également de remettre vos chaînes en thorium à Lexlort." },
    [4061] = { name = "La révolte des machines", objective = "S'aventurer dans les Steppes ardentes et récupérer 10 Fragments d'élémentaires cassés pour la Hiérophante Theodora Mulvadania. Theodora vous a indiqué que les golems et les élémentaires étaient la source de ces fragments." },
    [4062] = { name = "La révolte des machines", objective = "Apporter l'Echantillon de fragment d'élémentaire à Lotwil Veriatus. Theodora vous a dit qu'il se trouvait au camp à l'est." },
    [5002] = { name = "Message à Maxwell", objective = "Se rendre dans les Steppes ardentes et confier les Renseignements de Bijou au maréchal Maxwell." },
    [4981] = { name = "Agent Bijou", objective = "Aller au Pic Blackrock et découvrir ce qui est arrivé à Bijou." },
    [5065] = { name = "Les tablettes perdues de Mosh'aru", objective = "Apporter la troisième et la quatrième tablette Mosh'aru au Prospecteur Ironboot à Tanaris." },
    [4726] = { name = "L'essence de rejeton", objective = "Apporter 8 Essences de Rejeton et le Draco-Incarcinatrix 900 à Tinkee Steamboil à la Corniche des flammes dans les Steppes ardentes." },
    [4808] = { name = "Felnok Steelspring", objective = "Donner la Lettre de Tinkee à Felnok Steelspring." },
    [4809] = { name = "Cornes de Noroît", objective = "Apporter 8 Cornes intactes de Noroît à Felnok Steelspring." },
    [4810] = { name = "Retourner voir Tinkee", objective = "Apporter le Paquet de Felnok à Tinkee Steamboil dans les Steppes ardentes." },
    [4907] = { name = "Tinkee Steamboil", objective = "Parler à Tinkee Steamboil." },
    [4734] = { name = "Un oeuf congelé", objective = "Utiliser le Prototype d'Oeufilloscope sur un oeuf dans la Colonie." },
    [4903] = { name = "Ordre du chef de guerre", objective = "Tuer le généralissime Omokk, le maître de guerre Voone et le seigneur Wyrmthalak. Récupérer les Importants documents Blackrock. Retourner voir le chef de guerre Goretooth à Kargath une fois la mission accomplie." },
    [4941] = { name = "Sagesse d'Eitrigg", objective = "Parler à Eitrigg, à Orgrimmar. Après avoir discuté avec Eitrigg, demander conseil à Thrall. Vous avez déjà vu Eitrigg dans les Appartements de Thrall." },
    [4974] = { name = "Pour la Horde !", objective = "Aller au Pic Blackrock et tuer le Chef de guerre, Rend Blackhand. Prendre sa tête et retourner à Orgrimmar." },
    [6566] = { name = "Ce que le vent apporte", objective = "Écouter Thrall." },
    [6567] = { name = "Le Champion de la Horde", objective = "Chercher Rexxar. Le Chef de guerre vous a dit où il était. Chercher sur les chemins de Désolace, entre les Serres-Rocheuses et Feralas." },
    [6568] = { name = "Le testament de Rexxar", objective = "Apporter le Testament de Rexxar à Myranda la Mégère, dans les Maleterres de l’ouest." },
    [6402] = { name = "Le rendez-vous à Stormwind", objective = "Aller à la Cité de Stormwind et se rendre aux portes de la ville. Parlez à l'écuyer Rowe, afin qu'il informe le maréchal Windsor de votre arrivée." },
    [6403] = { name = "La grande mascarade", objective = "Suivre Reginald Windsor dans Stormwind. Le protéger contre toute menace !" },
    [6501] = { name = "L'Œil de dragon", objective = "Vous devez écumer le monde pour pouvoir rétablir le pouvoir du Fragment de l'Oeil de dragon. La seule information dont vous disposez à propos de cette chose, c’est qu’elle existe." },
    [6570] = { name = "Brandeguerre", objective = "Aller à la tourbière du Ver, dans le marécage d'Âprefange, et chercher la tanière de Brandeguerre. Une fois à l’intérieur, porter l’Amulette de subversion draconique, et parler à Brandeguerre." },
    [6582] = { name = "L'épreuve des crânes, Clairvoyant", objective = "Vous devez trouver Clairvoyant, le drake champion du Vol bleu, et le tuer. Arracher son crâne à son cadavre, et le rapporter à Brandeguerre. Clairvoyant se trouve au Berceau-de-l'Hiver." },
    [6583] = { name = "L'épreuve des crânes, Somnus", objective = "Détruire le Champion drake du Vol vert, Somnus. Arracher son crâne à son cadavre, puis le rapporter à Brandeguerre." },
    [6584] = { name = "L'épreuve des crânes, Chronalis", objective = "Chronalis, enfant de Nozdormu, garde les Grottes du temps, dans le Désert de Tanaris. Tuez-le et rapportez son crâne à Brandeguerre." },
    [6585] = { name = "L'épreuve des crânes, Axtroz", objective = "Aller à Grim Batol et traquer Axtroz, le Champion drake du Vol rouge. Le tuer et arracher son crâne, puis l’apporter à Brandeguerre." },
    [6601] = { name = "Ascension...", objective = "Il semble que la comédie soit finie. Vous savez que l’Amulette de subversion draconique, créée par Myranda la Mégère, ne fonctionnera pas à l’intérieur du pic Blackrock. Peut-être devriez-vous trouver Rexxar et lui exposer votre fâcheuse situation. Montrez-lui l'Amulette drakefeu terne. Avec un peu de chance, il saura quoi faire." },
    [5089] = { name = "Ordres du général Drakkisath", objective = "Remettre les Ordres du général Drakkisath au maréchal Maxwell dans les Steppes ardentes." },
    [5527] = { name = "Un reliquaire de pureté", objective = "Rendez-vous en Silithus et cherchez un Reliquaire de pureté dans les ruines du village de Sudevent. Si vous parvenez à le trouver, ramenez-le à Rabine Saturna à Havrenuit, Reflet-de-Lune." },
    [5244] = { name = "Les ruines de Kel'Theril", objective = "Parler à Jaron Stoneshaper au village de Pluie-d'Etoiles" },
    [5245] = { name = "Les Esprits troublés de Kel'Theril", objective = "Utiliser la Pique de Jaron pour trouver les quatre Fragments de relique des Bien-nés. Les apporter à Aurora Skycaller dans les Maleterres de l’est." },
    [5246] = { name = "Fragments du passé", objective = "Trouver les Ecrits sacrés des Bien-nés dans le temple de Zin-Malor à Azshara et les apporter à Aurora Skycaller à la tour du Col du nord, dans les Maleterres de l'est." },
    [7637] = { name = "L'accent sur le sacrifice", objective = "Rendez-vous à Ironforge et procurez-vous l’Encensoir d’exorcisme du grand prêtre Rohan. Pour vous le procurer, il vous faudra verser une donation de 150 pièces d’or." },
    [7639] = { name = "Des preuves de jugement", objective = "Ramener l’Encensoir d’exorcisme au seigneur Grayson Shadowbreaker, dans le Quartier de cathédrale de Stormwind." },
    [7640] = { name = "Exorciser Val-Terreur", objective = "Servez-vous de l’Encensoir d’exorcisme pour chasser les esprits qui tourmentent Val-Terreur. Lorsque vous aurez tué 25 Esprits de Val-Terreur, retournez voir le seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind." },
    [7641] = { name = "L'œuvre de Grimand Elmore", objective = "Parlez à Grimand Elmore dans le Quartier des nains de Stormwind." },
    [7642] = { name = "Une ribambelle d'objets", objective = "Apporter 40 Etoffes runiques, 6 Barres d’arcanite, 10 Larmes d’Arthas, 5 Fioles d’eau sacrée de Stratholme, et 150 pièces d’or à Grimand Elmore, au Quartier des nains de Stormwind." },
    [7648] = { name = "Le chef d'œuvre de Grimand", objective = "Présentez le Caparaçon d’arcanite au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind, pour inspection." },
    [7645] = { name = "Fourrage enrichi en manne", objective = "Récupérer 20 Biscuits enrichis en manne, l’ingrédient vital qui permet de préparer du Fourrage enrichi en manne, pour le compte de Merideth Carlson de Southore dans les contreforts d’Hillsbrad. L’Aube d’argent est la seule à fabriquer ces biscuits. Vous devrez également lui donner 50 pièces d’or pour apaiser sa susceptibilité." },
    [7563] = { name = "Rage de sang", objective = "Apporter 30 bouteilles de Sang de bêtes enragées à Mor'zul Bloodbringer dans les Steppes ardentes." },
    [7564] = { name = "Gorzeeki Wildeyes", objective = "Apporter la Caisse de sang à Gorzeeki Wildeyes dans les Steppes ardentes." },
    [7623] = { name = "Le seigneur Banehollow", objective = "Achetez des Potions des ténèbres à Gorzeeki dans les Steppes ardentes. Servez-vous en pour vous rendre à Jaedenar, et parlez au seigneur Banehollow." },
    [7624] = { name = "Ulathek le traître", objective = "Affrontez Ulathek, puis apportez le Coeur du traître au seigneur Banehollow à Jaedenar." },
    [7625] = { name = "Poussière d'étoile xorothienne", objective = "Acheter de la Poussière d’étoiles xorothienne à Ur’dan. L’apporter à Gorzeeki dans les Steppes ardentes." },
    [7626] = { name = "La Cloche de Dethmoora", objective = "Apportez 10 Elixirs de Puissance de l'ombre à Gorzeeki Wildeyes dans les Steppes ardentes." },
    [7627] = { name = "La Roue de la Marche noire", objective = "Apportez 6 Grands éclats brilliants et 25 charges de Minerai de sombre fer à Gorzeeki dans les Steppes ardentes." },
    [7628] = { name = "La Chandelle de l'apocalypse", objective = "Apportez 35 Ecailles de dragon noir à Gozeeki WIldeyes dans les Steppes ardentes." },
    [7630] = { name = "L'arcanite", objective = "Apporter 3 Barres d’arcanite à Gorzeeki dans les Steppes ardentes." },
    [5461] = { name = "L'humain, Ras Murmegivre", objective = "Voyager jusqu’aux hautes-terres d'Arathi, et aller aux ruines de Stromgarde. Fouiller Stromgarde pour trouver un Souvenir de la mémoire. Si une telle trouvaille est faite, rapporter l’objet au magistrat Marduke." },
    [5462] = { name = "Le moribond, Ras Murmegivre", objective = "Voyager jusqu’à l’Espoir de lumière dans les Maleterres de l'est et trouver Leonid Barthalomew le Révéré. Lui montrer le Souvenir de la mémoire et lui dire tout ce que vous avez découvert." },
    [5464] = { name = "Le cadeau de Menethil", objective = "Apporter le Souvenir lié à Leonid Barthalomew dans les Maleterres de l’est." },
    [5465] = { name = "Souvenir lié", objective = "Retourner auprès du Magistrat Marduke à Caer Darrow. Lui montrer le Souvenir lié." },
    [5522] = { name = "Leonid Barthalomew", objective = "Apporter les Oeufs congelés à Leonid Barthalomew dans les Maleterres de l’est." },
    [5531] = { name = "Betina Bigglezink", objective = "Apporter les Oeufs congelés à Betina Bigglezink." },
    [7644] = { name = "Le caparaçon en arcanite béni", objective = "Retourner dans le quartier de la cathédrale de Stormwind avec le Caparaçon d’arcanite béni pour voir le seigneur Grayson Shadowbreaker." },
    [7646] = { name = "Le Clairvoyant", objective = "Apportez un Diamant d’Azeroth et un Diamant noir en parfait état au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind." },
    [7667] = { name = "Assistance matérielle", objective = "Si vous voulez aider Sagorne Crestrider de la vallée de la Sagesse d'Orgrimmar, apportez-lui un Diamant d’Azeroth et un Diamant noir en parfait état." },
    [5251] = { name = "L'archiviste", objective = "Voyager jusqu’à Stratholme et trouver l’Archiviste Galford de la Croisade écarlate. L’abattre et brûler les Archives écarlates." },
    [5542] = { name = "Chiens-démons", objective = "Tuer 20 Chiens pestiférés chétifs, 5 Chiens pestiférés et 5 Chiens pestiférés frénétiques. Retourner voir Tirion Fordring, quand la mission sera terminée." },
    [5543] = { name = "Ciel couleur de sang", objective = "Tuer 30 Chauves-souris pestiférées, puis retourner voir Tirion Fordring." },
    [5544] = { name = "Larve putride", objective = "Chercher les Larves putrides et les Dévoreurs de la région. Les tuer et récupérer leur viande. Retourner voir Tirion Fordring quand 15 pièces de Chair de Ver putride auront été récupérées." },
    [5742] = { name = "Rédemption", objective = "Écouter ce que Tirion Fordring a à dire." },
    [5781] = { name = "Aux mémoires perdues", objective = "Aller au caveau de Zaeldarr - situé dans la section la plus au sud des Maleterres de l’est - et récupérer le Marteau de Taelan. Retourner auprès de Tirion Fordring après avoir accompli la mission." },
    [5845] = { name = "De l'honneur perdu", objective = "Se rendre à Valnord, dans la région nord-est des Maleterres de l’est, et récupérer le Symbole de l’honneur perdu. Revenir auprès de Tirion Fordring quand la tâche est accomplie." },
    [5846] = { name = "L'amour et la famille", objective = "Voyager jusqu’à l’île de Caer Darrow, dans la région centre-sud des Maleterres, et chercher un indice de l’emplacement du tableau." },
    [5262] = { name = "La vérité vient du ciel", objective = "Apporter la Tête de Balnazzar au duc Nicholas Zverenhoff dans les Maleterres de l’est." },
    [6133] = { name = "L'ordre du seigneur forestier", objective = "Aller vers la frontière nord des Maleterres de l’est et récupérer le Registre de Quel'Thalas. L’objet se trouve quelque part dans le gîte de Quel'Lithien. Tuer également 8 Forestiers, 8 Eclaireurs et 8 Bûcherons." },
    [6042] = { name = "Les petits soucis de la non-vie", objective = "Tuer 20 Chauves-souris pestiférées nuisibles et 10 Chauves-souris pestiférées monstrueuses. Retourner voir Nathanos le Flétrisseur quand ce sera fait." },
    [6022] = { name = "Tuer utile", objective = "Allez à l'est à la Croisée de Corin et détruisez les membres du Fléau qui habitent la ville. Rassemblez sept morceaux de Pourriture vivante en moins de dix minutes. Utilisez le Mortier et le pilon pour réduire la Pourriture vivante en Pourriture coagulée." },
    [6135] = { name = "Crépuscaile, oh comme je te hais !", objective = "Trouver Crépuscaile et la tuer. Récupérer une Touffe de fourrure de Crépuscaile sur son cadavre, puis l’apporter à Nathanos le Flétrisseur. Il paraît que Crépuscaile hante les terres qui se trouvent au nord de la ferme des Marris." },
    [6136] = { name = "Le corpulent", objective = "Trouver Creusechair, dans les terres au nord des Maleterres de l’est, et le tuer. Retourner voir Nathanos le Flétrisseur quand la mission sera terminée." },
  },
  esES = {
    [1113] = { name = "Corazones de fervor", objective = "El maestro boticario Faranell de Entrañas quiere 20 corazones de fervor." },
    [6521] = { name = "Una alianza nefasta", objective = "Lleva la cabeza del embajador Malcin a Varimathras, que está en Entrañas." },
    [1956] = { name = "Poder en Uldaman", objective = "Hazte con una fuente de poder obsidiano y llévasela a Tabetha en el Marjal Revolcafango." },
    [4143] = { name = "Bruma del mal", objective = "Reúne 5 muestras de bruma Atal'ai y después ve a ver de nuevo a Muigin al Cráter de Un'Goro." },
    [4146] = { name = "Combustible de irradior", objective = "Entrega el Controlador descargado y 5 muestras de bruma Atal'ai a Larion, en el Refugio de Marshal." },
    [9053] = { name = "Un ingrediente mejor", objective = "Consigue una vid pútrida de las que custodia el guardián en las profundidades del Templo Sumergido y después ve a ver de nuevo a Torwa Abrecaminos." },
    [8232] = { name = "El draco verde", objective = "Llévale el colmillo de Morphaz a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath." },
    [8253] = { name = "Destruye a Morphaz", objective = "Recupera el fragmento arcano de Morphaz y llévaselo al archimago Xylem." },
    [8418] = { name = "La forja de la piedra del poderío", objective = "Lleva las plumas vudú a Ashlam Puñovalor." },
    [8257] = { name = "La sangre de Morphaz", objective = "Mata a Morphaz en el hundido Templo de Atal'Hakkar y lleva su sangre a Greta Pezuñamusgo en Frondavil. Encontrarás la entrada al templo hundido en el Pantano de las Penas." },
    [8236] = { name = "La llave azur", objective = "Devuélvele la llave azur a Lord Jorach Ravenholdt." },
    [8413] = { name = "Vudú", objective = "Lleva las plumas vudú a Bath'rah el Cazavientos." },
    [8422] = { name = "Plumas de trol", objective = "Reúne un total de 6 plumas vudú en el Templo Sumergido." },
    [8425] = { name = "Plumas Vudú", objective = "Llévale las plumas vudú de los trols del Templo Sumergido al Héroe Caído de la Horda." },
    [4362] = { name = "El destino del reino", objective = "Vuelve a las Profundidades de Roca Negra y rescata a la princesa Moira Barbabronce de las garras del emperador Dragan Thaurissan." },
    [4003] = { name = "El rescate real", objective = "Mata al emperador Dagran Thaurissan para liberar a la princesa Barbabronce del hechizo." },
    [7201] = { name = "El último elemento", objective = "Viaja a las Profundidades de Roca Negra y recupera 10 esencias de los elementos. Tu primer impulso es buscar los golems y a los creadores de golems. Recuerdas que Vivian Latumba también murmuró entre dientes algo sobre los elementales." },
    [4286] = { name = "Buena mercancía", objective = "Viaja a las Profundidades de Roca Negra y recupera 20 riñoneras Hierro Negro. Vuelve junto a Oralius cuando hayas completado esta tarea. Se da por sentado que los enanos Hierro Negro de las Profundidades de Roca Negra llevan estos inventos de riñoneras." },
    [7848] = { name = "Armonización con el Núcleo", objective = "Entra en el Núcleo de Magma de las Profundidades de Roca Negra y recoge un fragmento de núcleo. LLévaselo a Lothos Levantagrietas a la Montaña Roca Negra." },
    [5001] = { name = "Las pertenencias de Bijou", objective = "Encuentra las pertenencias de Bijou y devuélveselas. ¡Suerte!" },
    [4982] = { name = "Las pertenencias de Bijou", objective = "Encuentra las pertenencias de Bijou y devuélveselas. Recuerdas que ella mencionó haberlas ocultado en la planta baja de la ciudad." },
    [4788] = { name = "Las últimas tablillas", objective = "Llévale la quinta y sexta tablillas de Mosh'aru al prospector Ferrobota, que está en Tanaris." },
    [6569] = { name = "Ilusiones oculares", objective = "Viaja a la Cumbre de Roca Negra y recoge 20 ojos de dragauro negro. Cuando hayas terminado tu tarea regresa con Myranda la Fada." },
    [4764] = { name = "El Broche de Equipasino", objective = "Llévale el broche de Equipasino a Mayara Alasol en Las Estepas Ardientes." },
    [4768] = { name = "La tablilla de Rocanegra", objective = "Llévale la tablilla de Rocanegra a la maga oscura Vivian Latumba en Kargath." },
    [5160] = { name = "El Protectorado de la matrona", objective = "Viaja hasta la Cuna del Invierno y encuentra a Haleh. Dale la escama de Awbee." },
    [5526] = { name = "Fragmentos de gangrevid", objective = "Encuentra gangrevid en La Masacre y coge un fragmento. Es probable que solo puedas conseguirlo si derrotas a Alzzin el Formaferal. Usa el relicario de pureza para guardar el fragmento y llévaselo al rabino Saturna a Amparo de la Noche, en Claro de la Luna." },
    [7463] = { name = "El refresco arcano", objective = "Viaja al Barrio Alabeo de La Masacre y mata al elemental de agua, Hidromilecio. Lleva la esencia de Hidromilecio al guardián del Conocimiento Lydros que está en El Athenaeum." },
    [7461] = { name = "Locura interior", objective = "Debes destruir a los guardianes que rodean las 5 torres que controlan la Prisión de Immol'thar. Una vez desactivadas las torres, el campo de fuerza que rodea a Immol'thar se disipará. Entra en la Prisión de Immol'thar y erradica al demonio que hace guardia en su interior. Por último, haz frente al príncipe Tortheldrin en El Athenaeum. Si consigues completar esta misión, ve al patio a buscar al Anciano Shen'dralar." },
    [5247] = { name = "Fragmentos del pasado", objective = "Consigue una barra encantada de torio, 5 cristales de restauración y un vial de agua funesta para Aurora Llamacielo, en la Torre del Paso Norte, en las Tierras de la Peste del Este." },
    [7643] = { name = "El antiguo espíritu equino", objective = "Consigue comida para caballos para alimentar a un espíritu equino. Por lo visto, Merideth Carlson, en Costasur, tiene esa comida. Ve a la mazmorra de La Masacre, en Feralas y mata a Tendris Madeguerra. Al hacerlo, liberarás al antiguo espíritu equino. Dale la comida para caballos y lo aplacarás. Por último, dale la gualdrapa de arcanita para que la bendiga." },
    [7631] = { name = "Terrorecus de Xoroth", objective = "Lee las instrucciones de Mor'zul. Invoca al Corcel de la Muerte Xorothiano, derrótalo y después vincula su espíritu al tuyo." },
    [7506] = { name = "El Sueño Esmeralda", objective = "Devuelve el libro a sus legítimos dueños." },
    [7503] = { name = "La mayor raza de cazadores", objective = "Devuelve el libro a sus legítimos dueños." },
    [7500] = { name = "El Recetario del Arcanista", objective = "Devuelve el libro a sus legítimos dueños." },
    [7501] = { name = "La Luz y cómo alterarla", objective = "Devuelve el libro a sus legítimos dueños." },
    [7504] = { name = "Sagrada Bologna: lo que la Luz nunca te dirá", objective = "Devuelve el libro a sus legítimos dueños." },
    [7498] = { name = "Garona: un estudio acerca de la discreción y la traición", objective = "Devuelve el libro a sus legítimos dueños." },
    [7505] = { name = "El choque de Escarcha y tú", objective = "Devuelve el libro a sus legítimos dueños." },
    [7502] = { name = "Controlar las Sombras", objective = "Devuelve el libro a sus legítimos dueños." },
    [7499] = { name = "Códice de Defensa", objective = "Devuelve el libro a sus legítimos dueños." },
    [7629] = { name = "Entrega de diablillo", objective = "Llévale el diablillo en un tarro al laboratorio de alquimia de Scholomance. Después de crear el pergamino llévale el tarro a Gorzeeki Ojosalvajes." },
    [7647] = { name = "Juzgar y redimir", objective = "Utiliza el augurador en el centro del sótano de El Gran Osario en Scholomance. Al hacerlo, aparecerán los espíritus que tienes que juzgar. Si derrotas a esos espíritus, aparecerá el Caballero de la Muerte Atracoscuro. Acaba con él y reclama el alma perdida del cargo caído. Entrega el alma redimida del cargo y la gualdrapa encantada bendecida al cargo caído de Atracoscuro." },
    [7668] = { name = "La amenaza de Atracoscuro", objective = "Usa el augurador que se encuentra en el corazón del sótano de El Gran Osario en Scholomance. Al hacerlo se presentarán los espíritus a los que tienes que enfrentarte. La derrota de estos espíritus invoca al Caballero de la Muerte Atracoscuro, derrótalo. Llévale la cabeza de Atracoscuro a Sagorne Montacresta en el Valle de la Sabiduría, en Orgrimmar." },
    [5463] = { name = "El Obsequio de Menethil", objective = "Viaja a Stratholme y encuentra el Obsequio de Menethil. Coloca el Recuerdo de Evocación en suelo no consagrado." },
    [261] = { name = "El sendero Escarlata", objective = "Destruye 30 devastadores no-muertos y luego ve a buscar al hermano Antón a Punta de Nijel." },
    [1052] = { name = "El sendero Escarlata", objective = "Lleva la carta de mención honorífica del hermano Antón a Raleigh el Devoto, en Costasur." },
    [6522] = { name = "Una alianza nefasta", objective = "Lleva el pergamino a Varimathras, que está en Entrañas." },
    [720] = { name = "Un signo de esperanza", objective = "Localiza al prospector Ryedol y dile que Grez Dedomaza está vivo." },
    [738] = { name = "Encontrar a Agmond", objective = "Encuentra a Agmond." },
    [739] = { name = "Murdaloc", objective = "Mata al asesino de Agmond, Murdaloc. Mata a 12 partehuesos Petracripta. Preséntate ante el prospector Vetaferro en Loch Modan." },
    [723] = { name = "Tener fe en el porvenir", objective = "Llévale el amuleto de Piemartillo al prospector Ryedol en las Tierras Inhóspitas." },
    [724] = { name = "Tener fe en el porvenir", objective = "Llévale el amuleto de Piemartillo a Karnik el Historiador en Forjaz." },
    [725] = { name = "Avertir de la amenaza", objective = "Encuentra al consejero Belgrum y dale su nota." },
    [726] = { name = "Avertir de la amenaza", objective = "Habla con Karnik el Historiador." },
    [762] = { name = "Un embajador de mal", objective = "Mata al embajador Infernus en la Fortaleza de Angor llévale la prueba de su muerte al consejero Belgrum en Forjaz." },
    [2198] = { name = "El collar hecho añicos", objective = "Busca al creador del collar hecho añicos y descubre para qué sirve." },
    [2199] = { name = "Esa información tiene un precio", objective = "Lleva 5 lingotes de plata a Talvash del Kissel a Forjaz." },
    [2200] = { name = "El regreso a Uldaman", objective = "Busca pistas sobre el paradero del collar de Talvash en Uldaman. Dijo que un paladín muerto fue su último dueño." },
    [2318] = { name = "La traducción del diario", objective = "Encuentra a alguien que pueda traducir el diario del paladín. El lugar más cercano en el que podrás encontrar a alguien es Kargath, en las Tierras Inhóspitas." },
    [2338] = { name = "La traducción del diario", objective = "Préstale el collar a Jarkal. A cambio, te traducirá el diario." },
    [2500] = { name = "Componentes de Tierras Inhóspitas", objective = "Ve a las Tierras Inhóspitas a buscar los ingredientes que te ha pedido Ghak Sanadón y llévaselos a Thelsamar." },
    [2258] = { name = "Componentes de Tierras Inhóspitas", objective = "Llévale 5 mollejas de águila ratonera, 10 colmillos de coyote del risco y 5 fragmentos de elemental de piedra a Jarkal Musgofusión en Kargath, en las Tierras Inhóspitas." },
    [1954] = { name = "El orbe infernal", objective = "Lleva un orbe infernal a Tabetha en el Marjal Revolcafango." },
    [1955] = { name = "El exorcismo", objective = "Mata al demonio del orbe y habla con Tabetha." },
    [2988] = { name = "Las jaulas de Secacorteza", objective = "Mira en las jaulas de los poblados Secacorteza y vuelve a ver al maestro de grifos Garracha." },
    [2989] = { name = "El Altar de Zul", objective = "Mira en el Altar de Zul y vuelve a ver al maestro de grifos Garracha." },
    [2990] = { name = "Thadius Sombramacabra", objective = "Lleva la pluma de Picoafilado a Thadius Sombramacabra a Las Tierras Devastadas." },
    [2933] = { name = "Botellas de veneno", objective = "Lleva una botella de veneno a algún boticario de Molino Tarren." },
    [2934] = { name = "Glándula de veneno intacta", objective = "Lleva una glándula de veneno intacta al boticario Lydon de Molino Tarren." },
    [2935] = { name = "Consulta al maestro Gadrin", objective = "Habla con el maestro Gadrin en el Poblado Sen'jin." },
    [3520] = { name = "Los espíritus de los estriadores", objective = "Captura el espíritu de 3 estridadores en Feralas y después ve a ver a Yeh'kinya al Puerto Bonvapor." },
    [1448] = { name = "En búsqueda del templo", objective = "Brohann Barriliga, en Ventormenta, quiere que busques el Templo de Atal'Hakkar." },
    [1449] = { name = "A las Tierras del Interior", objective = "Habla con el Gran señor feudal Falstad Martillo Salvaje en el Pico Nidal, en las Tierras del Interior." },
    [1450] = { name = "Maestro de grifos Garracha", objective = "Habla con el maestro de grifos Garracha dentro de la pajarera del Pico Nidal." },
    [1451] = { name = "Rapsodio Machacacanillas", objective = "Busca a Rapsodio Machacacanillas en las Tierras del Interior." },
    [1452] = { name = "El cubata de Kalimdor de Rapsodio", objective = "Rapsodio Machacacanillas, en las Tierras del Interior, quiere que le lleves 3 mollejas de Roc, 3 hígados de Groddoc y 3 hígados de piel pétrea." },
    [1469] = { name = "El relato de Rapsodio", objective = "Lleva el fragmento de la tablilla Atal'ai a Brohann Barriliga, en Ventormenta." },
    [1424] = { name = "Charca de Lágrimas", objective = "Fel'zerul, en Rocal, quiere que consigas 10 artefactos Atal'ai." },
    [1429] = { name = "El exiliado Atal'ai", objective = "Lleva los artefactos Atal'ai al exiliado Atal'ai en las Tierras del Interior." },
    [1444] = { name = "Vuelve con Fel'Zerul", objective = "Vuelve a ver a Fel'Zerul en Rocal." },
    [3444] = { name = "El Círculo de Piedras", objective = "Recupera el Círculo de Piedras del taller de Marvon Buscarroblones, en Trinquete." },
    [4787] = { name = "El huevo antiguo", objective = "Llévale el huevo antiguo a Yeh'kinya, que está en Tanaris." },
    [4141] = { name = "Muigin y Larion", objective = "Recoge 15 pétalos de sangre y ve a ver a Muigin." },
    [4142] = { name = "Visita a Gregan", objective = "Llévale un pétalo de sangre a Gregan Vomitabrebaje de Feralas." },
    [4145] = { name = "Larion y Muigin", objective = "Caza 5 latigadores Pétalo de Sangre, 5 trilladores Pétalo de Sangre, 5 desolladores Pétalo de Sangre y 5 tramperos Pétalo de Sangre para Larion en el Refugio de Marshal." },
    [4147] = { name = "El taller de Marvon", objective = "Viaja hasta el taller de Marvon Buscarroblones en Trinquete." },
    [9052] = { name = "Veneno de pétalo de sangre", objective = "Reúne 8 champiñones de sangre y 8 aguijones Gorishi, y ve a ver de nuevo a Torwa Abrecaminos al Cráter de Un'Goro." },
    [9051] = { name = "Prueba de toxicidad", objective = "Clávale la púa de devilsaurio a un devilsaurio. Ve a ver de nuevo a Torwa Abrecaminos al Cráter de Un'Goro cuando hayas completado tu tarea." },
    [8153] = { name = "Cuernos de corcel", objective = "Llévale un par de cuernos de corcel perfectos a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath." },
    [8231] = { name = "Los vándalos marinos", objective = "Llévale 6 escamas de vándalo marino a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath." },
    [8251] = { name = "El polvo mágico", objective = "Llévale 10 puñados de polvo purpuríneo al archimago Xylem." },
    [8252] = { name = "El coral de las sirenas", objective = "Reúne 6 corales encantados y llévaselos al archimago Xylem." },
    [8414] = { name = "Expulsión de los demonios", objective = "Recoge 20 Piedras de la Plaga de esbirros y entrégaselas al Alto Sacerdote Thel'danis en las Tierras de la Peste del Oeste." },
    [8416] = { name = "Piedras inertes de la Plaga", objective = "Lleva la Piedra inerte de la Plaga al comandante Ashlam Puñovalor en el Alto del Orvallo." },
    [8255] = { name = "Los corceles Pezuñamusgo", objective = "Consigue 4 glándulas de corcel sanos y llévaselas a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath." },
    [8256] = { name = "El icor de los no-muertos", objective = "Consigue un icor de los no-muertos para Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath." },
    [8234] = { name = "Bolsa azur sellada", objective = "Recupera la bolsa azur sellada del chamán Fauces de Madera en Azshara. Llévale entonces la bolsa al archimago Xylem, que también se encuentra en Azshara." },
    [8235] = { name = "Los fragmentos codificados", objective = "Llévale 10 fragmentos codificados al archimago Xylem en Azshara." },
    [8410] = { name = "Maestría elemental", objective = "Recoge una muestra de aire, fuego, tierra y agua para Bath'rah el Cazavientos." },
    [8412] = { name = "Tótem espiritual", objective = "Lleva lo necesario para el tótem del espíritu a Bath'rah el Cazavientos." },
    [8419] = { name = "Pedido de un diablillo", objective = "Lleva una pieza de tela de inferi a Diblis en Frondavil." },
    [8420] = { name = "Caliente y picante", objective = "Lleva un retal de tela de inferi a Diblis a Frondavil." },
    [8421] = { name = "La mercancía equivocada", objective = "Lleva 10 maderas putrefactas y 4 esencias de veneno a Diblis a Frondavil." },
    [8423] = { name = "Parentesco guerrero", objective = "Mata a 7 jabinfernos de Las Tierras Devastadas y vuelve junto al Héroe Caído de la Horda." },
    [8424] = { name = "La guerra contra los Sombra Jurada", objective = "Acaba con los Sombra Jurada en las Tierras Devastadas y regresa junto al Héroe Caído de la Horda." },
    [3801] = { name = "El legado de los Hierro Negro", objective = "Habla con Franclorn Forjafina si te interesa obtener una llave de la ciudad." },
    [4262] = { name = "Gran maestro Pyron", objective = "Mata al gran maestro Pyron y vuelve junto a Jalinda Sprig. Recuerdas que Jalinda dijo que Pyron guardaba la cantera. Quizás deberías empezar a buscar allí." },
    [3702] = { name = "Las ruinas humeantes de Thaurissan", objective = "Escucha al historiador regio Archesonus relatar la historia de Thaurissan." },
    [3701] = { name = "Las ruinas humeantes de Thaurissan", objective = "Ve a las Ruinas de Thaurissan, en las Estepas Ardientes, y recopila información sobre los tesoros de Thaurissan. Informa al historiador regio Archesonus." },
    [4341] = { name = "Kharan Martillazo", objective = "Ve a las Profundidades de Roca Negra y encuentra a Kharan Martillazo. El rey dijo que estaba prisionero allí; busca una cárcel." },
    [4342] = { name = "La leyenda de Kharan", objective = "Escucha la historia de Kharan Martillazo." },
    [4361] = { name = "Portador de malas noticias", objective = "Regresa a Forjaz y dale las malas noticias al rey Magni Barbabronce." },
    [4182] = { name = "La amenaza de los dragonantes", objective = "Mata 15 cachorrillos negros, 10 dragauros negros, 4 vermis negros y 1 draco negro. Vuelve junto a Helendis Rivacuerno cuando hayas acabado la tarea." },
    [4183] = { name = "Los verdaderos maestros", objective = "Viaja a Villa del Lago y entrégale la carta de Helendis Rivacuerno al magistrado Salomón." },
    [4184] = { name = "Los verdaderos maestros", objective = "Ve a Ventormenta para entregar la petición de ayuda de Solomon al Gran Señor Bolvar Fordragon. Vive en el Castillo de Ventormenta." },
    [4185] = { name = "Los verdaderos maestros", objective = "Habla con el Alto Señor Bolvar Fordragon después de hablar con Lady Katrana Prestor." },
    [4186] = { name = "Los verdaderos maestros", objective = "Lleva el decreto de Bolvar al magistrado Salomón en la Villa del Lago." },
    [4223] = { name = "Los verdaderos maestros", objective = "Habla con el alguacil Maxwell en Las Estepas Ardientes." },
    [4224] = { name = "Los verdaderos maestros", objective = "Habla con John Andrajoso para averiguar el destino del alguacil Windsor y vuelve junto al alguacil Maxwell cuando hayas completado la tarea. Recuerdas que el alguacil Maxwell comentó algo sobre buscarlo en una cueva hacia el norte." },
    [4241] = { name = "El alguacil Windsor", objective = "Viaja a la Montaña Roca Negra al noroeste y adéntrate en las Profundidades de Roca Negra. Averigua qué le ha ocurrido al alguacil Windsor. Recuerdas que John Andrajoso había comentado que se habían llevado a una cárcel a Windsor." },
    [4242] = { name = "Esperanza perdida", objective = "Dale las malas noticias a alguacil Maxwell." },
    [4264] = { name = "Una nota arrugada", objective = "Puede que acabes de toparte con algo que le interesaría ver al alguacil Windsor. Puede que haya esperanza, después de todo." },
    [4282] = { name = "Una esperanza hecha trizas", objective = "Devuélvele al alguacil Windsor la información perdida. El alguacil Windsor cree que la información está siendo retenida en manos del Señor Gólem Argelmach y del general Forjira." },
    [3906] = { name = "La discordia de las llamas", objective = "Ve a la cantera de la Montaña Roca Negra y ejecuta al gran maestro Pyron. Vuelve junto a Truenozón cuando hayas completado este encargo." },
    [3981] = { name = "Comandante Gor'shak", objective = "Encuentra al comandante Gor'shak en las Profundidades de Roca Negra. Recuerdas que en el dibujo burdo había rejas sobre el rostro del orco. Quizás deberías buscar una cárcel o algo similar." },
    [3982] = { name = "¿Qué pasa?", objective = "Defiende a Gor'shak." },
    [4001] = { name = "¿Qué pasa?", objective = "Habla con Kharan Martillazo y recaba información sobre el secuestro de la princesa Moira Barbabronce. Llévale esa información a Thrall en Orgrimmar. Recuerdas que Gor'shak mencionó que Kharan estaba preso en una celda cercana." },
    [4002] = { name = "Los Reinos del Este", objective = "Si aceptas la misión, habla con Thrall." },
    [4081] = { name = "MATAR INMEDIATAMENTE: enanos Hierro Negro", objective = "Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores! El señor de la guerra Dientegore quiere que mates a 15 custodios de Yunque Colérico, 10 alcaides de Yunque Colérico y 5 lacayos de Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea." },
    [4122] = { name = "Grark Lorkrub", objective = "Ve a Las Estepas Ardientes y encuentra a Grark Lorkrub. Recuerdas que Lexlort mencionó que lo habían visto por última vez en una colosal fortaleza Roca Negra. Cuando encuentres a Grark Lorkrub, usa los grilletes de torio para atarlo y condúcelo de vuelta por la Montaña Roca Negra hasta La Garganta de Fuego. Lexlort tendrá a algunos de sus hombres esperándote al otro lado para llevarse a Grark detenido." },
    [4121] = { name = "¡Estás en un aprieto!", objective = "Escolta al prisionero, Grark Lorkrub, a través de Las Estepas Ardientes y la Montaña Roca Negra hasta La Garganta de Fuego. Recuerdas que Lexlort mencionó que tendría a algunos de sus hombres esperándote al otro lado para llevarse a Grark detenido. También tendrás que entregarle a Lexlort los grilletes de torio." },
    [4061] = { name = "La revuelta de las máquinas", objective = "Adéntrate en Las Estepas Ardientes y recupera 10 fragmentos de elemental agrietado para Hierofante Theodora Mulvadania. Recuerdas que Theodora mencionó que los golems y elementales de esa región eran la fuente de estos fragmentos." },
    [4062] = { name = "La revuelta de las máquinas", objective = "Lleva el ejemplar de fragmento de Elemental a Lotwil Veriatus. Recuerdas que Theodora dijo que Lotwil se encontraba en un campamento hacia el este." },
    [5002] = { name = "Un mensaje para Maxwell", objective = "Viaja a Las Estepas Ardientes y dale la información sobre Bijou al alguacil Maxwell." },
    [4981] = { name = "La espía Bijou", objective = "Viaja hasta la Cumbre de Roca Negra y averigua qué le ha ocurrido a Bijou." },
    [5065] = { name = "Las tablillas perdidas de Mosh'aru", objective = "Llévale la tercera y cuarta tablillas de Mosh'aru al prospector Ferrobota, que está en Tanaris." },
    [4726] = { name = "Esencia de cría", objective = "Llévale 8 esencias de cría y el Draco Incarcinatrix 900 a Tinkee Vaporino en el Peñacho Llamarada, en Las Estepas Ardientes." },
    [4808] = { name = "Felnok Acerovera", objective = "Entrégale la carta de Tinkee a Felnok Acerovera." },
    [4809] = { name = "Cuernos de quimera venfresco", objective = "Llévale 8 cuernos de quimera venfresco sin fisuras a Felnok Acerovera." },
    [4810] = { name = "Vuelve con Tinkee", objective = "Llévale el paquete de Felnok a Tinkee Vaporio en Las Estepas Ardientes." },
    [4907] = { name = "Tinkee Vaporino", objective = "Habla con Tinkee Vaporio." },
    [4734] = { name = "Un huevo congelado", objective = "Usa el prototipo de ovosciloscopio sobre un huevo de El Grajero." },
    [4903] = { name = "La orden del Señor de la Guerra", objective = "Mata al Alto señor Omokk, al maestro de guerra Voone y al Señor Supremo Vermiothalak. Recupera importantes documentos Roca Negra. Vuelve junto al señor de la guerra Dientegore en Kargath cuando hayas cumplido la misión." },
    [4941] = { name = "La sabiduría de Eitrigg", objective = "Habla con Eitrigg en Orgrimmar. Cuando hayas tratado unos asuntos con Eitrigg, busca el consejo de Thrall. Recuerdas haber visto a Eitrigg en la Cámara de Thrall." },
    [4974] = { name = "¡Por la Horda!", objective = "Ve a Cumbre de Roca Negra para matar al Jefe de Guerra Rend Puño Negro. Llévale su cabeza a Orgrimmar." },
    [6566] = { name = "Lo que trae el viento", objective = "Escucha a Thrall." },
    [6567] = { name = "El Campeón de la Horda", objective = "Busca a Rexxar. El Jefe de Guerra ha dicho que estará en Desolace, entre Sierra Espolón y Feralas." },
    [6568] = { name = "El testamento de Rexxar", objective = "Entrega el testamento de Rexxar a Myranda la Fada. Está en las Tierras de la Peste del Oeste." },
    [6402] = { name = "Tienes un cita en Ventormenta", objective = "Viaja hasta Ventormenta y aventúrate tras las puertas de la ciudad. Habla con el escudero Rowe para que haga saber al alguacil Windsor sobre tu llegada." },
    [6403] = { name = "La gran farsa", objective = "Sigue a Reginald Windsor por Ventormenta. ¡Protégele del peligro!" },
    [6501] = { name = "El Ojo del dragón", objective = "Debes buscar por todo el mundo y encontrar un ser capaz de restaurar el poder del fragmento del Ojo del dragón. La única información que tienes sobre dicho ser, es que existe." },
    [6570] = { name = "Brasaliza", objective = "Viaja a la Ciénaga de Fuego del Marjal Revolcafango y busca el Cubil de Brasaliza. Cuando estés dentro ponte el Amuleto de Subversión Dracónica y habla con Brasaliza." },
    [6582] = { name = "La prueba de las calaveras, Arúspice", objective = "Debes encontrar a Arúspice, el campeón draco del Vuelo Azul y matarlo. Separa su calavera de su cuerpo y llévasela a Brasaliza. Sabes que puedes encontrar a Arúspice en Cuna del Invierno." },
    [6583] = { name = "La prueba de las calaveras, Somnus", objective = "Destruye al campeón draco del Vuelo Verde, Somnus. Lleva su calavera a Brasaliza." },
    [6584] = { name = "La prueba de las calaveras, Chronalis", objective = "Chronalis, hijo de Nozdormu, custodia las Cavernas del Tiempo en el Desierto de Tanaris. Destrúyelo y lleva su calavera a Brasaliza." },
    [6585] = { name = "La prueba de las calaveras, Axtroz", objective = "Viaja a Grim Batol y encuentra a Axtroz, el campeón draco del Vuelo Rojo. Destrúyelo y hazte con su calavera. Llévasela a Brasaliza." },
    [6601] = { name = "El ascenso", objective = "Diría que se acabaron las charadas. Ya sabes que el Amuleto de Subversión Dracónica que Myranda la Fada creó para ti no funcionará en el interior de la Cumbre de Roca Negra. Quizás deberías buscar a Rexxar y explicarle el apuro en el que te encuentras. Enséñale el amuleto pirodraco apagado. Con un poco de suerte, él sabrá que hay que hacer ahora." },
    [5089] = { name = "Orden del general Drakkisath", objective = "Llévale la orden del general Drakkisath al alguacil Maxwell en Las Estepas Ardientes." },
    [5527] = { name = "Un relicario de pureza", objective = "Ve a Silithus a buscar un relicario de pureza en las ruinas de la Aldea del Viento del Sur. Llévaselo al rabino Saturna a Amparo de la Noche, en Claro de la Luna." },
    [5244] = { name = "Las ruinas de Kel'Theril", objective = "Habla con Jaron Tallapiedras en Aldea Estrella Fugaz." },
    [5245] = { name = "Espíritus condenados de Kel'Theril", objective = "Utiliza el pico de Jaron para encontrar los cuatro fragmentos de reliquia de los altonatos. Llévaselas a Aurora Llamacielo en las Tierras de la Peste del Este." },
    [5246] = { name = "Fragmentos del pasado", objective = "Encuentra las escrituras altonatas sagradas del templo de Zin-Malor en Azshara y tráelas para Aurora Llamacielo, en la Torre del Paso Norte en las Tierras de la Peste del Este." },
    [7637] = { name = "Énfasis en el sacrificio", objective = "Viaja a Forjaz y consigue el incensario de exorcismos del sumo sacerdote Rohan. Tendrás que hacer una donación de 150 monedas de oro para conseguirlo." },
    [7639] = { name = "Mostrarse juicioso", objective = "Devuelve el incensario de exorcismos a Lord Quiebrasombras en el Distrito de la Catedral de Ventormenta." },
    [7640] = { name = "Exorcismo en Valle del Terror", objective = "Utiliza el incensario de exorcismos para expulsar los espíritus que atormentan el Valle del Terror. Cuando hayas matado 25 espíritus del Valle del Terror, vuelve a ver a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta." },
    [7641] = { name = "El trabajo de Grimand Elmore", objective = "Habla con Grimand Elmore en el Distrito de los Enanos, en Ventormenta." },
    [7642] = { name = "Recopilación de artículos", objective = "Lleva 40 paños rúnicos, 6 lingotes de arcanita, 10 lágrimas de Arthas, 5 frascos de agua sagrada de Stratholme y 150 monedas de oro a Grimand Elmore en el Distrito de los Enanos de Ventormenta." },
    [7648] = { name = "Un trabajo bien hecho", objective = "Lleva la gualdrapa de arcanita a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta para que la inspeccione." },
    [7645] = { name = "Alimento para caballo enriquecido con maná", objective = "Consigue 20 galletas de maná, ingrediente principal del alimento especial para caballos, y llévaselas a Merideth Carlson a las Laderas de Trabalomas, en Costasur. Solo Alba Argenta fabrica esas galletas. También tienes que darle 50 piezas de oro para aplacar su orgullo herido." },
    [7563] = { name = "La ira de sangre", objective = "Llévale 30 botellas de sangre de bestia embravecida a Mor'zul Sangredoble en Las Estepas Ardientes." },
    [7564] = { name = "Ojosalvajes", objective = "Llévale el estuche de sangre a Gorzeeki Ojosalvajes en Las Estepas Ardientes." },
    [7623] = { name = "Lord Pesadilla", objective = "Cómprale oscuras pociones a Gorzeeki en Las Estepas Ardientes. Usa la pociones para viajar por Jaedenar y habla con Lord Pesadilla." },
    [7624] = { name = "Ulathek el Traidor", objective = "Enfréntate a Ulathek y llévale el corazón del traidor a Lord Pesadilla en Jaedenar." },
    [7625] = { name = "Polvo estelar xorotiano", objective = "Cómprale polvo estelar xorotiano a Ur'dan. Llévaselo a Gorzeeki Ojosalvajes en Las Estepas Ardientes." },
    [7626] = { name = "La Campana de Dethmoora", objective = "Llévale 10 elixires de poder de las sombras a Gorzeeki Ojosalvajes en Las Estepas Ardientes." },
    [7627] = { name = "Rueda de la Marcha Negra", objective = "Llévale 6 grandes fragmentos brillantes y 25 minerales de hierro negro a Gorzeeki Ojosalvajes en Las Estepas Ardientes." },
    [7628] = { name = "La Vela del Apocalipsis", objective = "Lleva 35 escamas de dragón negro a Gorzeeki Ojosalvajes a Las Estepas Ardientes." },
    [7630] = { name = "La arcanita", objective = "Lleva 3 lingotes de arcanita a Gorzeeki Ojosalvajes a Las Estepas Ardientes." },
    [5461] = { name = "El humano, Ras Levescarcha", objective = "Viaja a las Tierras Altas de Arathi, a las Ruinas de Stromgarde. En Stromgarde busca un Recuerdo de Evocación. Si lo encuentras llévaselo al magistrado Marduke." },
    [5462] = { name = "El moribundo, Ras Levescarcha", objective = "Viaja a Esperanza de la Luz en las Tierras de la Peste del Este y busca a Leonid Barthalomew el Venerado. Enséñale el Recuerdo de Evocación y cuéntale todo lo que has descubierto." },
    [5464] = { name = "El Obsequio de Menethil", objective = "Lleva las Memorias del Vínculo del Alma a Leonid Barthalomew a las Tierras de la Peste del Este." },
    [5465] = { name = "Memorias del Vínculo del Alma", objective = "Vuelve con el magistrado Marduke a Castel Darrow. Muéstrale las Memorias del Vínculo del Alma." },
    [5522] = { name = "Leonid Barthalomew", objective = "Lleva los huevos congelados a Leonid Barthalomew a las Tierras de la Peste del Este." },
    [5531] = { name = "Betina Bigglezink", objective = "Lleva los huevos congelados a Betina Bigglezink, que está fuera." },
    [7644] = { name = "La gualdrapa de arcanita bendecida", objective = "Devuelve la Blessed Arcanite Barding a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta." },
    [7646] = { name = "Arúspice", objective = "Lleva un diamante de Azeroth y un diamante negro prístino a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta." },
    [7667] = { name = "Asistencia material", objective = "Si te interesa ayudar a Sagorne Montacresta, llévale 1 diamante de Azeroth y 1 diamante negro prístino al Valle de la Sabiduría, en Orgrimmar." },
    [5251] = { name = "El archivista", objective = "Viaja a Stratholme y encuentra al archivista Galford de La Cruzada Escarlata. Acaba con él y quema el Archivo Escarlata." },
    [5542] = { name = "Perros demoníacos", objective = "Mata 20 cachorros de can de la Peste, 5 canes de la Peste y 5 canes de la Peste demenciados. Cuando hayas terminado tu tarea regresa con Tirion Fordring." },
    [5543] = { name = "Cielos sangrientos", objective = "Mata 30 murcípestes y vuelve con Tirion Fordring." },
    [5544] = { name = "Gusanos carroñeros", objective = "Busca las larvas y devoradores carroñeros de la zona. Mátalos y recoge su carne. Regresa con Tirion Fordring cuando tengas 14 trozos de carne de gusano carroñero." },
    [5742] = { name = "Redención", objective = "Escucha lo que Tirion Fordring tiene que contarte." },
    [5781] = { name = "De recuerdos olvidados", objective = "Viaja a La Subgranja, en la sección más meridional de las Tierras de la Peste del Este, y recupera el Martillo de Taelan. Cuando hayas cumplido tu objetivo regresa con Tirion Fordring." },
    [5845] = { name = "Del honor perdido", objective = "Viaja a Vallenorte, en la zona noreste de las Tierras de la Peste del Este, y recupera el Símbolo del Honor Perdido. Cuando hayas cumplido tu objetivo regresa con Tirion Fordring." },
    [5846] = { name = "De amor y familia", objective = "Viaja a la isla de Castel Darrow, en la región sur del centro de las Tierras de la Peste. Allí, busca pistas sobre el paradero del cuadro." },
    [5262] = { name = "La verdad cae del cielo", objective = "Lleva la cabeza de Balnazzar al Duque Nicholas Zverenhoff en las Tierras de la Peste del Este." },
    [6133] = { name = "La orden del Señor de exploradores", objective = "Viaja a la frontera norte de las Tierras de la Peste del Este y recupera el Registro de Quel'Thalas. Se encuentra en algún lugar del Refugio Quel'Lithien. También tienes que matar a 8 exploradores, 8 zancaminos y 8 Leñantros." },
    [6042] = { name = "Los pequeños problemas de la no-vida", objective = "Mata a 20 murcipestes tóxicos y 10 murcipestes monstruosos. Vuelve con Nathanos Clamorinfecto cuando hayas acabado." },
    [6022] = { name = "Matar con un propósito", objective = "Viaja al Cruce de Corin al este y mata a los miembros de la Plaga que habitan allí. Recoge 7 piezas de putrefacción viva en 10 minutos. Utiliza el mortero y la mano de mortero para convertir la putrefacción viva en putrefacción coagulada." },
    [6135] = { name = "Alatardecer, cómo te odio…", objective = "Encuentra a Alatardecer y mátalo. Recoge un parche de piel de Alatardecer de su cadáver y llévaselo a Nathanos Clamorinfecto. Se dice que Alatardecer vaga por el campo, al norte de la Hacienda de Marris." },
    [6136] = { name = "El corpulento", objective = "Encuentra a Borelgore en las planicies del norte de las Tierras de la Peste del Este y destrúyelo. Vuelve junto a Nathanos Clamorinfecto cuando hayas cumplido la misión." },
  },
  ptBR = {
    [1113] = { name = "Corações do fanatismo", objective = "O Mestre-boticário Faranello, da Cidade Baixa, quer 20 Corações do Fanatismo." },
    [6521] = { name = "Uma aliança profana", objective = "Leve a cabeça do Embaixador Malcin para Varimatras, na Cidade Baixa." },
    [1956] = { name = "Poder em Uldaman", objective = "Recupere uma Fonte de Energia de Obsidiana e leve-a para Tabetha no Pântano Vadeoso." },
    [4143] = { name = "Brumas do mal", objective = "Colha 5 amostras de Bruma de Atal'ai, depois fale novamente com Melco na Cratera Un'Goro." },
    [4146] = { name = "Combustível de fulminadora", objective = "Entregue a Fulminadora Descarregada e 5 amostras de Bruma de Atal'ai a Lário, no Refúgio do Marshal." },
    [9053] = { name = "Um ingrediente melhor", objective = "Consiga uma Trepadeira Pútrida do guardião no fundo do Templo Submerso e fale novamente com Torwa Mateiro." },
    [8232] = { name = "O draco verde", objective = "Leve o Dente de Morphaz para Ogtinc em Azshara. Ogtinc mora no alto dos penhascos a nordeste das Ruínas de Eldarath." },
    [8253] = { name = "A destruição de Morphaz", objective = "Recupere o Estilhaço Arcano de posse de Morphaz e fale novamente com o Arquimago Tauriel." },
    [8418] = { name = "Forjando o megalito", objective = "Leve as Penas Vodu para Ashlam Punhobom." },
    [8257] = { name = "Sangue de Morphaz", objective = "Mate Morphaz no templo submerso de Atal'Hakkar e leve o sangue dele para Greta Musgo no Casco na Selva Maleva. A entrada do templo submerso fica no Pântano das Mágoas." },
    [8236] = { name = "A chave lazúli", objective = "Leve a Chave Lazúli para o Lorde Jorach Corvoforte." },
    [8413] = { name = "O Vodu", objective = "Leve as Penas Vodu para Bath'rah, o Vigia dos Ventos." },
    [8422] = { name = "Penas de troll", objective = "Leve um total de 6 Penas Vodu dos trolls do templo submerso." },
    [8425] = { name = "Penas Vodu", objective = "Leve as Penas Vodu dos trolls do Templo Submerso para o Herói Caído da Horda." },
    [4362] = { name = "O destino do reino", objective = "Volte ao Abismo Rocha Negra e resgate a Princesa Moira Barbabronze das garras malignas do Imperador Dagran Thaurissan." },
    [4003] = { name = "O resgate real", objective = "Mate o Imperador Dagran Thaurissan e liberte a Princesa Moira Barbabronze do feitiço maligno." },
    [7201] = { name = "O último elemento", objective = "Vá até o Abismo Rocha Negra e obtenha 10 Essências dos Elementos. Seu primeiro impulso é procurar nos golens e criadores de golens. Você lembra que Vivian Latumba também mencionou elementais." },
    [4286] = { name = "Produto de primeira", objective = "Viaje para o Abismo Rocha Negra e recupere 20 Pochetes Ferro Negro. Fale novamente com Oralius quando tiver completado a tarefa. Você supõe que os anões Ferro Negro de dentro do Abismo Rocha Negra carregam essa tal de \"pochete\"." },
    [7848] = { name = "Harmonização com o Núcleo", objective = "Vá ao portal da entrada do Núcleo Derretido no Abismo Rocha Negra e recupere um Fragmento de Núcleo. Fale novamente com Lothos Fendespéril na Montanha Rocha Negra após recuperar o Fragmento de Núcleo." },
    [5001] = { name = "Pertences da Biju", objective = "Encontre os Pertences de Biju e devolva-os a ela. Boa sorte!" },
    [4982] = { name = "Pertences da Biju", objective = "Encontre os Pertences de Biju e devolva-os a ela. Ela mencionou tê-los guardado no nível mais profundo da cidade." },
    [4788] = { name = "As últimas tabuletas", objective = "Leve a Quinta e a Sexta Tabuletas Mosh'Aru ao Prospector Botaférrea, em Tanaris." },
    [6569] = { name = "Ilusões ópticas", objective = "Vá para o Pico da Rocha Negra e colete 20 Olhos de Dragomorfo Preto. Fale novamente com Myranda, a Bruxa Velha, depois que tiver terminado a tarefa." },
    [4764] = { name = "Broche do Finitudo", objective = "Leve o Broche do Finitudo para Mayara Asaluz nas Estepes Ardentes." },
    [4768] = { name = "A tabuleta de Pedranegra", objective = "Leve a Tabuleta de Pedranegra à Umbramante Vivian Latumba, em Karrath." },
    [5160] = { name = "A protetorada-máter", objective = "Viaje para Hibérnia e encontre Haleh. Entregue para ela a Escama do Albi." },
    [5526] = { name = "Pedaços de Vinhavil", objective = "Encontre a Vinhavil no Gládio Cruel e obtenha uma lasca dela. É bem provável que você só consiga encontrar uma depois da derrota de Azzin, o Selvamorfo. Use o Relicário da Pureza para selar a lasca com segurança e leve-a de volta para Ravine Saturna, no Refúgio Noturno, que fica na Clareira da Lua." },
    [7463] = { name = "Bebida arcana", objective = "Vá ao Distrito Lenhatorta, no Gládio Cruel, e mate o elemental da água, Rebentágua. Leve a Essência de Rebentágua para o Erudito Lydros, no Ateneu." },
    [7461] = { name = "A loucura intrínseca", objective = "Mate os guardiões que cercam os cinco pilares de força da Prisão de Immol'thar. Quando os pilares se desligarem, o campo de força que cerca Immol'thar se dissipará. Destrua o terrível demônio que fica no coração da Prisão de Immol'thar. Por fim, enfrente o Príncipe Tortheldrin, no Ateneu. Fale novamente com a Anciã Shen'dralar, no pátio, após cumprir a missão." },
    [5247] = { name = "Fragmentos do passado", objective = "Leve uma Barra de Tório Encantado, 5 Restaurações de Cristal e uma Ampola de Água Hedionda para Aurora Clamacéus perto da Torre do Passo Norte nas Terras Pestilentas Orientais." },
    [7643] = { name = "O Espírito Equino Antigo", objective = "Obtenha uma ração de cavalo especial para alimentar o cavalo espiritual. Aparentemente, Judite Castanheira, que vive na Costa Sul, é a fornecedora da tal ração. Entre na masmorra de Gládio Cruel, em Feralas, e mate Gavíneo Lenhatorta. Isso libertará o Espírito Equino Antigo. Alimente-o com a ração de cavalo especial, o que acalmará o espírito. Finalmente, dê-lhe a Barda de Arcanita para que ele a abençoe." },
    [7631] = { name = "Corcel Medonho de Zoroth", objective = "Leia as Instruções de Mor'zul. Evoque um Corcel Medonho Zorothiano, derrote-o e então vincule o espírito dele a você." },
    [7506] = { name = "O Sonho Esmeralda...", objective = "Devolva o livro aos legítimos donos." },
    [7503] = { name = "A Grande Corrida dos Caçadores", objective = "Devolva o livro aos legítimos donos." },
    [7500] = { name = "Livro de Receitas do Arcanista", objective = "Devolva o livro aos legítimos donos." },
    [7501] = { name = "A Luz e Como Ativá-la", objective = "Devolva o livro aos legítimos donos." },
    [7504] = { name = "Caçarolas: O Que a Luz Não lhe Contará", objective = "Devolva o livro aos legítimos donos." },
    [7498] = { name = "Garona: Um Estudo sobre Furtividade e Traição", objective = "Devolva o livro aos legítimos donos." },
    [7505] = { name = "O Choque Gélido e Você", objective = "Devolva o livro aos legítimos donos." },
    [7502] = { name = "Sombras Agrilhoantes", objective = "Devolva o livro aos legítimos donos." },
    [7499] = { name = "Códice de Defesa", objective = "Devolva o livro aos legítimos donos." },
    [7629] = { name = "Entrega de diabrete", objective = "Leve o Diabrete numa Jarra para o laboratório de alquimia em Scolomântia. Depois que o pergaminho for criado, devolva a jarra para Gorzeeki Olholouco." },
    [7647] = { name = "Julgamento e redenção", objective = "Use o Cristal Divinatório no coração do porão do Grande Ossário, em Scolomântia. Isso invocará espíritos que você precisará julgar. A derrota dos espíritos evocará o Cavaleiro da Morte Noctilatrus. Derrote-o e reclame a alma perdida do corcel caído. Entregue a Alma Redimida do Corcel e a Barda Encantada Abençoada ao Corcel Caído de Noctilatrus." },
    [7668] = { name = "A ameaça de Noctilatrus", objective = "Use o Cristal Divinatório no coração do porão do Grande Ossário, em Scolomântia. Isso invocará espíritos que você precisará enfrentar. A derrota dos espíritos evocará o Cavaleiro da Morte Noctilatrus. Derrote-o. Leve a Cabeça de Noctilatrus para Sagorne Monta Crista, no Vale da Sabedoria, em Orgrimmar." },
    [5463] = { name = "Dádiva de Menethil", objective = "Vá até Stratholme e encontre a Dádiva de Menethil. Ponha o Livro de Recordações no solo profanado." },
    [261] = { name = "No caminho Escarlate", objective = "Destrua 30 Assoladores Mortos-vivos, depois fale novamente com o Irmão Anton no Posto do Nijel." },
    [1052] = { name = "No caminho Escarlate", objective = "Leve a Carta de Comenda de Anton para Raul, o Devotado, na Costa Sul." },
    [6522] = { name = "Uma aliança profana", objective = "Leve o Pergaminho Pequeno para Varimatras, na Cidade Baixa." },
    [720] = { name = "Um sinal de esperança", objective = "Encontre o Prospector Ryedol e avise que Grez Pé-de-malho está vivo." },
    [738] = { name = "Encontre Agmundo", objective = "." },
    [739] = { name = "Murdaloc", objective = "Mate Murdaloc, o assassino de Agmundo. Mate 12 Quebraossos da Abóbada de Pedra. Apresente-se ao Prospector Bandaferro em Loch Modan." },
    [723] = { name = "Prospector da fé", objective = "Leve o Amuleto do Pé-de-malho para o Prospector Ryedol nos Ermos." },
    [724] = { name = "Prospector da fé", objective = "Leve o Amuleto do Pé-de-malho para o Historiador Karnik, em Altaforja." },
    [725] = { name = "A notícia de uma ameaça", objective = "Encontre o Conselheiro Belgrum e entregue o bilhete." },
    [726] = { name = "A notícia de uma ameaça", objective = "Fale com o Historiador Karnik." },
    [762] = { name = "Um embaixador do mal", objective = "Mate o Embaixador Infernus na Fortaleza Angor e leve a prova de sua morte para o Conselheiro Belgrum em Altaforja." },
    [2198] = { name = "O colar estilhaçado", objective = "Procure o criador original do colar estilhaçado para saber sobre seu valor potencial." },
    [2199] = { name = "Aí tem truta!", objective = "Leve cinco barras de prata para Didiê Du Mocó em Altaforja." },
    [2200] = { name = "De volta a Uldaman", objective = "Procure pistas sobre disposição atual do colar de Didiê dentro de Uldaman. O paladino morto que ele mencionou foi a última pessoa a portá-lo." },
    [2318] = { name = "Traduzindo o diário", objective = "Encontre alguém que consiga traduzir o diário do paladino. O local mais próximo que pode ter alguém que o faça é Karrath, nos Ermos." },
    [2338] = { name = "Traduzindo o diário", objective = "Empreste o colar a Jarkal. Em troca, ele vai traduzir o diário para você." },
    [2500] = { name = "Busca pelos reagentes dos Ermos", objective = "Consiga os reagentes dos Ermos de que Ghak Toquecura precisa, então fale novamente com ele em Thelsamar." },
    [2258] = { name = "Busca pelos reagentes dos Ermos", objective = "Leve 5 Moelas de Urubu, 10 Presas de Coiote do Rochedo e 5 Estilhaços de Elemental da Rocha para Jarkal Limuno em Karrath, Ermos." },
    [1954] = { name = "O Orbe Infernal", objective = "Leve um Orbe Infernal para Tabetha no Pântano Vadeoso." },
    [1955] = { name = "O Exorcismo", objective = "Mate o Demônio do Orbe, depois fale com Tabetha." },
    [2988] = { name = "Jaulas Cascasseca", objective = "Verifique as jaulas nas duas aldeias Cascasseca, depois fale novamente com o Mestre de Grifos Garra-de-acha." },
    [2989] = { name = "Altar de Zul", objective = "Verifique o topo do Altar de Zul, depois fale novamente com o Mestre de Grifos Garra-de-acha." },
    [2990] = { name = "Tádius Sombraustera", objective = "Leve a Pena de Bicoafiado para Tádius Sombraustera na Barreira do Inferno." },
    [2933] = { name = "Garrafas de peçonha", objective = "Leve uma Garrafa de Peçonha para um boticário na Serraria Tarren." },
    [2934] = { name = "Vesícula de peçonha intacta", objective = "Leve a Vesícula de Peçonha Intacta para o Boticário Lindolfo na Serraria Tarren." },
    [2935] = { name = "Consulte o Mestre Gadrin", objective = "Fale com o Mestre Gadrin na Aldeia Sen'jin." },
    [3520] = { name = "Espíritos guinchadores", objective = "Capture os espíritos de 3 guinchadores em Feralas, e depois fale novamente com Yeh'kinya no Porto de Bondebico." },
    [1448] = { name = "Em busca do templo", objective = "Brohann Barrilga, em Ventobravo, quer que você saia à procura do Templo de Atal'Hakkar." },
    [1449] = { name = "Rumo às Terras Agrestes", objective = "Fale com o Alto Thane Falstad Martelo Feroz no Ninho da Águia nas Terras Agrestes." },
    [1450] = { name = "Mestre de Grifos Garra-de-acha", objective = "Fale com o Mestre de Grifos Garra-de-acha no Aviário do Ninho da Águia." },
    [1451] = { name = "Rapsódico Festanjeiro", objective = "Procure Rapsódico Festanjeiro nas Terras Agrestes." },
    [1452] = { name = "O Coquetel de Kalimdor do Rapsódico", objective = "Rapsódico Festanjeiro, nas Terras Agrestes, quer que você consiga 3 Moelas de Roca, 3 Fígados de Groddoc e 3 Fígados de Veloférreo." },
    [1469] = { name = "O caso do Rapsódico", objective = "Leve o Fragmento de Tabuleta Atal'ai para Brohann Barrilga em Ventobravo." },
    [1424] = { name = "Poço de Lágrimas", objective = "Vil'zerul, no Pedregal, quer que você colete 10 Artefatos Atal'ai." },
    [1429] = { name = "O exilado Atal'ai", objective = "Leve o Saco de Artefatos Atal'ai para o Exilado Atal'ai nas Terras Agrestes." },
    [1444] = { name = "Retorno a Vil'zerul", objective = "Fale novamente com Vil'Zerul em Pedregal." },
    [3444] = { name = "O círculo de pedra", objective = "Busque o Círculo de Pedra na oficina de Marlon Catarrebite em Vila Catraca." },
    [4787] = { name = "O ovo velho", objective = "Leve o Ovo Velho para Yeh'kinya, em Tanaris." },
    [4141] = { name = "Melco e Lário", objective = "Colha 15 Pétalas Sangrentas e fale novamente com Melco." },
    [4142] = { name = "Uma visita a Gregan", objective = "Leve uma Pétala Sangrenta para Gregan Cospechope em Feralas." },
    [4145] = { name = "Lário e Melco", objective = "Cace 5 Açoitadeiras Pétala Sangrenta, 5 Látegas Pétala Sangrenta, 5 Esfoladoras Pétala Sangrenta e 5 Laçadoras Pétala Sangrenta para Lário, do Refúgio do Marshal." },
    [4147] = { name = "Oficina do Marlon", objective = "Vá até a oficina de Marlon Catarrebite na Vila Catraca." },
    [9052] = { name = "Veneno de Pétala Sangrenta", objective = "Colete 8 Cogumelos Vermelhos e 8 Ferrões de Gorishi e fale novamente com Torwa Mateiro na Cratera Un'Goro." },
    [9051] = { name = "Exame de intoxicação", objective = "Espete um Demossauro com uma Farpa para Demossauro. Fale novamente com Torwa Mateiro na Cratera Un'goro depois que tiver terminado a tarefa." },
    [8153] = { name = "Galhada de ginete", objective = "Leve um par de Galhadas Perfeitas de Ginete para Ogtinc em Azshara. Ogtinc vive no alto dos penhascos a nordeste das Ruínas de Eldarath." },
    [8231] = { name = "Furando onda", objective = "Leve 6 Escamas de Fura-ondas para Ogtinc em Azshara. Ogtinc mora no alto dos penhascos a nordeste das Ruínas de Eldarath." },
    [8251] = { name = "Pó Mágico", objective = "Leve 10 Poeiras Reluzentes para o Arquimago Tauriel." },
    [8252] = { name = "Coral de sirenas", objective = "Obtenha 6 Corais Encantados e entregue-os ao Arquimago Tauriel." },
    [8414] = { name = "Dissipando o mal", objective = "Colete 20 Pedras do Flagelo do Lacaio e leve-as ao Sumo Sacerdote Thel'danis nas Terras Pestilentas Ocidentais." },
    [8416] = { name = "Pedras do Flagelo inertes", objective = "Leve a Pedra do Flagelo Inerte ao Comandante Ashlam Punhobom no Morro do Ventogelante." },
    [8255] = { name = "Ginetes sagrados", objective = "Obtenha 4 Glândulas de Ginete Saudável leve-as para Ogtinc em Azshara. Ogtinc vive no alto dos penhascos a nordeste das Ruínas de Eldarath." },
    [8256] = { name = "A linfa de morte-viva", objective = "Obtenha uma Linfa de Morte-viva para Ogtinc em Azshara. Ogtinc mora no alto dos penhascos a nordeste das Ruínas de Eldarath." },
    [8234] = { name = "Saco lazúli lacrado", objective = "Recupere o Saco Lazúli Lacrado com o Xamã Presamatos, em Azshara. Então o leve para o Arquimago Tauriel, também em Azshara." },
    [8235] = { name = "Fragmentos codificados", objective = "Leve 10 Fragmentos Codificados para o Arquimago Tauriel em Azshara." },
    [8410] = { name = "Mestre dos elementos", objective = "Colete uma amostra de ar, fogo, terra e água para Bath'rah, o Vigia dos Ventos." },
    [8412] = { name = "Totem de espírito", objective = "Leve as partes para Bath'rah, o Vigia dos Ventos, fazer o totem de espírito." },
    [8419] = { name = "Pedido de diabrete", objective = "Leve um pedaço de Tecido Vil para Diabretim, em Selva Maleva." },
    [8420] = { name = "Quente e pinicante", objective = "Leve um pedaço de Tecido Vil para Diabretim, em Selva Maleva." },
    [8421] = { name = "O enchimento errado", objective = "Leve 10 pedaços de Madeira Podre e 4 Essências de Peçonha para Diabretim em Selva Maleva." },
    [8423] = { name = "Parentesco guerreiro", objective = "Mate 7 Javiltuscos na Barreira do Inferno e fale novamente com o Herói Caído da Horda." },
    [8424] = { name = "Guerra aos devotos da sombra", objective = "Mate os Devotos da Sombra na Barreira do Inferno e fale novamente com o Herói Caído da Horda." },
    [3801] = { name = "Legado dos Ferro Negro", objective = "Fale com Franclorn Forjífice se tiver interesse em obter uma chave para a parte principal da cidade." },
    [4262] = { name = "Mestre Supremo Piro", objective = "Mate o Mestre Supremo Piro e fale novamente com Jalinda Ramo. Você se lembra de Jalinda ter dito que Piro guarda a pedreira. Que tal procurar por lá?" },
    [3702] = { name = "As fumegantes Ruínas de Thaurissan", objective = "Escute a Historiadora Real Arquefilis recontar a história de Thaurissan." },
    [3701] = { name = "As fumegantes Ruínas de Thaurissan", objective = "Vá até as Ruínas de Thaurissan, nas Estepes Ardentes, e descubra informações sobre as Relíquias de Thaurissan. Fale novamente com a Historiadora Real Arquefilis quando terminar." },
    [4341] = { name = "Kharan Feromalho", objective = "Viaje para Abismo Rocha Negra e encontre Kharan Feromalho. O Rei mencionou que Kharan estava preso lá — talvez seja bom procurar uma prisão." },
    [4342] = { name = "O conto de Kharan", objective = "Ouça Kharan Feromalho contar a história dele." },
    [4361] = { name = "Informante das más notícias", objective = "Volte a Altaforja e dê as más notícias ao Rei Magni Barbabronze." },
    [4182] = { name = "Ameaça draconiana", objective = "Mate 15 Filhotes Negros, 10 Dragomorfos Negros, 4 Draconoides Negros e 1 Draco Negro. Fale novamente com Helendis Flumicórnio quando a tarefa estiver concluída." },
    [4183] = { name = "Os verdadeiros mestres", objective = "Viaje até Vila Plácida e entregue a Carta de Helendis Flumicórnio ao Magistrado Salomão." },
    [4184] = { name = "Os verdadeiros mestres", objective = "Viaje para Ventobravo e entregue o Apelo de Salomão ao Grão-lorde Bolvar Fordragon. Bolvar reside na Bastilha Ventobravo." },
    [4185] = { name = "Os verdadeiros mestres", objective = "Fale com o Grão-lorde Bolvar Fordragon depois de falar com a Lady Katrana Prestor." },
    [4186] = { name = "Os verdadeiros mestres", objective = "Leve o Decreto de Bolvar para o Magistrado Salomão, em Vila Plácida." },
    [4223] = { name = "Os verdadeiros mestres", objective = "Fale com o Oficial Maxwell nas Estepes Ardentes." },
    [4224] = { name = "Os verdadeiros mestres", objective = "Fale com João Roto para saber o destino do Marechal Vilasboas e fale novamente com o Oficial Maxwell quando tiver completado essa tarefa. Você se lembra do Oficial Maxwell lhe dizendo para procurá-lo em uma caverna ao norte." },
    [4241] = { name = "Marechal Vilasboas", objective = "Viaje para a Montanha Rocha Negra, a noroeste, e entre no Abismo Rocha Negra. Descubra o que aconteceu com o Marechal Vilasboas. Você se lembra de João Roto falando sobre Vilasboas ter sido arrastado para uma prisão." },
    [4242] = { name = "Esperança abandonada", objective = "Leve as más notícias ao Oficial Maxwell." },
    [4264] = { name = "Bilhete amassado", objective = "Você pode ter acabado de descobrir algo que o Marechal Vilasboas estaria interessado em ver. Pode haver esperança, afinal." },
    [4282] = { name = "Um fiapo de esperança", objective = "Recupere as Informações Perdidas do Marechal Vilasboas. O Marechal Vilasboas acredita que as informações estão sendo mantidas pelo Lorde Golem Argelmach e pelo General Forjaversa." },
    [3906] = { name = "Desarmonia das chamas", objective = "Vá até a pedreira da Montanha Rocha Negra e mate o Mestre Supremo Piro. Fale novamente com Coração Trovejante quando tiver cumprido essa tarefa." },
    [3981] = { name = "Comandante Gor'shak", objective = "Encontre o Comandante Gor'shak no Abismo Rocha Negra. Você se lembra que o tosco desenho incluía barras rabiscadas sobre o orc. Talvez você devesse procurar algum tipo de prisão." },
    [3982] = { name = "O que está acontecendo?", objective = "Defenda Gor'shak." },
    [4001] = { name = "O que está acontecendo?", objective = "Fale com Kharan Feromalho para obter informações sobre o sequestro da Princesa Moira Barbabronze. Leve as informações para Thrall em Orgrimmar. Gor'shak mencionou que Kharan estava preso em uma cela próxima." },
    [4002] = { name = "Os Reinos do Leste", objective = "Fale com Thrall se estiver <preparado/preparada> para assumir a missão que ele planejou." },
    [4081] = { name = "SE VIR, MATE: Anões Ferro Negro", objective = "Desbrave o Abismo Rocha Negra e destrua aqueles invasores degenerados! O Senhor da Guerra Trincador quer que você mate 15 Guardas Furiadastra, 10 Carcereiros Furiadastra e 5 Soldados Rasos Furiadastra. Fale novamente com ele quando o trabalho estiver terminado." },
    [4122] = { name = "Grark Lorkrub", objective = "Vá para as Estepes Ardentes e encontre Grark Lorkrub. Segundo Lexlort, ele foi visto pela última vez em uma imensa fortaleza Rocha Negra. Quando encontrar Grark Lorkrub, use os Grilhões de Tório para prendê-lo e levá-lo de volta à Garganta Abrasadora, passando pela Montanha Rocha Negra. Os homens de Lexlort estarão esperando do outro lado para levar Grark sob sua custódia." },
    [4121] = { name = "Situação precária", objective = "Escolte seu prisioneiro, Grark Lorkrub, pelas Estepes Ardentes, atravessando a Montanha Rocha Negra até chegar à Garganta Abrasadora. Você se lembra de ter ouvido Lexlort dizer que mandaria seus homens esperar no outro lado para levar Grark sob custódia. Você também vai precisar entregar os Grilhões de Tório para Lexlort." },
    [4061] = { name = "O levante das máquinas", objective = "Vá para as Estepes Ardentes e recupere 10 Estilhaços Elementais Fraturados para a Hierofante Theodora Malvadania. Você se lembra que Theodora mencionou que os golens e elementais dessa região são uma fonte desses estilhaços." },
    [4062] = { name = "O levante das máquinas", objective = "Leve a Amostra de Estilhaço Elemental para Lotwil Viriato. Segundo Theodora, Lotwil estava escalado em um acampamento ao leste." },
    [5002] = { name = "Mensagem para Maxwell", objective = "Viaje para as Estepes Ardentes e dê as Informações de Biju para o Oficial Maxwell." },
    [4981] = { name = "Agente Biju", objective = "Vá ao Pico da Rocha Negra e descubra o que aconteceu com Biju." },
    [5065] = { name = "As tabuletas Mosh'Aru perdidas", objective = "Leve a Terceira e a Quarta Tabuletas Mosh'Aru ao Prospector Botaférrea, em Tanaris." },
    [4726] = { name = "Essência da Reprodução", objective = "Leve 8 Essências da Reprodução e o Draco-incarcinatrix 900 a Vera Brequim no Monte Candente, que fica nas Estepes Ardentes." },
    [4808] = { name = "Felnok Molaço", objective = "Leve a Carta de Vera para Felnok Molaço." },
    [4809] = { name = "Chifres de ventogelante", objective = "Leve 8 Chifres Inteiriços de Quimera Ventogelante para Felnok Molaço." },
    [4810] = { name = "Fale novamente com Vera", objective = "Leve o Pacote do Felnok para Vera Brequim, nas Estepes Ardentes." },
    [4907] = { name = "Vera Brequim", objective = "Fale com Vera Brequim." },
    [4734] = { name = "Congelar os ovos", objective = "Use o Protótipo de Ovosciloscópio em um ovo no Viveiro." },
    [4903] = { name = "O comando do Senhor da Guerra", objective = "Mate o Grão-lorde Omokk, o Senhor da Guerra Voone e o Lorde Supremo Wyrmthalak. Recupere Documentos Importantes dos Rocha Negra. Fale novamente com o Senhor da Guerra Trincador, em Karrath, quanto a missão tiver sido cumprida." },
    [4941] = { name = "A sabedoria de Eitrigg", objective = "Fale com Eitrigg em Orgrimmar. Quando tiver discutido o assunto com Eitrigg, busque o conselho de Thrall. Você se lembra de ter visto Eitrigg nos aposentos de Thrall." },
    [4974] = { name = "Pela Horda!", objective = "Viaje para o Pico da Rocha Negra e mate o Chefe Guerreiro Laceral Mão Negra. Pegue sua cabeça e volte para Orgrimmar." },
    [6566] = { name = "O que o vento carrega", objective = "Ouça Thrall." },
    [6567] = { name = "O campeão da Horda", objective = "Procure Rexxar. O Chefe Guerreiro <o/a> instruiu quanto ao paradeiro dele. Procure nos caminhos de Desolação, entre a Cordilheira das Torres de Pedra e Feralas." },
    [6568] = { name = "O testamento de Rexxar", objective = "Leve o Testamento de Rexxar para Myranda, a Bruxa Velha, nas Terras Pestilentas Ocidentais." },
    [6402] = { name = "Encontro marcado em Ventobravo", objective = "Viaje a Ventobravo e vá até os portões da cidade. Fale com o Escudeiro Rui para que ele avise ao Marechal Vilasboas que você chegou." },
    [6403] = { name = "O grande baile de máscaras", objective = "Siga Reginaldo Vilasboas através de Ventobravo. Proteja-o de qualquer ataque!" },
    [6501] = { name = "O Olho do Dragão", objective = "Você deve vasculhar o mundo em busca de uma criatura capaz de restaurar o poder do Fragmento do Olho do dragão. A única informação que você tem sobre essa criatura é que ela existe." },
    [6570] = { name = "Ardeluta", objective = "Vá até o Pântano da Serpe, no Pântano Vadeoso, e procure o Covil de Ardeluta. Quando estiver lá, use o Amuleto de Subversão Dracônica e fale com Ardeluta." },
    [6582] = { name = "O teste dos crânios: Áugure", objective = "Encontre e mate o Áugure, o draco da Revoada Dragônica Azul. Arranque a cabeça do draco morto e leve-a para Ardeluta. Você sabe que o Áugure se encontra em Hibérnia." },
    [6583] = { name = "O teste dos crânios: Somnus", objective = "Destrua Somnus, o draco campeão da Revoada Verde. Pegue seu crânio e leve-o para Ardeluta." },
    [6584] = { name = "O teste dos crânios: Chronalis", objective = "Guardando as Cavernas do Tempo no Deserto de Tanaris, encontra-se Chronalis, filho de Nozdormu. Destrua-o e leve seu crânio para Ardeluta." },
    [6585] = { name = "O teste dos crânios: Axtroz", objective = "Vá para Grim Batol e encontre Axtroz, o draco campeão da Revoada Vermelha. Destrua-o e arranque sua cabeça. Leve o crânio para Ardeluta." },
    [6601] = { name = "Ascensão...", objective = "Pelo jeito, a farsa chegou ao fim. Você já sabe que o Amuleto de Subversão Dracônica criado por Myranda, a Bruxa Velha, não vai funcionar no Pico da Rocha Negra. Você devia ir atrás de Rexxar e explicar a situação. Mostre a ele o Amuleto da Chama Dracônica Fraco. Pode ser que ele saiba o que fazer." },
    [5089] = { name = "Comando do General Drakkisath", objective = "Leve o Comando do General Drakkisath para o Oficial Maxwell nas Estepes Ardentes." },
    [5527] = { name = "Relicário da Pureza", objective = "Viaje até Silithus e procure um Relicário da Pureza dentro das ruínas da Vila do Vento Sul. Se conseguir encontrá-lo, regresse com ele até Ravine Saturna, no Refúgio Noturno, que fica na Clareira da Lua." },
    [5244] = { name = "Ruínas de Kel'Theril", objective = "Fale com Jaron Moldapedra na Aldeia Chuva Estelar." },
    [5245] = { name = "Espíritos atormentados de Kel'Theril", objective = "Use a Picareta do Jaron para encontrar os quatro Fragmentos da Relíquia dos Altaneiros. Leve-os para Aurora Clamacéus nas Terras Pestilentas Orientais." },
    [5246] = { name = "Fragmentos do passado", objective = "Encontre os Escritos Sagrados dos Altaneiros no Templo de Zin-Malor, em Azshara, e leve-os para Aurora Clamacéus, perto da Torre do Passo Norte nas Terras Pestilentas Orientais." },
    [7637] = { name = "Ênfase em sacrifício", objective = "Viaje para Altaforja e obtenha o Incensório de Exorcismo do Sumo Sacerdote Rohan. Você precisará fazer uma doação de 150 moedas de ouro para obtê-lo." },
    [7639] = { name = "O devido julgamento", objective = "Leve o Incensório de Exorcismo para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo." },
    [7640] = { name = "Exorcizando a Várzea do Medo", objective = "Use o Incensório de Exorcismo para expulsar os espíritos que atormentam a Várzea do Medo. Quando você tiver eliminado 25 Espíritos da Várzea do Medo, fale novamente com Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo." },
    [7641] = { name = "O trabalho de Grimand Elmore", objective = "Fale com Grimand Elmore em Ventobravo no Distrito dos Anões de Ventobravo." },
    [7642] = { name = "Coleta de produtos", objective = "Leve 40 Runatramas, 6 Barras de Arcanita, 10 Lágrimas-de-arthas, 5 ampolas de Água Benta de Stratholme e 150 moedas de ouro para Grimand Elmore, no Distrito dos Anões de Ventobravo." },
    [7648] = { name = "O melhor trabalho de Grimand", objective = "Leve a Barda de Arcanita para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo para que ele a inspecione." },
    [7645] = { name = "Ração de Cavalo Enriquecida com Mana", objective = "Obtenha 20 Biscoitos de Maná Enriquecido — o ingrediente chave para fazer Ração de Cavalo Enriquecida com Mana — para Judite Castanheira da Costa Sul, no Contraforte de Eira dos Montes. A Aurora Argêntea é conhecida como a única fornecedora dos biscoitos. Você também precisa dar a ela 50 moedas de ouro para a apaziguar os ânimos dela." },
    [7563] = { name = "Raiva de Sangue", objective = "Leve 30 garrafas de Sangue de Fera em Fúria para Mor'zul Trazangre nas Estepes Ardentes." },
    [7564] = { name = "Olholouco", objective = "Leve o Caixote de Sangue para Gorzeeki Olholouco nas Estepes Ardentes." },
    [7623] = { name = "Lorde Nihilus", objective = "Compre Poções Sombrias de Gorzeeki nas Estepes Ardentes. Use as poções para viajar através de Jaedenar e fale com Lorde Nihilus." },
    [7624] = { name = "Ulathek, o traidor", objective = "Confronte Ulathek, depois leve o Coração do Traidor para o Lorde Nihilus em Jaedenar." },
    [7625] = { name = "Poeira Estelar Zorothiana", objective = "Compre Poeira Estelar Zorothiana de Ur'dan. Leve-a para Gorzeeki Olholouco nas Estepes Ardentes." },
    [7626] = { name = "Sino de Defimura", objective = "Leve 10 Elixires de Poder Sombrio para Gorzeeki Olholouco nas Estepes Ardentes." },
    [7627] = { name = "Roda da Marcha Negra", objective = "Leve 6 Estilhaços Brilhantes Grandes e 25 Minérios de Ferro Negro para Gorzeeki nas Estepes Ardentes." },
    [7628] = { name = "Vela do Juízo Final", objective = "Leve 35 Escamas de Dragão Negro para Gorzeeki Olholouco nas Estepes Ardentes." },
    [7630] = { name = "Arcanita", objective = "Leve 3 Barras de Arcanita para Gorzeeki nas Estepes Ardentes." },
    [5461] = { name = "Ras Friomúrmuro, o humano", objective = "Viaje para o Planalto Arathi, até as ruínas de Stromgarde. Vasculhe Stromgarde em busca de um Livro de Recordações. Se encontrar o item, retorne com ele até o Magistrado Marduque." },
    [5462] = { name = "Ras Friomúrmuro, o moribundo", objective = "Viaje para a Capela Esperança da Luz, nas Terras Pestilentas Orientais, e procure por Leonid Bartolomeu, o Venerado. Mostre a ele o Livro de Recordações e conte tudo o que descobriu." },
    [5464] = { name = "Dádiva de Menethil", objective = "Leve a Lembrança Vinculada para Leonid Bartolomeu, nas Terras Pestilentas Orientais." },
    [5465] = { name = "Lembrança Vinculada", objective = "Fale novamente com o Magistrado Marduque, no Castro das Flechas. Mostre-lhe a Lembrança Vinculada." },
    [5522] = { name = "Leonid Bartolomeu", objective = "Leve os Ovos Congelados para Leonid Bartolomeu, nas Terras Pestilentas Orientais." },
    [5531] = { name = "Betina Bigozinco", objective = "Leve os Ovos Congelados para Betina Bigozinco." },
    [7644] = { name = "Barda de Arcanita Abençoada", objective = "Leve a Barda de Arcanita Abençoada para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo." },
    [7646] = { name = "O Cristal Divinatório", objective = "Leve um Diamante Azerotiano e um Diamante Preto Límpido para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo." },
    [7667] = { name = "Ajuda material", objective = "Se você tiver interesse em ajudar Sagorne Monta Crista, no Vale da Sabedoria de Orgrimmar, leve para ele um Diamante Azerotiano e um Diamante Preto Límpido." },
    [5251] = { name = "O arquivista", objective = "Viaje até Stratholme e encontre o Arquivista Galford da Cruzada Escarlate. Destrua-o e queime o Arquivo Escarlate." },
    [5542] = { name = "Cães demoníacos", objective = "Mate 20 Cães Pestilentos Miúdos, 5 Cães Pestilentos e 5 Cães Pestilentos Frenéticos. Fale novamente com Tirion Fordring quando a tarefa estiver concluída." },
    [5543] = { name = "Céu tingido de sangue", objective = "Mate 30 Quirópragos e fale novamente com Tirion Fordring." },
    [5544] = { name = "Carne de verme carniceiro", objective = "Procure os Vermes Carniceiros e os Devoradores de Carniça da região. Mate-os e tire a carne. Fale novamente com Tirion Fordring depois que tiver juntado 15 Nacos de Carne de Verme Carniceiro." },
    [5742] = { name = "Redenção", objective = "Escute o que Tirion Fordring tem a dizer." },
    [5781] = { name = "Elixir de memórias esquecidas", objective = "Viaje para a Chácara Secreta, no extremo sul das Terras Pestilentas Orientais, e recupere o Martelo de Taelan. Fale novamente com Tirion Fordring ao completar seu objetivo." },
    [5845] = { name = "Da honra perdida", objective = "Viaje para o Vilarejo do Norte, na região nordeste das Terras Pestilentas Orientais, e recupere o Símbolo da Honra Perdida. Fale novamente com Tirion Fordring ao completar seu objetivo." },
    [5846] = { name = "Do amor e da família", objective = "Viaje para a ilha de Castro das Flechas, na região centro-sul das Terras Pestilentas, e procure pistas sobre o paradeiro da pintura." },
    [5262] = { name = "A verdade desaba sobre todos", objective = "Leve a Cabeça do Balnazzar para o Duque Nicolau Zverenhoff nas Terras Pestilentas Orientais." },
    [6133] = { name = "A mando do lorde patrulheiro", objective = "Vá à fronteira norte das Terras Pestilentas Orientais e recupere os Arquivos de Quel'Thalas em algum lugar do Abrigo Quel'Lithien. Você também precisa matar 8 Patrulheiros, 8 Trilheiros e 8 Mateiros." },
    [6042] = { name = "Pequenos transtornos da Morte-em-Vida", objective = "Mate 20 Quirópragos Nóxios e 10 Quirópragos Monstruosos. Fale novamente com Nathanos Arauto da Praga quando você tiver terminado." },
    [6022] = { name = "Matar com propósito", objective = "Vá ao Cruzamento de Corin, a leste, e mate membros do Flagelo que habitam a cidade. Colete 7 pedaços de Putrefação Viva em menos de 10 minutos. Use o Almofariz e Pilão para moer a Putrefação Viva, de maneira a transformá-la em Putrefação Coagulada." },
    [6135] = { name = "Ah, Quiroscuro, como vos odeio...", objective = "Encontre Quiroscuro e mate-o. Do cadáver, extraia um Tufo de Pele de Quiroscuro e leve para Nathanos Arauto da Praga. Dizem que Quiroscuro vaga pelo campo ao norte do Sítio dos Marris." },
    [6136] = { name = "O corpulento", objective = "Encontre Brocassangre nos ermos do norte das Terras Pestilentas e destrua-o. Fale novamente com Nathanos Arauto da Praga quando tiver cumprido a missão." },
  },
  ruRU = {
    [1113] = { name = "Сердца Доблести", objective = "Мастер-аптекарь Фаранелл из Подгорода просит принести ему 20 сердец Доблести." },
    [6521] = { name = "Нечестивый союз", objective = "Принести голову посла Малкина Вариматрасу в Подгород." },
    [1956] = { name = "Сила Ульдамана", objective = "Добудьте обсидиановый источник силы и принесите его Табете в Пыльную трясину." },
    [4143] = { name = "Туман зла", objective = "Соберите 5 образцов тумана Аталаи и принесите их Майджину в Кратер Ун'Горо." },
    [4146] = { name = "Питание для шокера", objective = "Доставьте незаряженный шокер и 5 образцов тумана Аталаи Лариону в Укрытие Маршалла." },
    [9053] = { name = "Лучший ингредиент", objective = "Возьмите гнилую лозу у стража на дне затонувшего храма и вернитесь к Землепроходцу Торве." },
    [8232] = { name = "Зеленый дракон", objective = "Принесите зуб Морфаза Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата." },
    [8253] = { name = "Уничтожить Морфаза", objective = "Добудьте кристалл тайной магии из брюха Морфаза и принесите его верховному магу Ксилему." },
    [8418] = { name = "Создание камня силы", objective = "Принесите вудуистские перья Ашламу Отважному Кулаку." },
    [8257] = { name = "Кровь Морфаза", objective = "Убейте Морфаза в затонувшем храме Атал'Хаккара и принесите его кровь Грете Замшелому Копыту в Оскверненный лес. Вход в храм сокрыт на болоте Печали." },
    [8236] = { name = "Лазурный ключ", objective = "Принесите лазурный ключ лорду Черному Ворону." },
    [8413] = { name = "Вуду", objective = "Принесите вудуистские перья Бат'ре Ветростражу." },
    [8422] = { name = "Тролли Пера", objective = "Принесите 6 вудуистских перьев троллей из затонувшего храма." },
    [8425] = { name = "Вудуистские перья", objective = "Принесите вудуистские перья павшему герою Орды, забрав их у троллей в Затонувшем Храме." },
    [4362] = { name = "Судьба королевства", objective = "Вернитесь в Глубины Черной горы и освободите принцессу Мойру Бронзобород от злобного императора Даграна Тауриссана." },
    [4003] = { name = "Спасение принцессы", objective = "Убейте императора Даграна Тауриссана и освободите принцессу Мойру Бронзобород от его черного заклятия." },
    [7201] = { name = "Последняя Стихия", objective = "Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности Стихий. Стоит начать поиски с големов и их создателей. Вивиан Лаграв также бормотала что-то про элементалей." },
    [4286] = { name = "Хороший товар", objective = "Отправьтесь в глубины Черной горы и принесите 20 поясных сумок дворфов Черного Железа. По выполнении задания вернуться к Орелиусу. Предположительно поясные сумки можно отобрать у дворфов Черного Железа в глубинах Черной горы." },
    [7848] = { name = "Сродство с недрами", objective = "Отправляйтесь через портал, ведущий к Огненным Недрам в Глубинах Черной горы и добудьте фрагмент ядра. Принесите его Лотосу Хранителю Портала к Черной горе." },
    [5001] = { name = "Вещи Блестяшки", objective = "Найдите вещи Блестяшки и верните их владелице. Удачи!" },
    [4982] = { name = "Вещи Блестяшки", objective = "Найдите вещи Блестяшки и верните их владелице. Блестяшка сказала, что она спрятала свое оборудование где-то на нижнем ярусе подземелья." },
    [4788] = { name = "Последние таблички", objective = "Принесите пятую и шестую таблички Мошару геологу Железному Башмаку в Танарисе." },
    [6569] = { name = "Иллюзии Ока", objective = "Отправляйтесь на пик Черной горы и добудьте 20 глаз черных драконидов. По выполнении задания вернитесь к Миранде Колдунье." },
    [4764] = { name = "Пряжка Роковой оснастки", objective = "Принесите пряжку Роковой оснастки Майре Светлое Крыло в Пылающие степи." },
    [4768] = { name = "Табличка Темнокамня", objective = "Принесите табличку Темного Камня тенемагу Вивиан Лаграв в Каргат." },
    [5160] = { name = "Матрона-защитница", objective = "Дойдите до Зимних Ключей и найдите Халех. Отдайте ей пластину чешуи Ауби." },
    [5526] = { name = "Осколки сквернита", objective = "Отыщите Сквернит в Забытом Городе и подберите его осколок. Есть шанс, что вам удастся его добыть, только убив Алззина Вертоградаря. Крепко заприте осколок в реликварии Чистоты, затем верните его Рабину Сатурне в Ночную Гавань в Лунной поляне." },
    [7463] = { name = "Магический напиток", objective = "Ступайте в Квартал Криводревов Забытого Города и убейте элементаля воды Гидротварь. Вернитесь в Читальню к сказителю Лидросу и принесите ему сущность Гидротвари." },
    [7461] = { name = "Древнее безумие", objective = "Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер'тера, рассеется. Войдите в Тюрьму Бессмер'тера и уничтожьте злого демона, который находится внутри. И, наконец, сразитесь с принцем Тортелдрином в Читальне. Если задание будет выполнено успешно, вернитесь во двор, к прародительнице Шен'дралар." },
    [5247] = { name = "Фрагменты прошлого", objective = "Принесите зачарованный слиток тория, 5 кристаллов Восстановления и фиал пугающей воды Авроре Зову Небес к башне Северного Перевала, в Восточных Чумных землях." },
    [7643] = { name = "Дух древнего коня", objective = "Купите лошадиный корм для Духа древнего коня у Меридет Карлсон в Южнобережье. Убейте Тендриса Криводрева в башне Забытого Города в Фераласе и освободите духа. Накормите духа кормом и получите благословление для арканитового чепрака." },
    [7631] = { name = "Ксоротианский конь погибели", objective = "Прочтите инструкции Мор'зула. Призовите ксоротианского коня погибели, одолейте его и подчините его дух." },
    [7506] = { name = "Изумрудный сон", objective = "Верните книгу законным владельцам." },
    [7503] = { name = "Величайшая гонка охотников", objective = "Верните книгу законным владельцам." },
    [7500] = { name = "Поваренная книга чародея", objective = "Верните книгу законным владельцам." },
    [7501] = { name = "Свет и как его раскачать", objective = "Верните книгу законным владельцам." },
    [7504] = { name = "Святая Болонья: О чем не говорит Свет", objective = "Верните книгу законным владельцам." },
    [7498] = { name = "Гарона: Исследование уловок и предательства", objective = "Верните книгу законным владельцам." },
    [7505] = { name = "Ледяной шок и вы", objective = "Верните книгу законным владельцам." },
    [7502] = { name = "Укрощая тени", objective = "Верните книгу законным владельцам." },
    [7499] = { name = "Кодекс Обороны", objective = "Верните книгу законным владельцам." },
    [7629] = { name = "Доставка беса", objective = "Отнесите беса в бутылке в алхимическую лабораторию Некроситета. После создания пергамента верните бутылку Горзиеки Дикоглазу." },
    [7647] = { name = "Суд и расплата", objective = "Используйте магический кристалл в центре подвала Главного склепа в Некроситете. Победите вызванных духов, а затем – рыцаря смерти Темного Терзателя, который появится после поражения духов. Верните падшему скакуну Темного Терзателя его спасенную душу и покройте его благословенным зачарованным чепраком." },
    [7668] = { name = "Угроза Темного Губителя", objective = "Используйте кристальный предсказатель в Главном склепе в Некроситете. Сразитесь с духами. Когда появится Темный Терзатель, убейте его. Принесите голову Темного Терзателя Сагорну Гривастому Страннику в Аллею Мудрости Оргриммара." },
    [5463] = { name = "Дар Менетила", objective = "Отправляйтесь в Стратхольм и отыщите Дар Менетила. Положите книгу Воспоминаний на оскверненную землю." },
    [261] = { name = "Путями Алого ордена", objective = "Убейте 30 опустошителей-отрекшихся и вернитесь к брату Антону на Высоте Найджела." },
    [1052] = { name = "По пути Алых", objective = "Отнесите рекомендательное письмо брата Антона Ролею Благочестивому в Южнобережье." },
    [6522] = { name = "Нечестивый союз", objective = "Отнесите маленький свиток Вариматрасу в Подгород." },
    [720] = { name = "Предвестник надежды", objective = "Найдите геолога Ржанеца и сообщите, что Грез Тяжелоступ жив." },
    [738] = { name = "Найти Эгмонда", objective = "Найдите Эгмонда." },
    [739] = { name = "Мурдалок", objective = "Уничтожьте убийцу Эгмонда, Мурдалока. Убейте 12 костегрызов из племени Каменного Свода. Сообщите геологу Сталекруту в Лок Модане обо всем, что произошло." },
    [723] = { name = "Клятва верности", objective = "Отнесите амулет Тяжелоступа геологу Ржанецу в Бесплодные земли." },
    [724] = { name = "Клятва верности", objective = "Отнесите амулет Тяжелоступа историку Карнику в Стальгорне." },
    [725] = { name = "Слухи об угрозе", objective = "Найдите советника Белграма и отдайте ему записку." },
    [726] = { name = "Слухи об угрозе", objective = "Поговорите с историком Карником." },
    [762] = { name = "Посланник зла", objective = "Убейте посла Инфернуса в Крепости Ангор и принесите доказательство его смерти советнику Белграму в Стальгорн." },
    [2198] = { name = "Порванное ожерелье", objective = "Найдите создателя ожерелья, чтобы узнать, чего оно стоит." },
    [2199] = { name = "Мудрость за деньги", objective = "Принесите пять серебряных слитков Талвашу де Кисселю в Стальгорн." },
    [2200] = { name = "Назад в Ульдаман", objective = "Выясните, где именно в Ульдамане находится ожерелье Талваша. Убитый паладин, о котором он упоминал, был последним владельцем этого ожерелья." },
    [2318] = { name = "Трудности перевода", objective = "Найдите кого-нибудь, кто сможет перевести для вас дневник паладина. Ближайший к вам такой умелец, скорее всего, найдется в Каргате, форпосте в Бесплодных Землях." },
    [2338] = { name = "Трудности перевода", objective = "Одолжите ожерелье Джаркалу. Взамен он переведет дневник." },
    [2500] = { name = "За реактивами в Бесплодные земли", objective = "Добудьте в Бесплодных землях реактивы для Гхака Целителя и отнесите их ему в Телcамар." },
    [2258] = { name = "Пробежка по Бесплодным землям", objective = "Принесите 5 вторых желудков канюка, 10 клыков скального койота и 5 осколков каменных элементалей Джаркалу Смешанному Лишайнику в Каргат." },
    [1954] = { name = "Сфера Подземного огня", objective = "Принесите сферу Подземного огня Табете из Пылевых топей." },
    [1955] = { name = "Поединок с демоном", objective = "Убейте демона сферы, а потом поговорите с Табетой." },
    [2988] = { name = "Тролльи клетки", objective = "Проверьте клетки в двух деревнях Сухокожих и возвращайтесь к дрессировщику грифонов Разящему Когтю." },
    [2989] = { name = "Алтарь Зула", objective = "Осмотрите вершину Алтаря Зула и возвращайтесь к укротителю грифонов Разящему Когтю." },
    [2990] = { name = "Тадиус Мрачная Тень", objective = "Принесите перо Остроклюва Тадиусу Мрачной Тени в Выжженные земли." },
    [2933] = { name = "Бутыли с ядом", objective = "Принесите бутылку яда аптекарю на Мельницу Таррен." },
    [2934] = { name = "Неповрежденная ядовитая железа", objective = "Принесите неповрежденную ядовитую железу аптекарю Лидону на Мельницу Таррен." },
    [2935] = { name = "Разговор с мастером Гадрином", objective = "Поговорите с мастером Гадрином в деревне Сен'джин." },
    [3520] = { name = "Духи крикунов", objective = "Поймайте души трех крикунов из Фераласа и возвращайтесь к Йе'кинье в Порт Картеля." },
    [1448] = { name = "В поисках Храма", objective = "Найдите Храм Атал'Хаккара и сообщите о его местонахождении Брохану Бочкопузу из Штормграда." },
    [1449] = { name = "Во Внутренние земли", objective = "Поговорите с Верховным таном Фалстадом Громовым Молотом на Заоблачном Пике во Внутренних землях." },
    [1450] = { name = "Укротитель грифонов Разящий Коготь", objective = "Поговорите с укротителем грифонов Разящим Когтем в питомнике на Заоблачном Пике." },
    [1451] = { name = "Рапсод Землекоп", objective = "Найдите Рапсода Землекопа во Внутренних землях." },
    [1452] = { name = "Калимдорский коктейль", objective = "Принесите Рапсоду Землекопу 3 куска потрохов руха, 3 печени гроддока и 3 печени железномеха." },
    [1469] = { name = "Рапсодия о болоте", objective = "Отнесите фрагмент таблички Атал'ай Брохану Бочкопузу в Штормград." },
    [1424] = { name = "Озеро Слез", objective = "Соберите 10 артефактов Атал'ай для Фелзерула из Каменора." },
    [1429] = { name = "Изгнанник Атал'ай", objective = "Принесите сверток с артефактами Атал'ай к изгнаннику Атал'ай во Внутренние земли." },
    [1444] = { name = "Возвращение к Фел'зерулу", objective = "Вернитесь в Каменор к Фел'зерулу." },
    [3444] = { name = "Круглый камень", objective = "Заберите круглый камень из мастерской Марвона Клепальщика в Кабестане." },
    [4787] = { name = "Древнее яйцо", objective = "Принесите древнее яйцо Йе'кинье в Танарис." },
    [4141] = { name = "Майджин и Ларион", objective = "Соберите 15 кровоцветов и принесите их Майджину." },
    [4142] = { name = "Визит к Грегану", objective = "Отнесите кровоцвет Грегану Пивоплюю в Фералас." },
    [4145] = { name = "Ларион и Майджин", objective = "Уничтожьте 5 кровоцветов-хлестунов, 5 кровоцветов-крепкозубов, 5 кровоцветов-живодеров и 5 кровоцветов-звероловов по просьбе Лариона из Укрытия Маршалла." },
    [4147] = { name = "Мастерская Марвона", objective = "Отправьтесь к Марвону Клепальщику в его мастерскую в Кабестане." },
    [9052] = { name = "Яд кровоцвета", objective = "Соберите 8 кровошляпочников и 8 жал Гориши и вернитесь к Землепроходцу Торве в Кратер Ун'Горо." },
    [9051] = { name = "Испытание яда", objective = "Уколите девизавра колючкой девизавра. По выполнении задания вернитесь к Землепроходцу Торве." },
    [8153] = { name = "Рога и копыта", objective = "Принесите пару великолепных рогов мохоногого оленя Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата." },
    [8231] = { name = "Охота на волномета", objective = "Принесите 6 чешуй волношлепа Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата." },
    [8251] = { name = "Волшебная пыль", objective = "Принесите 10 горстей сияющей пыли верховному магу Ксилему." },
    [8252] = { name = "Кораллы сирен", objective = "Соберите 6 заколдованных кораллов и принесите их верховному магу Ксилему." },
    [8414] = { name = "Борьба со злом", objective = "Принесите 20 камней Плети приспешников верховному жрецу Тель'данису в Западные Чумные земли." },
    [8416] = { name = "Бездействующие камни Плети", objective = "Отнесите бездействующий камень командиру Асламу Отважному Кулаку на Берег Промозглого Ветра." },
    [8255] = { name = "Охота на беговых оленей", objective = "Добудьте 4 железы здорового мохоногого оленя и принесите их Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата." },
    [8256] = { name = "Лимфа нежити", objective = "Принесите лимфу нежити Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата." },
    [8234] = { name = "Запечатанная лазурная сумка", objective = "Добудьте запечатанную лазурную сумку у шамана из племени Древобрюхов в Азшаре. Затем отнесите сумку верховному магу Ксилему в Азшаре." },
    [8235] = { name = "Зашифрованные фрагменты", objective = "Принесите 10 зашифрованных фрагментов верховному магу Ксилему в Азшару." },
    [8410] = { name = "Покорение стихий", objective = "Соберите образцы воздуха, огня, земли и воды по поручению Бат'ры Ветростража." },
    [8412] = { name = "Тотем духов", objective = "Принесите части тотема Духа Бат'ре Ветростражу." },
    [8419] = { name = "Просьба беса", objective = "Отнесите Бесенку из Оскверненного леса отрез ткани Скверны." },
    [8420] = { name = "Пробирает!", objective = "Принесите отрез ткани Скверны Бесенку в Оскверненный лес." },
    [8421] = { name = "Бросовый материал", objective = "Принесите 10 кусков гнилой древесины и 4 порции экстракта ядовитой крови Бесенку в Оскверненный лес." },
    [8423] = { name = "Воинское испытание", objective = "Убейте 7 Зловепрей в Выжженных землях и вернитесь к павшему герою Орды." },
    [8424] = { name = "Война против Приверженцев Тени", objective = "Убейте Приверженцев Тени в Выжженных землях и вернитесь к павшему герою Орды." },
    [3801] = { name = "Наследие Черного Железа", objective = "Чтобы получить ключ от города, поговорите с Франклорном Искусником." },
    [4262] = { name = "Подчинитель Пирон", objective = "Убейте подчинителя Пирона и вернитесь к Джалинде Тирлипуньке. Кажется, Джалинда говорила, что Пирон охраняет каменоломню. Может, поискать его там?" },
    [3702] = { name = "Дымящиеся руины Тауриссана", objective = "Узнайте от королевского историка Аркессона историю Тауриссана." },
    [3701] = { name = "Дымящиеся руины Тауриссана", objective = "Пойдите в руины Тауриссана в Пылающих степях и добудьте информацию из таурисанских реликвий. Вернитесь к королевскому историку Аркессону." },
    [4341] = { name = "Каран Могучий Молот", objective = "Пойдите в Глубины Черной горы и найдите Карана Могучего Молота. Король упомянул, что Каран сидит там в плену – может, стоит поискать темницу." },
    [4342] = { name = "Рассказ Карана", objective = "Выслушайте рассказ Карана Могучего Молота." },
    [4361] = { name = "Недобрые вести", objective = "Вернитесь в Стальгорн и сообщите нехорошие новости королю Магни Бронзобороду." },
    [4182] = { name = "Драконья угроза", objective = "Убейте 15 детенышей черного дракона, 10 черных драконидов, 4 черных драконид и 1 черного дракона. По выполнении задания вернитесь к Хелендису Речному Мысу." },
    [4183] = { name = "Подлинные хозяева", objective = "Отправьтесь в Приозерье и доставьте письмо Хелендиса Речного Мыса мировому судье Соломону." },
    [4184] = { name = "Подлинные хозяева", objective = "Передайте обращение Соломона верховному лорду Болвару Фордрагону. Болвар Фордрагон пребывает в Крепости Штормграда." },
    [4185] = { name = "Подлинные хозяева", objective = "Поговорите с Верховным лордом Болваром Фордрагоном после беседы с леди Катраной Престор." },
    [4186] = { name = "Подлинные хозяева", objective = "Отнесите указ Болвара мировому судье Соломону в Приозерье." },
    [4223] = { name = "Подлинные хозяева", objective = "Поговорите с маршалом Максвеллом в Пылающих степях." },
    [4224] = { name = "Подлинные хозяева", objective = "Поговорите с Джоном-Оборванцем и узнайте о судьбе маршала Виндзора. По выполнении задания вернитесь к маршалу Максвеллу. Кажется, маршал Максвелл говорил, что Джона следует искать в пещере на севере." },
    [4241] = { name = "Маршал Винздор", objective = "Отправляйтесь на Черную гору на северо-западе и войдите в ее глубины. Узнайте, что сталось с маршалом Виндзором. Кажется, Джон-Оборванец говорил о том, что Виндзора утащили в темницу." },
    [4242] = { name = "Утраченная надежда", objective = "Сообщите маршалу Максвеллу плохие новости." },
    [4264] = { name = "Измятая записка", objective = "Не исключено, что ваша находка заинтересует маршала Виндзора. Может быть, все не так плохо, и надежда еще жива." },
    [4282] = { name = "Проблеск надежды", objective = "Верните маршалу Виндзору утерянную информацию. Маршал уверен, что информацией завладели повелитель големов Аргелмах и генерал Кузня Гнева." },
    [3906] = { name = "Дисгармония пламени", objective = "Отправьтесь в карьер у Черной горы и уничтожьте Подчинителя Пирона. По выполнению вернитесь к Громосерду." },
    [3981] = { name = "Командир Гор'шак", objective = "Найдите командира Гор'шака в Глубинах Черной горы. Судя по рисунку в записке, искать следует в темнице где-то вроде того." },
    [3982] = { name = "Что происходит?", objective = "Защитите Горшака." },
    [4001] = { name = "Что происходит?", objective = "Поговорите с дворфом по имени Каран Могучий Молот и соберите информацию о похищении принцессы Мойры Бронзобород. Передайте информацию Траллу в Оргриммар. Карана держат в темнице напротив." },
    [4002] = { name = "Восточные королевства", objective = "Поговорите с Траллом." },
    [4081] = { name = "УНИЧТОЖИТЬ НА МЕСТЕ: Дворфы Черного Железа", objective = "Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров! По приказу полководца Клинозуба уничтожьте 15 охранников, 10 надсмотрщиков и 5 пехотинцев из клана Ярости Горна. Вернитесь сразу по выполнении задания." },
    [4122] = { name = "Грарк Лоркруб", objective = "Отправьтесь в Пылающие степи и найдите Грарка Лоркруба. Лекслорт упоминал, что в последний раз предателя видели в крепости Черной горы. По обнаружении Грарка Лоркруба закуйте его в ториевые оковы и затем доставьте его от Черной горы к Тлеющему ущелью, Лекслорт и его подчиненные займутся допросом преступника." },
    [4121] = { name = "Опасное положение", objective = "Отконвоируйте пленника, Грарка Лорктуба, через Пылающие степи и Черную гору к Тлеющему ущелью. Лекслорт что-то говорил насчет того, что по другую сторону будут ждать его ребята, которые уведут Грарка в тюрьму. Также отдайте Лекслорту ториевые оковы." },
    [4061] = { name = "Восстание машин", objective = "Отправляйтесь в Пылающие степи и соберите 10 осколков элементалей для верховной жрицы Теодоры Мальвадании. Теодора упоминала, что осколки можно найти у элементалей и големов." },
    [4062] = { name = "Восстание машин", objective = "Отнесите образец осколка элементаля Лотвилю Вериатусу. Теодора упоминала, что его лагерь находится на востоке." },
    [5002] = { name = "Донесение Максвелла", objective = "Передайте маршалу Максвеллу информацию Блестяшки." },
    [4981] = { name = "Агент Блестяшка", objective = "Отправьтесь к пику Черной горы и выясните, что сталось с Блестяшкой." },
    [5065] = { name = "Утраченные таблички Мошару", objective = "Принесите третью и четвертую таблички Мошару геологу Железному Башмаку в Танарис." },
    [4726] = { name = "Сущность детеныша дракона", objective = "Принесите 8 сущностей детенышей драконов и Драко-инкарцинатор 900 Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях." },
    [4808] = { name = "Фелнок Сталлист", objective = "Отнесите письмо Тинки Фелноку Сталлисту." },
    [4809] = { name = "Рога стылодыхов", objective = "Принесите 8 безупречных рогов стылодыха Фелноку Сталлисту." },
    [4810] = { name = "Возвращение к Тинки", objective = "Отнесите ящик Фелнока Тинки Кипеллер в Пылающие степи." },
    [4907] = { name = "Тинки Кипеллер", objective = "Поговорите с Тинки Кипеллер." },
    [4734] = { name = "Заморозка яйца", objective = "Испытайте прототип яйцехладоскопа на одном из яиц в Гнездовье." },
    [4903] = { name = "Приказ полководца", objective = "Убейте вождя Омокка, воеводу Вуна и повелителя Змейталака. Найденные при них важные бумаги Черной горы доставьте полководцу Клинозубу в Каргат." },
    [4941] = { name = "Мудрость Эйтригга", objective = "Поговорите с Эйтриггом в Оргриммаре. После этого обратитесь к вождю Траллу. В последний раз Эйтригг был в в зале приемов Тралла." },
    [4974] = { name = "За Орду!", objective = "Пойдите в Пик Черной горы и убейте вождя Ренда Чернорука. Принесите его голову в Оргриммар." },
    [6566] = { name = "Что принес ветер", objective = "Выслушайте Тралла." },
    [6567] = { name = "Защитник Орды", objective = "Найдите Рексара. Вождь сказал, что он бродит в Пустошах, по дороге, что ведет из Когтичтых гор в Фералас." },
    [6568] = { name = "Завет Рексара", objective = "Доставьте письмо Рексара Миранде Колдунье в Западные Чумные земли." },
    [6402] = { name = "Встреча в Штормграде", objective = "Отправьтесь в Штормград и подойдите к городским воротам. Поговорите с оруженосцем Роу, чтобы он сообщил маршалу Виндзору о вашем прибытии." },
    [6403] = { name = "Великий Маскарад", objective = "Сопроводите Реджинальда Виндзора через весь Штормград. Защитите его!" },
    [6501] = { name = "Око дракона", objective = "Найдите существа, способные вернуть силу фрагменту амулета Ока дракона. Все, что об этих существах известно – это то, что они есть." },
    [6570] = { name = "Огнебор", objective = "Отправляйтесь в Драконьи топи в Пылевых топях и найдите Логово Огнебора. Оказавшись внутри, наденьте амулет Обмана драконов и поговорите с Огнебором." },
    [6582] = { name = "Черепа: Провидец", objective = "Найдите в Зимних Ключах избранного бойца синих дракона по имени Провидец и убейте его. С его черепом вернитесь к Огнебору." },
    [6583] = { name = "Черепа: Сомнус", objective = "Убейте вожака зеленых драконов Сомнуса и вернитесь с его черепом к Огнебору." },
    [6584] = { name = "Черепа: Хроналис", objective = "Убейте Хроналиса, охраняющего Пещеры Времени в Пустыне Танарис и вернитесь с его черепом к Огнебору." },
    [6585] = { name = "Черепа: Акстроз", objective = "Отправьтесь в Грим Батол и убейте Акстроза, избранного бойца красных драконов. Принесите его череп Огнебору." },
    [6601] = { name = "Вознесение", objective = "Казалось бы, загадка разгадана. Ты знаешь, что амулет обмана драконов, который сделала для тебя Миранда Колдунья, не будет работать на пике Черной горы. Найди Рексара и расскажи о возникших затруднениях. Покажи ему амулет угасающего пламени дракона. Будем надеяться, он знает что делать." },
    [5089] = { name = "Приказ генерала Драккисата", objective = "Отнесите приказ генерала Драккисата маршалу Максвеллу в Пылающие степи." },
    [5527] = { name = "Реликварий Чистоты", objective = "Отправляйтесь в Силитус и найдите реликварий Чистоты в руинах деревни Южного Ветра. Если вам удастся его найти, возвращайтесь к Рабину Сатурне в Ночную Гавань в Лунной поляне." },
    [5244] = { name = "Руины Кел'Терила", objective = "Поговорите с Джероном Гранильщиком в деревне Звездопада." },
    [5245] = { name = "Беспокойные духи Кел'Терила", objective = "Используйте кирку Джерона, чтобы добыть фрагменты реликвии высокорожденных, Принесите их Авроре Зову Небес в Восточные Чумные земли." },
    [5246] = { name = "Фрагменты прошлого", objective = "Найдите Священные письмена высокорожденных в Храме Зин-Малор, в Азшаре и принесите их Авроре Зову Небес к Башне Северного перевалa, в Восточных Чумных землях." },
    [7637] = { name = "Жертва необходима", objective = "Доберитесь до Стальгорна и получите курильницу экзорцизма у Верховного жреца Рохана. За курильницу нужно будет внести плату в размере 150 золотых монет." },
    [7639] = { name = "Демонстрация истинного правосудия", objective = "Принесите курильницу экзорцизма лорду Грейсону Тенелому в Храмовый квартал Штормграда." },
    [7640] = { name = "Изгнание призраков из Долины Ужаса", objective = "Используйте курильницу экзорцизма для вызова из-под земли призраков, мучающих Долину Ужаса. Когда убьете 25 духов долины Ужаса, вернитесь к лорду Грейсону Тенелому в Храмовый квартал Штормграда." },
    [7641] = { name = "Работа Гриманда Элмора", objective = "Поговорите с Гримандом Элмором в Квартале Дворфов Штормграда." },
    [7642] = { name = "Сбор необходимого", objective = "Принесите Гриманду Элмору в Квартал Дворфов Штормграда 40 отрезов рунной ткани, 6 арканитовых слитков, 10 цветков слезы Артаса, 5 сосудов со святой водой Стратхольма и 150 золотых монет." },
    [7648] = { name = "Шедевр Гриманда", objective = "Покажите арканитовый чепрак лорду Грейсону Тенелому в Храмовом квартале Штормграда." },
    [7645] = { name = "Обогащенный манной лошадиный корм", objective = "Принесите 20 витаминизированных печений из манны – ключевых составляющих обогащенного манной лошадиного корма – Меридет Карлсон в Южнобережье в предгорьях Хилсбрада. Продаются они только в Серебряном Рассвете. Кроме того, понадобится дать ей 50 золотых, чтобы успокоить ее ущемленное самолюбие." },
    [7563] = { name = "Ярость крови", objective = "Принесите 30 бутылок крови яростных зверей Мор'зулу Кровопуску в Пылающие степи." },
    [7564] = { name = "Дикоглаз", objective = "Принесите ларец Крови Горзиеки Дикоглазу в Пылающие степи." },
    [7623] = { name = "Лорд Гиблопуст", objective = "Купите зелья Теней у Горзиеки в Пылающих степях. Приняв зелья, пройдите в Джеденар и поговорите с лордом Гиблопустом." },
    [7624] = { name = "Улатек Предатель", objective = "Сразитесь с Улатеком и принесите сердце предателя лорду Гиблопусту в Джеденар." },
    [7625] = { name = "Зоротианская звездная пыль", objective = "Купите зоротианскую звездную пыль у Ур'Дана. Отнесите ее Горзиеки Дикоглазу в Пылающие степи." },
    [7626] = { name = "Колокол Детмуры", objective = "Отнесите 10 эликсиров Силы Теней Горзиеки Дикоглазу в Пылающие степи." },
    [7627] = { name = "Колесо Черного Похода", objective = "Отнесите 6 больших блестящих осколка и 25 кусков руды черного железа Дикоглазу в Пылающие степи." },
    [7628] = { name = "Свеча Судного Дня", objective = "Принесите 35 шкур черного дракона Горзиеки Дикоглазу в Пылающие степи." },
    [7630] = { name = "Арканит", objective = "Принесите 3 арканитовых слитка Горзиеки в Пылающие степи." },
    [5461] = { name = "Рас Ледяной Шепот – человек", objective = "Отправляйтесь в высокогорья Арати, в руины Стромгарда. Поищите в Стромгарде книгу Воспоминаний. Если удастся ее отыскать, отнесите ее мировому судье Мардуку." },
    [5462] = { name = "Рас Ледяной Шепот – гибель", objective = "Отправляйтесь в часовню Светлых надежд в Восточных Чумных землях и найдите Леонида Бартоломея Чтимого. Покажите ему книгу Воспоминаний и расскажите обо всем, о чем удалось узнать." },
    [5464] = { name = "Дар Менетила", objective = "Отнесите Книгу Души Леониду Бартоломею в Восточные Чумные земли." },
    [5465] = { name = "Книга Души", objective = "Возвращайтесь к мировому судье Мардуку в Каэр Дарроу. Покажите ему Книгу Души." },
    [5522] = { name = "Леонид Барталомей", objective = "Принесите охлажденные яйца Леониду Бартоломею в Восточные Чумные земли." },
    [5531] = { name = "Бетина Биггльцинк", objective = "Принесите охлажденные яйца Бетине Биггльцинк." },
    [7644] = { name = "Благословенный арканитовый чепрак", objective = "Вернитесь вместе с благословенным арканитовым чепраком к лорду Грейсону Тенелому в Храмовый квартал Штормграда." },
    [7646] = { name = "Магический кристалл", objective = "Принесите азеротский алмаз и безупречный черный алмаз лорду Грейсону Тенелому в Храмовый квартал Штормграда." },
    [7667] = { name = "Существенная помощь", objective = "Принесите Сагорну Гребнестраннику в Аллею Мудрости в Оргриммаре азеротский алмаз и безупречный черный алмаз." },
    [5251] = { name = "Архивариус", objective = "Отправляйтесь в Стратхольм и отыщите архивариуса Галфорда из Алого ордена. Убейте его и сожгите архив Алых." },
    [5542] = { name = "Псы-демоны", objective = "Убейте 20 карликовых чумных псов, 5 чумных псов и 5 бесноватых чумных псов. По выполнении задания вернитесь к Тириону Фордрингу." },
    [5543] = { name = "Окровавленные небеса", objective = "Убейте 30 чумных нетопырей и вернитесь к Тириону Фордрингу." },
    [5544] = { name = "Мясо личинок-трупоедов", objective = "Найдите личинок-падальщиков и падальщиков-пожирателей. Убейте побольше и наберите из мяса. Возвращайтесь к Тириону Фордрингу, когда накопите 15 кусков мяса червей-трупоедов." },
    [5742] = { name = "Спасение", objective = "Выслушайте Тириона Фордринга." },
    [5781] = { name = "Символ ушедших дней", objective = "Отправляйтесь в Крипту – в самой южной части Восточных Чумных земель – и добудьте молот Таэлана. Отнесите его Тириону Фордрингу." },
    [5845] = { name = "Символ утраченной чести", objective = "Отправляйтесь в Северный дол, что в северо-восточной части Восточных Чумных земель и найдите там символ утраченной чести. После этого вернитесь к Тириону Фордрингу." },
    [5846] = { name = "Символ семейной любви", objective = "Отправляйтесь на остров Каэр Дарроу в центральной части Чумных земель и поищите там картину." },
    [5262] = { name = "Ошеломляющая истина", objective = "Отнесите голову Бальназара герцогу Николасу Зверенхоффу в Восточные Чумные земли." },
    [6133] = { name = "Охота на следопытов", objective = "Отправляйтесь в северные пределы Восточных Чумных земель и заполучите реестр Кель'Таласа. Документ находится где-то в Сторожке Кель'Литиен. Также убейте 8 следопытов, 8 разведчиц дорог и 8 лесников." },
    [6042] = { name = "Мелочи нежизни", objective = "Истребите 20 пагубных нетопырей и 10 чудовищных чумных нетопырей. После возвращайтесь к Натаносу Гнилостеню." },
    [6022] = { name = "Преднамеренное убийство", objective = "Отправляйтесь на восток в Перекресток Корина и убейте несколько населяющих его созданий Плети. Соберите 7 кусков живой гнили менее, чем за 10 минут. С помощью ступки и пестика превратите живую гниль в сгущенную гниль." },
    [6135] = { name = "Проклятый Тенекрыл", objective = "Выследите Тенекрыла и убейте его. Принесите полоску меха Тенекрыла Натаносу Гнилостеню. Говорят, Тенекрыл рыщет в землях к северу от имения Марриса." },
    [6136] = { name = "Огромный червь", objective = "Найдите и уничтожьте Мерзкослиза в северных пустошах Восточных Чумных земель. Возвращайтесь к Натаносу Гнилостеню по выполнению задания." },
  },
  koKR = {
    [1113] = { name = "열정의 증거", objective = "언더시티에 있는 수석 연금술사 파라넬에게 열정의 증거 20개를 가져가야 합니다." },
    [6521] = { name = "사악한 동맹", objective = "사절 말킨을 처치한 다음 언더시티에 있는 바리마트라스에게 그의 머리카락을 증거로 가져가야 합니다." },
    [1956] = { name = "울다만의 마력원천", objective = "흑요석 마력원천을 구해서 먼지진흙 습지대에 있는 타베사에게 가져가야 합니다." },
    [4143] = { name = "악의 아지랑이", objective = "아탈라이 아지랑이 5개를 모은 후 운고로 분화구에 있는 무이긴에게 돌아가야 합니다." },
    [4146] = { name = "구제장치 연료", objective = "마샬의 야영지에 있는 라리온에게 충전 안된 구제장치와 아탈라이 아지랑이 5개를 가져가야 합니다." },
    [9053] = { name = "더욱 강력한 재료", objective = "가라앉은 사원 하층부의 수호병으로부터 썩은 덩굴을 찾은 후 토르와 패스파인더에게 돌아가십시오." },
    [8232] = { name = "녹색 비룡 몰파즈", objective = "아즈샤라에 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있는 오그틴크에게 몰파즈의 이빨을 가져가야 합니다." },
    [8253] = { name = "몰파즈 처치", objective = "몰파즈에게서 신비의 결정을 되찾아 대마법사 실렘에게 가져가야 합니다." },
    [8418] = { name = "퇴마석 만들기", objective = "아쉬람 발러피스트에게 황색 부두 깃털, 청색 부두 깃털, 녹색 부두 깃털을 각 2개씩 가져가야 합니다." },
    [8257] = { name = "몰파즈의 피", objective = "아탈학카르 신전에서 몰파즈를 처치하고 그의 피를 악령의 숲에 있는 그레타 모스후프에게 가져다주어야 합니다. 가라앉은 신전의 입구는 슬픔의 늪에 있습니다." },
    [8236] = { name = "하늘색 열쇠", objective = "조라크 라벤홀트 경에게 하늘색 열쇠를 가져가야 합니다." },
    [8413] = { name = "부두교 마법", objective = "바람의감시자 바스라에게 부두 깃털들을 가져가야 합니다." },
    [8422] = { name = "트롤의 깃털", objective = "가라앉은 사원에 있는 트롤의 부두 깃털 6개를 가져가야 합니다." },
    [8425] = { name = "부두 깃털", objective = "호드 영웅의 넋에게 가라앉은 사원에 있는 트롤들에게서 황색 부두 깃털, 청색 부두 깃털, 녹색 부두 깃털을 빼앗아 각 2개씩 가져가야 합니다." },
    [4362] = { name = "왕국의 운명", objective = "검은바위 나락으로 돌아가 제왕 다그란 타우릿산의 사악한 손아귀에서 공주 모이라 브론즈비어드를 구출해야 합니다." },
    [4003] = { name = "공주 구출", objective = "제왕 다그란 타우릿산을 처치하고 그의 사악한 마법에서 공주 모이라 브론즈비어드를 해방시켜야 합니다." },
    [7201] = { name = "마지막 원소", objective = "검은바위 나락으로 가서 원소의 정수 10개를 회수해야 합니다. 먼저 골렘이나 골렘 제조자부터 찾아보십시오. 비비안 라그레이브가 정령에 대해 중얼거리듯 얘기한 것도 기억이 납니다." },
    [4286] = { name = "좋은 물건", objective = "검은바위 나락으로 가서 검은무쇠단 벨트주머니 20개를 얻어야 합니다. 이 임무를 완수하면 랄리우스에게 돌아가십시오. 검은바위 나락 안에 사는 검은무쇠단 드워프들이 이 '벨트주머니'라는 물건을 지니고 다닐 것입니다." },
    [7848] = { name = "심장부와의 조화", objective = "검은바위 나락의 화산 심장부 입구에 있는 차원의 문으로 가서 핵 조각을 하나 찾아야 합니다. 핵 조각을 가지고 검은바위 산에 있는 로소스 리프트웨이커에게로 돌아가십시오." },
    [5001] = { name = "비쥬의 소지품", objective = "을 찾아 그녀에게 돌려줘야 합니다!" },
    [4982] = { name = "비쥬의 물건들", objective = "비쥬의 소지품을 찾아서 그녀에게 돌아가야 합니다. 비쥬가 도시의 바닥에 소지품을 숨겼다고 했습니다." },
    [4788] = { name = "마지막 서판", objective = "다섯 번째와 여섯 번째 모쉬아루 서판을 타나리스에 있는 발굴조사단장 아이언부트에게 갖다주어야 합니다." },
    [6569] = { name = "눈동자의 환영", objective = "검은바위 첨탑으로 가서 검은 용혈족의 눈동자 20개를 모아서 노파 미란다에게 돌아가야 합니다." },
    [4764] = { name = "파멸의 기념물", objective = "불타는 평원에 있는 마야라 브라이트윙에게 파멸의 기념물을 가져가야 합니다." },
    [4768] = { name = "다크스톤 서판", objective = "카르가스에 있는 어둠마법사 비비안 라그레이브에게 다크스톤 서판을 가져가야 합니다." },
    [5160] = { name = "대섭정", objective = "여명의 설원으로 가서 헬레를 찾아 그녀에게 아우비의 비늘을 전해야 합니다." },
    [5526] = { name = "악령덩굴 조각", objective = "혈투의 전장에서 악령덩굴 조각을 채취하십시오. 칼날바람 알진을 물리쳐야만 얻을 수 있을 것입니다. 정화의 성물함에 단단히 봉인한 후, 달의 숲의 나이트헤이븐에 있는 라빈 사투르나에게 돌아가야 합니다." },
    [7463] = { name = "신비의 원기 회복 주문", objective = "혈투의 전장에 있는 굽이나무 지구로 가서 물의 정령인 히드로스폰을 처치하십시오. 히드로스폰의 정수를 가지고 도서관에 있는 현자 리드로스에게 돌아가야 합니다." },
    [7461] = { name = "내면의 광기", objective = "이몰타르의 감옥에 힘을 공급하는 다섯 개의 수정탑을 둘러싼 수호자들을 처치해야 합니다. 수정탑의 마력이 약해지면 이몰타르를 둘러싼 마법진도 분산될 것입니다. 이몰타르의 감옥에 들어가 그 심장부에 서 있는 사악한 이몰타르를 처치하고, 마지막으로 도서관에 있는 토르텔드린 왕자와 맞서 싸우십시오. 이 임무를 완수하면 안마당에 있는 셴드랄라 고대인에게 돌아가야 합니다." },
    [5247] = { name = "과거의 조각", objective = "마력 깃든 토륨 주괴 1개와 회복의 수정 5개, 그리고 혈투의 웅덩이 물병을 동부 역병지대의 북부관문 경비탑 근처에 있는 아우로라 스카이콜러에게 가져가야 합니다." },
    [7643] = { name = "고대 준마의 영혼", objective = "사우스쇼어에 있는 메리데스 칼슨에게 말의 영혼에게 먹일 특별한 말 먹이를 얻어야 합니다. 페랄라스에 있는 혈투의 전장 던전으로 가서 굽이나무 텐드리스를 무찔러야 합니다. 굽이나무 텐드리스를 무찌르고 고대 준마의 영혼이 풀려나면 특별한 말 먹이를 먹여 영혼을 진정시키십시오. 마지막으로 아케이나이트 마갑을 주면 영혼이 축복을 내릴 것입니다." },
    [7631] = { name = "소로스의 공포마", objective = "모르줄의 지시서를 잘 읽으십시오. 소로시안 공포마를 소환해 물리친 후 그 영혼을 결속시켜야 합니다." },
    [7506] = { name = "에메랄드의 꿈...", objective = "주인에게 책을 되돌려주십시오." },
    [7503] = { name = "사냥꾼의 위대한 혈통", objective = "주인에게 책을 되돌려주십시오." },
    [7500] = { name = "신비술사의 요리책", objective = "주인에게 책을 되돌려주십시오." },
    [7501] = { name = "빛과 정의에 관하여", objective = "주인에게 책을 되돌려주십시오." },
    [7504] = { name = "성스러운 볼로냐: 빛이 알려주지 않는 것들", objective = "주인에게 책을 되돌려주십시오." },
    [7498] = { name = "가로나: 은신과 기만에 대한 연구", objective = "주인에게 책을 되돌려주십시오." },
    [7505] = { name = "냉기 충격과 주술", objective = "주인에게 책을 되돌려주십시오." },
    [7502] = { name = "지배의 그림자", objective = "주인에게 책을 되돌려주십시오." },
    [7499] = { name = "방어의 고서", objective = "주인에게 책을 되돌려주십시오." },
    [7629] = { name = "임프 배달", objective = "단지 안에 든 임프를 스칼로맨스에 있는 연금술 실험대로 가져가야 합니다. 양피지가 완성되면 단지를 고르지키 와일드아이즈에게 되돌려 주십시오." },
    [7647] = { name = "심판과 구원의 손길", objective = "스칼로맨스에 있는 대형 납골당 지하의 중심부로 가서 예언의 탐지기를 사용해야 합니다. 그러면 영혼들이 나타날 것이니 그들을 해치우십시오. 그들을 해치우면 죽음의 기사 다크리버가 나타날 것이니 그를 물리친 다음 군마의 영혼의 잃어버린 영혼을 되찾아야 합니다. 구원된 군마의 영혼과 축복받은 아케이나이트 마갑을 다크리버 군마의 영혼에게 돌려줘야 합니다." },
    [7668] = { name = "다크리버의 위협", objective = "스칼로맨스에 있는 대형 납골당 지하의 중앙으로 가서 예언의 탐지기를 사용하십시오. 그러면 유령들이 나타날 것입니다. 그들을 해치우십시오. 그리고 곧이어 나타날 죽음의 기사 다크리버를 해치워야 합니다. 그런 다음 그 증거로 오그리마, 지혜의 골짜기에 있는 사고른 크레스트스트라이더에게 다크리버의 머리카락을 가져가야 합니다." },
    [5463] = { name = "메네실의 선물", objective = "스트라솔름으로 가서 메네실의 선물을 찾아서 그 부정한 땅 위에 추억의 유품을 두어야 합니다." },
    [261] = { name = "붉은십자군의 길", objective = "언데드 약탈자 30마리를 처치한 후 나이젤의 야영지에 있는 수사 안톤에게 돌아가야 합니다." },
    [1052] = { name = "붉은십자군의 길", objective = "사우스쇼어에 있는 경건한 신자 랄레이에게 수사 안톤의 추천서를 가져가야 합니다." },
    [6522] = { name = "사악한 동맹", objective = "작은 두루마리를 언더시티에 있는 바리마트라스에게 가져가야 합니다." },
    [720] = { name = "희망의 전조", objective = "발굴조사단장 라이돌을 찾아 해머토 그레즈가 살아 있다는 사실을 알려야 합니다." },
    [738] = { name = "아그몬드 찾기", objective = "아그몬드를 찾아야 합니다." },
    [739] = { name = "멀달록", objective = "아그몬드를 살해한 멀달록을 처치해야 합니다. 바위동굴일족 뼈다귀싸움꾼 12마리를 처치해야 합니다. 그 후 모단 호수에 있는 발굴조사단장 아이언밴드에게 보고하십시오." },
    [723] = { name = "돈독한 믿음", objective = "황야의 땅에 있는 발굴조사단장 라이돌에게 해머토의 아뮬렛을 가져가야 합니다." },
    [724] = { name = "돈독한 믿음", objective = "아이언포지에 있는 역사학자 카르닉에게 해머토의 아뮬렛을 가져가야 합니다." },
    [725] = { name = "위협의 경고", objective = "조언자 벨그룸을 찾아 봉인된 쪽지를 전해야 합니다." },
    [726] = { name = "위협의 경고", objective = "역사학자 카르닉과 대화해야 합니다." },
    [762] = { name = "악의 사자", objective = "고통의 요새에 있는 사자 인페르누스를 처치하고 아이언포지에 있는 조언자 벨그룸에게 그의 죽음에 대한 증거를 가져가야 합니다." },
    [2198] = { name = "부서진 목걸이", objective = "의 잠재적 가치를 알아내기 위해 원 제작자를 찾아야 합니다." },
    [2199] = { name = "정보의 대가", objective = "아이언포지에 있는 탈바쉬 델 키젤에게 은괴 5개를 가져가야 합니다." },
    [2200] = { name = "울다만으로 돌아가기", objective = "울다만 안에서 탈바쉬의 목걸이의 행방에 대한 단서를 찾아야 합니다. 탈바쉬가 말했던 성기사가 그 단서를 가진 최후의 인물일 것입니다." },
    [2318] = { name = "일지 번역", objective = "성기사의 일지를 번역할 수 있는 이를 찾아야 합니다. 그런 자가 있을만한 가장 가까운 곳은 황야의 땅에 있는 카르가스입니다." },
    [2338] = { name = "일지 번역", objective = "자칼에게 목걸이를 빌려주면 그에 대한 보답으로 일지를 번역해 줄 것입니다." },
    [2500] = { name = "황야의 땅에서 재료 찾기", objective = "황야의 땅에서 필요한 재료를 구한 후 텔사마에 있는 가크 힐터치에게 돌아가야 합니다." },
    [2258] = { name = "황야의 땅에서 재료 찾기", objective = "황야의 땅에서 자칼 모스멜드에게 대머리수리 모래주머니 5개, 바위산코요테 송곳니 10개, 바위 정령 파편 5개를 가져가야 합니다." },
    [1954] = { name = "지옥의 보주", objective = "먼지진흙 습지대에 있는 타베사에게 지옥의 보주를 가져가야 합니다." },
    [1955] = { name = "악마 퇴치", objective = "보주의 악마를 물리치고 타베사와 대화하십시오." },
    [2988] = { name = "마른나무껍질부족 우리", objective = "마른나무껍질 마을 두 곳에 있는 우리들을 확인한 후, 그리핀 조련사 탈론액스에게 돌아가십시오." },
    [2989] = { name = "줄의 제단", objective = "위를 확인한 후, 그리핀 조련사 탈론액스에게 돌아가십시오." },
    [2990] = { name = "샤디우스 그림섀이드", objective = "뾰족부리의 깃털을 저주받은 땅에 있는 샤디우스 그림섀이드에게 가져가야 합니다." },
    [2933] = { name = "독병", objective = "타렌 밀농장에 있는 연금술사에게 독병을 가져가야 합니다." },
    [2934] = { name = "온전한 독주머니", objective = "타렌 밀농장에 있는 연금술사 라이던에게 온전한 독주머니를 가져가야 합니다." },
    [2935] = { name = "가드린 장로와 상의", objective = "센진 마을에 있는 가드린 장로와 대화하십시오." },
    [3520] = { name = "계곡천둥매의 영혼", objective = "페랄라스에 있는 3마리의 계곡천둥매의 영혼을 모은 후 스팀휘들 항구에 있는 예킨야에게 돌아가야 합니다." },
    [1448] = { name = "신전을 찾아서", objective = "스톰윈드에 있는 브로한 캐스크벨리가 아탈학카르 신전을 찾아 달라고 부탁했습니다." },
    [1449] = { name = "동부 내륙지로", objective = "동부 내륙지 맹금의 봉우리에 있는 대영주 폴스타트 와일드해머와 대화해야 합니다." },
    [1450] = { name = "그리핀 조련사 탈론액스", objective = "맹금의 봉우리 출격장 안에 있는 그리핀 조련사 탈론액스와 대화해야 합니다." },
    [1451] = { name = "랩소디 신디거", objective = "동부 내륙지에서 랩소디 신디거를 찾아야 합니다." },
    [1452] = { name = "랩소디의 칼림도어 칵테일", objective = "동부 내륙지에 있는 랩소디 신디거가 로크 모래주머니 3개, 그로독 고릴라 간 3개, 무쇠곰 간 3개를 가져다 달라고 부탁했습니다." },
    [1469] = { name = "랩소디의 이야기", objective = "스톰윈드에 있는 브로한 캐스크벨리에게 아탈라이 서판 조각을 가져가야 합니다." },
    [1424] = { name = "눈물의 연못", objective = "스토나드에 있는 펠제룰이 아탈라이 유물 10개를 모아 달라고 부탁했습니다." },
    [1429] = { name = "추방된 아탈라이 트롤", objective = "동부 내륙지에 있는 추방된 아탈라이트롤에게 아탈라이 유물 자루를 가져가야 합니다." },
    [1444] = { name = "펠제룰에게 돌아가기", objective = "스토나드에 있는 펠제룰에게 돌아가야 합니다." },
    [3444] = { name = "돌무리", objective = "톱니항에 있는 마본 리벳시커의 작업장에서 마본의 궤짝에 담긴 아탈라이 돌무리를 회수해야 합니다." },
    [4787] = { name = "고대의 알", objective = "을 타나리스에 있는 예킨야에게 가져다주어야 합니다." },
    [4141] = { name = "무이긴과 라리온", objective = "붉은꽃잎 15개를 모아 무이긴에게 돌아가야 합니다." },
    [4142] = { name = "그레간 방문", objective = "페랄라스에 있는 그레간 브루스퓨에게 붉은꽃잎을 가져가야 합니다." },
    [4145] = { name = "라리온과 무이긴", objective = "마샬의 야영지에 있는 라리온에게 채찍줄기 붉은꽃잎덩굴손 5마리, 덩이줄기 붉은꽃잎덩굴손 5마리, 칼날가시 붉은꽃잎덩굴손 5마리, 질긴뿌리 붉은꽃잎덩굴손 5마리를 사냥해야 합니다." },
    [4147] = { name = "마본의 작업장", objective = "톱니항에 있는 마본 리벳시커의 작업장으로 가야 합니다." },
    [9052] = { name = "붉은꽃잎 독", objective = "붉은갓버섯 8개와 고리쉬 독침 8개를 모아서 운고로 분화구에 있는 토르와 패스파인더에게 돌아가십시오." },
    [9051] = { name = "독성 테스트", objective = "데빌사우루스 가시로 데빌사우루스를 찔러야 합니다. 임무를 완수하면 운고로 분화구에 있는 토르와 패스파인더에게 돌아가야 합니다." },
    [8153] = { name = "순록 뿔", objective = "아즈샤라에 있는 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있는 오그틴크에게 완전한 순록 뿔 한 쌍을 가져가야 합니다." },
    [8231] = { name = "폭풍히드라 사냥", objective = "아즈샤라에 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있는 오그틴크에게 폭풍히드라 비늘 6개를 가져가야 합니다." },
    [8251] = { name = "마법의 티끌", objective = "대마법사 실렘에게 반짝이는 가루 10개를 가져가야 합니다." },
    [8252] = { name = "세이렌의 산호", objective = "대마법사 실렘에게 마력 깃든 산호 6개를 가져가야 합니다." },
    [8414] = { name = "악마 퇴치", objective = "서부 역병지대에 있는 대사제 텔다니스에게 앞잡이의 스컬지석 20개를 모아 가져가야 합니다." },
    [8416] = { name = "마력을 잃은 스컬지석", objective = "서리바람 거점에 있는 사령관 아쉬람 발러피스트에게 마력을 잃은 스컬지석을 가져가야 합니다." },
    [8255] = { name = "순록을 찾아서", objective = "건강한 순록의 분비샘 4개를 찾아 아즈샤라의 오그틴크에게 가져가야 합니다. 오그틴크는 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있습니다." },
    [8256] = { name = "불사의 영액", objective = "아즈샤라의 오그틴크에게 불사의 영액을 가져다주어야 합니다. 오그틴크는 엘다라스 폐허 북동쪽 절벽 꼭대기에 있습니다." },
    [8234] = { name = "봉인된 하늘색 자루", objective = "아즈샤라에 있는 나무구렁일족 주술사에게서 봉인된 하늘색 자루를 되찾은 후, 그 가방을 아즈샤라에 있는 대마법사 실렘에게 가져가야 합니다." },
    [8235] = { name = "암호화된 페이지", objective = "아즈샤라에 있는 대마법사 실렘에게 암호화 된 페이지 10개를 가져가야 합니다." },
    [8410] = { name = "원소에 대한 깨달음", objective = "물, 불, 대지, 바람의 샘플을 수집하여 바람의감시자 바스라에게 가져가야 합니다." },
    [8412] = { name = "정기의 토템", objective = "바람의감시자 바스라에게 정기의 토템을 만드는데 필요한 재료들을 가져가야 합니다." },
    [8419] = { name = "임프의 부탁", objective = "악령의 숲에 있는 임프시에게 지옥 옷감을 한 장 가져가야 합니다." },
    [8420] = { name = "뜨거운 소유욕", objective = "악령의 숲에 있는 임프시에게 지옥 옷감을 한 장 가져가야 합니다." },
    [8421] = { name = "인형 재료", objective = "악령의 숲에 있는 임프시에게 썩은 나무 10개와 피멍울 정수 4개를 가져가야 합니다." },
    [8423] = { name = "전사의 일족", objective = "저주받은 땅에 있는 지옥멧돼지 7마리를 처치하고 호드 영웅의 넋에게 돌아가야 합니다." },
    [8424] = { name = "어둠의혈맹과의 전쟁", objective = "저주받은 땅에서 어둠의혈맹 숙련사제, 이교도, 암살단원을 각 20명씩 해치우고 호드 영웅의 넋에게 돌아가야 합니다." },
    [3801] = { name = "검은무쇠단 유물", objective = "도시 주요 지역으로 통하는 열쇠를 얻고 싶다면 프랑클론 포지라이트와 대화하십시오." },
    [4262] = { name = "멸망의 파이론", objective = "을 처치한 후 잘린다 스프리그에게 돌아가야 합니다. 잘린다가 말하기를 파이론은 채석장을 지키고 있다고 하니 그곳을 수색해야 할 것 같습니다." },
    [3702] = { name = "불타는 타우릿산의 폐허", objective = "왕실사학자 아케소누스가 들려 주는 타우릿산의 역사를 들어야 합니다." },
    [3701] = { name = "불타는 타우릿산의 폐허", objective = "불타는 평원, 타우릿산의 폐허에 있는 타우릿산 유물에서 정보를 얻어야 합니다. 정보를 발견하면 왕실사학자 아케소누스에게 돌아가야 합니다." },
    [4341] = { name = "카란 마이트해머", objective = "검은바위 나락으로 가서 카란 마이트해머를 찾아야 합니다. 국왕은 카란이 그곳에 포로로 잡혀 있을 것이라고 말했습니다. 그곳 감옥을 찾아보는 것이 좋겠습니다." },
    [4342] = { name = "카란의 이야기", objective = "카란 마이트해머가 하는 이야기를 들어야 합니다." },
    [4361] = { name = "나쁜 소식 전달", objective = "아이언포지로 돌아가 국왕 마그니 브론즈비어드에게 이 나쁜 소식을 전해야 합니다." },
    [4182] = { name = "용혈족의 위협", objective = "검은 새끼용 15마리, 검은용혈족 10마리, 검은고룡족 4마리와 검은 비룡 1마리를 처치한 후, 헬렌디스 리버혼에게 돌아가야 합니다." },
    [4183] = { name = "진정한 지도자", objective = "레이크샤이어로 가서 집정관 솔로몬에게 헬렌디스 리버혼의 편지를 전달해야 합니다." },
    [4184] = { name = "진정한 지도자", objective = "스톰윈드로 가서 대영주 볼바르 폴드라곤에게 볼바르에게 보내는 솔로몬의 탄원서를 전해주어야 합니다. 볼바르는 스톰윈드 왕궁에 있습니다." },
    [4185] = { name = "진정한 지도자", objective = "여군주 카트라나 프레스톨과 얘기를 나눈 후, 대영주 볼바르 폴드라곤과 대화하십시오." },
    [4186] = { name = "진정한 지도자", objective = "레이크샤이어에 있는 집정관 솔로몬에게 볼바르의 명령서를 가져가야 합니다." },
    [4223] = { name = "진정한 지도자", objective = "불타는 평원에 있는 치안대장 맥스웰과 대화하십시오." },
    [4224] = { name = "진정한 지도자", objective = "털보 존을 만나 치안대장 윈저의 행방에 대해서 알아낸 다음 치안대장 맥스웰에게 돌아가 보고해야 합니다. 치안대장 맥스웰은 북쪽에 있는 동굴에서 털보 존을 찾아보라고 했습니다." },
    [4241] = { name = "치안대장 윈저", objective = "북서쪽에 있는 검은바위 산으로 가서 검은바위 나락으로 들어가십시오. 치안대장 윈저에게 무슨 일이 있었는지 알아내야 합니다. 털보 존은 윈저가 감옥으로 끌려갔다고 했습니다." },
    [4242] = { name = "실망", objective = "치안대장 맥스웰에게 나쁜 소식을 전해줘야 합니다." },
    [4264] = { name = "꼬깃꼬깃한 쪽지", objective = "방금 우연히 치안대장 윈저가 보고 싶어할 듯한 물건을 찾은 것 같습니다. 어쩌면 희망이 있을지도 모릅니다." },
    [4282] = { name = "잔존하는 희망", objective = "치안대장 윈저의 잃어버린 단서를 가져 와야 합니다. 치안대장 윈저는 골렘 군주 아젤마크와 사령관 앵거포지가 이 정보를 가지고 있을 것이라 생각합니다." },
    [3906] = { name = "화염의 부조화", objective = "검은바위 산에 있는 채석장으로 가서 멸망의 파이론을 처치해야 합니다. 이 임무를 완수한 후 썬더하트에게 돌아가십시오." },
    [3981] = { name = "사령관 고르샤크", objective = "검은바위 나락에서 사령관 고르샤크를 찾아야 합니다. 조잡하게 그려진 오크 그림에 쇠창살이 그려져 있던 것이 생각납니다. 감옥 같은 곳을 찾아봐야 할 것 같습니다." },
    [3982] = { name = "사태 파악", objective = "고르샤크를 보호해야 합니다." },
    [4001] = { name = "사태 파악", objective = "카란 마이트해머와 대화하여 공주 모이라 브론즈비어드의 납치에 대한 정보를 모은 후, 그 정보를 오그리마에 있는 스랄에게 가져가야 합니다. 고르샤크가 카란이 근처 감방에 갇혀 있다고 말했던 것이 기억납니다." },
    [4002] = { name = "동부 왕국", objective = "스랄이 계획한 임무를 맡을 준비가 되었으면 스랄과 다시 한번 대화하십시오." },
    [4081] = { name = "죽음의 본보기: 검은무쇠단 드워프", objective = "검은바위 나락으로 가서 사악한 침략자들을 쳐부수십시오! 장군 고어투스가 성난모루단 보초 15명, 성난모루단 교도관 10명, 성난모루단 보병 5명을 처치해 달라고 부탁했습니다. 임무를 완수하면 장군 고어투스에게 돌아가십시오." },
    [4122] = { name = "그랄크 로크럽", objective = "불타는 평원으로 가서 그랄크 로크럽을 찾아야 합니다. 렉스로트가 그를 마지막으로 거대한 검은바위 요새에서 보았다고 말했던 것이 기억납니다. 그랄크 로크럽을 찾으면 토륨 족쇄를 사용해 그를 포박한 뒤 다시 검은바위 산을 지나 이글거리는 협곡으로 데려가야 합니다. 렉스로트의 부하들이 반대편에서 기다리고 있다가 그랄크를 인계받을 것입니다." },
    [4121] = { name = "곤경", objective = "포로인 그랄크 로크럽을 호송해 불타는 평원을 지나고 검은바위 산을 넘어 이글거리는 협곡으로 가야 합니다. 반대편에서 렉스로트의 부하들이 기다리다가 그랄크 로크럽을 인계받도록 하겠다고 렉스로트가 말했던 것이 기억납니다. 또한 토륨 족쇄를 렉스로트에게 전해주어야 합니다." },
    [4061] = { name = "기계들의 봉기", objective = "불타는 평원으로 가서 제사장 테오도라 뮬바다니아에게 가져갈 부서진 원소 파편 10개를 모아야 합니다. 그 지역의 골렘과 정령들에게서 이 파편을 구할 수 있을 거라고 테오도라가 말했던 것이 기억납니다." },
    [4062] = { name = "기계들의 봉기", objective = "로트윌 베리아투스에게 원소 파편 견본을 가져가야 합니다. 테오도라가 로트윌은 동쪽 야영지에 있다고 얘기했던 것이 기억납니다." },
    [5002] = { name = "멕스웰에게의 전보", objective = "불타는 평원에 있는 치안대장 맥스웰에게 비쥬의 정보를 전해야 합니다." },
    [4981] = { name = "요원 비쥬", objective = "검은바위 첨탑으로 가서 비쥬에게 무슨 일이 생겼는지 알아봐야 합니다." },
    [5065] = { name = "모쉬아루의 잃어버린 서판", objective = "세 번째와 네 번째 모쉬아루 서판을 찾아 타나리스에 있는 발굴조사단장 아이언부트에게 갖다주어야 합니다." },
    [4726] = { name = "새끼용의 정수", objective = "불타는 평원의 화염 마루에 있는 팅키 스팀보일에게 새끼용의 정수 8개와 새끼용 속박장치 900을 가져가야 합니다." },
    [4808] = { name = "펠노크 스틸스프링", objective = "팅키의 편지를 펠노크 윈터스프링에게 가져다주어야 합니다." },
    [4809] = { name = "서리바람 키메라의 뿔", objective = "펠노크 윈터스프링에게 온전한 서리바람 키메라의 뿔 8개를 가져가야 합니다." },
    [4810] = { name = "팅키에게 돌아가는 길", objective = "불타는 평원의 팅키 스팀보일에게 펠노크의 소포를 가져가야 합니다." },
    [4907] = { name = "팅키 스팀보일", objective = "과 대화해야 합니다." },
    [4734] = { name = "알껍질 냉동", objective = "알껍질급속냉각기 견본을 둥지에 있는 알에 사용해야 합니다." },
    [4903] = { name = "장군의 명령", objective = "대군주 오모크와 대장군 부네, 대군주 웜타라크를 처단해야 합니다. 검은바위의 중요한 문서들을 확보해야 합니다. 임무를 완수하는 대로 카르가스의 장군 고어투스에게로 돌아가야 합니다." },
    [4941] = { name = "아이트리그의 지혜", objective = "오그리마의 스랄의 요새에 있는 아이트리그와 대화해야 합니다. 아이트리그의 얘기를 듣고 난 후에는 대족장 스랄과 상의해야 합니다." },
    [4974] = { name = "호드를 위하여!", objective = "검은바위 첨탑으로 가서 대족장 렌드 블랙핸드를 처치하십시오. 그 증거로 그의 머리카락을 가지고 오그리마로 돌아와야 합니다." },
    [6566] = { name = "바람이 전해 온 소식", objective = "스랄의 이야기를 들어야 합니다." },
    [6567] = { name = "호드의 용사", objective = "렉사르를 찾아야 합니다. 그의 행방은 대족장이 설명해 주었습니다. 돌발톱 산맥과 페랄라스 사이에 있는 잊혀진 땅의 길에서 찾아 보십시오." },
    [6568] = { name = "렉사르의 유언", objective = "서부 역병지대에 있는 노파 미란다에게 렉사르의 유서를 전달해야 합니다." },
    [6402] = { name = "스톰윈드 회합", objective = "스톰윈드 도시 성문으로 가서, 수습기사 로우와 대화하면 그가 당신의 도착을 치안대장 윈저에게 알릴 것입니다." },
    [6403] = { name = "대단한 가장무도회", objective = "레지널드 윈저를 따라 스톰윈드를 통과해 왕궁으로 가야합니다. 윈저를 보호하십시오!" },
    [6501] = { name = "용의 눈", objective = "전 세계를 뒤져 용의눈 조각의 힘을 복원할 수 있는 자를 찾아야 합니다. 이와 관련해 알고 있는 유일한 정보는 그러한 자들이 존재한다는 것뿐입니다." },
    [6570] = { name = "엠버스트라이프", objective = "먼지진흙 습지대에 있는 용의 둥지로 가서 엠버스트라이프의 굴을 찾아야 합니다. 안으로 들어가서 용족 파멸의 아뮬렛을 착용하고 엠버스트라이프와 대화해야 합니다." },
    [6582] = { name = "해골 시험 - 스크라이어", objective = "여명의 설원에서 찾을 수 있는 푸른용군단의 용사 스크라이어를 찾아 처치해야 합니다. 그의 시체에서 해골을 수습해서 엠버스트라이프에게 돌아가야 합니다." },
    [6583] = { name = "해골 시험 - 솜누스", objective = "녹색용군단의 우두머리 솜누스를 처치한 후 그의 해골을 수습해서 엠버스트라이프에게 돌아가야 합니다." },
    [6584] = { name = "해골 시험 - 크로날리스", objective = "노즈도르무의 자손인 크로날리스가 타나리스 사막에 있는 시간의 동굴을 지키고 있습니다. 그를 처치한 후 그의 해골을 엠버스트라이프에게 가져가야 합니다." },
    [6585] = { name = "해골 시험 - 악트로즈", objective = "그림 바톨로 가서 붉은용군단의 우두머리 악트로즈를 찾아 그를 처치한 다음 그의 해골을 수습하여 엠버스트라이프에게 돌아가야 합니다." },
    [6601] = { name = "진급", objective = "이제 가면놀이는 끝난 것 같습니다. 노파 미란다가 만든 용족 파멸의 아뮬렛이 검은바위 첨탐 안에서 원래 구실을 하지 않는 것을 알고 있습니다. 아마도 렉사르를 찾아가 곤경에 처한 상황을 설명하는 것이 좋겠습니다. 렉사르에게 흐릿한 비룡불꽃 아뮬렛을 보여주면 아마도 필요한 게 무엇인지 알 수 있을 겁니다." },
    [5089] = { name = "사령관 드라키사스의 명령서", objective = "불타는 평원에 있는 치안대장 맥스웰에게 사령관 드라키사스의 명령서를 가져가야 합니다." },
    [5527] = { name = "정화의 성물함", objective = "실리더스로 가서 마파람 마을 부근 유적지에 있을 정화의 성물함을 찾아내야 합니다. 찾게 되면 달의 숲의 나이트헤이븐에 있는 라빈 사투르나에게 돌아가야 합니다." },
    [5244] = { name = "켈테릴의 폐허", objective = "별똥별 마을에 있는 야론 스톤셰이퍼와 대화하십시오." },
    [5245] = { name = "켈테릴의 고통받는 영혼", objective = "야론의 곡괭이를 사용해 귀족 유물 조각 4개를 찾아 동부 역병지대에 있는 아우로라 스카이콜러에 갖다주어야 합니다." },
    [5246] = { name = "과거의 조각들", objective = "아즈샤라에 있는 진말로의 신전에서 귀족의 성서를 찾아야 합니다. 동부 역병지대의 북부관문 경비탑 근처에 있는 아우로라 스카이콜러에게 가져가십시오." },
    [7637] = { name = "희생의 중요성", objective = "아이언포지에 가서 대사제 로한의 퇴마 향로를 가져와야 합니다. 퇴마 향로를 얻으려면 150골드를 기부해야 합니다." },
    [7639] = { name = "희생과 심판", objective = "퇴마 향로를 가지고 스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 돌아가야 합니다." },
    [7640] = { name = "테러데일 퇴마", objective = "퇴마 향로를 사용하여 테러데일에 고통을 주는 영혼을 몰아내야 합니다. 25명의 테러데일 영혼을 해치운 다음 스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 돌아가야 합니다." },
    [7641] = { name = "그리만트 엘모어의 마갑", objective = "스톰윈드의 드워프 지구에 있는 그리만트 엘모어와 대화해야 합니다." },
    [7642] = { name = "마갑 재료 수집", objective = "룬무늬 옷감 40개, 아케이나이트 주괴 6개, 아서스의 눈물 10개, 스트라솔름 성수 물병 5개 그리고 150골드를 스톰윈드의 드워프 지구에 있는 그리만트 엘모어에게 가져가야 합니다." },
    [7648] = { name = "그리만트의 걸작품", objective = "스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 아케이나이트 마갑을 가져가야 합니다." },
    [7645] = { name = "맛좋은 만나 사료", objective = "맛좋은 만나빵 20개를 모아서 힐스브래드 구릉지의 사우스쇼어에 있는 메리데스 칼슨에게 가져가야 합니다. 맛좋은 만나빵은 맛좋은 만나 사료에 꼭 필요한 재료입니다. 맛좋은 만나빵은 은빛 여명회에서 독점적으로 파는 것으로 알려져 있습니다. 메리데스 칼슨에게도 50골드를 주어야만 화가 난 마음을 진정시킬 수 있습니다." },
    [7563] = { name = "피의 광란", objective = "불타는 평원에 있는 모르줄 블러드브링어에게 흉포한 올빼미야수의 피 30병을 가져가야 합니다." },
    [7564] = { name = "와일드아이즈", objective = "불타는 평원에 있는 고르지키 와일드아이즈에게 피가 담긴 상자를 가져가야 합니다." },
    [7623] = { name = "군주 베인할로우", objective = "불타는 평원에 있는 고르지키에게서 어둠의 물약을 구입해야 합니다. 이 물약을 사용하여 자에데나르로 가서 군주 베인할로우와 대화하십시오." },
    [7624] = { name = "배신자 울라텍", objective = "울라텍과 맞서 싸운 후 자에데나르에 있는 베인할로우 군주에게 배신자의 증거를 가져가야 합니다." },
    [7625] = { name = "소로시안 별가루", objective = "우르단에게서 소로시안 별가루를 구입한 후, 불타는 평원에 있는 고르지키 와일드아이즈에게 가져가야 합니다." },
    [7626] = { name = "데스무라의 종", objective = "불타는 평원에 있는 고르지키 와일드아이즈에게 암흑 강화의 비약 10개를 가져가야 합니다." },
    [7627] = { name = "어둠의 물레", objective = "불타는 평원에 있는 고르지키 와일드아이즈에게 눈부신 큰 결정 6개와 검은무쇠 광석 25개를 가져가야 합니다." },
    [7628] = { name = "심판의 양초", objective = "불타는 평원에 있는 고르지키 와일드아이즈에게 검은용 비늘 35개를 가져가야 합니다." },
    [7630] = { name = "아케이나이트", objective = "불타는 평원에 있는 고르지키에게 아케이나이트 주괴 3개를 가져가야 합니다." },
    [5461] = { name = "라스 프로스트위스퍼", objective = "아라시 고원에 있는 스트롬가드 폐허로 가십시오. 스트롬가드에서 추억의 유품을 찾아야 합니다. 그런 물건을 찾으면 집정관 마르듀크에게 돌아가야 합니다." },
    [5462] = { name = "망자, 라스 프로스트위스퍼", objective = "동부 역병지대에 있는 희망의 빛 예배당으로 가서 존경받는 리어니드 바돌로매를 찾아서 추억의 유품을 보여 주고 알아낸 사실에 대해 모두 얘기해야 합니다." },
    [5464] = { name = "메네실의 선물", objective = "동부 역병지대에 있는 리어니드 바돌로매에게 영혼이 씌인 유품을 가져가야 합니다." },
    [5465] = { name = "영혼이 씌인 유품", objective = "카엘 다로우에 있는 집정관 마르듀크에게 돌아가십시오. 그에게 영혼이 씌인 유품을 보여줘야 합니다." },
    [5522] = { name = "리어니드 바돌로매", objective = "동부 역병지대에 있는 리어니드 바돌로매에게 얼어붙은 알을 가져가야 합니다." },
    [5531] = { name = "베티나 비글징크", objective = "에게 얼어붙은 알을 가져가야 합니다." },
    [7644] = { name = "축복받은 아케이나이트 마갑", objective = "을 가지고 스톰윈드의 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 돌아가야 합니다." },
    [7646] = { name = "예언의 탐지기", objective = "스톰윈드의 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 아제로스 다이아몬드와 온전한 검은 다이아몬드를 가져가야 합니다." },
    [7667] = { name = "물질적인 부탁", objective = "오그리마, 지혜의 골짜기에 있는 사고른 크레스트스트라이더의 일을 도우려면 그에게 아제로스 다이아몬드와 온전한 검은 다이아몬드를 가져가야 합니다." },
    [5251] = { name = "기록관", objective = "스트라솔름으로 가서 붉은십자군의 기록관, 갈포드를 찾아서 그를 처치하고 붉은십자군 기록을 불태워 버려야 합니다." },
    [5542] = { name = "지옥개", objective = "새끼 역병사냥개 20마리, 역병사냥개 5마리와 광포한 역병사냥개 5마리를 처치하십시오. 임무를 완수하면 티리온 폴드링에게 돌아가야 합니다." },
    [5543] = { name = "핏빛 하늘", objective = "역병박쥐 30마리를 처치한 후 티리온 폴드링에게 돌아가야 합니다." },
    [5544] = { name = "청소부구더기", objective = "부근에서 청소부구더기와 걸신들린 청소부구더기를 찾아 처치하고 청소부구더기 고기덩어리 15개를 모은 후 티리온 폴드링에게 돌아가야 합니다." },
    [5742] = { name = "구원", objective = "티리온 폴드링이 하려고 하는 말이 무엇인지 들어야 합니다." },
    [5781] = { name = "잃어버린 기억들", objective = "동부 역병지대의 최남쪽에 있는 지하 납골당으로 가서 탤런의 망치를 되찾은 후 티리온 폴드링에게 돌아가서 임무를 완수해야 합니다." },
    [5845] = { name = "명예의 상징", objective = "동부 역병지대의 북동쪽에 있는 노스데일로 가서 실추된 명예의 상징을 되찾은 후 티리온 폴드링에게 돌아가서 임무를 완수해야 합니다." },
    [5846] = { name = "가족과 사랑", objective = "역병지대의 남쪽 중앙에 있는 카엘 다로우로 가서 초상화가 어디쯤 있는지에 대한 단서를 찾아야 합니다." },
    [5262] = { name = "밝혀지는 진실", objective = "동부 역병지대에 있는 공작 니콜라스 즈바른호프에게 발나자르의 혼을 가져가야 합니다." },
    [6133] = { name = "순찰대장의 명령", objective = "동부 역병지대의 북쪽 경계로 이동하여 쿠엘탈라스 기록부를 찾아야 합니다. 기록부는 쿠엘리시엔 오두막 어딘가에 있습니다. 순찰자 8명, 길잡이 8명, 수렵꾼 8명을 해치워야 합니다." },
    [6042] = { name = "성가신 녀석들", objective = "맹독 역병박쥐 20마리와 기괴한 역병박쥐 10마리를 해치운 후 나타노스 블라이트 콜러에게 돌아가야 합니다." },
    [6022] = { name = "이유 있는 살육", objective = "동쪽의 코린 삼거리로 가서 마을에 사는 스컬지를 해치워 10분 안에 살아있는 부패물 7개를 모으십시오. 막자 사발을 사용해서 살아있는 부패물을 갈아 응고된 부패물로 만들어야 합니다." },
    [6135] = { name = "혐오스런 그늘날개", objective = "마리스 농장 북부의 변두리를 배회하고 있는 그늘날개를 찾아 해치워야 합니다. 시체에서 그늘날개 모피 조각을 찾아 나타노스 브라이트콜러에게 가져가야 합니다." },
    [6136] = { name = "뚱뚱보 괴물", objective = "동부 역병지대 북부 불모지에서 피고름구더기를 찾아 물리친 후 나타노스 블라이트콜러에게 돌아가야 합니다." },
  },
  zhCN = {
    [1113] = { name = "狂热之心", objective = "幽暗城的大药剂师法拉尼尔需要20颗狂热之心。" },
    [6521] = { name = "邪恶的盟友", objective = "把玛克林大使的头颅交给幽暗城的瓦里玛萨斯。" },
    [1956] = { name = "奥达曼的能量源", objective = "找到一个黑曜石能量源，将其交给尘泥沼泽的塔贝萨。" },
    [4143] = { name = "邪恶之雾", objective = "收集5份阿塔莱之雾的样本，然后向安戈洛环形山的穆尔金复命。" },
    [4146] = { name = "除草器的燃料", objective = "收集5份阿塔莱之雾的样本，然后将它们送到马绍尔营地的拉瑞安那里。" },
    [9053] = { name = "更好的材料", objective = "从沉没的神庙底部的守卫身上得到一些腐烂藤蔓，把它们交给托尔瓦·寻路者。" },
    [8232] = { name = "神庙中的绿龙", objective = "将摩弗拉斯的牙齿交给艾萨拉的奥汀克。他住在埃达拉斯废墟东北部悬崖的顶端。" },
    [8253] = { name = "毁灭摩弗拉斯", objective = "从摩弗拉斯身上取回奥术碎片，然后返回大法师克希雷姆那儿。" },
    [8418] = { name = "铸造力量之石", objective = "前往沉没的神庙，从巨魔守护者们身上取得巫毒羽毛，然后把它们交给阿什拉姆·瓦罗菲斯特。" },
    [8257] = { name = "摩弗拉斯之血", objective = "前往沉没的阿塔哈卡神庙，杀死绿龙摩弗拉斯，将他的血液交给费伍德森林中的格雷塔·苔蹄。沉没的神庙的入口就在悲伤沼泽中。" },
    [8236] = { name = "碧蓝钥匙", objective = "将碧蓝钥匙交给乔拉齐·拉文霍德公爵。" },
    [8413] = { name = "巫毒羽毛", objective = "将巫毒羽毛交给捕风者巴斯拉。" },
    [8422] = { name = "巨魔的羽毛", objective = "到沉没的神庙去，从巨魔们身上获得6支巫毒羽毛。" },
    [8425] = { name = "巫毒羽毛", objective = "将你从沉没的神庙的巨魔身上得到的巫毒羽毛交给部落英雄的灵魂。" },
    [4362] = { name = "王国的命运", objective = "回到黑石深渊，从达格兰·索瑞森大帝的魔掌中救出铁炉堡公主茉艾拉·铜须。" },
    [4003] = { name = "拯救公主", objective = "杀掉达格兰·索瑞森大帝，然后将铁炉堡公主茉艾拉·铜须从他的邪恶诅咒中拯救出来。" },
    [7201] = { name = "最后的元素", objective = "到黑石深渊去取得10份元素精华。你应该在那些作战傀儡和傀儡制造者身上找找，另外，薇薇安·拉格雷也提到了一些有关元素生物的话题……" },
    [4286] = { name = "好东西", objective = "到黑石深渊去找到20个黑铁挎包。当你完成任务之后，回到奥拉留斯那里复命。你认为黑石深渊里的黑铁矮人应该会有这些黑铁挎包。" },
    [7848] = { name = "熔火之心的传送门", objective = "进入黑石深渊，在通往熔火之心的传送门附近找到一块熔火碎片，然后回到黑石山脉的洛索斯·天痕那里。" },
    [5001] = { name = "比修的装置", objective = "找到比修的装置并把它们还给她。祝你好运！" },
    [4982] = { name = "比修的装置", objective = "找到比修的装置并把它们还给她。你记得她说过她把装置藏在城市的最底层。" },
    [4788] = { name = "最后的石板", objective = "将第五块和第六块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。" },
    [6569] = { name = "黑龙幻象", objective = "到黑石塔去收集20颗黑色龙人的眼球，完成任务之后回到巫女麦兰达那里。" },
    [4764] = { name = "末日扣环", objective = "将末日扣环交给燃烧平原的玛亚拉·布莱特文。" },
    [4768] = { name = "黑暗石板", objective = "将黑暗石板交给卡加斯的暗法师薇薇安·拉格雷。" },
    [5160] = { name = "监护者", objective = "到冬泉谷去找到哈尔琳，把奥比的鳞片交给她。" },
    [5526] = { name = "魔藤碎片", objective = "在厄运之槌中找到魔藤，然后从它上面采集一块碎片。只有干掉了奥兹恩之后，你才能进行采集工作。使用净化之匣安全地封印碎片，然后将其交给月光林地永夜港的拉比恩·萨图纳。" },
    [7463] = { name = "久违的法师", objective = "到厄运之槌的扭木广场去杀掉水元素海多斯博恩。把海多斯博恩精华交给图书馆的博学者莱德罗斯。" },
    [7461] = { name = "伊莫塔尔的疯狂", objective = "你必须干掉5座水晶塔周围的守卫，那5座水晶塔维持着关押伊莫塔尔的监狱。一旦水晶塔的能量被削弱，伊莫塔尔周围的能量力场就会消散。 进入伊莫塔尔的监狱，干掉站在中间的那个恶魔。最后，在图书馆挑战托塞德林王子。 当任务完成之后，到庭院中去找辛德拉古灵。" },
    [5247] = { name = "历史的残片", objective = "给东瘟疫之地的奥萝拉带去一块魔化瑟银锭、5块恢复水晶，以及一小瓶恐怖之水。" },
    [7643] = { name = "上古圣马之魂", objective = "你需要特殊的饲料来喂养灵魂马。南海镇的梅丽德丝·卡尔森可以为你提供这样的粮草。 到菲拉斯的厄运之槌去，杀掉特迪斯·扭木，释放上古圣马之魂。用特殊的粮草喂养它，这样可以安抚它的灵魂。最后，把奥金马铠交给它就可以完成祝福。" },
    [7631] = { name = "克索诺斯恐惧战马", objective = "阅读莫苏尔的指南，并召唤出一匹克索诺斯恐惧战马，击败它，然后控制它的灵魂。" },
    [7506] = { name = "翡翠梦境……", objective = "将这本典籍交给它的主人。" },
    [7503] = { name = "最伟大的猎手", objective = "将这本典籍交给它的主人。" },
    [7500] = { name = "奥法师的食谱", objective = "将这本典籍交给它的主人。" },
    [7501] = { name = "圣光之力", objective = "将这本典籍交给它的主人。" },
    [7504] = { name = "光明不会告诉你的事情", objective = "将这本典籍交给它的主人。" },
    [7498] = { name = "迦罗娜：潜行与诡计研究", objective = "将这本典籍交给它的主人。" },
    [7505] = { name = "你与冰霜震击", objective = "将这本典籍交给它的主人。" },
    [7502] = { name = "束缚之影", objective = "将这本典籍交给它的主人。" },
    [7499] = { name = "防御宝典", objective = "将这本典籍交给它的主人。" },
    [7629] = { name = "瓶中的小鬼", objective = "把瓶中的小鬼带到通灵学院的炼金实验室中。在小鬼制造出羊皮纸之后，把瓶子还给戈瑟奇·邪眼。" },
    [7647] = { name = "审判和救赎", objective = "在通灵学院尸骨储藏所地下室的中心使用预言水晶球。将你要审判的灵魂引领出来。将这些灵魂击败然后死亡骑士达克雷尔就将被召唤出来。将其击败然后获得堕落战马的灵魂。 把赎罪的战马之魂和被祝福的奥金马铠一起附在达克雷尔的堕落战马身上。" },
    [7668] = { name = "达克雷尔的威胁", objective = "在通灵学院的尸骨储藏所地下室中心使用预言水晶球，这样将会召来一些灵魂，你必须与它们交战。将这些灵魂击败，死亡骑士达克雷尔就会出现。 击败达克雷尔，将他的头颅交给奥格瑞玛智慧谷的萨格尼。" },
    [5463] = { name = "米奈希尔的礼物", objective = "到斯坦索姆城里去找到米奈希尔的礼物，把巫妖生前的遗物放在那块邪恶的土地上。" },
    [261] = { name = "血色之路", objective = "杀掉30个亡灵劫掠者，然后向尼耶尔前哨站的安东修士复命。" },
    [1052] = { name = "血色之路", objective = "将安东修士的表彰信带给南海镇的虔诚的莱雷恩。" },
    [6522] = { name = "邪恶的盟友", objective = "把小卷轴交给幽暗城的瓦里玛萨斯。" },
    [720] = { name = "一线希望", objective = "找到勘察员雷杜尔，告诉他铁趾格雷兹还活着。" },
    [738] = { name = "寻找阿戈莫德", objective = "找到阿戈莫德。" },
    [739] = { name = "莫达洛克", objective = "干掉杀害阿戈莫德的凶手：莫达洛克。 顺便杀掉12个石窟断骨者。 然后向洛克莫丹的勘察员基恩萨·铁环报告。" },
    [723] = { name = "铁趾的遗愿", objective = "把铁趾的护符交给荒芜之地的勘察员雷杜恩。" },
    [724] = { name = "铁趾的遗愿", objective = "把铁趾的护符交给铁炉堡的史学家卡尼克。" },
    [725] = { name = "亡者的警告", objective = "找到顾问贝尔格拉姆，把便笺交给他。" },
    [726] = { name = "亡者的警告", objective = "和史学家卡尼克谈一谈。" },
    [762] = { name = "邪恶的使者", objective = "杀死苦痛堡垒中的因弗努斯大使，把证明他已死亡的信物交给铁炉堡的顾问贝尔格拉姆。" },
    [2198] = { name = "破碎的项链", objective = "找到破碎的项链的来源，从而了解其潜在的价值。" },
    [2199] = { name = "昂贵的知识", objective = "给铁炉堡的塔瓦斯德·基瑟尔带去五块银锭。" },
    [2200] = { name = "回到奥达曼", objective = "去奥达曼寻找塔瓦斯的魔法项链，被杀的圣骑士是最后一个拿着它的人。" },
    [2318] = { name = "翻译日记", objective = "在荒芜之地的卡加斯哨所里寻找一个可以帮你翻译圣骑士日记的人。" },
    [2338] = { name = "翻译日记", objective = "将项链借给加卡尔。作为交换，他将帮你翻译日记。" },
    [2500] = { name = "荒芜之地的材料", objective = "从荒芜之地拿到加克所需的材料，然后回到塞尔萨玛去见他。" },
    [2258] = { name = "荒芜之地的试剂", objective = "前往荒芜之地取回加卡尔需要的试剂，然后回到卡加斯把试剂交给他。" },
    [1954] = { name = "地狱火宝珠", objective = "将一颗地狱火宝珠交给尘泥沼泽的塔贝萨。" },
    [1955] = { name = "驱除魔鬼", objective = "杀死宝珠之魔，然后与塔贝萨谈一谈。" },
    [2988] = { name = "枯木巨魔的牢笼", objective = "检查两个枯木巨魔村落里的笼子，然后向狮鹫管理员沙拉克·鹰斧回复。" },
    [2989] = { name = "祖尔祭坛", objective = "检查祖尔祭坛的顶部，然后向狮鹫管理员沙拉克·鹰斧报告。" },
    [2990] = { name = "萨迪斯·格希德", objective = "将沙普比克的羽毛交给诅咒之地的萨迪斯·格希德。" },
    [2933] = { name = "毒液瓶", objective = "将毒药瓶交给塔伦米尔的某个药剂师。" },
    [2934] = { name = "完好无损的毒囊", objective = "将完好无损的毒囊交给塔伦米尔的药剂师林度恩。" },
    [2935] = { name = "请教加德林大师", objective = "与森金村的加德林大师谈一谈。" },
    [3520] = { name = "尖啸者的灵魂", objective = "在菲拉斯捕获3个尖啸者的灵魂，然后回到热砂港的叶基亚那里去。" },
    [1448] = { name = "调查神庙", objective = "暴风城的布罗哈恩·铁桶要求你去找到阿塔哈卡神庙。" },
    [1449] = { name = "去辛特兰的旅程", objective = "找到辛特兰的弗斯塔德·蛮锤。" },
    [1450] = { name = "狮鹫管理员", objective = "与辛特兰的鹰巢山狮鹫饲养场里的狮鹫管理员沙拉克·鹰斧谈一谈。" },
    [1451] = { name = "拉普索迪·铁铲", objective = "去辛特兰找到拉普索迪·铁铲。" },
    [1452] = { name = "拉普索迪的卡利姆多鸡尾酒", objective = "辛特兰的拉普索迪·铁铲要求你带给他3块大鹏的砂囊、3块格罗多克猩猩的肝脏和3块铁鬃熊的肝脏。" },
    [1469] = { name = "拉普索迪的故事", objective = "将阿塔莱石板碎片交给暴风城的布罗哈恩·铁桶。" },
    [1424] = { name = "泪水之池", objective = "斯通纳德的费泽鲁尔要求你收集10件阿塔莱神器。" },
    [1429] = { name = "阿塔莱流放者", objective = "将一捆阿塔莱神器交给辛特兰的阿塔莱流放者。" },
    [1444] = { name = "向费泽鲁尔复命", objective = "向斯通纳德的费泽鲁尔回报。" },
    [3444] = { name = "石环", objective = "到棘齿城去，从玛尔冯·瑞文斯克的车间里取回石环。" },
    [4787] = { name = "远古之卵", objective = "将远古之卵交给塔纳利斯的叶基亚。" },
    [4141] = { name = "穆尔金和拉瑞安", objective = "从安戈洛尔环形山的血瓣花猛击者和血瓣花掠夺者身上收集15个血瓣花，然后向穆尔金回复。" },
    [4142] = { name = "造访格雷甘", objective = "把血瓣花交给菲拉斯的格雷甘·山酒。" },
    [4145] = { name = "拉瑞安和穆尔金", objective = "为马绍尔营地里的拉瑞安杀掉5个血瓣花鞭笞者、5个血瓣花捕兽者、5个血瓣花掠夺者和5个血瓣花猛击者。" },
    [4147] = { name = "玛尔冯的车间", objective = "到棘齿城去，在玛尔冯·瑞文斯克的车间里找到他。" },
    [9052] = { name = "血瓣毒药", objective = "收集一些血帽和格里什钉刺，然后向托尔瓦·寻路者复命。" },
    [9051] = { name = "毒性测试", objective = "将魔暴龙之刺扎入一只魔暴龙的体内。" },
    [8153] = { name = "苔蹄快步者的鹿角", objective = "将一副完好的苔蹄快步者鹿角交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶。" },
    [8231] = { name = "碎浪多头怪", objective = "将6块碎浪多头怪的鳞片交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶部。" },
    [8251] = { name = "魔法的尘埃", objective = "为大法师克希雷姆收集10份闪光尘埃。" },
    [8252] = { name = "纳迦的珊瑚", objective = "收集6块魔化珊瑚，然后把它们交给大法师克希雷姆。" },
    [8414] = { name = "驱散邪恶", objective = "收集20个爪牙的天灾石，并将它们交给西瘟疫之地的高阶牧师赛尔丹尼斯。" },
    [8416] = { name = "惰性天灾石", objective = "将惰性天灾石交给冰风岗的指挥官阿什拉姆·瓦罗菲斯特。" },
    [8255] = { name = "苔蹄快步者", objective = "收集4份健康的野鹿腺体，把它们交给艾萨拉的奥汀克。奥汀克住在埃达拉斯废墟东北部悬崖的顶部。" },
    [8256] = { name = "亡灵的腐液", objective = "为艾萨拉的奥汀克带回一份亡灵腐液。奥汀克住在埃达拉斯废墟东北部悬崖的顶端。" },
    [8234] = { name = "密封的蓝袋子", objective = "从艾萨拉的木喉萨满祭司那儿取回密封的蓝袋子，将它交给艾萨拉的大法师克希雷姆。" },
    [8235] = { name = "密文碎片", objective = "将10块密文碎片交给艾萨拉的大法师克希雷姆。" },
    [8410] = { name = "元素掌握", objective = "为捕风者巴斯拉收集一份空气样本、一份火元素样本、一份土元素样本和一份水元素样本。" },
    [8412] = { name = "灵魂图腾", objective = "将灵魂图腾所需的材料交给捕风者巴斯拉。" },
    [8419] = { name = "小鬼的要求", objective = "将一块恶魔布交给费伍德森林的伊普斯。" },
    [8420] = { name = "灼热的疼痛", objective = "将一块恶魔布交给费伍德森林的伊普斯。" },
    [8421] = { name = "奇怪的材料", objective = "将10块腐烂的木头和4个血毒精华交给费伍德森林的伊普斯。" },
    [8423] = { name = "战士的血脉", objective = "杀死7头地狱野猪，然后回到部落英雄的灵魂那儿。" },
    [8424] = { name = "魔誓者之战", objective = "杀死诅咒之地的魔誓者，然后回到部落英雄的灵魂那儿。" },
    [3801] = { name = "黑铁的遗产", objective = "如果你想要得到进入这座城市主城区的钥匙，就去和弗兰克罗恩·铸铁谈一谈。" },
    [4262] = { name = "征服者派隆", objective = "杀掉征服者派隆，然后向加琳达复命。 加琳达告诉过你，派隆守在采矿场中，也许你应该去那里找找。" },
    [3702] = { name = "索瑞森废墟", objective = "听皇家历史学家阿克瑟努斯讲述索瑞森的历史。" },
    [3701] = { name = "索瑞森废墟", objective = "到燃烧平原的索瑞森废墟中去，从索瑞森遗物上搜集信息。当你收集到足够的信息之后，就回到皇家历史学家阿克瑟努斯那里。" },
    [4341] = { name = "卡兰·巨锤", objective = "去黑石深渊找到卡兰·巨锤。 国王提到卡兰在那里负责看守囚犯——也许你应该在监狱附近寻找他。" },
    [4342] = { name = "卡兰的故事", objective = "听卡兰·巨锤说他的故事。" },
    [4361] = { name = "糟糕的消息", objective = "回到铁炉堡，把这个坏消息带给国王麦格尼·铜须。" },
    [4182] = { name = "黑龙的威胁", objective = "杀掉15条黑色小龙、10条黑色龙人和1条黑色幼龙。当你完成任务之后就向赫林迪斯·河角回报。" },
    [4183] = { name = "真正的主人", objective = "把赫林迪斯·河角的信交给湖畔镇的所罗门镇长。" },
    [4184] = { name = "真正的主人", objective = "到暴风城去把所罗门的求援信交给伯瓦尔·弗塔根公爵。 伯瓦尔在暴风要塞里。" },
    [4185] = { name = "真正的主人", objective = "与女伯爵卡特拉娜·普瑞斯托谈话，然后再与伯瓦尔·弗塔根公爵谈话。" },
    [4186] = { name = "真正的主人", objective = "把伯瓦尔的命令交给湖畔镇的所罗门镇长。" },
    [4223] = { name = "真正的主人", objective = "和燃烧平原的麦克斯韦尔元帅谈一谈。" },
    [4224] = { name = "真正的主人", objective = "和狼狈不堪的约翰谈谈来了解温德索尔元帅的命运，然后回到麦克斯韦尔元帅那里。 你想起麦克斯韦尔元帅说过他在一个北面的洞穴那里。" },
    [4241] = { name = "温德索尔元帅", objective = "到西北部的黑石山脉去，在黑石深渊中找到温德索尔元帅的下落。 狼狈不堪的约翰曾告诉你说温德索尔被关进了一个监狱。" },
    [4242] = { name = "被遗弃的希望", objective = "把这个坏消息传达给麦克斯韦尔元帅。" },
    [4264] = { name = "弄皱的便笺", objective = "温德索尔元帅也许会对你手中的东西感兴趣。毕竟，希望还没有被完全扼杀。" },
    [4282] = { name = "一丝希望", objective = "找回温德索尔元帅遗失的情报。 温德索尔元帅确信那些情报在安格弗将军和傀儡统帅阿格曼奇的手里。" },
    [3906] = { name = "不和谐的烈焰", objective = "到黑石山脉的采石场去干掉征服者派隆，然后向桑德哈特回报。" },
    [3981] = { name = "指挥官哥沙克", objective = "在黑石深渊里找到指挥官哥沙克。 在那幅草图上画着的是一个铁栏后面的兽人，也许你应该到某个类似监狱的地方去找找看。" },
    [3982] = { name = "出了什么事？", objective = "保护哥沙克。" },
    [4001] = { name = "出了什么事？", objective = "与卡兰·巨锤谈一谈，收集关于绑架公主铁炉堡公主茉艾拉·铜须这一事件的情报。将情报反馈给奥格瑞玛城里的萨尔。 哥沙克提到过卡兰被关在附近的某个牢房中。" },
    [4002] = { name = "东部王国", objective = "如果你准备好要接受萨尔所安排的任务，就去找他谈一谈。" },
    [4081] = { name = "格杀勿论：黑铁矮人", objective = "到黑石深渊去消灭那些邪恶的侵略者！ 军官高图斯要你去杀死15个铁怒卫士、10个铁怒狱卒和5个铁怒步兵。完成任务之后回去向他复命。" },
    [4122] = { name = "格拉克·洛克鲁布", objective = "到燃烧平原去找到格拉克·洛克鲁布。你回忆起雷克斯洛特曾经提起过，格拉克应该是在一座大型的黑石要塞中。 当你找到格拉克·洛克鲁布之后，用瑟银镣铐把他铐起来，然后将其带回灼热峡谷。雷克斯洛特会让他的部下等在那里接应你。" },
    [4121] = { name = "押送囚徒", objective = "押送你的囚犯格拉克·洛克鲁布。穿过燃烧平原和黑石山脉，一直走到灼热峡谷。 雷克斯洛特曾经告诉过你，他会让他的人等在黑石山脉的另外一边准备接收格拉克。 另外，你还要把瑟银镣铐一并还给雷克斯洛特。" },
    [4061] = { name = "机器的崛起", objective = "到燃烧平原去为塞朵拉·穆瓦丹尼收集10块断裂的元素碎片。 塞朵拉曾经说过，那里的机械傀儡和元素生物是这种碎片的主要来源。" },
    [4062] = { name = "机器的崛起", objective = "将元素碎片样本交给鲁特维尔·沃拉图斯。 塞朵拉说鲁特维尔就在东边的一处营地里。" },
    [5002] = { name = "给麦克斯韦尔的消息", objective = "到燃烧平原去，把比修的情报交给麦克斯韦尔元帅。" },
    [4981] = { name = "狡猾的比修", objective = "到黑石塔去查明比修的下落。" },
    [5065] = { name = "失落的摩沙鲁石板", objective = "把第三块和第四块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。" },
    [4726] = { name = "雏龙精华", objective = "将龙灵采集器900型和8份雏龙精华交给燃烧平原烈焰峰的丁奇·斯迪波尔。" },
    [4808] = { name = "菲诺克", objective = "把丁奇的信交给菲诺克。" },
    [4809] = { name = "冰风奇美拉角", objective = "将8支完整的冰风奇美拉角交给菲诺克。" },
    [4810] = { name = "返回丁奇身边", objective = "把菲诺克的包裹交给燃烧平原的丁奇·斯迪波尔。" },
    [4907] = { name = "丁奇·斯迪波尔", objective = "与丁奇·斯迪波尔谈一谈。" },
    [4734] = { name = "冷冻龙蛋", objective = "在孵化间对着某颗龙蛋使用龙蛋冷冻器初号机。" },
    [4903] = { name = "高图斯的命令", objective = "杀死欧莫克大王、指挥官沃恩和维姆萨拉克。找到重要的黑石文件，然后向卡加斯的军官高图斯汇报。" },
    [4941] = { name = "伊崔格的智慧", objective = "和奥格瑞玛的伊崔格谈一谈。讨论完毕后，咨询萨尔的意见。 你回忆起曾在萨尔的大厅中见过伊崔格。" },
    [4974] = { name = "为部落而战！", objective = "去黑石塔杀死大酋长雷德·黑手，带着他的头颅返回奥格瑞玛。" },
    [6566] = { name = "风吹来的消息", objective = "听萨尔讲话。" },
    [6567] = { name = "部落的勇士", objective = "按照酋长的指示找到雷克萨。他在石爪山和菲拉斯之间的凄凉之地游荡。" },
    [6568] = { name = "雷克萨的证明", objective = "把雷克萨的证明交给西瘟疫之地的巫女麦兰达。" },
    [6402] = { name = "集合在暴风城", objective = "前往暴风城的城门。与侍卫洛文交谈，他会通知温德索尔元帅你已经到达了。" },
    [6403] = { name = "潜藏者", objective = "跟随雷吉纳德·温德索尔元帅在暴风城中前进。保护他，别让他受到伤害！" },
    [6501] = { name = "巨龙之眼", objective = "你必须寻遍世界以找到一种能恢复龙眼碎片的能量的生物。你对这种生物的唯一了解就是：他们确实存在。" },
    [6570] = { name = "埃博斯塔夫", objective = "到尘泥沼泽中的巨龙沼泽去，找到埃博斯塔夫的洞穴。进入洞穴之后戴上龙形护符，然后跟埃博斯塔夫交谈。" },
    [6582] = { name = "龙骨试炼，斯克利尔", objective = "找到蓝龙斯克利尔并杀掉他。从他的身上取下他的颅骨，然后将其交给埃博斯塔夫。 你可以在冬泉谷找到斯克利尔。" },
    [6583] = { name = "龙骨试炼，索姆努斯", objective = "杀掉绿龙索姆努斯，把他的颅骨交给埃博斯塔夫。" },
    [6584] = { name = "龙骨试炼，克鲁纳里斯", objective = "诺兹多姆的孩子克鲁纳里斯在塔纳利斯沙漠守卫着时光之穴。杀了他，把他的颅骨交给埃博斯塔夫。" },
    [6585] = { name = "龙骨试炼，埃克托兹", objective = "到格瑞姆巴托去杀掉红龙埃克托兹，把他的颅骨交给埃博斯塔夫。" },
    [6601] = { name = "晋升……", objective = "看来这场假面舞会就要结束了。你知道麦兰达为你制作的龙形护符在黑石塔里面不会发挥作用，也许你应该去找雷克萨，将你的困境告诉他。把黯淡的龙火护符给他看看，也许他知道下一步该怎么做。" },
    [5089] = { name = "达基萨斯将军的命令", objective = "把达基萨斯将军的命令交给燃烧平原的麦克斯韦尔元帅。" },
    [5527] = { name = "净化之匣", objective = "到希利苏斯的南风村去寻找净化之匣。然后将其交给月光林地永夜港的拉比恩·萨图纳。" },
    [5244] = { name = "凯斯利尔废墟", objective = "与坠星村的加隆·石矛谈一谈。" },
    [5245] = { name = "凯斯利尔的怨灵", objective = "使用加隆的镐来寻找四块上层精灵遗物的碎片，把它们交给东瘟疫之地的奥萝拉。" },
    [5246] = { name = "历史的残片", objective = "在艾萨拉的辛玛洛神殿里找到神圣的上层精灵笔迹，并将它带给位于东瘟疫之地的北地哨塔附近的奥萝拉。" },
    [7637] = { name = "牺牲精神", objective = "到铁炉堡去找高阶牧师洛汉，从他那里拿到驱魔香炉。你需要捐赠150金币来获得它。" },
    [7639] = { name = "圣骑士的审判", objective = "把驱魔香炉交给暴风城教堂区的格雷森·沙东布瑞克公爵。" },
    [7640] = { name = "恐惧谷的灵魂", objective = "使用驱魔香炉召唤恐惧谷中的灵魂。当你杀掉25个恐惧谷的灵魂之后，回到暴风城教堂区的格雷森·沙东布瑞克公爵那里复命。" },
    [7641] = { name = "格瑞曼德·艾尔默", objective = "与暴风城矮人区的格瑞曼德·艾尔默谈一谈。" },
    [7642] = { name = "收集材料", objective = "把40块符文布、6块奥金锭、10棵阿尔萨斯之泪、5瓶斯坦索姆圣水和150枚金币交给暴风城矮人区的格瑞曼德·艾尔默。" },
    [7648] = { name = "艾尔默的手艺", objective = "把奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。" },
    [7645] = { name = "魔法粮草", objective = "把制作魔法粮草所需要的重要材料：20块可口的魔法点心带给希尔斯布莱德丘陵的梅丽德丝·卡尔森。据说银色黎明会出售这种饼干。 你还需要给她50金币来对她进行安抚。" },
    [7563] = { name = "血之狂暴", objective = "把30瓶狂暴野兽的血交给燃烧平原的莫苏尔·召血者。" },
    [7564] = { name = "戈瑟奇·邪眼", objective = "把血箱交给燃烧平原的戈瑟奇·邪眼。" },
    [7623] = { name = "魔王贝恩霍勒", objective = "从燃烧平原的戈瑟奇那里购买暗影药水。 使用这种药剂进入加德纳尔，然后与魔王贝恩霍勒谈一谈。" },
    [7624] = { name = "背叛者乌拉泰克", objective = "找到并杀死乌拉泰克，然后把叛徒之心交给加德纳尔的魔王贝恩霍勒。" },
    [7625] = { name = "克索诺斯星尘", objective = "从乌尔丹那里购买克索诺斯星尘，把它交给燃烧平原的戈瑟奇·邪眼。" },
    [7626] = { name = "达斯莫拉之铃", objective = "把10瓶暗影之力药剂交给燃烧平原的戈瑟奇·邪眼。" },
    [7627] = { name = "黑暗战车之轮", objective = "把6份大块魔光碎片和25块黑铁矿石交给燃烧平原的戈瑟奇·邪眼。" },
    [7628] = { name = "末日蜡烛", objective = "把35块黑龙鳞片交给燃烧平原的戈瑟奇·邪眼。" },
    [7630] = { name = "奥金锭", objective = "把3块奥金锭交给燃烧平原的戈瑟奇·邪眼。" },
    [5461] = { name = "莱斯·霜语", objective = "到阿拉希高地的激流堡遗迹里面寻找巫妖生前的遗物。如果你能找到这样的东西，就把它交给马杜克镇长。" },
    [5462] = { name = "亡灵莱斯·霜语", objective = "到东瘟疫之地的圣光之愿礼拜堂去找到莱尼德·巴萨罗梅，给他看看巫妖生前的遗物，并告诉他你收集到的情报。" },
    [5464] = { name = "米奈希尔的礼物", objective = "把禁锢灵魂的遗物交给东瘟疫之地的莱尼德·巴萨罗梅。" },
    [5465] = { name = "禁锢灵魂的遗物", objective = "回到凯尔达隆的马杜克镇长那里，把禁锢灵魂的遗物交给他。" },
    [5522] = { name = "莱尼德·巴萨罗梅", objective = "把冰冻的龙蛋交给东瘟疫之地的莱尼德·巴萨罗梅。" },
    [5531] = { name = "贝蒂娜·比格辛克", objective = "将冰冻的龙蛋交给贝蒂娜·比格辛克。" },
    [7644] = { name = "被祝福的奥金马铠", objective = "将被祝福的奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。" },
    [7646] = { name = "预言水晶球", objective = "把一块艾泽拉斯钻石和一块原始黑钻石交给暴风城教堂区的格雷森·沙东布瑞克公爵。" },
    [7667] = { name = "收集材料", objective = "如果你愿意帮助奥格瑞玛智慧谷的萨格尼，就将一块艾泽拉斯钻石和一块原始黑钻石交给他。" },
    [5251] = { name = "档案管理员", objective = "在斯坦索姆城中找到血色十字军的档案管理员加尔福特，杀掉他，然后烧毁血色十字军档案。" },
    [5542] = { name = "恶魔之犬", objective = "杀掉20条瘟疫幼犬、5条瘟疫犬和5条狂怒的瘟疫犬。任务完成之后向提里奥·弗丁复命。" },
    [5543] = { name = "血染的天空", objective = "杀死30只瘟疫蝙蝠，然后向提里奥·弗丁复命。" },
    [5544] = { name = "腐肉虫", objective = "在东瘟疫之地搜索腐肉虫和腐肉吞噬者。杀了它们并收集它们的肉。当你收集到15块食腐虫肉块之后，就回到提里奥·弗丁那里。" },
    [5742] = { name = "救赎", objective = "听听提里奥·弗丁要说什么。" },
    [5781] = { name = "遗忘的记忆", objective = "到东瘟疫之地最南端的墓室去找回泰兰之锤。完成目标之后，返回提里奥·弗丁那里。" },
    [5845] = { name = "失落的荣耀", objective = "到东瘟疫之地东北部的北谷去，找到失落荣耀的象征。完成目标之后向提里奥·弗丁复命。" },
    [5846] = { name = "爱与家庭", objective = "到凯尔达隆岛去，寻找关于那副画的线索。凯尔达隆岛在瘟疫之地南部的湖中央。" },
    [5262] = { name = "可怕的真相", objective = "将巴纳扎尔的头颅交给东瘟疫之地的尼古拉斯·瑟伦霍夫公爵。" },
    [6133] = { name = "游侠之王的命令", objective = "到东瘟疫之地的北方边界去找回奎尔萨拉斯名册，这件物品在奎尔林斯小屋的某处。 另外你还必须杀掉8个游侠、8个巡路者和8个护林者。" },
    [6042] = { name = "讨厌的蝙蝠", objective = "杀掉20只毒性瘟疫蝙蝠和10只巨型瘟疫蝙蝠，然后回到纳萨诺斯·凋零者那里。" },
    [6022] = { name = "杀戮的理由", objective = "到东边的考林路口去屠杀镇里的亡灵天灾。在10分钟内收集7块生命腐质，使用研钵和捣杵将其研磨成凝固腐质。" },
    [6135] = { name = "暗翼蝠", objective = "找到暗翼蝠并杀掉它。从尸体上取下一块暗翼蝠的皮，并把它交给纳萨诺斯·凋零者。 据说暗翼蝠游荡在玛瑞斯农场北面的荒原上。" },
    [6136] = { name = "肥大的食腐虫", objective = "找到东瘟疫之地北方荒原中的淤血虫并消灭它。任务完成之后，向纳萨诺斯·凋零者复命。" },
  },
  zhTW = {
    [1113] = { name = "狂熱之心", objective = "幽暗城的大藥劑師法拉尼爾需要20顆狂熱之心。" },
    [6521] = { name = "邪惡的盟友", objective = "把瑪克林大使的頭顱交給幽暗城的瓦里瑪薩斯。" },
    [1956] = { name = "奧達曼的能量源", objective = "找到一個黑曜石能量源，將其交給塵泥沼澤的塔貝薩。" },
    [4143] = { name = "邪惡之霧", objective = "收集5份阿塔萊之霧的樣本，然後向安戈洛環形山的穆爾金覆命。" },
    [4146] = { name = "除草器的燃料", objective = "收集5份阿塔萊之霧的樣本，然後將它們送到馬紹爾營地的拉瑞安那裡。" },
    [9053] = { name = "更好的材料", objective = "從沉沒的神廟底部的守衛身上得到一些腐爛藤蔓，把它們交給托爾瓦·尋路者。" },
    [8232] = { name = "神廟中的綠龍", objective = "將摩弗拉斯的牙齒交給艾薩拉的奧汀克。他住在埃達拉斯廢墟東北部懸崖的頂端。" },
    [8253] = { name = "毀滅摩弗拉斯", objective = "從摩弗拉斯身上取回奧術碎片，然後返回大法師克希雷姆那兒。" },
    [8418] = { name = "鑄造力量之石", objective = "前往沉沒的神廟，從巨魔守護者們身上取得巫毒羽毛，然後把它們交給阿什拉姆·瓦羅菲斯特。" },
    [8257] = { name = "摩弗拉斯之血", objective = "前往沉沒的阿塔哈卡神廟，殺死綠龍摩弗拉斯，將他的血液交給費伍德森林中的格雷塔·苔蹄。沉沒的神廟的入口就在悲傷沼澤中。" },
    [8236] = { name = "碧藍鑰匙", objective = "將碧藍鑰匙交給喬拉齊·拉文霍德公爵。" },
    [8413] = { name = "巫毒羽毛", objective = "將巫毒羽毛交給捕風者巴斯拉。" },
    [8422] = { name = "巨魔的羽毛", objective = "到沉沒的神廟去，從巨魔們身上獲得6支巫毒羽毛。" },
    [8425] = { name = "巫毒羽毛", objective = "將你從沉沒的神廟的巨魔身上得到的巫毒羽毛交給部落英雄的靈魂。" },
    [4362] = { name = "王國的命運", objective = "回到黑石深淵，從達格蘭·索瑞森大帝的魔掌中救出鐵爐堡公主茉艾拉·銅須。" },
    [4003] = { name = "拯救公主", objective = "殺掉達格蘭·索瑞森大帝，然後將鐵爐堡公主茉艾拉·銅須從他的邪惡詛咒中拯救出來。" },
    [7201] = { name = "最後的元素", objective = "到黑石深淵去取得10份元素精華。你應該在那些作戰傀儡和傀儡製造者身上找找，另外，薇薇安·拉格雷也提到了一些有關元素生物的話題……" },
    [4286] = { name = "好東西", objective = "到黑石深淵去找到20個黑鐵挎包。當你完成任務之後，回到奧拉留斯那裡覆命。你認為黑石深淵裡的黑鐵矮人應該會有這些黑鐵挎包。" },
    [7848] = { name = "熔火之心的傳送門", objective = "進入黑石深淵，在通往熔火之心的傳送門附近找到一塊熔火碎片，然後回到黑石山脈的洛索斯·天痕那裡。" },
    [5001] = { name = "比修的裝置", objective = "找到比修的裝置並把它們還給她。祝你好運！" },
    [4982] = { name = "比修的裝置", objective = "找到比修的裝置並把它們還給她。你記得她說過她把裝置藏在城市的最底層。" },
    [4788] = { name = "最後的石板", objective = "將第五塊和第六塊摩沙魯石板交給塔納利斯的勘查員詹斯·鐵靴。" },
    [6569] = { name = "黑龍幻象", objective = "到黑石塔去收集20顆黑色龍人的眼球，完成任務之後回到巫女麥蘭達那裡。" },
    [4764] = { name = "末日釦環", objective = "將末日釦環交給燃燒平原的瑪亞拉·布萊特文。" },
    [4768] = { name = "黑暗石板", objective = "將黑暗石板交給卡加斯的暗法師薇薇安·拉格雷。" },
    [5160] = { name = "監護者", objective = "到冬泉谷去找到哈爾琳，把奧比的鱗片交給她。" },
    [5526] = { name = "魔藤碎片", objective = "在厄運之槌中找到魔藤，然後從它上面採集一塊碎片。只有幹掉了奧茲恩之後，你才能進行採集工作。使用淨化之匣安全地封印碎片，然後將其交給月光林地永夜港的拉比恩·薩圖納。" },
    [7463] = { name = "久違的法師", objective = "到厄運之槌的扭木廣場去殺掉水元素海多斯博恩。把海多斯博恩精華交給圖書館的博學者萊德羅斯。" },
    [7461] = { name = "伊莫塔爾的瘋狂", objective = "你必須幹掉5座水晶塔周圍的守衛，那5座水晶塔維持著關押伊莫塔爾的監獄。一旦水晶塔的能量被削弱，伊莫塔爾周圍的能量力場就會消散。 進入伊莫塔爾的監獄，幹掉站在中間的那個惡魔。最後，在圖書館挑戰託塞德林王子。 當任務完成之後，到庭院中去找辛德拉古靈。" },
    [5247] = { name = "歷史的殘片", objective = "給東瘟疫之地的奧蘿拉帶去一塊魔化瑟銀錠、5塊恢復水晶，以及一小瓶恐怖之水。" },
    [7643] = { name = "上古聖馬之魂", objective = "你需要特殊的飼料來餵養靈魂馬。南海鎮的梅麗德絲·卡爾森可以為你提供這樣的糧草。 到菲拉斯的厄運之槌去，殺掉特迪斯·扭木，釋放上古聖馬之魂。用特殊的糧草餵養它，這樣可以安撫它的靈魂。最後，把奧金馬鎧交給它就可以完成祝福。" },
    [7631] = { name = "克索諾斯恐懼戰馬", objective = "閱讀莫蘇爾的指南，並召喚出一匹克索諾斯恐懼戰馬，擊敗它，然後控制它的靈魂。" },
    [7506] = { name = "翡翠夢境……", objective = "將這本典籍交給它的主人。" },
    [7503] = { name = "最偉大的獵手", objective = "將這本典籍交給它的主人。" },
    [7500] = { name = "奧法師的食譜", objective = "將這本典籍交給它的主人。" },
    [7501] = { name = "聖光之力", objective = "將這本典籍交給它的主人。" },
    [7504] = { name = "光明不會告訴你的事情", objective = "將這本典籍交給它的主人。" },
    [7498] = { name = "迦羅娜：潛行與詭計研究", objective = "將這本典籍交給它的主人。" },
    [7505] = { name = "你與冰霜震擊", objective = "將這本典籍交給它的主人。" },
    [7502] = { name = "束縛之影", objective = "將這本典籍交給它的主人。" },
    [7499] = { name = "防禦寶典", objective = "將這本典籍交給它的主人。" },
    [7629] = { name = "瓶中的小鬼", objective = "把瓶中的小鬼帶到通靈學院的鍊金實驗室中。在小鬼製造出羊皮紙之後，把瓶子還給戈瑟奇·邪眼。" },
    [7647] = { name = "審判和救贖", objective = "在通靈學院屍骨儲藏所地下室的中心使用預言水晶球。將你要審判的靈魂引領出來。將這些靈魂擊敗然後死亡騎士達克雷爾就將被召喚出來。將其擊敗然後獲得墮落戰馬的靈魂。 把贖罪的戰馬之魂和被祝福的奧金馬鎧一起附在達克雷爾的墮落戰馬身上。" },
    [7668] = { name = "達克雷爾的威脅", objective = "在通靈學院的屍骨儲藏所地下室中心使用預言水晶球，這樣將會召來一些靈魂，你必須與它們交戰。將這些靈魂擊敗，死亡騎士達克雷爾就會出現。 擊敗達克雷爾，將他的頭顱交給奧格瑞瑪智慧谷的薩格尼。" },
    [5463] = { name = "米奈希爾的禮物", objective = "到斯坦索姆城裡去找到米奈希爾的禮物，把巫妖生前的遺物放在那塊邪惡的土地上。" },
    [261] = { name = "血色之路", objective = "殺掉30個亡靈劫掠者，然後向尼耶爾前哨站的安東修士覆命。" },
    [1052] = { name = "血色之路", objective = "將安東修士的表彰信帶給南海鎮的虔誠的萊雷恩。" },
    [6522] = { name = "邪惡的盟友", objective = "把小卷軸交給幽暗城的瓦里瑪薩斯。" },
    [720] = { name = "一線希望", objective = "找到勘察員雷杜爾，告訴他鐵趾格雷茲還活著。" },
    [738] = { name = "尋找阿戈莫德", objective = "找到阿戈莫德。" },
    [739] = { name = "莫達洛克", objective = "幹掉殺害阿戈莫德的兇手：莫達洛克。 順便殺掉12個石窟斷骨者。 然後向洛克莫丹的勘察員基恩薩·鐵環報告。" },
    [723] = { name = "鐵趾的遺願", objective = "把鐵趾的護符交給荒蕪之地的勘察員雷杜恩。" },
    [724] = { name = "鐵趾的遺願", objective = "把鐵趾的護符交給鐵爐堡的史學家卡尼克。" },
    [725] = { name = "亡者的警告", objective = "找到顧問貝爾格拉姆，把便箋交給他。" },
    [726] = { name = "亡者的警告", objective = "和史學家卡尼克談一談。" },
    [762] = { name = "邪惡的使者", objective = "殺死苦痛堡壘中的因弗努斯大使，把證明他已死亡的信物交給鐵爐堡的顧問貝爾格拉姆。" },
    [2198] = { name = "破碎的項鍊", objective = "找到破碎的項鍊的來源，從而瞭解其潛在的價值。" },
    [2199] = { name = "昂貴的知識", objective = "給鐵爐堡的塔瓦斯德·基瑟爾帶去五塊銀錠。" },
    [2200] = { name = "回到奧達曼", objective = "去奧達曼尋找塔瓦斯的魔法項鍊，被殺的聖騎士是最後一個拿著它的人。" },
    [2318] = { name = "翻譯日記", objective = "在荒蕪之地的卡加斯哨所裡尋找一個可以幫你翻譯聖騎士日記的人。" },
    [2338] = { name = "翻譯日記", objective = "將項鍊借給加卡爾。作為交換，他將幫你翻譯日記。" },
    [2500] = { name = "荒蕪之地的材料", objective = "從荒蕪之地拿到加克所需的材料，然後回到塞爾薩瑪去見他。" },
    [2258] = { name = "荒蕪之地的試劑", objective = "前往荒蕪之地取回加卡爾需要的試劑，然後回到卡加斯把試劑交給他。" },
    [1954] = { name = "地獄火寶珠", objective = "將一顆地獄火寶珠交給塵泥沼澤的塔貝薩。" },
    [1955] = { name = "驅除魔鬼", objective = "殺死寶珠之魔，然後與塔貝薩談一談。" },
    [2988] = { name = "枯木巨魔的牢籠", objective = "檢查兩個枯木巨魔村落裡的籠子，然後向獅鷲管理員沙拉克·鷹斧回覆。" },
    [2989] = { name = "祖爾祭壇", objective = "檢查祖爾祭壇的頂部，然後向獅鷲管理員沙拉克·鷹斧報告。" },
    [2990] = { name = "薩迪斯·格希德", objective = "將沙普比克的羽毛交給詛咒之地的薩迪斯·格希德。" },
    [2933] = { name = "毒液瓶", objective = "將毒藥瓶交給塔倫米爾的某個藥劑師。" },
    [2934] = { name = "完好無損的毒囊", objective = "將完好無損的毒囊交給塔倫米爾的藥劑師林度恩。" },
    [2935] = { name = "請教加德林大師", objective = "與森金村的加德林大師談一談。" },
    [3520] = { name = "尖嘯者的靈魂", objective = "在菲拉斯捕獲3個尖嘯者的靈魂，然後回到熱砂港的葉基亞那裡去。" },
    [1448] = { name = "調查神廟", objective = "暴風城的布羅哈恩·鐵桶要求你去找到阿塔哈卡神廟。" },
    [1449] = { name = "去辛特蘭的旅程", objective = "找到辛特蘭的弗斯塔德·蠻錘。" },
    [1450] = { name = "獅鷲管理員", objective = "與辛特蘭的鷹巢山獅鷲飼養場裡的獅鷲管理員沙拉克·鷹斧談一談。" },
    [1451] = { name = "拉普索迪·鐵鏟", objective = "去辛特蘭找到拉普索迪·鐵鏟。" },
    [1452] = { name = "拉普索迪的卡利姆多雞尾酒", objective = "辛特蘭的拉普索迪·鐵鏟要求你帶給他3塊大鵬的砂囊、3塊格羅多克猩猩的肝臟和3塊鐵鬃熊的肝臟。" },
    [1469] = { name = "拉普索迪的故事", objective = "將阿塔萊石板碎片交給暴風城的布羅哈恩·鐵桶。" },
    [1424] = { name = "淚水之池", objective = "斯通納德的費澤魯爾要求你收集10件阿塔萊神器。" },
    [1429] = { name = "阿塔萊流放者", objective = "將一捆阿塔萊神器交給辛特蘭的阿塔萊流放者。" },
    [1444] = { name = "向費澤魯爾覆命", objective = "向斯通納德的費澤魯爾回報。" },
    [3444] = { name = "石環", objective = "到棘齒城去，從瑪爾馮·瑞文斯克的車間裡取回石環。" },
    [4787] = { name = "遠古之卵", objective = "將遠古之卵交給塔納利斯的葉基亞。" },
    [4141] = { name = "穆爾金和拉瑞安", objective = "從安戈洛爾環形山的血瓣花猛擊者和血瓣花掠奪者身上收集15個血瓣花，然後向穆爾金回覆。" },
    [4142] = { name = "造訪格雷甘", objective = "把血瓣花交給菲拉斯的格雷甘·山酒。" },
    [4145] = { name = "拉瑞安和穆爾金", objective = "為馬紹爾營地裡的拉瑞安殺掉5個血瓣花鞭笞者、5個血瓣花捕獸者、5個血瓣花掠奪者和5個血瓣花猛擊者。" },
    [4147] = { name = "瑪爾馮的車間", objective = "到棘齒城去，在瑪爾馮·瑞文斯克的車間裡找到他。" },
    [9052] = { name = "血瓣毒藥", objective = "收集一些血帽和格里什釘刺，然後向托爾瓦·尋路者覆命。" },
    [9051] = { name = "毒性測試", objective = "將魔暴龍之刺扎入一隻魔暴龍的體內。" },
    [8153] = { name = "苔蹄快步者的鹿角", objective = "將一副完好的苔蹄快步者鹿角交給艾薩拉的奧汀克。奧汀克居住在埃達拉斯廢墟東北部的懸崖頂。" },
    [8231] = { name = "碎浪多頭怪", objective = "將6塊碎浪多頭怪的鱗片交給艾薩拉的奧汀克。奧汀克居住在埃達拉斯廢墟東北部的懸崖頂部。" },
    [8251] = { name = "魔法的塵埃", objective = "為大法師克希雷姆收集10份閃光塵埃。" },
    [8252] = { name = "納迦的珊瑚", objective = "收集6塊魔化珊瑚，然後把它們交給大法師克希雷姆。" },
    [8414] = { name = "驅散邪惡", objective = "收集20個爪牙的天災石，並將它們交給西瘟疫之地的高階牧師賽爾丹尼斯。" },
    [8416] = { name = "惰性天災石", objective = "將惰性天災石交給冰風崗的指揮官阿什拉姆·瓦羅菲斯特。" },
    [8255] = { name = "苔蹄快步者", objective = "收集4份健康的野鹿腺體，把它們交給艾薩拉的奧汀克。奧汀克住在埃達拉斯廢墟東北部懸崖的頂部。" },
    [8256] = { name = "亡靈的腐液", objective = "為艾薩拉的奧汀克帶回一份亡靈腐液。奧汀克住在埃達拉斯廢墟東北部懸崖的頂端。" },
    [8234] = { name = "密封的藍袋子", objective = "從艾薩拉的木喉薩滿祭司那兒取回密封的藍袋子，將它交給艾薩拉的大法師克希雷姆。" },
    [8235] = { name = "密文碎片", objective = "將10塊密文碎片交給艾薩拉的大法師克希雷姆。" },
    [8410] = { name = "元素掌握", objective = "為捕風者巴斯拉收集一份空氣樣本、一份火元素樣本、一份土元素樣本和一份水元素樣本。" },
    [8412] = { name = "靈魂圖騰", objective = "將靈魂圖騰所需的材料交給捕風者巴斯拉。" },
    [8419] = { name = "小鬼的要求", objective = "將一塊惡魔布交給費伍德森林的伊普斯。" },
    [8420] = { name = "灼熱的疼痛", objective = "將一塊惡魔布交給費伍德森林的伊普斯。" },
    [8421] = { name = "奇怪的材料", objective = "將10塊腐爛的木頭和4個血毒精華交給費伍德森林的伊普斯。" },
    [8423] = { name = "戰士的血脈", objective = "殺死7頭地獄野豬，然後回到部落英雄的靈魂那兒。" },
    [8424] = { name = "魔誓者之戰", objective = "殺死詛咒之地的魔誓者，然後回到部落英雄的靈魂那兒。" },
    [3801] = { name = "黑鐵的遺產", objective = "如果你想要得到進入這座城市主城區的鑰匙，就去和弗蘭克羅恩·鑄鐵談一談。" },
    [4262] = { name = "征服者派隆", objective = "殺掉征服者派隆，然後向加琳達覆命。 加琳達告訴過你，派隆守在採礦場中，也許你應該去那裡找找。" },
    [3702] = { name = "索瑞森廢墟", objective = "聽皇家歷史學家阿克瑟努斯講述索瑞森的歷史。" },
    [3701] = { name = "索瑞森廢墟", objective = "到燃燒平原的索瑞森廢墟中去，從索瑞森遺物上搜集資訊。當你收集到足夠的資訊之後，就回到皇家歷史學家阿克瑟努斯那裡。" },
    [4341] = { name = "卡蘭·巨錘", objective = "去黑石深淵找到卡蘭·巨錘。 國王提到卡蘭在那裡負責看守囚犯——也許你應該在監獄附近尋找他。" },
    [4342] = { name = "卡蘭的故事", objective = "聽卡蘭·巨錘說他的故事。" },
    [4361] = { name = "糟糕的訊息", objective = "回到鐵爐堡，把這個壞訊息帶給國王麥格尼·銅須。" },
    [4182] = { name = "黑龍的威脅", objective = "殺掉15條黑色小龍、10條黑色龍人和1條黑色幼龍。當你完成任務之後就向赫林迪斯·河角回報。" },
    [4183] = { name = "真正的主人", objective = "把赫林迪斯·河角的信交給湖畔鎮的所羅門鎮長。" },
    [4184] = { name = "真正的主人", objective = "到暴風城去把所羅門的求援信交給伯瓦爾·弗塔根公爵。 伯瓦爾在暴風要塞裡。" },
    [4185] = { name = "真正的主人", objective = "與女伯爵卡特拉娜·普瑞斯托談話，然後再與伯瓦爾·弗塔根公爵談話。" },
    [4186] = { name = "真正的主人", objective = "把伯瓦爾的命令交給湖畔鎮的所羅門鎮長。" },
    [4223] = { name = "真正的主人", objective = "和燃燒平原的麥克斯韋爾元帥談一談。" },
    [4224] = { name = "真正的主人", objective = "和狼狽不堪的約翰談談來了解溫德索爾元帥的命運，然後回到麥克斯韋爾元帥那裡。 你想起麥克斯韋爾元帥說過他在一個北面的洞穴那裡。" },
    [4241] = { name = "溫德索爾元帥", objective = "到西北部的黑石山脈去，在黑石深淵中找到溫德索爾元帥的下落。 狼狽不堪的約翰曾告訴你說溫德索爾被關進了一個監獄。" },
    [4242] = { name = "被遺棄的希望", objective = "把這個壞訊息傳達給麥克斯韋爾元帥。" },
    [4264] = { name = "弄皺的便箋", objective = "溫德索爾元帥也許會對你手中的東西感興趣。畢竟，希望還沒有被完全扼殺。" },
    [4282] = { name = "一絲希望", objective = "找回溫德索爾元帥遺失的情報。 溫德索爾元帥確信那些情報在安格弗將軍和傀儡統帥阿格曼奇的手裡。" },
    [3906] = { name = "不和諧的烈焰", objective = "到黑石山脈的採石場去幹掉征服者派隆，然後向桑德哈特回報。" },
    [3981] = { name = "指揮官哥沙克", objective = "在黑石深淵裡找到指揮官哥沙克。 在那幅草圖上畫著的是一個鐵欄後面的獸人，也許你應該到某個類似監獄的地方去找找看。" },
    [3982] = { name = "出了什麼事？", objective = "保護哥沙克。" },
    [4001] = { name = "出了什麼事？", objective = "與卡蘭·巨錘談一談，收集關於綁架公主鐵爐堡公主茉艾拉·銅須這一事件的情報。將情報反饋給奧格瑞瑪城裡的薩爾。 哥沙克提到過卡蘭被關在附近的某個牢房中。" },
    [4002] = { name = "東部王國", objective = "如果你準備好要接受薩爾所安排的任務，就去找他談一談。" },
    [4081] = { name = "格殺勿論：黑鐵矮人", objective = "到黑石深淵去消滅那些邪惡的侵略者！ 軍官高圖斯要你去殺死15個鐵怒衛士、10個鐵怒獄卒和5個鐵怒步兵。完成任務之後回去向他覆命。" },
    [4122] = { name = "格拉克·洛克魯布", objective = "到燃燒平原去找到格拉克·洛克魯布。你回憶起雷克斯洛特曾經提起過，格拉克應該是在一座大型的黑石要塞中。 當你找到格拉克·洛克魯布之後，用瑟銀鐐銬把他銬起來，然後將其帶回灼熱峽谷。雷克斯洛特會讓他的部下等在那裡接應你。" },
    [4121] = { name = "押送囚徒", objective = "押送你的囚犯格拉克·洛克魯布。穿過燃燒平原和黑石山脈，一直走到灼熱峽谷。 雷克斯洛特曾經告訴過你，他會讓他的人等在黑石山脈的另外一邊準備接收格拉克。 另外，你還要把瑟銀鐐銬一併還給雷克斯洛特。" },
    [4061] = { name = "機器的崛起", objective = "到燃燒平原去為塞朵拉·穆瓦丹尼收集10塊斷裂的元素碎片。 塞朵拉曾經說過，那裡的機械傀儡和元素生物是這種碎片的主要來源。" },
    [4062] = { name = "機器的崛起", objective = "將元素碎片樣本交給魯特維爾·沃拉圖斯。 塞朵拉說魯特維爾就在東邊的一處營地裡。" },
    [5002] = { name = "給麥克斯韋爾的訊息", objective = "到燃燒平原去，把比修的情報交給麥克斯韋爾元帥。" },
    [4981] = { name = "狡猾的比修", objective = "到黑石塔去查明比修的下落。" },
    [5065] = { name = "失落的摩沙魯石板", objective = "把第三塊和第四塊摩沙魯石板交給塔納利斯的勘查員詹斯·鐵靴。" },
    [4726] = { name = "雛龍精華", objective = "將龍靈採集器900型和8份雛龍精華交給燃燒平原烈焰峰的丁奇·斯迪波爾。" },
    [4808] = { name = "菲諾克", objective = "把丁奇的信交給菲諾克。" },
    [4809] = { name = "冰風奇美拉角", objective = "將8支完整的冰風奇美拉角交給菲諾克。" },
    [4810] = { name = "返回丁奇身邊", objective = "把菲諾克的包裹交給燃燒平原的丁奇·斯迪波爾。" },
    [4907] = { name = "丁奇·斯迪波爾", objective = "與丁奇·斯迪波爾談一談。" },
    [4734] = { name = "冷凍龍蛋", objective = "在孵化間對著某顆龍蛋使用龍蛋冷凍器初號機。" },
    [4903] = { name = "高圖斯的命令", objective = "殺死歐莫克大王、指揮官沃恩和維姆薩拉克。找到重要的黑石檔案，然後向卡加斯的軍官高圖斯彙報。" },
    [4941] = { name = "伊崔格的智慧", objective = "和奧格瑞瑪的伊崔格談一談。討論完畢後，諮詢薩爾的意見。 你回憶起曾在薩爾的大廳中見過伊崔格。" },
    [4974] = { name = "為部落而戰！", objective = "去黑石塔殺死大酋長雷德·黑手，帶著他的頭顱返回奧格瑞瑪。" },
    [6566] = { name = "風吹來的訊息", objective = "聽薩爾講話。" },
    [6567] = { name = "部落的勇士", objective = "按照酋長的指示找到雷克薩。他在石爪山和菲拉斯之間的淒涼之地遊蕩。" },
    [6568] = { name = "雷克薩的證明", objective = "把雷克薩的證明交給西瘟疫之地的巫女麥蘭達。" },
    [6402] = { name = "集合在暴風城", objective = "前往暴風城的城門。與侍衛洛文交談，他會通知溫德索爾元帥你已經到達了。" },
    [6403] = { name = "潛藏者", objective = "跟隨雷吉納德·溫德索爾元帥在暴風城中前進。保護他，別讓他受到傷害！" },
    [6501] = { name = "巨龍之眼", objective = "你必須尋遍世界以找到一種能恢復龍眼碎片的能量的生物。你對這種生物的唯一瞭解就是：他們確實存在。" },
    [6570] = { name = "埃博斯塔夫", objective = "到塵泥沼澤中的巨龍沼澤去，找到埃博斯塔夫的洞穴。進入洞穴之後戴上龍形護符，然後跟埃博斯塔夫交談。" },
    [6582] = { name = "龍骨試煉，斯克利爾", objective = "找到藍龍斯克利爾並殺掉他。從他的身上取下他的顱骨，然後將其交給埃博斯塔夫。 你可以在冬泉谷找到斯克利爾。" },
    [6583] = { name = "龍骨試煉，索姆努斯", objective = "殺掉綠龍索姆努斯，把他的顱骨交給埃博斯塔夫。" },
    [6584] = { name = "龍骨試煉，克魯納里斯", objective = "諾茲多姆的孩子克魯納里斯在塔納利斯沙漠守衛著時光之穴。殺了他，把他的顱骨交給埃博斯塔夫。" },
    [6585] = { name = "龍骨試煉，埃克托茲", objective = "到格瑞姆巴託去殺掉紅龍埃克托茲，把他的顱骨交給埃博斯塔夫。" },
    [6601] = { name = "晉升……", objective = "看來這場假面舞會就要結束了。你知道麥蘭達為你製作的龍形護符在黑石塔裡面不會發揮作用，也許你應該去找雷克薩，將你的困境告訴他。把黯淡的龍火護符給他看看，也許他知道下一步該怎麼做。" },
    [5089] = { name = "達基薩斯將軍的命令", objective = "把達基薩斯將軍的命令交給燃燒平原的麥克斯韋爾元帥。" },
    [5527] = { name = "淨化之匣", objective = "到希利蘇斯的南風村去尋找淨化之匣。然後將其交給月光林地永夜港的拉比恩·薩圖納。" },
    [5244] = { name = "凱斯利爾廢墟", objective = "與墜星村的加隆·石矛談一談。" },
    [5245] = { name = "凱斯利爾的怨靈", objective = "使用加隆的鎬來尋找四塊上層精靈遺物的碎片，把它們交給東瘟疫之地的奧蘿拉。" },
    [5246] = { name = "歷史的殘片", objective = "在艾薩拉的辛瑪洛神殿裡找到神聖的上層精靈筆跡，並將它帶給位於東瘟疫之地的北地哨塔附近的奧蘿拉。" },
    [7637] = { name = "犧牲精神", objective = "到鐵爐堡去找高階牧師洛漢，從他那裡拿到驅魔香爐。你需要捐贈150金幣來獲得它。" },
    [7639] = { name = "聖騎士的審判", objective = "把驅魔香爐交給暴風城教堂區的格雷森·沙東布瑞克公爵。" },
    [7640] = { name = "恐懼谷的靈魂", objective = "使用驅魔香爐召喚恐懼谷中的靈魂。當你殺掉25個恐懼谷的靈魂之後，回到暴風城教堂區的格雷森·沙東布瑞克公爵那裡覆命。" },
    [7641] = { name = "格瑞曼德·艾爾默", objective = "與暴風城矮人區的格瑞曼德·艾爾默談一談。" },
    [7642] = { name = "收集材料", objective = "把40塊符文布、6塊奧金錠、10棵阿爾薩斯之淚、5瓶斯坦索姆聖水和150枚金幣交給暴風城矮人區的格瑞曼德·艾爾默。" },
    [7648] = { name = "艾爾默的手藝", objective = "把奧金馬鎧交給暴風城教堂區的格雷森·沙東布瑞克公爵。" },
    [7645] = { name = "魔法糧草", objective = "把製作魔法糧草所需要的重要材料：20塊可口的魔法點心帶給希爾斯布萊德丘陵的梅麗德絲·卡爾森。據說銀色黎明會出售這種餅乾。 你還需要給她50金幣來對她進行安撫。" },
    [7563] = { name = "血之狂暴", objective = "把30瓶狂暴野獸的血交給燃燒平原的莫蘇爾·召血者。" },
    [7564] = { name = "戈瑟奇·邪眼", objective = "把血箱交給燃燒平原的戈瑟奇·邪眼。" },
    [7623] = { name = "魔王貝恩霍勒", objective = "從燃燒平原的戈瑟奇那裡購買暗影藥水。 使用這種藥劑進入加德納爾，然後與魔王貝恩霍勒談一談。" },
    [7624] = { name = "背叛者烏拉泰克", objective = "找到並殺死烏拉泰克，然後把叛徒之心交給加德納爾的魔王貝恩霍勒。" },
    [7625] = { name = "克索諾斯星塵", objective = "從烏爾丹那裡購買克索諾斯星塵，把它交給燃燒平原的戈瑟奇·邪眼。" },
    [7626] = { name = "達斯莫拉之鈴", objective = "把10瓶暗影之力藥劑交給燃燒平原的戈瑟奇·邪眼。" },
    [7627] = { name = "黑暗戰車之輪", objective = "把6份大塊魔光碎片和25塊黑鐵礦石交給燃燒平原的戈瑟奇·邪眼。" },
    [7628] = { name = "末日蠟燭", objective = "把35塊黑龍鱗片交給燃燒平原的戈瑟奇·邪眼。" },
    [7630] = { name = "奧金錠", objective = "把3塊奧金錠交給燃燒平原的戈瑟奇·邪眼。" },
    [5461] = { name = "萊斯·霜語", objective = "到阿拉希高地的激流堡遺蹟裡面尋找巫妖生前的遺物。如果你能找到這樣的東西，就把它交給馬杜克鎮長。" },
    [5462] = { name = "亡靈萊斯·霜語", objective = "到東瘟疫之地的聖光之願禮拜堂去找到萊尼德·巴薩羅梅，給他看看巫妖生前的遺物，並告訴他你收集到的情報。" },
    [5464] = { name = "米奈希爾的禮物", objective = "把禁錮靈魂的遺物交給東瘟疫之地的萊尼德·巴薩羅梅。" },
    [5465] = { name = "禁錮靈魂的遺物", objective = "回到凱爾達隆的馬杜克鎮長那裡，把禁錮靈魂的遺物交給他。" },
    [5522] = { name = "萊尼德·巴薩羅梅", objective = "把冰凍的龍蛋交給東瘟疫之地的萊尼德·巴薩羅梅。" },
    [5531] = { name = "貝蒂娜·比格辛克", objective = "將冰凍的龍蛋交給貝蒂娜·比格辛克。" },
    [7644] = { name = "被祝福的奧金馬鎧", objective = "將被祝福的奧金馬鎧交給暴風城教堂區的格雷森·沙東布瑞克公爵。" },
    [7646] = { name = "預言水晶球", objective = "把一塊艾澤拉斯鑽石和一塊原始黑鑽石交給暴風城教堂區的格雷森·沙東布瑞克公爵。" },
    [7667] = { name = "收集材料", objective = "如果你願意幫助奧格瑞瑪智慧谷的薩格尼，就將一塊艾澤拉斯鑽石和一塊原始黑鑽石交給他。" },
    [5251] = { name = "檔案管理員", objective = "在斯坦索姆城中找到血色十字軍的檔案管理員加爾福特，殺掉他，然後燒燬血色十字軍檔案。" },
    [5542] = { name = "惡魔之犬", objective = "殺掉20條瘟疫幼犬、5條瘟疫犬和5條狂怒的瘟疫犬。任務完成之後向提里奧·弗丁覆命。" },
    [5543] = { name = "血染的天空", objective = "殺死30只瘟疫蝙蝠，然後向提里奧·弗丁覆命。" },
    [5544] = { name = "腐肉蟲", objective = "在東瘟疫之地搜尋腐肉蟲和腐肉吞噬者。殺了它們並收集它們的肉。當你收集到15塊食腐蟲肉塊之後，就回到提里奧·弗丁那裡。" },
    [5742] = { name = "救贖", objective = "聽聽提里奧·弗丁要說什麼。" },
    [5781] = { name = "遺忘的記憶", objective = "到東瘟疫之地最南端的墓室去找回泰蘭之錘。完成目標之後，返回提里奧·弗丁那裡。" },
    [5845] = { name = "失落的榮耀", objective = "到東瘟疫之地東北部的北谷去，找到失落榮耀的象徵。完成目標之後向提里奧·弗丁覆命。" },
    [5846] = { name = "愛與家庭", objective = "到凱爾達隆島去，尋找關於那副畫的線索。凱爾達隆島在瘟疫之地南部的湖中央。" },
    [5262] = { name = "可怕的真相", objective = "將巴納扎爾的頭顱交給東瘟疫之地的尼古拉斯·瑟倫霍夫公爵。" },
    [6133] = { name = "遊俠之王的命令", objective = "到東瘟疫之地的北方邊界去找回奎爾薩拉斯名冊，這件物品在奎爾林斯小屋的某處。 另外你還必須殺掉8個遊俠、8個巡路者和8個護林者。" },
    [6042] = { name = "討厭的蝙蝠", objective = "殺掉20只毒性瘟疫蝙蝠和10只巨型瘟疫蝙蝠，然後回到納薩諾斯·凋零者那裡。" },
    [6022] = { name = "殺戮的理由", objective = "到東邊的考林路口去屠殺鎮裡的亡靈天災。在10分鐘內收集7塊生命腐質，使用研缽和搗杵將其研磨成凝固腐質。" },
    [6135] = { name = "暗翼蝠", objective = "找到暗翼蝠並殺掉它。從屍體上取下一塊暗翼蝠的皮，並把它交給納薩諾斯·凋零者。 據說暗翼蝠遊蕩在瑪瑞斯農場北面的荒原上。" },
    [6136] = { name = "肥大的食腐蟲", objective = "找到東瘟疫之地北方荒原中的淤血蟲並消滅它。任務完成之後，向納薩諾斯·凋零者覆命。" },
  },
}
for lang, list in pairs(PDF_QUESTS) do
    local content = FDJ.ContentLocales[lang] or {}
    FDJ.ContentLocales[lang] = content
    content.quests = content.quests or {}
    for id, entry in pairs(list) do
        if content.quests[id] == nil then content.quests[id] = entry end
    end
end

-- Quests added in the second compendium pass.
local AUDIT2_QUESTS = {
    deDE = {
        [4295] = { name = "Rocknots Bier" },
