for lang, list in pairs(BREADCRUMB_QUESTS) do
    local content = FDJ.ContentLocales[lang] or {}
    FDJ.ContentLocales[lang] = content
    content.quests = content.quests or {}
    for id, entry in pairs(list) do
        local q = content.quests[id] or {}
        content.quests[id] = q
        q.name = q.name or entry.name
        q.objective = q.objective or entry.objective
    end
end
