    [78699] = { name = "伯絲卡之眼", objective = "到焚木村附近的密件領取C的報酬。", description = "在主城收到C的下一封信後即可接取。", note = "盜賊職業任務，接在「澤索司號角」之後；C的下一封信（約30級）會再次把你帶到密件。每個區域都要穿上血色新兵的制服：潛行或攻擊會讓它失效。", warning = "單人任務：你必須獨自完成，不能在隊伍中。" },
